import React, { useState } from 'react';
import {
  flexRender,
  getCoreRowModel,
  useReactTable,
  getPaginationRowModel,
  getSortedRowModel,
  getFilteredRowModel,
} from '@tanstack/react-table';
import { FiChevronLeft, FiChevronRight, FiChevronsLeft, FiChevronsRight, FiSearch } from 'react-icons/fi';

const DataTable = ({ 
    columns, 
    data, 
    searchPlaceholder = "Search...",
    onRowClick,
    isLoading = false
}) => {
  const [sorting, setSorting] = useState([]);
  const [globalFilter, setGlobalFilter] = useState('');

  const table = useReactTable({
    data,
    columns,
    state: {
      sorting,
      globalFilter,
    },
    onSortingChange: setSorting,
    onGlobalFilterChange: setGlobalFilter,
    getCoreRowModel: getCoreRowModel(),
    getPaginationRowModel: getPaginationRowModel(),
    getSortedRowModel: getSortedRowModel(),
    getFilteredRowModel: getFilteredRowModel(),
  });

  return (
    <div className="space-y-4">
      {/* Toolbar */}
      <div className="flex justify-between items-center">
        <div className="relative w-64">
          <FiSearch className="absolute left-3 top-1/2 -translate-y-1/2 text-textMuted" />
          <input
            value={globalFilter ?? ''}
            onChange={e => setGlobalFilter(e.target.value)}
            className="w-full pl-10 pr-4 py-2 bg-white/5 border border-white/10 rounded-lg text-white placeholder-textMuted focus:outline-none focus:ring-2 focus:ring-primary/50 transition-all"
            placeholder={searchPlaceholder}
          />
        </div>
      </div>

      {/* Table Container */}
      <div className="glass-panel overflow-x-auto rounded-xl">
        <table className="w-full text-left border-collapse">
          <thead>
            {table.getHeaderGroups().map(headerGroup => (
              <tr key={headerGroup.id} className="border-b border-white/10 bg-white/5">
                {headerGroup.headers.map(header => (
                  <th 
                    key={header.id} 
                    className="p-4 text-sm font-semibold text-textMuted whitespace-nowrap cursor-pointer hover:text-white transition-colors"
                    onClick={header.column.getToggleSortingHandler()}
                  >
                    <div className="flex items-center space-x-2">
                        {flexRender(
                        header.column.columnDef.header,
                        header.getContext()
                        )}
                        {{
                        asc: ' 🔼',
                        desc: ' 🔽',
                        }[header.column.getIsSorted()] ?? null}
                    </div>
                  </th>
                ))}
              </tr>
            ))}
          </thead>
          <tbody>
            {isLoading ? (
                <tr>
                    <td colSpan={columns.length} className="p-8 text-center text-textMuted">
                        <div className="w-6 h-6 border-2 border-primary border-t-transparent rounded-full animate-spin mx-auto mb-2"></div>
                        Loading data...
                    </td>
                </tr>
            ) : table.getRowModel().rows.length === 0 ? (
                <tr>
                    <td colSpan={columns.length} className="p-8 text-center text-textMuted">
                        No results found.
                    </td>
                </tr>
            ) : (
                table.getRowModel().rows.map(row => (
                <tr 
                    key={row.id} 
                    className={`border-b border-white/5 hover:bg-white/5 transition-colors ${onRowClick ? 'cursor-pointer' : ''}`}
                    onClick={() => onRowClick && onRowClick(row.original)}
                >
                    {row.getVisibleCells().map(cell => (
                    <td key={cell.id} className="p-4 text-sm text-textMain">
                        {flexRender(cell.column.columnDef.cell, cell.getContext())}
                    </td>
                    ))}
                </tr>
                ))
            )}
          </tbody>
        </table>
      </div>

      {/* Pagination */}
      <div className="flex items-center justify-between glass-panel px-4 py-3 rounded-lg">
        <div className="text-sm text-textMuted">
            Showing {table.getRowModel().rows.length.toLocaleString()} of{' '}
            {table.getPrePaginationRowModel().rows.length.toLocaleString()} Rows
        </div>
        
        <div className="flex items-center space-x-2">
          <button
            className="p-2 rounded-lg bg-white/5 hover:bg-white/10 text-white disabled:opacity-50 disabled:cursor-not-allowed transition-colors"
            onClick={() => table.setPageIndex(0)}
            disabled={!table.getCanPreviousPage()}
          >
            <FiChevronsLeft />
          </button>
          <button
            className="p-2 rounded-lg bg-white/5 hover:bg-white/10 text-white disabled:opacity-50 disabled:cursor-not-allowed transition-colors"
            onClick={() => table.previousPage()}
            disabled={!table.getCanPreviousPage()}
          >
            <FiChevronLeft />
          </button>
          
          <span className="text-sm text-textMain px-4">
            Page <span className="font-semibold">{table.getState().pagination.pageIndex + 1}</span> of{' '}
            <span className="font-semibold">{table.getPageCount()}</span>
          </span>

          <button
            className="p-2 rounded-lg bg-white/5 hover:bg-white/10 text-white disabled:opacity-50 disabled:cursor-not-allowed transition-colors"
            onClick={() => table.nextPage()}
            disabled={!table.getCanNextPage()}
          >
            <FiChevronRight />
          </button>
          <button
            className="p-2 rounded-lg bg-white/5 hover:bg-white/10 text-white disabled:opacity-50 disabled:cursor-not-allowed transition-colors"
            onClick={() => table.setPageIndex(table.getPageCount() - 1)}
            disabled={!table.getCanNextPage()}
          >
            <FiChevronsRight />
          </button>
        </div>
        
        <select
          value={table.getState().pagination.pageSize}
          onChange={e => {
            table.setPageSize(Number(e.target.value))
          }}
          className="bg-white/5 border border-white/10 rounded-lg text-sm text-white px-3 py-2 outline-none focus:ring-1 focus:ring-primary"
        >
          {[10, 20, 30, 40, 50].map(pageSize => (
            <option key={pageSize} value={pageSize} className="bg-background text-white">
              Show {pageSize}
            </option>
          ))}
        </select>
      </div>
    </div>
  );
};

export default DataTable;

import { useState } from 'react';
import useAuthStore from '../store/authStore';
import axiosInstance from '../api/axiosInstance';
import { FiSave, FiUploadCloud, FiUser } from 'react-icons/fi';
import toast from 'react-hot-toast';

const RegisterStaff = () => {
  const [formData, setFormData] = useState({
    username: '',
    name: '',
    password: '',
    role: 'cashier',
    pin: '',
    avatar: ''
  });
  
  const [isLoading, setIsLoading] = useState(false);

  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData(prev => ({ ...prev, [name]: value }));
  };

  // Convert File to Base64 String
  const handleFileChange = (e) => {
    const file = e.target.files[0];
    if (file) {
      if (file.size > 2 * 1024 * 1024) { // 2MB restriction
          toast.error("File cannot be larger than 2MB.");
          return;
      }
      const reader = new FileReader();
      reader.onloadend = () => {
        setFormData(prev => ({ ...prev, avatar: reader.result }));
      };
      reader.readAsDataURL(file);
    }
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setIsLoading(true);
    
    const loadingToast = toast.loading('Registering staff...');

    try {
      // The backend expects password to be at least 8 chars if provided, 
      // but if we leave it blank in formData, we must rely on backend default 'cafe1234'
      const payload = { ...formData };
      if (!payload.password) delete payload.password;

      const res = await axiosInstance.post('/auth/admin/users/create/', payload);
      
      if (res.data.success) {
          toast.success(`Staff account ${formData.username} created!`);
          setFormData({
              username: '', name: '', password: '', role: 'cashier', pin: '', avatar: ''
          });
      }
    } catch (err) {
      toast.error(err.response?.data?.detail || "Registration failed. Check if username or PIN is valid.");
    } finally {
      toast.dismiss(loadingToast);
      setIsLoading(false);
    }
  };

  return (
    <div className="max-w-3xl mx-auto space-y-6">
      <div className="mb-8">
          <h1 className="text-3xl font-bold bg-clip-text text-transparent bg-gradient-to-r from-primary to-accent">
              Register New Staff
          </h1>
          <p className="text-textMuted mt-1">Create accounts for cashiers, waiters, and managers.</p>
      </div>

      <form onSubmit={handleSubmit} className="glass-panel p-6 md:p-8 space-y-8">
        
        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            <div>
                <label className="block text-sm font-medium text-textMuted mb-1">Username *</label>
                <input required type="text" name="username" value={formData.username} onChange={handleChange} className="glass-input w-full" placeholder="e.g. jdoe" />
            </div>
            <div>
                <label className="block text-sm font-medium text-textMuted mb-1">Full Name *</label>
                <input required type="text" name="name" value={formData.name} onChange={handleChange} className="glass-input w-full" placeholder="John Doe" />
            </div>

            <div>
                <label className="block text-sm font-medium text-textMuted mb-1">Role *</label>
                <select name="role" required value={formData.role} onChange={handleChange} className="glass-input w-full appearance-none">
                    <option value="waiter">Waiter</option>
                    <option value="cashier">Cashier</option>
                    <option value="barista">Barista</option>
                    <option value="manager">Manager</option>
                    <option value="super_admin">Super Admin</option>
                </select>
            </div>
            
            <div>
                <label className="block text-sm font-medium text-textMuted mb-1">Login Password</label>
                <input type="password" name="password" minLength={8} value={formData.password} onChange={handleChange} className="glass-input w-full" placeholder="Leaves empty for default (cafe1234)" />
            </div>

            <div>
                <label className="block text-sm font-medium text-textMuted mb-1">4-6 Digit Staff PIN</label>
                <input type="text" name="pin" minLength={4} maxLength={6} pattern="\d+" value={formData.pin} onChange={(e) => handleChange({ target: { name: 'pin', value: e.target.value.replace(/\D/g, '')}} )} className="glass-input w-full tracking-widest" placeholder="e.g. 1234" />
            </div>
        </div>

        <div className="space-y-4">
            <h2 className="text-xl font-semibold border-b border-white/10 pb-2 text-primary">Avatar Profile Photo</h2>
            <div className="flex items-center space-x-6">
                <div className="w-24 h-24 rounded-full bg-surface border border-dashed border-slate-600 flex items-center justify-center overflow-hidden shrink-0">
                    {formData.avatar ? (
                        <img src={formData.avatar} alt="Preview" className="w-full h-full object-cover" />
                    ) : (
                        <FiUser className="w-8 h-8 text-textMuted" />
                    )}
                </div>
                <div className="flex-1">
                    <label className="btn-secondary w-full md:w-auto inline-flex cursor-pointer space-x-2 text-sm px-4 py-2">
                        <FiUploadCloud className="w-5 h-5" />
                        <span>Upload Custom Avatar Image</span>
                        <input type="file" accept="image/*" onChange={handleFileChange} className="hidden" />
                    </label>
                    <p className="text-xs text-textMuted mt-2">Max limit: 2MB. Square ratio recommended.</p>
                </div>
            </div>
        </div>

        <div className="pt-4 flex justify-end">
            <button type="submit" disabled={isLoading} className="btn-primary space-x-2 px-8">
                <FiSave className="w-5 h-5" />
                <span>{isLoading ? 'Registering...' : 'Register Staff Account'}</span>
            </button>
        </div>

      </form>
    </div>
  );
};

export default RegisterStaff;

import React, { useState, useEffect } from 'react';
import { useForm } from 'react-hook-form';
import { 
    FiSave, FiLoader, FiGlobe, FiDollarSign, FiPrinter, FiShield, FiDatabase,
    FiDownload, FiUploadCloud, FiCheckCircle, FiSettings
} from 'react-icons/fi';
import { settingsApi } from '../api/settingsApi';
import toast from 'react-hot-toast';
import useSettingsStore from '../store/settingsStore';
import ReceiptPreview from '../components/ReceiptPreview'; // We will build this next

const TABS = [
    { id: 'general', label: 'Store Info', icon: FiGlobe },
    { id: 'financial', label: 'Financial & Localization', icon: FiDollarSign },
    { id: 'receipt', label: 'Printers & Receipts', icon: FiPrinter },
    { id: 'system', label: 'System & Backup', icon: FiDatabase },
];

export default function Settings() {
    const { settings, fetchSettings } = useSettingsStore();
    const [activeTab, setActiveTab] = useState('general');
    const [isSaving, setIsSaving] = useState(false);
    const [isBackingUp, setIsBackingUp] = useState(false);
    
    const { register, handleSubmit, reset, watch, setValue, formState: { errors } } = useForm({
        defaultValues: settings || {}
    });

    const [logoBase64, setLogoBase64] = useState(settings?.logo_base64 || '');

    // Real-time watching for the Preview component
    const watchReceiptProps = watch(['brand_name', 'brand_phone', 'address', 'tax_label', 'tax_rate', 'tax_inclusive', 'receipt_printer_type', 'receipt_language', 'receipt_header_msg', 'receipt_footer_msg', 'wifi_password', 'currency']);

    useEffect(() => {
        if (settings) {
            reset(settings);
            setLogoBase64(settings.logo_base64 || '');
        }
    }, [settings, reset]);

    const handleLogoUpload = (e) => {
        const file = e.target.files[0];
        if (file) {
            const reader = new FileReader();
            reader.onloadend = () => {
                const base64String = reader.result;
                setLogoBase64(base64String);
                setValue('logo_base64', base64String, { shouldDirty: true });
            };
            reader.readAsDataURL(file);
        }
    };

    const onSubmit = async (data) => {
        setIsSaving(true);
        try {
            await settingsApi.updateSettings(data);
            await fetchSettings(); // Refresh global local storage State
            toast.success('Settings updated successfully!');
        } catch (error) {
            console.error('Failed to update settings:', error);
            const msg = error.response?.data?.detail || error.response?.data?.error || 'Failed to update settings';
            toast.error(msg);
        } finally {
            setIsSaving(false);
        }
    };

    const handleDownloadBackup = async () => {
        setIsBackingUp(true);
        try {
            const res = await settingsApi.downloadBackup();
            const url = window.URL.createObjectURL(new Blob([res.data]));
            const link = document.createElement('a');
            link.href = url;
            link.setAttribute('download', `waitless_backup_${new Date().toISOString().split('T')[0]}.json`);
            document.body.appendChild(link);
            link.click();
            link.parentNode.removeChild(link);
            toast.success('Backup downloaded successfully!');
        } catch (error) {
            toast.error('Failed to download backup');
        } finally {
            setIsBackingUp(false);
        }
    };

    const handleRestoreUpload = async (e) => {
        const file = e.target.files[0];
        if (!file) return;

        const confirm = window.confirm("WARNING: This will completely OVERWRITE your database with the backup file. Are you absolutely sure?");
        if (!confirm) {
            e.target.value = null;
            return;
        }

        const restoreToast = toast.loading("Restoring database... Please do not close this window.");
        try {
            await settingsApi.uploadRestore(file);
            toast.success("System Restored Successfully! Reloading in 3 seconds...", { id: restoreToast });
            setTimeout(() => {
                window.location.reload();
            }, 3000);
        } catch (error) {
            console.error(error);
            toast.error("Restore failed. Check console for details.", { id: restoreToast });
        } finally {
            e.target.value = null;
        }
    };

    if (!settings) {
        return (
            <div className="flex justify-center items-center h-[calc(100vh-100px)]">
                <FiLoader className="w-8 h-8 animate-spin text-primary" />
            </div>
        );
    }

    return (
        <div className="p-6 max-w-7xl mx-auto flex flex-col items-center">
            
            <div className="w-full flex justify-between items-center mb-6">
                <div>
                    <h1 className="text-2xl font-bold text-white flex items-center">
                        <FiShield className="mr-3 text-primary" /> System Settings
                    </h1>
                    <p className="text-textMuted mt-1 text-sm">Configure branch details, POS behavior, taxes, and backups.</p>
                </div>
            </div>

            <div className="w-full grid grid-cols-1 lg:grid-cols-4 gap-6">
                {/* Sidebar Tabs */}
                <div className="lg:col-span-1 space-y-2">
                    {TABS.map(tab => {
                        const Icon = tab.icon;
                        const isActive = activeTab === tab.id;
                        return (
                            <button
                                key={tab.id}
                                onClick={() => setActiveTab(tab.id)}
                                className={`w-full flex items-center p-4 rounded-xl transition-all duration-200 text-left ${
                                    isActive 
                                    ? 'bg-primary/20 text-primary border border-primary/30 shadow-lg shadow-primary/10' 
                                    : 'bg-black/20 text-textMuted hover:bg-white/5 border border-transparent'
                                }`}
                            >
                                <Icon className={`w-5 h-5 mr-3 ${isActive ? 'text-primary' : 'opacity-70'}`} />
                                <span className="font-semibold">{tab.label}</span>
                            </button>
                        );
                    })}
                </div>

                {/* Main Content Area */}
                <div className="lg:col-span-3 glass-panel p-6 rounded-2xl relative min-h-[600px]">
                    <form onSubmit={handleSubmit(onSubmit)} className="space-y-6">
                        
                        {/* TAB: GENERAL */}
                        {activeTab === 'general' && (
                            <div className="animate-fade-in space-y-6">
                                <h2 className="text-xl font-bold text-white mb-6 border-b border-white/10 pb-2">Store Information</h2>
                                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                                    <div className="space-y-1 md:col-span-2">
                                        <label className="text-sm font-medium text-textMuted block mb-2">Cafe Logo</label>
                                        <div className="flex items-center space-x-6 bg-black/20 p-4 rounded-xl border border-white/5">
                                            <div className="w-20 h-20 rounded-xl overflow-hidden bg-primary/20 flex items-center justify-center shrink-0 border border-primary/30">
                                                {logoBase64 ? (
                                                    <img src={logoBase64} alt="Current Logo" className="w-full h-full object-contain" />
                                                ) : (
                                                    <span className="text-xs text-primary font-bold">No Logo</span>
                                                )}
                                            </div>
                                            <div className="flex-1 space-y-2">
                                                <input 
                                                    type="file" 
                                                    accept="image/*" 
                                                    onChange={handleLogoUpload}
                                                    className="block w-full text-sm text-textMuted file:mr-4 file:py-2 file:px-4 file:rounded-full file:border-0 file:text-sm file:font-semibold file:bg-primary/20 file:text-primary hover:file:bg-primary/30 transition-colors"
                                                />
                                                <p className="text-xs text-textMuted">Recommended format: Square PNG or JPG, max 500x500px.</p>
                                            </div>
                                            {/* Hidden input to ensure it gets registered if present */}
                                            <input type="hidden" {...register('logo_base64')} />
                                        </div>
                                    </div>
                                    
                                    <div className="space-y-1">
                                        <label className="text-sm font-medium text-textMuted">Brand / Store Name</label>
                                        <input {...register('brand_name', { required: true })} className="input w-full" placeholder="e.g. Waitless Cafe" />
                                    </div>
                                    <div className="space-y-1">
                                        <label className="text-sm font-medium text-textMuted">Contact Phone</label>
                                        <input {...register('brand_phone')} className="input w-full" placeholder="e.g. 01099641402" />
                                    </div>
                                    <div className="space-y-1 md:col-span-2">
                                        <label className="text-sm font-medium text-textMuted">Physical Address</label>
                                        <input {...register('address')} className="input w-full" placeholder="123 Main St, City" />
                                    </div>
                                    <div className="space-y-1 md:col-span-2">
                                        <label className="text-sm font-medium text-textMuted">Social Link / QR Data</label>
                                        <input {...register('social_link')} className="input w-full" placeholder="https://instagram.com/yourcafe" />
                                        <p className="text-xs text-textMuted mt-1">If set, a QR code pointing here will be printed on receipts.</p>
                                    </div>
                                    <div className="space-y-1 md:col-span-2">
                                        <label className="text-sm font-medium text-textMuted">Operating Hours (Internal Reference)</label>
                                        <textarea {...register('operating_hours')} className="input w-full h-24" placeholder="Mon-Fri: 8am - 10pm..." />
                                    </div>
                                </div>
                            </div>
                        )}

                        {/* TAB: FINANCIAL */}
                        {activeTab === 'financial' && (
                            <div className="animate-fade-in space-y-6">
                                <h2 className="text-xl font-bold text-white border-b border-white/10 pb-2">Financial & Localization</h2>
                                
                                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                                    <div className="space-y-1 bg-black/20 p-4 rounded-xl border border-white/5">
                                        <label className="text-sm font-bold text-white block mb-2">Primary Currency</label>
                                        <select {...register('currency')} className="input w-full">
                                            <option value="EGP">Egyptian Pound (EGP)</option>
                                            <option value="USD">US Dollar ($)</option>
                                            <option value="EUR">Euro (€)</option>
                                            <option value="SAR">Saudi Riyal (SAR)</option>
                                            <option value="AED">Emirati Dirham (AED)</option>
                                        </select>
                                    </div>

                                    <div className="space-y-1 bg-black/20 p-4 rounded-xl border border-white/5">
                                        <label className="text-sm font-bold text-white block mb-2">POS Interface Language</label>
                                        <select {...register('default_language')} className="input w-full">
                                            <option value="en">English</option>
                                            <option value="ar">Arabic (عربي)</option>
                                        </select>
                                        <p className="text-xs text-textMuted mt-2">Sets the default UI language for new staff sessions.</p>
                                    </div>
                                    
                                    <div className="md:col-span-2 grid grid-cols-1 md:grid-cols-3 gap-6 mt-4">
                                        <div className="space-y-1">
                                            <label className="text-sm font-medium text-textMuted">Tax Label</label>
                                            <input {...register('tax_label')} className="input w-full" placeholder="VAT, GST, etc." />
                                        </div>
                                        <div className="space-y-1">
                                            <label className="text-sm font-medium text-textMuted">Tax Rate (%)</label>
                                            <input type="number" step="0.01" {...register('tax_rate')} className="input w-full" />
                                        </div>
                                        <div className="space-y-1">
                                            <label className="text-sm font-medium text-textMuted">Service Charge (%)</label>
                                            <input type="number" step="0.01" {...register('service_charge_rate')} className="input w-full" />
                                        </div>
                                    </div>
                                    
                                    <div className="md:col-span-2 flex items-center space-x-3 p-4 bg-primary/10 border border-primary/20 rounded-xl">
                                        <input type="checkbox" {...register('tax_inclusive')} id="tax_inc" className="w-5 h-5 rounded border-white/20 bg-black/20 text-primary focus:ring-primary" />
                                        <label htmlFor="tax_inc" className="font-medium text-white cursor-pointer select-none">
                                            Prices are Tax Inclusive
                                            <span className="block text-xs text-textMuted font-normal mt-0.5">If checked, taxes are calculated *out* of the final price rather than added on top.</span>
                                        </label>
                                    </div>
                                </div>
                            </div>
                        )}

                        {/* TAB: PRINTERS & RECEIPTS */}
                        {activeTab === 'receipt' && (
                            <div className="animate-fade-in flex flex-col xl:flex-row gap-8">
                                <div className="flex-1 space-y-6">
                                    <h2 className="text-xl font-bold text-white border-b border-white/10 pb-2">Receipt Configuration</h2>
                                    
                                    <div className="space-y-1">
                                        <label className="text-sm font-bold text-white">Printer Paper Size</label>
                                        <select {...register('receipt_printer_type')} className="input w-full">
                                            <option value="thermal80">Thermal POS Printer (80mm)</option>
                                            <option value="thermal72">Thermal POS Printer (72mm)</option>
                                            <option value="a4">Standard A4 Printer</option>
                                            <option value="a5">Standard A5 Printer</option>
                                        </select>
                                    </div>

                                    <div className="space-y-1">
                                        <label className="text-sm font-bold text-white">Receipt Language</label>
                                        <select {...register('receipt_language')} className="input w-full">
                                            <option value="en">English</option>
                                            <option value="ar">Arabic</option>
                                        </select>
                                    </div>

                                    <div className="space-y-1">
                                        <label className="text-sm font-medium text-textMuted">Header Message (Top of Receipt)</label>
                                        <textarea {...register('receipt_header_msg')} className="input w-full h-20" placeholder="Welcome to our store!" />
                                    </div>

                                    <div className="space-y-1">
                                        <label className="text-sm font-medium text-textMuted">Footer Message (Bottom of Receipt)</label>
                                        <textarea {...register('receipt_footer_msg')} className="input w-full h-20" placeholder="Thank you for your visit!" />
                                    </div>

                                    <div className="space-y-1">
                                        <label className="text-sm font-medium text-textMuted">Guest Wi-Fi Password (Optional)</label>
                                        <input {...register('wifi_password')} className="input w-full" placeholder="e.g. cafe1234" />
                                        <p className="text-xs text-textMuted">Prints credentials securely at the bottom of the receipt.</p>
                                    </div>
                                </div>

                                {/* PREVIEW PANE SIDEBAR */}
                                <div className="w-full xl:w-96 shrink-0 bg-[#0f172a] rounded-2xl border border-white/10 overflow-hidden flex flex-col">
                                    <div className="bg-black/40 p-3 border-b border-white/10 text-center text-sm font-bold text-textMuted uppercase tracking-wider">
                                        Live Receipt Preview
                                    </div>
                                    <div className="p-4 flex-1 overflow-y-auto custom-scrollbar flex justify-center bg-gray-900/50">
                                        <ReceiptPreview data={watchReceiptProps} />
                                    </div>
                                </div>
                            </div>
                        )}

                        {/* TAB: SYSTEM & BACKUP */}
                        {activeTab === 'system' && (
                            <div className="animate-fade-in space-y-8">
                                <h2 className="text-xl font-bold text-white border-b border-white/10 pb-2">System Maintenance</h2>
                                
                                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                                    {/* POS Behavior */}
                                    <div className="bg-black/20 border border-white/10 p-5 rounded-xl space-y-4">
                                        <h3 className="font-bold text-white flex items-center mb-4"><FiSettings className="mr-2"/> Checkout Flow</h3>
                                        <div className="flex items-center space-x-3">
                                            <input type="checkbox" {...register('enable_tips')} id="tips_inc" className="w-5 h-5 rounded border-white/20 bg-black/20 text-primary focus:ring-primary" />
                                            <label htmlFor="tips_inc" className="font-medium text-white cursor-pointer select-none">
                                                Enable Tip Prompts
                                            </label>
                                        </div>
                                    </div>

                                    {/* Backups */}
                                    <div className="md:col-span-2 bg-gradient-to-br from-blue-500/10 to-transparent border border-blue-500/20 p-6 rounded-xl">
                                        <h3 className="text-lg font-bold text-blue-400 flex items-center mb-2">
                                            <FiDatabase className="mr-2" /> Database Backups
                                        </h3>
                                        <p className="text-sm text-textMuted mb-6">Create full JSON snapshots of your database, or safely restore the entire system from a previous snapshot.</p>
                                        
                                        <div className="flex flex-col sm:flex-row gap-4">
                                            <button 
                                                type="button"
                                                onClick={handleDownloadBackup}
                                                disabled={isBackingUp}
                                                className="btn bg-blue-500/20 hover:bg-blue-500/30 text-blue-400 flex items-center justify-center space-x-2 border border-blue-500/30 flex-1"
                                            >
                                                {isBackingUp ? <FiLoader className="animate-spin" /> : <FiDownload />}
                                                <span>{isBackingUp ? 'Generating...' : 'Download Full Backup (.json)'}</span>
                                            </button>
                                            
                                            <div className="relative flex-1">
                                                <input 
                                                    type="file" 
                                                    accept=".json"
                                                    onChange={handleRestoreUpload}
                                                    className="absolute inset-0 w-full h-full opacity-0 cursor-pointer"
                                                />
                                                <button 
                                                    type="button"
                                                    className="w-full btn bg-red-500/10 hover:bg-red-500/20 text-red-400 flex items-center justify-center space-x-2 border border-red-500/20"
                                                >
                                                    <FiUploadCloud />
                                                    <span>Restore from Backup</span>
                                                </button>
                                            </div>
                                        </div>
                                    </div>
                                </div>
                            </div>
                        )}

                        {/* SAVE BUTTON FOR GENERAL/FINANCIAL/RECEIPT TABS */}
                        {activeTab !== 'system' && (
                            <div className="pt-6 mt-6 border-t border-white/10 flex justify-end">
                                <button type="submit" disabled={isSaving} className="btn btn-primary flex items-center space-x-2 px-8 py-3 text-lg font-bold shadow-lg shadow-primary/20">
                                    {isSaving ? <FiLoader className="animate-spin w-5 h-5" /> : <FiSave className="w-5 h-5" />}
                                    <span>{isSaving ? 'Saving...' : 'Save Configuration'}</span>
                                </button>
                            </div>
                        )}
                    </form>
                </div>
            </div>
        </div>
    );
}

import React, { useState, useEffect } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { customersApi } from '../../api/customersApi';
import useSettingsStore from '../../store/settingsStore';
import PageHeader from '../../components/PageHeader';
import { FiArrowLeft, FiPrinter, FiUser, FiClock, FiShoppingBag, FiDollarSign } from 'react-icons/fi';
import toast from 'react-hot-toast';
import { format } from 'date-fns';

const CustomerProfile = () => {
    const { id } = useParams();
    const navigate = useNavigate();
    const [customer, setCustomer] = useState(null);
    const [stats, setStats] = useState(null);
    const [isLoading, setIsLoading] = useState(true);
    const { settings } = useSettingsStore();

    useEffect(() => {
        fetchCustomerData();
    }, [id]);

    const fetchCustomerData = async () => {
        setIsLoading(true);
        try {
            const [customerRes, statsRes] = await Promise.all([
                customersApi.getCustomer(id),
                customersApi.getCustomerStats(id)
            ]);
            setCustomer(customerRes.data);
            setStats(statsRes.data);
        } catch (error) {
            toast.error('Failed to load customer profile');
        } finally {
            setIsLoading(false);
        }
    };

    const handlePrint = () => {
        window.print();
    };

    if (isLoading) {
        return (
            <div className="flex items-center justify-center min-h-[50vh]">
                <div className="w-8 h-8 border-4 border-primary border-t-transparent rounded-full animate-spin"></div>
            </div>
        );
    }

    if (!customer || !stats) {
        return <div className="text-center text-textMuted mt-10">Customer not found.</div>;
    }

    // Determine printer width class based on settings
    const printerClass = {
        'thermal80': 'print:w-[80mm]',
        'thermal72': 'print:w-[72mm]',
        'a4': 'print:w-[210mm]',
        'a5': 'print:w-[148mm]'
    }[settings?.receipt_printer_type || 'thermal80'];

    return (
        <div className={`space-y-6 print:space-y-0 print:m-0 print:p-0 ${printerClass} mx-auto`}>
            {/* Screen-only header */}
            <div className="print:hidden">
                <button 
                    onClick={() => navigate('/customers')}
                    className="flex items-center text-textMuted hover:text-white mb-4 transition-colors text-sm font-medium"
                >
                    <FiArrowLeft className="mr-2" /> Back to Customers
                </button>
                <PageHeader 
                    title={`${customer.first_name} ${customer.last_name || ''}`}
                    subtitle={`Member since ${format(new Date(customer.created_at), 'MMMM yyyy')}`}
                    icon={FiUser}
                    action={{
                        label: "Print Account Statement",
                        icon: FiPrinter,
                        onClick: handlePrint
                    }}
                />
            </div>

            {/* Print-only header */}
            <div className="hidden print:block text-center mb-6 text-black border-b border-black pb-4">
                <h1 className="text-2xl font-bold">{settings?.brand_name || 'Waitless Cafe'}</h1>
                <p className="text-sm mt-1">Customer Account Statement</p>
                <div className="mt-4 text-left">
                    <p><strong>Name:</strong> {customer.first_name} {customer.last_name}</p>
                    <p><strong>Phone:</strong> {customer.phone}</p>
                    <p><strong>Date:</strong> {format(new Date(), 'dd/MM/yyyy HH:mm')}</p>
                </div>
            </div>

            {/* KPIs Grid */}
            <div className="grid grid-cols-2 md:grid-cols-4 gap-4 print:grid-cols-2 print:gap-2">
                <div className="glass-panel p-4 print:border-black print:text-black print:bg-white print:shadow-none">
                    <div className="flex items-center justify-between mb-2">
                        <span className="text-sm font-medium text-textMuted print:text-black">Total Visits</span>
                        <FiShoppingBag className="text-primary print:text-black w-5 h-5" />
                    </div>
                    <div className="text-2xl font-bold text-white print:text-black">{stats.total_visits}</div>
                </div>
                
                <div className="glass-panel p-4 print:border-black print:text-black print:bg-white print:shadow-none">
                    <div className="flex items-center justify-between mb-2">
                        <span className="text-sm font-medium text-textMuted print:text-black">Total Spent</span>
                        <FiDollarSign className="text-accent print:text-black w-5 h-5" />
                    </div>
                    <div className="text-2xl font-bold text-white print:text-black">
                        {settings?.currency || 'EGP'} {parseFloat(stats.total_spent).toFixed(2)}
                    </div>
                </div>

                <div className="glass-panel p-4 print:border-black print:text-black print:bg-white print:shadow-none">
                    <div className="flex items-center justify-between mb-2">
                        <span className="text-sm font-medium text-textMuted print:text-black">Tab Balance</span>
                        <FiClock className="text-orange-500 print:text-black w-5 h-5" />
                    </div>
                    <div className="text-2xl font-bold text-white print:text-black">
                        {settings?.currency || 'EGP'} {parseFloat(stats.tab_balance).toFixed(2)}
                    </div>
                </div>

                <div className="glass-panel p-4 print:border-black print:text-black print:bg-white print:shadow-none">
                    <div className="flex items-center justify-between mb-2">
                        <span className="text-sm font-medium text-textMuted print:text-black">Loyalty Points</span>
                        <FiUser className="text-green-500 print:text-black w-5 h-5" />
                    </div>
                    <div className="text-2xl font-bold text-white print:text-black">
                        {parseFloat(stats.loyalty_points).toFixed(0)} pts
                    </div>
                </div>
            </div>

            {/* Last Visit / Info Block */}
            <div className="glass-panel p-6 print:border-black print:text-black print:bg-white print:shadow-none print:mt-4">
                <h3 className="text-lg font-bold text-white print:text-black mb-4 flex items-center">
                    <FiClock className="mr-2 text-primary print:text-black" /> Account Details
                </h3>
                <div className="grid grid-cols-1 sm:grid-cols-2 gap-4 text-sm">
                    <div>
                        <span className="text-textMuted print:text-gray-600 block mb-1">Last Visit Date</span>
                        <span className="font-medium text-white print:text-black">
                            {stats.last_visit ? format(new Date(stats.last_visit), 'PPP p') : 'Never'}
                        </span>
                    </div>
                    <div>
                        <span className="text-textMuted print:text-gray-600 block mb-1">Current Tier</span>
                        <span className="font-medium text-white print:text-black">
                            {customer.loyalty_account?.current_tier?.name || 'Standard'}
                        </span>
                    </div>
                    <div>
                        <span className="text-textMuted print:text-gray-600 block mb-1">Marketing Consent</span>
                        <span className="font-medium text-white print:text-black">
                            {customer.marketing_consent ? 'Opted In' : 'None'}
                        </span>
                    </div>
                    <div>
                        <span className="text-textMuted print:text-gray-600 block mb-1">Customer Notes</span>
                        <span className="font-medium text-white print:text-black">
                            {customer.preferences?.general_notes || 'No notes on file.'}
                        </span>
                    </div>
                </div>
            </div>

            {/* Recent Orders */}
            <div className="glass-panel overflow-hidden print:border-black print:shadow-none print:mt-4">
                <div className="p-6 border-b border-white/5 print:border-black bg-white/5 print:bg-white">
                    <h3 className="text-lg font-bold text-white print:text-black flex items-center">
                        <FiShoppingBag className="mr-2 text-primary print:text-black" /> Recent Transactions
                    </h3>
                </div>
                <div className="overflow-x-auto">
                    <table className="w-full text-left text-sm print:text-xs">
                        <thead>
                            <tr className="border-b border-white/10 print:border-black bg-white/5 print:bg-white text-textMuted print:text-black font-semibold">
                                <th className="p-4">Date</th>
                                <th className="p-4">Order #</th>
                                <th className="p-4">Type</th>
                                <th className="p-4 text-right">Amount</th>
                            </tr>
                        </thead>
                        <tbody className="divide-y divide-white/5 print:divide-black">
                            {stats.recent_orders?.length === 0 ? (
                                <tr><td colSpan="4" className="p-4 text-center text-textMuted print:text-black">No transactions found.</td></tr>
                            ) : (
                                stats.recent_orders?.map((order, i) => (
                                    <tr key={i} className="hover:bg-white/5 print:hover:bg-transparent">
                                        <td className="p-4 text-white print:text-black">{format(new Date(order.created_at), 'dd MMM yyyy, HH:mm')}</td>
                                        <td className="p-4 font-mono text-textMuted print:text-black">{order.order_number}</td>
                                        <td className="p-4 text-white print:text-black capitalize">{order.order_type.replace('_', ' ')}</td>
                                        <td className="p-4 text-right font-bold text-accent print:text-black">
                                            {settings?.currency || 'EGP'} {parseFloat(order.total_amount).toFixed(2)}
                                        </td>
                                    </tr>
                                ))
                            )}
                        </tbody>
                    </table>
                </div>
            </div>
            
            {/* Print Footer */}
            <div className="hidden print:block text-center mt-8 text-xs text-black border-t border-black pt-4">
                <p>{settings?.receipt_footer_msg || '*** End of Statement ***'}</p>
            </div>
        </div>
    );
};

export default CustomerProfile;

import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { customersApi } from '../../api/customersApi';
import DataTable from '../../components/DataTable';
import PageHeader from '../../components/PageHeader';
import { FiUsers, FiPlus, FiEdit, FiTrash2, FiSearch, FiFilter, FiUser } from 'react-icons/fi';
import toast from 'react-hot-toast';
import CustomerModal from './CustomerModal';

const CustomersList = () => {
    const navigate = useNavigate();
    const [customers, setCustomers] = useState([]);
    const [isLoading, setIsLoading] = useState(true);
    const [searchQuery, setSearchQuery] = useState('');
    
    // Modal State
    const [isModalOpen, setIsModalOpen] = useState(false);
    const [editingCustomer, setEditingCustomer] = useState(null);

    useEffect(() => {
        fetchCustomers();
    }, []);

    const fetchCustomers = async () => {
        setIsLoading(true);
        try {
            const response = await customersApi.getCustomers();
            setCustomers(response.data);
        } catch (error) {
            toast.error('Failed to parse customer profiles');
        } finally {
            setIsLoading(false);
        }
    };

    const handleDelete = async (id) => {
        if (!window.confirm("Are you sure you want to delete this customer?")) return;
        try {
            await customersApi.deleteCustomer(id);
            toast.success('Customer removed successfully');
            fetchCustomers();
        } catch (error) {
            toast.error('Failed to delete customer');
        }
    };

    const handleEdit = (customer) => {
        setEditingCustomer(customer);
        setIsModalOpen(true);
    };

    const handleCreateCustomer = () => {
        setEditingCustomer(null);
        setIsModalOpen(true);
    };

    const handleModalSubmit = async (data) => {
        try {
            if (editingCustomer) {
                await customersApi.updateCustomer(editingCustomer.id, data);
                toast.success('Customer profile updated');
            } else {
                await customersApi.createCustomer(data);
                toast.success('New customer registered');
            }
            setIsModalOpen(false);
            fetchCustomers();
        } catch (error) {
            let errorMsg = 'Failed to save customer';
            const data = error.response?.data;
            
            if (data) {
                if (typeof data.detail === 'string') {
                    errorMsg = data.detail;
                } else if (typeof data === 'object') {
                    // Extract first validation error (e.g. { phone: ["already exists"] })
                    const firstKey = Object.keys(data)[0];
                    if (firstKey && Array.isArray(data[firstKey])) {
                        errorMsg = `${firstKey.replace('_', ' ')}: ${data[firstKey][0]}`;
                    } else if (firstKey && typeof data[firstKey] === 'string') {
                        errorMsg = data[firstKey];
                    }
                }
            }
            toast.error(errorMsg);
            console.error(error);
        }
    };

    const columns = [
        {
            header: "Name",
            accessorFn: (row) => `${row.first_name} ${row.last_name || ''}`,
        },
        { header: "Phone", accessorKey: "phone" },
        { 
            header: "Loyalty Tier", 
            id: "loyalty_tier",
            cell: ({ row }) => (
                <div className="flex items-center gap-2">
                    {row.original.loyalty_account?.current_tier_name ? (
                        <span 
                            className="px-2.5 py-0.5 rounded-full text-xs font-semibold"
                            style={{ 
                                backgroundColor: `${row.original.loyalty_account.current_tier_color}20`,
                                color: row.original.loyalty_account.current_tier_color 
                            }}
                        >
                            {row.original.loyalty_account.current_tier_name}
                        </span>
                    ) : (
                        <span className="text-textMuted italic text-sm">None</span>
                    )}
                    <span className="text-xs text-textMuted">
                        ({parseFloat(row.original.loyalty_account?.points_balance || 0)} pts)
                    </span>
                </div>
            )
        },
        { 
            header: "Tab Balance", 
            id: "tab_balance",
            cell: ({ row }) => (
                <span className={`font-semibold ${parseFloat(row.original.tab?.balance) > 0 ? 'text-red-600' : 'text-textMuted'}`}>
                    {parseFloat(row.original.tab?.balance || 0).toFixed(2)} EGP
                </span>
            )
        },
        {
            header: "Actions",
            id: "actions",
            cell: ({ row }) => (
                <div className="flex justify-end gap-2">
                    <button 
                        onClick={() => navigate(`/customers/${row.original.id}`)}
                        className="p-1.5 text-green-600 hover:bg-green-50 rounded-lg transition-colors"
                        title="View Profile"
                    >
                        <FiUser className="w-4 h-4" />
                    </button>
                    <button 
                        onClick={() => handleEdit(row.original)}
                        className="p-1.5 text-blue-600 hover:bg-blue-50 rounded-lg transition-colors"
                        title="Edit Customer"
                    >
                        <FiEdit className="w-4 h-4" />
                    </button>
                    <button 
                        onClick={() => handleDelete(row.original.id)}
                        className="p-1.5 text-red-600 hover:bg-red-50 rounded-lg transition-colors"
                        title="Delete Customer"
                    >
                        <FiTrash2 className="w-4 h-4" />
                    </button>
                </div>
            )
        }
    ];

    const filteredCustomers = customers.filter(c => 
        c.first_name.toLowerCase().includes(searchQuery.toLowerCase()) ||
        c.phone.includes(searchQuery)
    );

    return (
        <div className="space-y-6">
            <PageHeader 
                title="Customer CRM"
                subtitle="Manage loyalty members, store credit, and preferences"
                icon={FiUsers}
                action={{
                    label: "Add Customer",
                    icon: FiPlus,
                    onClick: handleCreateCustomer
                }}
            />

            {/* Filters Area */}
            <div className="flex flex-col sm:flex-row gap-4 p-4 glass-panel mb-6">
                <div className="relative flex-1">
                    <FiSearch className="absolute left-3 top-1/2 -translate-y-1/2 text-textMuted w-5 h-5" />
                    <input 
                        type="text"
                        placeholder="Search by name or phone number..."
                        value={searchQuery}
                        onChange={(e) => setSearchQuery(e.target.value)}
                        className="w-full pl-10 pr-4 py-2 border border-slate-200 dark:border-white/10 bg-background text-textMain rounded-lg focus:outline-none focus:ring-2 focus:ring-primary/20 focus:border-primary text-sm"
                    />
                </div>
                <button className="flex items-center justify-center gap-2 px-4 py-2 text-sm font-medium text-textMain bg-slate-50 dark:bg-white/5 border border-slate-200 dark:border-white/10 rounded-lg hover:bg-slate-100 dark:hover:bg-white/10 transition-colors">
                    <FiFilter className="w-4 h-4" /> Filters
                </button>
            </div>

            <DataTable 
                columns={columns}
                data={filteredCustomers}
                isLoading={isLoading}
                emptyMessage="No customers found matching your search."
            />

            <CustomerModal 
                isOpen={isModalOpen}
                onClose={() => setIsModalOpen(false)}
                onSubmit={handleModalSubmit}
                customer={editingCustomer}
            />
        </div>
    );
};

export default CustomersList;

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { toast } from 'react-hot-toast';
import { FiUpload, FiCheck, FiX, FiCheckCircle, FiFileText, FiRefreshCw } from 'react-icons/fi';
import { financeApi } from '../../../api/financeApi';
import useAuthStore from '../../../store/authStore';
import DataTable from '../../../components/DataTable';
import PageHeader from '../../../components/PageHeader';

export default function BankReconciliation() {
    const { user } = useAuthStore();
    const canReconcile = ['super_admin', 'manager'].includes(user?.role);

    const [accounts, setAccounts] = useState([]);
    const [reconciliations, setReconciliations] = useState([]);
    const [activeAccount, setActiveAccount] = useState('');
    const [isLoading, setIsLoading] = useState(true);

    // New Recon Form
    const [isFormOpen, setIsFormOpen] = useState(false);
    const [isSubmitting, setIsSubmitting] = useState(false);
    const [formData, setFormData] = useState({
        bank_account: '',
        period_start: '',
        period_end: ''
    });

    // Active Recon View
    const [activeRecon, setActiveRecon] = useState(null);
    const fileInputRef = useRef(null);

    useEffect(() => {
        fetchInitialData();
    }, []);

    const fetchInitialData = async () => {
        setIsLoading(true);
        try {
            const accRes = await financeApi.getBankAccounts();
            setAccounts(accRes.data);
            if (accRes.data.length > 0) {
                setActiveAccount(accRes.data[0].id);
                fetchReconciliations(accRes.data[0].id);
            } else {
                setIsLoading(false);
            }
        } catch (error) {
            toast.error("Failed to fetch bank accounts");
            setIsLoading(false);
        }
    };

    const fetchReconciliations = async (accountId) => {
        setIsLoading(true);
        try {
            const res = await financeApi.getReconciliations({ bank_account: accountId });
            setReconciliations(res.data);
        } catch (error) {
            console.error(error);
        } finally {
            setIsLoading(false);
        }
    };

    const fetchSingleRecon = async (id) => {
        const tid = toast.loading("Loading reconciliation details...");
        try {
            // Note: Our ViewSet doesn't have a single retrieve endpoint specified in financeApi yet, 
            // but DRF ModelViewSet provides it by default at /api/finance/bank-reconciliations/{id}/.
            // Let's just filter it from the list or make an explicit call if we add it.
            // For now, let's assume the nested items come with the list response.
            const recon = reconciliations.find(r => r.id === id);
            if (recon) setActiveRecon(recon);
            toast.dismiss(tid);
        } catch (error) {
            toast.error("Error loading details", { id: tid });
        }
    };

    const handleAccountChange = (e) => {
        const accId = e.target.value;
        setActiveAccount(accId);
        setActiveRecon(null);
        fetchReconciliations(accId);
    };

    const handleStartRecon = async (e) => {
        e.preventDefault();
        setIsSubmitting(true);
        const tid = toast.loading("Starting reconciliation...");
        try {
            const res = await financeApi.createReconciliation(formData);
            toast.success("Period started", { id: tid });
            setIsFormOpen(false);
            setFormData({ bank_account: '', period_start: '', period_end: '' });
            fetchReconciliations(activeAccount);
            setActiveRecon(res.data);
        } catch (error) {
            toast.error("Failed to start recon", { id: tid });
        } finally {
            setIsSubmitting(false);
        }
    };

    // CSV Parse Mock implementation (In a real app, use PapaParse)
    const handleFileUpload = async (e) => {
        const file = e.target.files[0];
        if (!file || !activeRecon) return;

        // Dummy text parser replacing PapaParse for demo
        const reader = new FileReader();
        reader.onload = async (event) => {
            const text = event.target.result;
            const lines = text.split('\n').filter(line => line.trim() !== '');
            // Assume CSV: Date,Description,Amount
            const items = lines.slice(1).map(line => {
                const [date, desc, amt] = line.split(',');
                return { date: date?.trim(), description: desc?.trim(), amount: parseFloat(amt?.trim()) };
            }).filter(i => i.date && !isNaN(i.amount));

            const tid = toast.loading("Importing bank statement...");
            try {
                await financeApi.importReconciliationCSV(activeRecon.id, { items });
                toast.success(`Imported ${items.length} records`, { id: tid });
                // We'd ideally re-fetch the single recon to get updated items
                fetchReconciliations(activeAccount); // Quick refresh hack
                setActiveRecon(null); // Force close to refresh view
            } catch (error) {
                toast.error("Failed to import CSV", { id: tid });
            }
        };
        reader.readAsText(file);
    };

    const handleMatch = async (systemId, bankId) => {
        const tid = toast.loading("Matching items...");
        try {
            await financeApi.matchReconciliationItem(activeRecon.id, {
                system_item: systemId,
                bank_item: bankId
            });
            toast.success("Items matched", { id: tid });
            fetchReconciliations(activeAccount);
            setActiveRecon(null); // Force refresh
        } catch (error) {
            toast.error("Match failed", { id: tid });
        }
    };

    const handleComplete = async () => {
        const tid = toast.loading("Completing reconciliation...");
        try {
            await financeApi.completeReconciliation(activeRecon.id);
            toast.success("Reconciliation locked", { id: tid });
            fetchReconciliations(activeAccount);
            setActiveRecon(null);
        } catch (error) {
            toast.error("Failed to complete", { id: tid });
        }
    };

    const columns = useMemo(() => [
        { header: 'Period Start', accessorKey: 'period_start' },
        { header: 'Period End', accessorKey: 'period_end' },
        { 
            header: 'Status', 
            accessorKey: 'status',
            cell: info => {
                const s = info.getValue();
                return <span className={`px-2 py-1 rounded text-xs font-bold ${
                    s === 'completed' ? 'bg-green-500/20 text-green-400' : 'bg-orange-500/20 text-orange-400'
                }`}>{s.replace('_', ' ').toUpperCase()}</span>;
            }
        },
        { header: 'System Bal', accessorKey: 'system_balance', cell: info => parseFloat(info.getValue()).toFixed(2) },
        { header: 'Bank Bal', accessorKey: 'bank_balance', cell: info => parseFloat(info.getValue()).toFixed(2) },
        { 
            header: 'Difference', 
            accessorKey: 'difference', 
            cell: info => {
                const diff = parseFloat(info.getValue());
                if (diff === 0) return <span className="text-green-400">0.00</span>;
                return <span className="text-red-400 font-bold">{diff.toFixed(2)}</span>;
            } 
        },
        {
            id: 'actions',
            header: 'Actions',
            cell: info => {
                return (
                    <button 
                        onClick={() => fetchSingleRecon(info.row.original.id)}
                        className="btn bg-white/5 hover:bg-white/10 py-1 px-3 text-xs"
                    >
                        View / Edit
                    </button>
                );
            }
        }
    ], [reconciliations]);

    if (isLoading) return <div className="p-6">Loading accounts...</div>;

    return (
        <div className="p-6 space-y-6 animate-fade-in relative h-[calc(100vh-100px)] flex flex-col">
            <PageHeader 
                title="Bank Reconciliation" 
                subtitle="Match system transactions with bank statements to ensure accuracy."
                icon={FiCheckCircle}
            />

            {/* Account Selector & New Recon Button */}
            <div className="flex justify-between items-center glass-panel p-4">
                <div className="flex items-center gap-4">
                    <label className="text-sm text-textMuted font-medium">Select Account:</label>
                    <select 
                        className="input min-w-[250px] bg-black/40"
                        value={activeAccount}
                        onChange={handleAccountChange}
                    >
                        {accounts.map(acc => (
                            <option key={acc.id} value={acc.id}>{acc.name} - {acc.bank_name}</option>
                        ))}
                    </select>
                </div>
                {canReconcile && !activeRecon && (
                    <button onClick={() => { setFormData({...formData, bank_account: activeAccount}); setIsFormOpen(true); }} className="btn btn-primary flex items-center gap-2">
                        <FiCheckCircle /> Start New Period
                    </button>
                )}
                {activeRecon && (
                    <button onClick={() => setActiveRecon(null)} className="btn bg-white/5 hover:bg-white/10 text-white flex gap-2 items-center">
                        Back to List
                    </button>
                )}
            </div>

            {/* Main Area: Either List or Active Recon View */}
            {!activeRecon ? (
                <div className="flex-1 overflow-hidden flex flex-col">
                    <DataTable 
                        columns={columns} 
                        data={reconciliations} 
                        hideSearch={true}
                    />
                </div>
            ) : (
                <div className="flex-1 flex flex-col gap-6 overflow-hidden">
                    {/* Active Recon Header */}
                    <div className="glass-panel p-5 grid grid-cols-4 gap-4 items-center border-l-4 border-primary">
                        <div>
                            <p className="text-xs text-textMuted uppercase tracking-wider">Period</p>
                            <p className="font-bold text-lg text-white">{activeRecon.period_start} <span className="text-textMuted mx-1">to</span> {activeRecon.period_end}</p>
                        </div>
                        <div>
                            <p className="text-xs text-textMuted uppercase tracking-wider">Status</p>
                            <span className={`inline-block mt-1 px-2 py-1 rounded text-xs font-bold ${activeRecon.status === 'completed' ? 'bg-green-500/20 text-green-400' : 'bg-orange-500/20 text-orange-400'}`}>
                                {activeRecon.status.replace('_', ' ').toUpperCase()}
                            </span>
                        </div>
                        <div>
                            <p className="text-xs text-textMuted uppercase tracking-wider">Difference</p>
                            <p className={`font-mono font-bold text-xl ${parseFloat(activeRecon.difference) === 0 ? 'text-green-400' : 'text-red-400'}`}>
                                {parseFloat(activeRecon.difference).toFixed(2)} EGP
                            </p>
                        </div>
                        <div className="flex justify-end gap-3">
                            {activeRecon.status !== 'completed' && (
                                <>
                                    <input type="file" ref={fileInputRef} className="hidden" accept=".csv" onChange={handleFileUpload} />
                                    <button onClick={() => fileInputRef.current?.click()} className="btn bg-white/5 hover:bg-white/10 text-white flex gap-2">
                                        <FiUpload /> Import CSV
                                    </button>
                                    <button onClick={handleComplete} className="btn bg-green-500 hover:bg-green-600 text-white flex gap-2 shadow-lg shadow-green-500/20">
                                        <FiCheck /> Complete (Lock)
                                    </button>
                                </>
                            )}
                        </div>
                    </div>

                    {/* Matching Interface (Two columns) */}
                    <div className="flex-1 grid grid-cols-2 gap-6 min-h-0">
                        {/* System Items */}
                        <div className="glass-panel p-2 flex flex-col">
                            <h4 className="text-center font-bold text-textMuted bg-white/5 py-2 rounded-t-lg border-b border-white/5 flex justify-center items-center gap-2">
                                <FiFileText /> System Records
                            </h4>
                            <div className="flex-1 overflow-y-auto p-2 space-y-2">
                                {activeRecon.items?.filter(i => i.source === 'system').map(item => (
                                    <div key={item.id} className={`p-3 rounded-lg border flex justify-between items-center transition-colors ${item.status === 'matched' ? 'bg-green-500/10 border-green-500/30' : 'bg-black/20 border-white/5 hover:border-primary/50 cursor-pointer'}`}>
                                        <div>
                                            <p className="font-mono text-xs text-textMuted">{item.date}</p>
                                            <p className="text-sm font-medium text-white">{item.description}</p>
                                        </div>
                                        <div className="text-right">
                                            <p className={`font-mono font-bold ${item.status === 'matched' ? 'text-green-400' : 'text-white'}`}>{parseFloat(item.amount).toFixed(2)}</p>
                                            {item.status === 'matched' && <span className="text-[10px] text-green-400 uppercase tracking-widest flex items-center gap-1 justify-end"><FiCheck size={10} /> Matched</span>}
                                        </div>
                                    </div>
                                ))}
                                {!activeRecon.items?.filter(i => i.source === 'system').length && (
                                    <p className="text-center text-textMuted py-8 text-sm">No system records found for this period.</p>
                                )}
                            </div>
                        </div>

                        {/* Bank Items */}
                        <div className="glass-panel p-2 flex flex-col">
                            <h4 className="text-center font-bold text-textMuted bg-white/5 py-2 rounded-t-lg border-b border-white/5 flex justify-center items-center gap-2">
                                <FiUpload /> Bank Statement (CSV)
                            </h4>
                            <div className="flex-1 overflow-y-auto p-2 space-y-2">
                                {activeRecon.items?.filter(i => i.source === 'bank').map(item => (
                                    <div key={item.id} className={`p-3 rounded-lg border flex justify-between items-center transition-colors ${item.status === 'matched' ? 'bg-green-500/10 border-green-500/30' : 'bg-black/20 border-white/5 hover:border-blue-500/50 cursor-pointer'}`}>
                                        <div>
                                            <p className="font-mono text-xs text-textMuted">{item.date}</p>
                                            <p className="text-sm font-medium text-white">{item.description}</p>
                                        </div>
                                        <div className="text-right flex items-center gap-3">
                                            {item.status !== 'matched' && activeRecon.status !== 'completed' && (
                                                <button onClick={() => {
                                                    // Super simple matching logic for demo — in real app you'd select system item then bank item
                                                    const sysItem = activeRecon.items.find(si => si.source === 'system' && si.status === 'unmatched' && parseFloat(si.amount) === parseFloat(item.amount));
                                                    if (sysItem) handleMatch(sysItem.id, item.id);
                                                    else toast.error("No exact matching unmatched system amount found");
                                                }} className="text-xs bg-blue-500/20 text-blue-400 px-2 py-1 rounded hover:bg-blue-500/30 transition-colors">Auto-Match Amount</button>
                                            )}
                                            <div>
                                                <p className={`font-mono font-bold ${item.status === 'matched' ? 'text-green-400' : 'text-orange-400'}`}>{parseFloat(item.amount).toFixed(2)}</p>
                                                {item.status === 'matched' && <span className="text-[10px] text-green-400 uppercase tracking-widest flex items-center gap-1 justify-end"><FiCheck size={10} /> Matched</span>}
                                            </div>
                                        </div>
                                    </div>
                                ))}
                                {!activeRecon.items?.filter(i => i.source === 'bank').length && (
                                    <div className="text-center py-8">
                                        <p className="text-textMuted text-sm mb-4">Upload a bank statement CSV to begin matching.</p>
                                        <button onClick={() => fileInputRef.current?.click()} className="btn bg-white/5 hover:bg-white/10 text-white mx-auto inline-flex gap-2">
                                            <FiUpload /> Browse CSV
                                        </button>
                                    </div>
                                )}
                            </div>
                        </div>
                    </div>
                </div>
            )}

            {/* NEW RECON FORM MODAL */}
            {isFormOpen && (
                <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/60 backdrop-blur-sm">
                    <form onSubmit={handleStartRecon} className="bg-[#1e293b] rounded-2xl w-full max-w-sm border border-white/10 overflow-hidden shadow-2xl">
                        <div className="p-5 border-b border-white/10 flex justify-between items-center bg-[#0f172a]">
                            <h3 className="font-bold text-white text-lg">Start Reconciliation</h3>
                            <button type="button" onClick={() => setIsFormOpen(false)} className="text-textMuted hover:text-white"><FiX /></button>
                        </div>
                        <div className="p-6 space-y-4">
                            <div>
                                <label className="block text-sm font-medium text-textMuted mb-1">Period Start</label>
                                <input required type="date" className="input w-full" value={formData.period_start} onChange={e => setFormData({...formData, period_start: e.target.value})} />
                            </div>
                            <div>
                                <label className="block text-sm font-medium text-textMuted mb-1">Period End</label>
                                <input required type="date" className="input w-full" value={formData.period_end} onChange={e => setFormData({...formData, period_end: e.target.value})} />
                            </div>
                            <p className="text-xs text-yellow-500/80 bg-yellow-500/10 p-2 rounded border border-yellow-500/20">
                                This will import all system transactions for the selected account within this exact date range.
                            </p>
                        </div>
                        <div className="p-5 border-t border-white/10 bg-[#0f172a] flex justify-end gap-3">
                            <button type="button" onClick={() => setIsFormOpen(false)} className="px-4 py-2 rounded-lg text-textMuted hover:bg-white/5 transition-colors">Cancel</button>
                            <button type="submit" disabled={isSubmitting} className="px-5 py-2 rounded-lg bg-primary hover:bg-primary/90 text-white font-bold transition-colors shadow-lg shadow-primary/20">Generate Period</button>
                        </div>
                    </form>
                </div>
            )}
        </div>
    );
}

import React, { useState, useEffect } from 'react';
import { toast } from 'react-hot-toast';
import { FiPlay, FiSquare, FiDownload, FiDollarSign, FiClock, FiActivity, FiCheckCircle } from 'react-icons/fi';
import { financeApi } from '../../../api/financeApi';
import useAuthStore from '../../../store/authStore';
import DataTable from '../../../components/DataTable';
import ConfirmModal from '../../../components/ConfirmModal';
import PageHeader from '../../../components/PageHeader';

const DENOMINATIONS = [500, 200, 100, 50, 20, 10, 5, 1];

export default function CashRegister() {
    const { user } = useAuthStore();
    const [currentShift, setCurrentShift] = useState(null);
    const [isLoading, setIsLoading] = useState(true);
    
    // Forms
    const [denominationsForm, setDenominationsForm] = useState(
        DENOMINATIONS.reduce((acc, den) => ({ ...acc, [den]: 0 }), {})
    );
    const [isSubmitting, setIsSubmitting] = useState(false);
    
    // Cash Drop Modal
    const [dropOpen, setDropOpen] = useState(false);
    const [dropAmount, setDropAmount] = useState('');
    const [dropNote, setDropNote] = useState('');

    // Discrepancy Reason for Closing
    const [closingReason, setClosingReason] = useState('');

    useEffect(() => {
        fetchCurrentShift();
    }, []);

    const fetchCurrentShift = async () => {
        setIsLoading(true);
        try {
            const res = await financeApi.getCurrentShift();
            setCurrentShift(res.data);
            if (res.data) {
                fetchMovements(res.data.id);
            }
        } catch (error) {
            if (error.response?.status !== 404) {
                toast.error("Failed to load shift data.");
            } else {
                setCurrentShift(null);
            }
        } finally {
            setIsLoading(false);
        }
    };

    const [movements, setMovements] = useState([]);
    const fetchMovements = async (shiftId) => {
        try {
            const res = await financeApi.getCashMovements({ shift: shiftId });
            setMovements(res.data);
        } catch (error) {
            console.error(error);
        }
    };

    const calculateTotal = () => {
        return DENOMINATIONS.reduce((sum, den) => sum + (den * (denominationsForm[den] || 0)), 0);
    };

    const handleDenomChange = (den, val) => {
        const parsed = parseInt(val) || 0;
        setDenominationsForm(prev => ({ ...prev, [den]: Math.max(0, parsed) }));
    };

    const handleOpenShift = async () => {
        const total = calculateTotal();
        const payload = {
            branch: user?.branch || 1, // Fallback if user doesn't have strict branch
            denominations: DENOMINATIONS.map(d => ({
                denomination: d, quantity: denominationsForm[d] || 0
            })).filter(d => d.quantity > 0)
        };

        setIsSubmitting(true);
        const tid = toast.loading("Opening shift...");
        try {
            const res = await financeApi.openShift(payload);
            toast.success(`Shift opened with ${total} EGP`, { id: tid });
            setCurrentShift(res.data);
            setDenominationsForm(DENOMINATIONS.reduce((acc, den) => ({ ...acc, [den]: 0 }), {}));
        } catch (error) {
            toast.error(error.response?.data?.error || "Error opening shift", { id: tid });
        } finally {
            setIsSubmitting(false);
        }
    };

    const handleCloseShift = async () => {
        const total = calculateTotal();
        const tid = toast.loading("Closing shift...");
        try {
            const payload = {
                denominations: DENOMINATIONS.map(d => ({
                    denomination: d, quantity: denominationsForm[d] || 0
                })).filter(d => d.quantity > 0),
                discrepancy_reason: closingReason
            };
            const res = await financeApi.closeShift(currentShift.id, payload);
            toast.success("Shift closed successfully", { id: tid });
            setCurrentShift(null); // Now closed, show open screen
            setDenominationsForm(DENOMINATIONS.reduce((acc, den) => ({ ...acc, [den]: 0 }), {}));
            setClosingReason('');
            
            // Optionally, we could show the EOD summary here
            if (res.data.discrepancy !== "0.00") {
                toast(`Discrepancy recorded: ${res.data.discrepancy} EGP`, { icon: '⚠️' });
            }
        } catch (error) {
            toast.error(error.response?.data?.error || "Error closing shift", { id: tid });
        }
    };

    const handleCashDrop = async () => {
        if (!dropAmount || parseFloat(dropAmount) <= 0) return toast.error("Enter a valid amount");
        setIsSubmitting(true);
        const tid = toast.loading("Recording cash drop...");
        try {
            await financeApi.createCashDrop({
                shift: currentShift.id,
                amount: parseFloat(dropAmount),
                note: dropNote
            });
            toast.success("Cash drop recorded", { id: tid });
            setDropOpen(false);
            setDropAmount('');
            setDropNote('');
            fetchMovements(currentShift.id);
        } catch (error) {
            toast.error("Failed to record cash drop", { id: tid });
        } finally {
            setIsSubmitting(false);
        }
    };

    const formatMoney = (val) => `${parseFloat(val || 0).toFixed(2)} EGP`;

    // ─────────────────────────────────────────────
    // RENDER LOGIC
    // ─────────────────────────────────────────────

    if (isLoading) return <div className="p-6">Loading...</div>;

    // Shift is OPEN -> Render Dashboard
    if (currentShift) {
        return (
            <div className="p-6 space-y-6 animate-fade-in">
                <PageHeader 
                    title="Active Cash Register" 
                    subtitle={`Shift started at ${new Date(currentShift.opened_at).toLocaleTimeString()}`}
                    icon={FiActivity}
                />

                {/* Status Bar */}
                <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
                    <div className="glass-panel p-5 border-l-4 border-primary">
                        <p className="text-textMuted text-sm font-medium">Opening Cash</p>
                        <p className="text-2xl font-bold text-white mt-1">{formatMoney(currentShift.opening_cash)}</p>
                    </div>
                    <div className="glass-panel p-5 border-l-4 border-green-500">
                        <p className="text-textMuted text-sm font-medium">Shift Revenue</p>
                        <p className="text-2xl font-bold text-white mt-1">Live from POS</p>
                    </div>
                    <div className="glass-panel p-5 border-l-4 border-orange-500">
                        <p className="text-textMuted text-sm font-medium">Cash Drops</p>
                        <p className="text-2xl font-bold text-white mt-1">
                            {formatMoney(currentShift.total_cash_drops || movements.filter(m => m.movement_type === 'cash_drop').reduce((s, m) => s + parseFloat(m.amount), 0)*-1)}
                        </p>
                    </div>
                    <div className="glass-panel p-5 border-l-4 border-blue-500 flex flex-col justify-center gap-2">
                        <button onClick={() => setDropOpen(true)} className="btn w-full bg-orange-500/20 text-orange-400 hover:bg-orange-500/30 flex items-center justify-center gap-2 py-2">
                            <FiDownload /> <span>Safe Drop</span>
                        </button>
                    </div>
                </div>

                <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
                    {/* Live Movement Log */}
                    <div className="lg:col-span-2 glass-panel p-6">
                        <h3 className="text-lg font-bold text-white mb-4 flex items-center gap-2">
                            <FiClock className="text-primary" /> 
                            <span>Live Register Log</span>
                        </h3>
                        <div className="overflow-x-auto">
                            <table className="w-full text-sm text-left">
                                <thead className="text-xs text-textMuted uppercase bg-white/5">
                                    <tr>
                                        <th className="px-4 py-3 rounded-tl-lg">Time</th>
                                        <th className="px-4 py-3">Type</th>
                                        <th className="px-4 py-3">Amount</th>
                                        <th className="px-4 py-3">Ref</th>
                                        <th className="px-4 py-3 rounded-tr-lg">Performed By</th>
                                    </tr>
                                </thead>
                                <tbody>
                                    {movements.map((m) => (
                                        <tr key={m.id} className="border-b border-white/5 hover:bg-white/5">
                                            <td className="px-4 py-3 text-textMuted">
                                                {new Date(m.created_at).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
                                            </td>
                                            <td className="px-4 py-3">
                                                <span className={`px-2 py-1 rounded text-xs font-medium ${
                                                    m.movement_type === 'sale' ? 'bg-green-500/20 text-green-400' :
                                                    m.movement_type === 'refund' ? 'bg-red-500/20 text-red-400' :
                                                    m.movement_type === 'cash_drop' ? 'bg-orange-500/20 text-orange-400' :
                                                    'bg-white/10 text-white'
                                                }`}>
                                                    {m.movement_type.replace('_', ' ').toUpperCase()}
                                                </span>
                                            </td>
                                            <td className={`px-4 py-3 font-mono font-bold ${parseFloat(m.amount) > 0 ? 'text-green-400' : 'text-red-400'}`}>
                                                {parseFloat(m.amount) > 0 ? '+' : ''}{formatMoney(m.amount)}
                                            </td>
                                            <td className="px-4 py-3 text-xs">{m.order_number || m.description || '-'}</td>
                                            <td className="px-4 py-3">{m.performed_by_name}</td>
                                        </tr>
                                    ))}
                                    {movements.length === 0 && (
                                        <tr>
                                            <td colSpan="5" className="text-center py-6 text-textMuted">No movements yet in this shift.</td>
                                        </tr>
                                    )}
                                </tbody>
                            </table>
                        </div>
                    </div>

                    {/* Closing Form */}
                    <div className="glass-panel p-6 border border-red-500/20">
                        <h3 className="text-lg font-bold text-red-400 mb-4 flex items-center gap-2">
                            <FiSquare /> 
                            <span>Close Shift</span>
                        </h3>
                        <p className="text-xs text-textMuted mb-6">Count your drawer to close the shift. Any discrepancy will be recorded.</p>
                        
                        <div className="grid grid-cols-2 gap-3 mb-6">
                            {DENOMINATIONS.map(den => (
                                <div key={den} className="flex items-center gap-2 bg-black/20 p-2 rounded-lg border border-white/5">
                                    <span className="text-xs font-bold text-white w-12">{den} L.E</span>
                                    <span className="text-textMuted text-xs">x</span>
                                    <input 
                                        type="number" min="0" 
                                        value={denominationsForm[den] || ''} 
                                        onChange={(e) => handleDenomChange(den, e.target.value)}
                                        className="input py-1 px-2 w-full text-right font-mono box-border" 
                                    />
                                </div>
                            ))}
                        </div>

                        <div className="bg-black/30 p-4 rounded-xl mb-6">
                            <div className="flex justify-between items-center">
                                <span className="text-sm font-medium text-textMuted">Counted Cash</span>
                                <span className="text-xl font-bold text-white font-mono">{formatMoney(calculateTotal())}</span>
                            </div>
                        </div>

                        <div className="mb-6">
                            <label className="block text-xs font-medium text-textMuted mb-2">Reason for discrepancy (if any)</label>
                            <textarea 
                                value={closingReason} onChange={e => setClosingReason(e.target.value)}
                                className="input w-full min-h-[60px] text-sm" placeholder="Optional notes..."
                            />
                        </div>

                        <button 
                            onClick={handleCloseShift}
                            className="bg-red-500 hover:bg-red-600 text-white font-bold w-full py-3 rounded-xl transition-colors shadow-lg shadow-red-500/20 flex justify-center items-center gap-2"
                        >
                            <FiSquare /> <span>Close Shift</span>
                        </button>
                    </div>
                </div>

                {/* Cash Drop Modal */}
                {dropOpen && (
                    <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/60 backdrop-blur-sm">
                        <div className="bg-[#1e293b] rounded-2xl w-full max-w-sm border border-white/10 overflow-hidden shadow-2xl">
                            <div className="p-5 border-b border-white/10 flex justify-between items-center bg-[#0f172a]">
                                <h3 className="font-bold text-white text-lg flex items-center gap-2">
                                    <FiDownload className="text-orange-400" /> Safe Drop
                                </h3>
                            </div>
                            <div className="p-6 space-y-4">
                                <div>
                                    <label className="block text-sm font-medium text-textMuted mb-1">Amount to drop (EGP)</label>
                                    <input 
                                        type="number" step="0.01" value={dropAmount} onChange={e => setDropAmount(e.target.value)}
                                        className="input w-full text-lg font-mono text-orange-400" autoFocus
                                    />
                                </div>
                                <div>
                                    <label className="block text-sm font-medium text-textMuted mb-1">Description (Optional)</label>
                                    <input 
                                        type="text" value={dropNote} onChange={e => setDropNote(e.target.value)}
                                        className="input w-full" placeholder="e.g., Mid-day pickup"
                                    />
                                </div>
                            </div>
                            <div className="p-5 border-t border-white/10 bg-[#0f172a] flex justify-end gap-3">
                                <button onClick={() => setDropOpen(false)} className="px-4 py-2 rounded-lg text-textMuted hover:bg-white/5 font-medium transition-colors">Cancel</button>
                                <button onClick={handleCashDrop} disabled={isSubmitting} className="px-4 py-2 rounded-lg bg-orange-500 hover:bg-orange-600 text-white font-bold shadow-lg shadow-orange-500/20 transition-colors">Confirm Drop</button>
                            </div>
                        </div>
                    </div>
                )}

            </div>
        );
    }

    // Shift is CLOSED -> Render Opening Form
    return (
        <div className="p-6 flex justify-center items-center min-h-[calc(100vh-100px)] animate-fade-in">
            <div className="w-full max-w-lg glass-panel p-8">
                <div className="text-center mb-8">
                    <div className="w-16 h-16 bg-primary/20 text-primary rounded-full flex items-center justify-center mx-auto mb-4 border border-primary/30">
                        <FiDollarSign className="w-8 h-8" />
                    </div>
                    <h2 className="text-2xl font-black text-white">Start New Shift</h2>
                    <p className="text-textMuted mt-2">Count your drawer to set the opening cash float.</p>
                </div>

                <div className="grid grid-cols-2 gap-4 mb-8">
                    {DENOMINATIONS.map(den => (
                        <div key={den} className="flex items-center gap-3 bg-black/20 p-3 rounded-xl border border-white/5 transition-colors focus-within:border-primary/50">
                            <span className="text-sm font-bold text-white w-14">{den} L.E</span>
                            <span className="text-textMuted">x</span>
                            <input 
                                type="number" min="0" 
                                value={denominationsForm[den] || ''} 
                                onChange={(e) => handleDenomChange(den, e.target.value)}
                                className="bg-transparent border-none text-right font-mono text-lg text-primary focus:ring-0 p-0 w-full outline-none" 
                                placeholder="0"
                            />
                        </div>
                    ))}
                </div>

                <div className="bg-primary/10 border border-primary/20 rounded-2xl p-6 mb-8 text-center">
                    <p className="text-textMuted font-medium text-sm uppercase tracking-widest mb-1">Total Opening Cash</p>
                    <p className="text-4xl font-black text-white font-mono">{formatMoney(calculateTotal())}</p>
                </div>

                <button 
                    onClick={handleOpenShift}
                    disabled={isSubmitting}
                    className="w-full bg-primary hover:bg-primary/90 text-white font-black py-4 rounded-xl shadow-[0_0_20px_rgba(59,130,246,0.4)] transition-all flex justify-center items-center gap-2 text-lg disabled:opacity-50"
                >
                    <FiPlay />
                    <span>Open Shift & Start Selling</span>
                </button>
            </div>
        </div>
    );
}

import React, { useState, useEffect, useMemo } from 'react';
import { toast } from 'react-hot-toast';
import { FiPlus, FiBriefcase, FiFileText, FiSend, FiDollarSign, FiCheckCircle } from 'react-icons/fi';
import { financeApi } from '../../../api/financeApi';
import useAuthStore from '../../../store/authStore';
import DataTable from '../../../components/DataTable';
import PageHeader from '../../../components/PageHeader';

export default function CorporateInvoices() {
    const { user } = useAuthStore();
    
    const [clients, setClients] = useState([]);
    const [invoices, setInvoices] = useState([]);
    const [isLoading, setIsLoading] = useState(true);
    const [activeTab, setActiveTab] = useState('invoices'); // 'clients' or 'invoices'

    // Form states
    const [clientFormOpen, setClientFormOpen] = useState(false);
    const [invoiceFormOpen, setInvoiceFormOpen] = useState(false);
    const [paymentFormOpen, setPaymentFormOpen] = useState(false);
    const [activeInvoice, setActiveInvoice] = useState(null); // For payment or ETA
    
    // Client formData
    const [clientData, setClientData] = useState({
        company_name: '', trn: '', commercial_registration: '', 
        contact_person: '', email: '', phone: '', address: '', payment_terms_days: 30
    });

    // Invoice formData
    const [invData, setInvData] = useState({
        client: '', issue_date: new Date().toISOString().split('T')[0], 
        due_date: new Date(Date.now() + 30*24*60*60*1000).toISOString().split('T')[0], 
        vat_rate: 14, service_charge: 0, notes: '',
        line_items: [{ description: '', quantity: 1, unit_price: '' }]
    });

    // Payment formData
    const [paymentData, setPaymentData] = useState({ amount: '', payment_method: 'bank_transfer', reference: '', date: new Date().toISOString().split('T')[0] });

    useEffect(() => {
        fetchData();
    }, []);

    const fetchData = async () => {
        setIsLoading(true);
        try {
            const [clientRes, invRes] = await Promise.all([
                financeApi.getClients(),
                financeApi.getInvoices()
            ]);
            setClients(clientRes.data);
            setInvoices(invRes.data);
        } catch (error) {
            toast.error("Failed to fetch corporate data");
        } finally {
            setIsLoading(false);
        }
    };

    // ── CLIENT ACTIONS ──

    const handleSaveClient = async (e) => {
        e.preventDefault();
        const tid = toast.loading("Saving client...");
        try {
            await financeApi.createClient(clientData);
            toast.success("Client saved", { id: tid });
            setClientFormOpen(false);
            setClientData({ company_name: '', trn: '', commercial_registration: '', contact_person: '', email: '', phone: '', address: '', payment_terms_days: 30 });
            fetchData();
        } catch (error) {
            toast.error("Error saving client", { id: tid });
        }
    };

    // ── INVOICE ACTIONS ──

    const handleAddLineItem = () => {
        setInvData(prev => ({ ...prev, line_items: [...prev.line_items, { description: '', quantity: 1, unit_price: '' }] }));
    };

    const handleLineItemChange = (index, field, value) => {
        const newItems = [...invData.line_items];
        newItems[index][field] = value;
        setInvData(prev => ({ ...prev, line_items: newItems }));
    };

    const handleRemoveLineItem = (index) => {
        setInvData(prev => ({ ...prev, line_items: prev.line_items.filter((_, i) => i !== index) }));
    };

    const handleSaveInvoice = async (e) => {
        e.preventDefault();
        if (invData.line_items.some(i => !i.description || !i.unit_price)) {
            return toast.error("Please complete all line items");
        }
        
        const tid = toast.loading("Creating invoice...");
        try {
            await financeApi.createInvoice(invData);
            toast.success("Invoice created", { id: tid });
            setInvoiceFormOpen(false);
            setInvData({ client: '', issue_date: '', due_date: '', vat_rate: 14, service_charge: 0, notes: '', line_items: [{ description: '', quantity: 1, unit_price: '' }] });
            fetchData();
            setActiveTab('invoices');
        } catch (error) {
            toast.error("Error creating invoice", { id: tid });
        }
    };

    const handleRecordPayment = async (e) => {
        e.preventDefault();
        if (!activeInvoice) return;

        const tid = toast.loading("Recording payment...");
        try {
            await financeApi.recordInvoicePayment(activeInvoice.id, paymentData);
            toast.success("Payment recorded", { id: tid });
            setPaymentFormOpen(false);
            setActiveInvoice(null);
            setPaymentData({ amount: '', payment_method: 'bank_transfer', reference: '', date: new Date().toISOString().split('T')[0] });
            fetchData();
        } catch (error) {
            toast.error("Payment failed", { id: tid });
        }
    };

    const handleEtaSubmit = async (invoiceId) => {
        const tid = toast.loading("Submitting to ETA...");
        try {
            await financeApi.submitInvoiceETA(invoiceId);
            toast.success("Invoice marked as submitted to ETA", { id: tid });
            fetchData();
        } catch (error) {
            toast.error("ETA submission failed", { id: tid });
        }
    };

    const handleSendInvoice = async (invoiceId) => {
        const tid = toast.loading("Marking as sent...");
        try {
            await financeApi.sendInvoice(invoiceId); // Wait, don't have this in frontend api yet? Assume it's a PATCH or specialized endpoint. Let's patch status.
            toast.success("Invoice marked as Sent", { id: tid });
            fetchData();
        } catch (error) {
            toast.error("Action failed", { id: tid });
        }
    };


    // ── COLUMNS ──

    const clientColumns = useMemo(() => [
        { header: 'Company Name', accessorKey: 'company_name', cell: info => <span className="font-bold text-white">{info.getValue()}</span> },
        { header: 'TRN', accessorFn: row => row.trn || '-' },
        { header: 'Contact', accessorFn: row => row.contact_person || '-' },
        { header: 'Phone', accessorFn: row => row.phone || '-' },
        { header: 'Payment Terms', accessorFn: row => `${row.payment_terms_days} days` },
        { header: 'Outstanding Bal', accessorKey: 'outstanding_balance', cell: info => <span className={`font-mono font-bold ${parseFloat(info.getValue()) > 0 ? 'text-orange-400' : 'text-green-400'}`}>{parseFloat(info.getValue()).toFixed(2)}</span> }
    ], []);

    const invoiceColumns = useMemo(() => [
        { header: 'Invoice #', accessorKey: 'invoice_number', cell: info => <span className="font-mono text-sm">{info.getValue()}</span> },
        { header: 'Client', accessorKey: 'client_name', cell: info => <span className="font-bold">{info.getValue()}</span> },
        { header: 'Issue Date', accessorKey: 'issue_date' },
        { header: 'Due Date', accessorKey: 'due_date' },
        { header: 'Total', accessorKey: 'total_amount', cell: info => <span className="font-mono text-white">{parseFloat(info.getValue()).toFixed(2)}</span> },
        { header: 'Amount Due', accessorKey: 'amount_due', cell: info => {
            const due = parseFloat(info.getValue());
            return <span className={`font-mono font-bold ${due > 0 ? 'text-orange-400' : 'text-green-400'}`}>{due.toFixed(2)}</span>;
        }},
        { 
            header: 'Status', 
            accessorKey: 'status',
            cell: info => {
                const s = info.getValue();
                return <span className={`px-2 py-1 rounded text-[10px] font-bold uppercase tracking-wider ${
                    s === 'paid' ? 'bg-green-500/20 text-green-400' :
                    s === 'sent' ? 'bg-blue-500/20 text-blue-400' :
                    s === 'overdue' ? 'bg-red-500/20 text-red-400' : 'bg-white/10 text-textMuted'
                }`}>{s}</span>;
            }
        },
        { 
            header: 'ETA', 
            accessorKey: 'eta_submitted',
            cell: info => info.getValue() ? <FiCheckCircle className="text-green-500" title="Submitted to Egyptian Tax Authority" /> : <span className="text-xs text-textMuted">Pending</span>
        },
        {
            id: 'actions',
            header: '',
            cell: info => {
                const row = info.row.original;
                return (
                    <div className="flex gap-2 justify-end">
                        {row.status === 'draft' && (
                            <button onClick={() => handleSendInvoice(row.id)} className="text-blue-400 hover:text-blue-300 p-1" title="Mark Sent"><FiSend /></button>
                        )}
                        {['sent', 'overdue'].includes(row.status) && (
                            <button onClick={() => { setActiveInvoice(row); setPaymentData({...paymentData, amount: row.amount_due}); setPaymentFormOpen(true); }} className="text-green-400 hover:text-green-300 p-1" title="Record Payment"><FiDollarSign /></button>
                        )}
                        {!row.eta_submitted && (
                            <button onClick={() => handleEtaSubmit(row.id)} className="text-purple-400 hover:text-purple-300 p-1" title="Submit to ETA"><FiFileText /></button>
                        )}
                    </div>
                );
            }
        }
    ], []);


    return (
        <div className="p-6 space-y-6 animate-fade-in">
            <PageHeader 
                title="Corporate Invoicing" 
                subtitle="Manage corporate clients, issue official tax invoices, and track payments & ETA submissions."
                icon={FiBriefcase}
            />

            {/* Tabs & Actions */}
            <div className="flex flex-col md:flex-row justify-between gap-4 items-center glass-panel p-2 rounded-xl">
                <div className="flex bg-black/40 rounded-lg p-1">
                    <button 
                        onClick={() => setActiveTab('invoices')}
                        className={`px-6 py-2 rounded-md text-sm font-medium transition-colors ${activeTab === 'invoices' ? 'bg-primary text-white shadow-lg' : 'text-textMuted hover:text-white'}`}
                    >
                        Invoices
                    </button>
                    <button 
                        onClick={() => setActiveTab('clients')}
                        className={`px-6 py-2 rounded-md text-sm font-medium transition-colors ${activeTab === 'clients' ? 'bg-primary text-white shadow-lg' : 'text-textMuted hover:text-white'}`}
                    >
                        Clients
                    </button>
                </div>
                
                <div className="flex gap-3 px-2">
                    {activeTab === 'clients' ? (
                        <button onClick={() => setClientFormOpen(true)} className="btn btn-primary flex items-center gap-2"><FiPlus /> New Client</button>
                    ) : (
                        <button onClick={() => setInvoiceFormOpen(true)} className="btn btn-primary flex items-center gap-2"><FiPlus /> Create Invoice</button>
                    )}
                </div>
            </div>

            {/* Data Tables */}
            {activeTab === 'clients' ? (
                <DataTable columns={clientColumns} data={clients} isLoading={isLoading} />
            ) : (
                <DataTable columns={invoiceColumns} data={invoices} isLoading={isLoading} />
            )}

            {/* CLIENT MODAL */}
            {clientFormOpen && (
                <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/60 backdrop-blur-sm">
                    <form onSubmit={handleSaveClient} className="bg-[#1e293b] rounded-2xl w-full max-w-lg border border-white/10 overflow-hidden shadow-2xl">
                        <div className="p-5 border-b border-white/10 flex justify-between items-center bg-[#0f172a]">
                            <h3 className="font-bold text-white text-lg">Add Corporate Client</h3>
                            <button type="button" onClick={() => setClientFormOpen(false)} className="text-textMuted"><FiX /></button>
                        </div>
                        <div className="p-6 grid grid-cols-2 gap-4 max-h-[70vh] overflow-y-auto">
                            <div className="col-span-2">
                                <label className="block text-sm font-medium text-textMuted mb-1">Company Name *</label>
                                <input required type="text" className="input w-full" value={clientData.company_name} onChange={e => setClientData({...clientData, company_name: e.target.value})} />
                            </div>
                            <div>
                                <label className="block text-sm font-medium text-textMuted mb-1">TRN (Tax Reg #)</label>
                                <input type="text" className="input w-full font-mono text-sm" value={clientData.trn} onChange={e => setClientData({...clientData, trn: e.target.value})} />
                            </div>
                            <div>
                                <label className="block text-sm font-medium text-textMuted mb-1">Commercial Reg.</label>
                                <input type="text" className="input w-full font-mono text-sm" value={clientData.commercial_registration} onChange={e => setClientData({...clientData, commercial_registration: e.target.value})} />
                            </div>
                            <div>
                                <label className="block text-sm font-medium text-textMuted mb-1">Contact Person</label>
                                <input type="text" className="input w-full" value={clientData.contact_person} onChange={e => setClientData({...clientData, contact_person: e.target.value})} />
                            </div>
                            <div>
                                <label className="block text-sm font-medium text-textMuted mb-1">Phone</label>
                                <input type="text" className="input w-full" value={clientData.phone} onChange={e => setClientData({...clientData, phone: e.target.value})} />
                            </div>
                            <div className="col-span-2">
                                <label className="block text-sm font-medium text-textMuted mb-1">Email</label>
                                <input type="email" className="input w-full" value={clientData.email} onChange={e => setClientData({...clientData, email: e.target.value})} />
                            </div>
                            <div className="col-span-2">
                                <label className="block text-sm font-medium text-textMuted mb-1">Payment Terms (Days net)</label>
                                <input type="number" className="input w-full" value={clientData.payment_terms_days} onChange={e => setClientData({...clientData, payment_terms_days: parseInt(e.target.value)})} />
                            </div>
                        </div>
                        <div className="p-5 border-t border-white/10 bg-[#0f172a] flex justify-end gap-3">
                            <button type="button" onClick={() => setClientFormOpen(false)} className="px-4 py-2 rounded-lg text-textMuted">Cancel</button>
                            <button type="submit" className="px-5 py-2 rounded-lg bg-primary text-white font-bold">Save Client</button>
                        </div>
                    </form>
                </div>
            )}

            {/* INVOICE MODAL */}
            {invoiceFormOpen && (
                <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/60 backdrop-blur-sm">
                    <form onSubmit={handleSaveInvoice} className="bg-[#1e293b] rounded-2xl w-full max-w-2xl border border-white/10 overflow-hidden shadow-2xl">
                        <div className="p-5 border-b border-white/10 flex justify-between items-center bg-[#0f172a]">
                            <h3 className="font-bold text-white text-lg">Create Tax Invoice</h3>
                            <button type="button" onClick={() => setInvoiceFormOpen(false)} className="text-textMuted"><FiX /></button>
                        </div>
                        <div className="p-6 space-y-5 max-h-[70vh] overflow-y-auto">
                            <div className="grid grid-cols-2 gap-4">
                                <div className="col-span-2 md:col-span-1">
                                    <label className="block text-sm font-medium text-textMuted mb-1">Client *</label>
                                    <select required className="input w-full" value={invData.client} onChange={e => setInvData({...invData, client: e.target.value})}>
                                        <option value="">Select Client</option>
                                        {clients.map(c => <option key={c.id} value={c.id}>{c.company_name}</option>)}
                                    </select>
                                </div>
                                <div className="grid grid-cols-2 gap-2">
                                    <div>
                                        <label className="block text-sm font-medium text-textMuted mb-1">Issue Date *</label>
                                        <input required type="date" className="input w-full text-sm" value={invData.issue_date} onChange={e => setInvData({...invData, issue_date: e.target.value})} />
                                    </div>
                                    <div>
                                        <label className="block text-sm font-medium text-textMuted mb-1">Due Date *</label>
                                        <input required type="date" className="input w-full text-sm" value={invData.due_date} onChange={e => setInvData({...invData, due_date: e.target.value})} />
                                    </div>
                                </div>
                            </div>

                            {/* Line Items */}
                            <div className="bg-black/20 p-4 rounded-xl border border-white/5">
                                <h4 className="font-medium text-white mb-3 text-sm">Line Items</h4>
                                {invData.line_items.map((item, idx) => (
                                    <div key={idx} className="flex gap-2 mb-2 items-start">
                                        <div className="flex-1">
                                            <input required type="text" placeholder="Description" className="input w-full text-sm py-2" value={item.description} onChange={e => handleLineItemChange(idx, 'description', e.target.value)} />
                                        </div>
                                        <div className="w-20">
                                            <input required type="number" min="0.1" step="0.1" placeholder="Qty" className="input w-full text-sm py-2" value={item.quantity} onChange={e => handleLineItemChange(idx, 'quantity', e.target.value)} />
                                        </div>
                                        <div className="w-28">
                                            <input required type="number" min="0" step="0.01" placeholder="Unit Price" className="input w-full text-sm py-2" value={item.unit_price} onChange={e => handleLineItemChange(idx, 'unit_price', e.target.value)} />
                                        </div>
                                        <div className="w-8 pt-1">
                                            {idx > 0 && <button type="button" onClick={() => handleRemoveLineItem(idx)} className="p-1 text-red-400 hover:bg-red-500/20 rounded"><FiX /></button>}
                                        </div>
                                    </div>
                                ))}
                                <button type="button" onClick={handleAddLineItem} className="text-primary text-sm font-medium hover:underline mt-2 flex items-center gap-1"><FiPlus /> Add Item</button>
                            </div>

                            <div className="grid grid-cols-2 gap-4">
                                <div>
                                    <label className="block text-sm font-medium text-textMuted mb-1">VAT Rate (%)</label>
                                    <input type="number" className="input w-full" value={invData.vat_rate} onChange={e => setInvData({...invData, vat_rate: e.target.value})} />
                                </div>
                                <div>
                                    <label className="block text-sm font-medium text-textMuted mb-1">Service Charge (Fixed)</label>
                                    <input type="number" step="0.01" className="input w-full" value={invData.service_charge} onChange={e => setInvData({...invData, service_charge: e.target.value})} />
                                </div>
                            </div>
                        </div>
                        <div className="p-5 border-t border-white/10 bg-[#0f172a] flex justify-end gap-3">
                            <button type="button" onClick={() => setInvoiceFormOpen(false)} className="px-4 py-2 rounded-lg text-textMuted">Cancel</button>
                            <button type="submit" className="px-5 py-2 rounded-lg bg-primary text-white font-bold">Generate Invoice</button>
                        </div>
                    </form>
                </div>
            )}

            {/* PAYMENT MODAL */}
            {paymentFormOpen && activeInvoice && (
                <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/60 backdrop-blur-sm">
                    <form onSubmit={handleRecordPayment} className="bg-[#1e293b] rounded-2xl w-full max-w-sm border border-green-500/30 overflow-hidden shadow-2xl">
                        <div className="p-5 border-b border-white/10 flex items-center gap-2 bg-[#0f172a]">
                            <FiDollarSign className="text-green-400 text-xl" />
                            <h3 className="font-bold text-white text-lg">Record Payment</h3>
                        </div>
                        <div className="p-6 space-y-4">
                            <div className="bg-green-500/10 text-green-400 p-3 rounded-lg text-sm border border-green-500/20 mb-4">
                                Invoice: <strong>{activeInvoice.invoice_number}</strong><br/>
                                Amount Due: <strong>{parseFloat(activeInvoice.amount_due).toFixed(2)} EGP</strong>
                            </div>
                            
                            <div>
                                <label className="block text-sm font-medium text-textMuted mb-1">Payment Amount *</label>
                                <input required type="number" step="0.01" max={activeInvoice.amount_due} className="input w-full text-lg font-mono text-green-400" value={paymentData.amount} onChange={e => setPaymentData({...paymentData, amount: e.target.value})} />
                            </div>
                            <div>
                                <label className="block text-sm font-medium text-textMuted mb-1">Method *</label>
                                <select required className="input w-full" value={paymentData.payment_method} onChange={e => setPaymentData({...paymentData, payment_method: e.target.value})}>
                                    <option value="bank_transfer">Bank Transfer</option>
                                    <option value="cash">Cash</option>
                                    <option value="cheque">Cheque</option>
                                </select>
                            </div>
                            <div>
                                <label className="block text-sm font-medium text-textMuted mb-1">Payment Date *</label>
                                <input required type="date" className="input w-full text-sm" value={paymentData.date} onChange={e => setPaymentData({...paymentData, date: e.target.value})} />
                            </div>
                            <div>
                                <label className="block text-sm font-medium text-textMuted mb-1">Reference</label>
                                <input type="text" className="input w-full text-sm font-mono" placeholder="TR-1234..." value={paymentData.reference} onChange={e => setPaymentData({...paymentData, reference: e.target.value})} />
                            </div>
                        </div>
                        <div className="p-5 border-t border-white/10 bg-[#0f172a] flex justify-end gap-3">
                            <button type="button" onClick={() => { setPaymentFormOpen(false); setActiveInvoice(null); }} className="px-4 py-2 rounded-lg text-textMuted">Cancel</button>
                            <button type="submit" className="px-5 py-2 rounded-lg bg-green-500 text-white font-bold shadow-lg shadow-green-500/20">Save Payment</button>
                        </div>
                    </form>
                </div>
            )}
        </div>
    );
}

import React, { useState, useEffect } from 'react';
import { toast } from 'react-hot-toast';
import { FiClock, FiLock, FiAlertTriangle, FiDollarSign, FiFileText } from 'react-icons/fi';
import { financeApi } from '../../../api/financeApi';
import useAuthStore from '../../../store/authStore';
import DataTable from '../../../components/DataTable';
import PageHeader from '../../../components/PageHeader';
import ConfirmModal from '../../../components/ConfirmModal';

export default function EndOfDay() {
    const { user } = useAuthStore();
    const canLock = ['super_admin', 'manager'].includes(user?.role);

    const [reports, setReports] = useState([]);
    const [isLoading, setIsLoading] = useState(true);

    const [isGenerateOpen, setIsGenerateOpen] = useState(false);
    const [generateDate, setGenerateDate] = useState(new Date().toISOString().split('T')[0]);
    const [isSubmitting, setIsSubmitting] = useState(false);

    const [lockReportId, setLockReportId] = useState(null);

    useEffect(() => {
        fetchReports();
    }, []);

    const fetchReports = async () => {
        setIsLoading(true);
        try {
            const res = await financeApi.getEODReports();
            setReports(res.data);
        } catch (error) {
            toast.error("Failed to fetch EOD reports");
        } finally {
            setIsLoading(false);
        }
    };

    const handleGenerate = async (e) => {
        e.preventDefault();
        setIsSubmitting(true);
        const tid = toast.loading("Generating EOD Summary...");
        try {
            const res = await financeApi.generateEOD({ date: generateDate, branch: user?.branch || 1 });
            toast.success("EOD Report Generated", { id: tid });
            setIsGenerateOpen(false);
            setReports(prev => [res.data, ...prev.filter(r => r.id !== res.data.id)]);
        } catch (error) {
            toast.error(error.response?.data?.error || "Failed to generate EOD", { id: tid });
        } finally {
            setIsSubmitting(false);
        }
    };

    const handleLock = async () => {
        const tid = toast.loading("Locking day...");
        try {
            await financeApi.lockEOD(lockReportId);
            toast.success("Day Locked Successfully", { id: tid });
            setLockReportId(null);
            fetchReports();
        } catch (error) {
            toast.error(error.response?.data?.error || "Failed to lock", { id: tid });
        }
    };

    const formatMoney = (val) => `${parseFloat(val || 0).toFixed(2)}`;

    const columns = [
        { header: 'Date', accessorKey: 'date' },
        { 
            header: 'Status', 
            accessorKey: 'is_locked',
            cell: info => info.getValue() 
                ? <span className="px-2 py-1 rounded text-[10px] font-bold uppercase tracking-wider bg-green-500/20 text-green-400 flex items-center gap-1 w-max"><FiLock/> Locked</span>
                : <span className="px-2 py-1 rounded text-[10px] font-bold uppercase tracking-wider bg-orange-500/20 text-orange-400 w-max">Draft</span>
        },
        { header: 'Gross Sales', accessorKey: 'total_sales', cell: info => <span className="font-mono">{formatMoney(info.getValue())}</span> },
        { header: 'Net Cash', accessorKey: 'net_cash', cell: info => <span className="font-mono">{formatMoney(info.getValue())}</span> },
        { 
            header: 'Discrepancy', 
            accessorKey: 'total_discrepancy', 
            cell: info => {
                const val = parseFloat(info.getValue());
                return val !== 0 
                    ? <span className="font-mono font-bold text-red-400 flex items-center gap-1"><FiAlertTriangle size={12}/> {val.toFixed(2)}</span>
                    : <span className="font-mono text-green-400">0.00</span>;
            }
        },
        { header: 'Generated At', accessorFn: row => new Date(row.created_at).toLocaleString([], { dateStyle: 'short', timeStyle: 'short' }) },
        { header: 'Generated By', accessorFn: row => row.generated_by_name || '-' },
        {
            id: 'actions',
            header: '',
            cell: info => {
                const row = info.row.original;
                return (
                    <div className="flex gap-2 justify-end">
                        <button onClick={() => {
                            // Print/View details logic (placeholder)
                            const w = window.open("", "_blank");
                            w.document.write(`<html><body style="font-family:monospace; padding: 20px;">
                                <h2>EOD Report - ${row.date}</h2>
                                <p>Status: ${row.is_locked ? 'LOCKED' : 'DRAFT'}</p>
                                <hr/>
                                <p>Total Sales: ${row.total_sales}</p>
                                <p>Total Refunds: ${row.total_refunds}</p>
                                <p>Total Cash Items: ${row.total_cash}</p>
                                <p>Total Card Items: ${row.total_card}</p>
                                <p>Net Cash (In System): ${row.net_cash}</p>
                                <hr/>
                                <p>Reported Discrepancy: ${row.total_discrepancy}</p>
                            </body></html>`);
                        }} className="text-blue-400 hover:text-blue-300 p-1" title="View Details">
                            <FiFileText />
                        </button>
                        
                        {!row.is_locked && canLock && (
                            <button onClick={() => setLockReportId(row.id)} className="text-orange-400 hover:text-orange-300 p-1" title="Lock Day">
                                <FiLock />
                            </button>
                        )}
                    </div>
                );
            }
        }
    ];

    return (
        <div className="p-6 space-y-6 animate-fade-in">
            <PageHeader 
                title="End of Day (EOD) Operations" 
                subtitle="Review daily summaries, verify discrepancies, and lock the financial day."
                icon={FiClock}
                action={
                    <button onClick={() => setIsGenerateOpen(true)} className="btn btn-primary flex items-center gap-2">
                        <FiClock /> Generate Summary
                    </button>
                }
            />

            <DataTable 
                columns={columns} 
                data={reports} 
                isLoading={isLoading} 
                hideSearch={true}
            />

            {/* GENERATE MODAL */}
            {isGenerateOpen && (
                <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/60 backdrop-blur-sm">
                    <form onSubmit={handleGenerate} className="bg-[#1e293b] rounded-2xl w-full max-w-sm border border-white/10 overflow-hidden shadow-2xl">
                        <div className="p-5 border-b border-white/10 flex justify-between items-center bg-[#0f172a]">
                            <h3 className="font-bold text-white text-lg">Generate EOD Summary</h3>
                            <button type="button" onClick={() => setIsGenerateOpen(false)} className="text-textMuted hover:text-white">✕</button>
                        </div>
                        <div className="p-6 space-y-4">
                            <p className="text-sm text-textMuted">This will aggregate all shifts, sales, and movements for the selected date into a single reviewable report.</p>
                            <div>
                                <label className="block text-sm font-medium text-textMuted mb-1">Target Date</label>
                                <input required type="date" className="input w-full" value={generateDate} onChange={e => setGenerateDate(e.target.value)} />
                            </div>
                        </div>
                        <div className="p-5 border-t border-white/10 bg-[#0f172a] flex justify-end gap-3">
                            <button type="button" onClick={() => setIsGenerateOpen(false)} className="px-4 py-2 rounded-lg text-textMuted hover:bg-white/5 transition-colors">Cancel</button>
                            <button type="submit" disabled={isSubmitting} className="px-5 py-2 rounded-lg bg-primary hover:bg-primary/90 text-white font-bold transition-colors shadow-lg shadow-primary/20">Generate</button>
                        </div>
                    </form>
                </div>
            )}

            {/* LOCK CONFIRMATION MODAL */}
            <ConfirmModal 
                isOpen={!!lockReportId}
                onClose={() => setLockReportId(null)}
                onConfirm={handleLock}
                title="Lock Trading Day?"
                message="Are you sure you want to lock this day? Once locked, no further sales, refunds, or expenses can be recorded for this date. This action cannot be undone."
                confirmText="Yes, Lock Day"
                confirmColor="bg-red-500 hover:bg-red-600"
            />
        </div>
    );
}

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { toast } from 'react-hot-toast';
import { FiPlus, FiCheck, FiX, FiPaperclip, FiTrendingUp } from 'react-icons/fi';
import { financeApi } from '../../../api/financeApi';
import useAuthStore from '../../../store/authStore';
import DataTable from '../../../components/DataTable';
import ConfirmModal from '../../../components/ConfirmModal';
import PageHeader from '../../../components/PageHeader';

export default function Expenses() {
    const { user } = useAuthStore();
    const canApprove = ['super_admin', 'manager'].includes(user?.role);

    const [expenses, setExpenses] = useState([]);
    const [categories, setCategories] = useState([]);
    const [summary, setSummary] = useState([]);
    const [isLoading, setIsLoading] = useState(true);

    // Form
    const [isFormOpen, setIsFormOpen] = useState(false);
    const [isSubmitting, setIsSubmitting] = useState(false);
    const [formData, setFormData] = useState({
        category: '',
        amount: '',
        vat_amount: '0',
        vendor: '',
        description: '',
        date: new Date().toISOString().split('T')[0],
        payment_method: 'cash',
        receipt_base64: ''
    });

    const fileInputRef = useRef(null);

    // Filters
    const [filters, setFilters] = useState({
        category: '',
        status: '',
        date_from: '',
        date_to: ''
    });

    useEffect(() => {
        fetchData();
    }, [filters]);

    const fetchData = async () => {
        setIsLoading(true);
        try {
            const [expRes, catRes, sumRes] = await Promise.all([
                financeApi.getExpenses(filters),
                financeApi.getExpenseCategories(),
                financeApi.getExpenseSummary()
            ]);
            setExpenses(expRes.data);
            setCategories(catRes.data);
            setSummary(sumRes.data);
        } catch (error) {
            toast.error("Failed to fetch expenses");
        } finally {
            setIsLoading(false);
        }
    };

    const handleFileChange = (e) => {
        const file = e.target.files[0];
        if (!file) return;
        const reader = new FileReader();
        reader.onloadend = () => setFormData(prev => ({ ...prev, receipt_base64: reader.result }));
        reader.readAsDataURL(file);
    };

    const handleSubmit = async (e) => {
        e.preventDefault();
        if (!formData.category || !formData.amount) return toast.error("Category and Amount are required");

        setIsSubmitting(true);
        const tid = toast.loading("Saving expense...");
        try {
            // Managers auto-approve their own inputs based on backend logic, or we just submit
            await financeApi.createExpense({
                ...formData,
                amount: parseFloat(formData.amount),
                vat_amount: parseFloat(formData.vat_amount || 0)
            });
            toast.success("Expense recorded successfully", { id: tid });
            setIsFormOpen(false);
            setFormData({
                category: '', amount: '', vat_amount: '0', vendor: '', description: '', 
                date: new Date().toISOString().split('T')[0], payment_method: 'cash', receipt_base64: ''
            });
            fetchData();
        } catch (error) {
            toast.error("Failed to save expense", { id: tid });
        } finally {
            setIsSubmitting(false);
        }
    };

    const handleApprove = async (id) => {
        const tid = toast.loading("Approving...");
        try {
            await financeApi.approveExpense(id);
            toast.success("Approved", { id: tid });
            fetchData();
        } catch (error) {
            toast.error("Error approving", { id: tid });
        }
    };

    const handleReject = async (id) => {
        const tid = toast.loading("Rejecting...");
        try {
            await financeApi.rejectExpense(id);
            toast.success("Rejected", { id: tid });
            fetchData();
        } catch (error) {
            toast.error("Error rejecting", { id: tid });
        }
    };

    const columns = useMemo(() => [
        { header: 'Date', accessorKey: 'date' },
        { header: 'Category', accessorFn: row => row.category_name },
        { header: 'Vendor', accessorFn: row => row.vendor || '-' },
        { header: 'Amount', accessorKey: 'amount', cell: info => <span className="font-mono font-bold text-white">{parseFloat(info.getValue()).toFixed(2)} EGP</span> },
        { header: 'Payment Method', accessorFn: row => row.payment_method.replace('_', ' ').toUpperCase(), cell: info => <span className="text-xs">{info.getValue()}</span> },
        { 
            header: 'Status', 
            accessorKey: 'status',
            cell: info => {
                const s = info.getValue();
                return <span className={`px-2 py-1 rounded text-xs font-bold ${
                    s === 'approved' ? 'bg-green-500/20 text-green-400' :
                    s === 'pending' ? 'bg-orange-500/20 text-orange-400' : 'bg-red-500/20 text-red-400'
                }`}>{s.toUpperCase()}</span>;
            }
        },
        { header: 'Created By', accessorFn: row => row.created_by_name || '-' },
        {
            id: 'actions',
            header: '',
            cell: info => {
                const row = info.row.original;
                return (
                    <div className="flex gap-2 justify-end">
                        {row.receipt_base64 && (
                            <button onClick={() => {
                                const w = window.open("");
                                w.document.write(`<img src="${row.receipt_base64}" />`);
                            }} className="text-textMuted hover:text-white" title="View Receipt">
                                <FiPaperclip className="w-4 h-4" />
                            </button>
                        )}
                        {row.status === 'pending' && canApprove && (
                            <>
                                <button onClick={() => handleApprove(row.id)} className="text-green-400 hover:text-green-300 bg-green-400/10 p-1.5 rounded" title="Approve">
                                    <FiCheck className="w-4 h-4" />
                                </button>
                                <button onClick={() => handleReject(row.id)} className="text-red-400 hover:text-red-300 bg-red-400/10 p-1.5 rounded" title="Reject">
                                    <FiX className="w-4 h-4" />
                                </button>
                            </>
                        )}
                    </div>
                );
            }
        }
    ], [canApprove]);

    return (
        <div className="p-6 space-y-6 animate-fade-in">
            <PageHeader 
                title="Expenses" 
                subtitle="Track operational costs, upload receipts, and manage budgets."
                icon={FiTrendingUp}
                action={
                    <button onClick={() => setIsFormOpen(true)} className="btn btn-primary flex items-center gap-2">
                        <FiPlus /> Record Expense
                    </button>
                }
            />

            {/* Budget Summary Progress Bars */}
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                {summary.map(cat => {
                    const pct = cat.budget > 0 ? Math.min(100, (cat.actual / cat.budget) * 100) : 0;
                    const isOver = cat.budget > 0 && cat.actual > cat.budget;
                    return (
                        <div key={cat.id} className="glass-panel p-4">
                            <div className="flex justify-between items-end mb-2">
                                <div>
                                    <h4 className="font-bold text-white">{cat.name}</h4>
                                    <p className="text-xs text-textMuted mt-0.5">Budget: {cat.budget > 0 ? `${cat.budget} EGP` : 'Not Set'}</p>
                                </div>
                                <div className="text-right">
                                    <span className={`font-mono text-lg font-bold ${isOver ? 'text-red-400' : 'text-primary'}`}>
                                        {cat.actual.toFixed(2)} EGP
                                    </span>
                                </div>
                            </div>
                            {cat.budget > 0 && (
                                <div className="w-full bg-white/5 rounded-full h-2">
                                    <div 
                                        className={`h-2 rounded-full ${isOver ? 'bg-red-500 shadow-[0_0_10px_rgba(239,68,68,0.5)]' : 'bg-primary shadow-[0_0_10px_rgba(59,130,246,0.5)]'}`}
                                        style={{ width: `${pct}%` }}
                                    ></div>
                                </div>
                            )}
                        </div>
                    );
                })}
            </div>

            <DataTable 
                columns={columns} 
                data={expenses} 
                isLoading={isLoading}
                hideSearch={true}
                extraFilters={
                    <div className="flex gap-3">
                        <select className="input text-sm p-2 w-40" value={filters.category} onChange={e => setFilters(p => ({ ...p, category: e.target.value }))}>
                            <option value="">All Categories</option>
                            {categories.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}
                        </select>
                        <select className="input text-sm p-2 w-32" value={filters.status} onChange={e => setFilters(p => ({ ...p, status: e.target.value }))}>
                            <option value="">All Statuses</option>
                            <option value="pending">Pending</option>
                            <option value="approved">Approved</option>
                            <option value="rejected">Rejected</option>
                        </select>
                    </div>
                }
            />

            {/* EXPENSE FORM MODAL */}
            {isFormOpen && (
                <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/60 backdrop-blur-sm">
                    <form onSubmit={handleSubmit} className="bg-[#1e293b] rounded-2xl w-full max-w-lg border border-white/10 overflow-hidden shadow-2xl">
                        <div className="p-5 border-b border-white/10 flex justify-between items-center bg-[#0f172a]">
                            <h3 className="font-bold text-white text-lg">Record Expense</h3>
                            <button type="button" onClick={() => setIsFormOpen(false)} className="text-textMuted hover:text-white"><FiX /></button>
                        </div>
                        <div className="p-6 space-y-4 max-h-[70vh] overflow-y-auto">
                            <div className="grid grid-cols-2 gap-4">
                                <div>
                                    <label className="block text-sm font-medium text-textMuted mb-1">Category *</label>
                                    <select required className="input w-full" value={formData.category} onChange={e => setFormData({...formData, category: e.target.value})}>
                                        <option value="">Select Category</option>
                                        {categories.filter(c => c.is_active).map(c => <option key={c.id} value={c.id}>{c.name}</option>)}
                                    </select>
                                </div>
                                <div>
                                    <label className="block text-sm font-medium text-textMuted mb-1">Date *</label>
                                    <input type="date" required className="input w-full" value={formData.date} onChange={e => setFormData({...formData, date: e.target.value})} />
                                </div>
                            </div>
                            
                            <div className="grid grid-cols-2 gap-4">
                                <div>
                                    <label className="block text-sm font-medium text-textMuted mb-1">Total Amount (EGP) *</label>
                                    <input type="number" step="0.01" required className="input w-full font-mono text-primary" value={formData.amount} onChange={e => setFormData({...formData, amount: e.target.value})} />
                                </div>
                                <div>
                                    <label className="block text-sm font-medium text-textMuted mb-1">VAT Included (EGP)</label>
                                    <input type="number" step="0.01" className="input w-full font-mono" value={formData.vat_amount} onChange={e => setFormData({...formData, vat_amount: e.target.value})} />
                                </div>
                            </div>

                            <div className="grid grid-cols-2 gap-4">
                                <div>
                                    <label className="block text-sm font-medium text-textMuted mb-1">Vendor / Payee</label>
                                    <input type="text" className="input w-full" value={formData.vendor} onChange={e => setFormData({...formData, vendor: e.target.value})} />
                                </div>
                                <div>
                                    <label className="block text-sm font-medium text-textMuted mb-1">Payment Method</label>
                                    <select className="input w-full" value={formData.payment_method} onChange={e => setFormData({...formData, payment_method: e.target.value})}>
                                        <option value="cash">Cash</option>
                                        <option value="card">Card</option>
                                        <option value="bank_transfer">Bank Transfer</option>
                                        <option value="petty_cash">Petty Cash</option>
                                    </select>
                                </div>
                            </div>

                            <div>
                                <label className="block text-sm font-medium text-textMuted mb-1">Description</label>
                                <textarea className="input w-full min-h-[60px]" value={formData.description} onChange={e => setFormData({...formData, description: e.target.value})} />
                            </div>

                            <div>
                                <label className="block text-sm font-medium text-textMuted mb-1">Receipt Image</label>
                                <input 
                                    type="file" accept="image/*" ref={fileInputRef} onChange={handleFileChange}
                                    className="block w-full text-sm text-textMuted file:mr-4 file:py-2 file:px-4 file:rounded-full file:border-0 file:text-sm file:font-semibold file:bg-primary/20 file:text-primary hover:file:bg-primary/30 transition-colors cursor-pointer"
                                />
                                {formData.receipt_base64 && <img src={formData.receipt_base64} alt="Receipt preview" className="mt-2 h-20 rounded-lg border border-white/10" />}
                            </div>
                        </div>
                        <div className="p-5 border-t border-white/10 bg-[#0f172a] flex justify-end gap-3">
                            <button type="button" onClick={() => setIsFormOpen(false)} className="px-4 py-2 rounded-lg text-textMuted hover:bg-white/5 transition-colors">Cancel</button>
                            <button type="submit" disabled={isSubmitting} className="px-5 py-2 rounded-lg bg-primary hover:bg-primary/90 text-white font-bold transition-colors shadow-lg shadow-primary/20">Record Expense</button>
                        </div>
                    </form>
                </div>
            )}
        </div>
    );
}

import React, { useState, useEffect } from 'react';
import { toast } from 'react-hot-toast';
import { FiPieChart, FiBarChart2, FiTrendingUp, FiBriefcase, FiDollarSign } from 'react-icons/fi';
import { 
    BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip as RechartsTooltip, ResponsiveContainer,
    PieChart, Pie, Cell, LineChart, Line, Legend
} from 'recharts';
import { financeApi } from '../../../api/financeApi';
import PageHeader from '../../../components/PageHeader';

const COLORS = ['#3b82f6', '#10b981', '#f59e0b', '#ef4444', '#8b5cf6', '#ec4899', '#14b8a6', '#f97316'];

export default function FinancialReports() {
    const [activeTab, setActiveTab] = useState('pnl');
    const [dateRange, setDateRange] = useState({ date_from: '', date_to: '' });
    const [reportData, setReportData] = useState(null);
    const [isLoading, setIsLoading] = useState(false);

    const TABS = [
        { id: 'pnl', label: 'Profit & Loss (P&L)', icon: <FiDollarSign /> },
        { id: 'cashflow', label: 'Cash Flow', icon: <FiTrendingUp /> },
        { id: 'tax', label: 'Tax Summary', icon: <FiBriefcase /> },
        { id: 'sales_analysis', label: 'Sales Analysis', icon: <FiPieChart /> },
        { id: 'expense_analysis', label: 'Expense Analysis', icon: <FiBarChart2 /> },
    ];

    useEffect(() => {
        fetchReport();
    }, [activeTab, dateRange]);

    const fetchReport = async () => {
        setIsLoading(true);
        try {
            const res = await financeApi.getFinancialReport({ type: activeTab, ...dateRange });
            setReportData(res.data);
        } catch (error) {
            toast.error("Failed to load report data");
            setReportData(null);
        } finally {
            setIsLoading(false);
        }
    };

    const formatMoney = (val) => `${parseFloat(val || 0).toFixed(2)} EGP`;

    // ──────────────────────────────────────────────
    // 1) PROFIT & LOSS (PNL)
    // ──────────────────────────────────────────────
    const renderPnL = () => {
        if (!reportData) return null;
        return (
            <div className="space-y-6 animate-fade-in">
                <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                    <div className="glass-panel p-6 border-l-4 border-green-500">
                        <p className="text-textMuted uppercase tracking-wider text-sm">Gross Sales</p>
                        <p className="text-3xl font-black text-white mt-2">{formatMoney(reportData.gross_sales)}</p>
                    </div>
                    <div className="glass-panel p-6 border-l-4 border-red-500">
                        <p className="text-textMuted uppercase tracking-wider text-sm">Discounts & Refunds</p>
                        <p className="text-3xl font-black text-red-400 mt-2">-{formatMoney(reportData.discounts + reportData.refunds)}</p>
                    </div>
                    <div className="glass-panel p-6 border-l-4 border-primary bg-primary/5 shadow-[0_0_30px_rgba(59,130,246,0.1)]">
                        <p className="text-primary font-bold uppercase tracking-wider text-sm">Net Revenue</p>
                        <p className="text-4xl font-black text-white mt-2">{formatMoney(reportData.net_revenue)}</p>
                    </div>
                </div>

                <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
                    <div className="glass-panel p-6">
                        <h3 className="font-bold text-lg mb-4 text-white">Operating Expenses</h3>
                        <div className="space-y-4">
                            {reportData.expenses_by_category.map((exp, idx) => (
                                <div key={idx} className="flex justify-between items-center border-b border-white/5 pb-2">
                                    <span className="text-textMuted">{exp.category__name}</span>
                                    <span className="font-mono font-bold text-white">{formatMoney(exp.total)}</span>
                                </div>
                            ))}
                            <div className="flex justify-between items-center pt-2 mt-4 border-t border-white/10">
                                <span className="text-red-400 font-bold uppercase">Total Expenses</span>
                                <span className="font-mono font-black text-red-400 text-xl">{formatMoney(reportData.total_expenses)}</span>
                            </div>
                        </div>
                    </div>
                    <div className="glass-panel p-6 flex flex-col justify-center items-center text-center">
                        <h3 className="text-textMuted uppercase tracking-widest font-bold mb-4">Operating Profit</h3>
                        <div className={`text-6xl font-black font-mono drop-shadow-2xl ${reportData.operating_profit >= 0 ? 'text-green-400' : 'text-red-500'}`}>
                            {reportData.operating_profit > 0 ? '+' : ''}{formatMoney(reportData.operating_profit)}
                        </div>
                        <p className="text-sm text-textMuted mt-6 w-3/4 mx-auto">Net Revenue minus Operating Expenses before taxes or interest.</p>
                    </div>
                </div>
            </div>
        );
    };

    // ──────────────────────────────────────────────
    // 2) CASH FLOW
    // ──────────────────────────────────────────────
    const renderCashFlow = () => {
        if (!reportData) return null;
        return (
            <div className="space-y-6 animate-fade-in">
                <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                    <div className="glass-panel p-6">
                        <p className="text-textMuted">Total Cash In</p>
                        <p className="text-2xl font-bold text-green-400 mt-1">{formatMoney(reportData.total_cash_in)}</p>
                    </div>
                    <div className="glass-panel p-6">
                        <p className="text-textMuted">Total Cash Out</p>
                        <p className="text-2xl font-bold text-red-400 mt-1">{formatMoney(reportData.total_cash_out)}</p>
                    </div>
                    <div className="glass-panel p-6 bg-white/5">
                        <p className="text-textMuted">Net Cash Flow</p>
                        <p className={`text-3xl font-bold mt-1 ${reportData.net_cash >= 0 ? 'text-green-500' : 'text-red-500'}`}>
                            {formatMoney(reportData.net_cash)}
                        </p>
                    </div>
                </div>

                <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
                    <div className="glass-panel p-6 h-[400px]">
                        <h3 className="font-bold text-white mb-6">Cash In by Method</h3>
                        <ResponsiveContainer width="100%" height="100%">
                            <PieChart>
                                <Pie
                                    data={reportData.cash_in_by_method} cx="50%" cy="45%" innerRadius={80} outerRadius={110}
                                    paddingAngle={5} dataKey="total" nameKey="payment_method"
                                >
                                    {reportData.cash_in_by_method.map((entry, index) => (
                                        <Cell key={`cell-${index}`} fill={COLORS[index % COLORS.length]} />
                                    ))}
                                </Pie>
                                <RechartsTooltip formatter={(value) => `${parseFloat(value).toFixed(2)} EGP`} contentStyle={{ backgroundColor: '#1e293b', borderColor: '#334155', color: '#fff' }} itemStyle={{ color: '#fff' }} />
                                <Legend />
                            </PieChart>
                        </ResponsiveContainer>
                    </div>
                    <div className="glass-panel p-6 h-[400px]">
                        <h3 className="font-bold text-white mb-6">Daily In/Out Trend</h3>
                        <ResponsiveContainer width="100%" height="100%">
                            <LineChart margin={{ top: 5, right: 20, bottom: 5, left: 0 }}>
                                <CartesianGrid strokeDasharray="3 3" stroke="#334155" vertical={false} />
                                <XAxis dataKey="day" stroke="#94a3b8" fontSize={12} allowDuplicatedCategory={false} />
                                <YAxis stroke="#94a3b8" fontSize={12} tickFormatter={(v) => `${v/1000}k`} />
                                <RechartsTooltip formatter={(value) => `${parseFloat(value).toFixed(2)} EGP`} contentStyle={{ backgroundColor: '#1e293b', borderColor: '#334155', color: '#fff' }} />
                                <Legend />
                                <Line data={reportData.daily_in} type="monotone" dataKey="total" name="Cash In" stroke="#10b981" strokeWidth={3} dot={false} />
                                <Line data={reportData.daily_out} type="monotone" dataKey="total" name="Cash Out" stroke="#ef4444" strokeWidth={3} dot={false} />
                            </LineChart>
                        </ResponsiveContainer>
                    </div>
                </div>
            </div>
        );
    };

    // ──────────────────────────────────────────────
    // 3) TAX SUMMARY
    // ──────────────────────────────────────────────
    const renderTax = () => {
        if (!reportData) return null;
        return (
            <div className="animate-fade-in max-w-2xl mx-auto">
                <div className="glass-panel p-8 text-center bg-blue-500/5 border-blue-500/20">
                    <FiBriefcase className="w-16 h-16 text-blue-500 mx-auto mb-6 opacity-80" />
                    <h2 className="text-2xl font-bold text-white mb-2">Total Liability Collected</h2>
                    <p className="text-6xl font-black font-mono text-white tracking-tighter drop-shadow-lg my-6">
                        {formatMoney(reportData.total_tax_liability)}
                    </p>
                    
                    <div className="grid grid-cols-2 gap-4 mt-8 pt-8 border-t border-white/10">
                        <div>
                            <p className="text-textMuted uppercase text-xs font-bold tracking-widest">VAT (Value Added Tax)</p>
                            <p className="text-2xl font-bold text-blue-400 mt-2">{formatMoney(reportData.vat_collected)}</p>
                        </div>
                        <div>
                            <p className="text-textMuted uppercase text-xs font-bold tracking-widest">Service Charge</p>
                            <p className="text-2xl font-bold text-indigo-400 mt-2">{formatMoney(reportData.service_charge_collected)}</p>
                        </div>
                    </div>
                </div>
            </div>
        );
    };

    // ──────────────────────────────────────────────
    // 4) SALES ANALYSIS
    // ──────────────────────────────────────────────
    const renderSales = () => {
        if (!reportData) return null;
        return (
            <div className="space-y-6 animate-fade-in">
                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                    <div className="glass-panel p-6 h-[400px]">
                        <h3 className="font-bold text-white mb-6">Revenue by Category</h3>
                        <ResponsiveContainer width="100%" height="100%">
                            <BarChart data={reportData.by_category} layout="vertical" margin={{ top: 5, right: 30, left: 20, bottom: 5 }}>
                                <CartesianGrid strokeDasharray="3 3" stroke="#334155" horizontal={false} />
                                <XAxis type="number" stroke="#94a3b8" fontSize={12} />
                                <YAxis dataKey="product__category__name" type="category" stroke="#94a3b8" fontSize={12} width={100} />
                                <RechartsTooltip cursor={{fill: 'rgba(255,255,255,0.05)'}} formatter={(value) => `${parseFloat(value).toFixed(2)} EGP`} contentStyle={{ backgroundColor: '#1e293b', borderColor: '#334155', color: '#fff' }} />
                                <Bar dataKey="revenue" fill="#3b82f6" radius={[0, 4, 4, 0]} barSize={20} />
                            </BarChart>
                        </ResponsiveContainer>
                    </div>

                    <div className="glass-panel p-6">
                        <h3 className="font-bold text-white mb-4">Top 10 Selling Items</h3>
                        <div className="space-y-3">
                            {reportData.top_items.map((item, idx) => (
                                <div key={idx} className="flex justify-between items-center bg-black/20 p-3 rounded-lg border border-white/5">
                                    <div className="flex items-center gap-3">
                                        <div className="w-8 h-8 rounded bg-white/10 flex items-center justify-center font-bold text-xs text-textMuted">{idx+1}</div>
                                        <div>
                                            <p className="font-bold text-white text-sm">{item.product__name}</p>
                                            <p className="text-xs text-textMuted">{item.qty} units sold</p>
                                        </div>
                                    </div>
                                    <span className="font-mono font-bold text-green-400">{formatMoney(item.revenue)}</span>
                                </div>
                            ))}
                        </div>
                    </div>
                </div>

                <div className="glass-panel p-6 flex justify-around">
                    <div className="text-center">
                        <p className="text-textMuted uppercase text-xs tracking-widest mb-1">Total Orders</p>
                        <p className="text-3xl font-black text-white">{reportData.total_orders}</p>
                    </div>
                    <div className="text-center">
                        <p className="text-textMuted uppercase text-xs tracking-widest mb-1">Average Ticket Size</p>
                        <p className="text-3xl font-black text-primary">{formatMoney(reportData.average_ticket)}</p>
                    </div>
                </div>
            </div>
        );
    };

    // ──────────────────────────────────────────────
    // 5) EXPENSE ANALYSIS
    // ──────────────────────────────────────────────
    const renderExpenses = () => {
        if (!reportData) return null;
        return (
            <div className="space-y-6 animate-fade-in">
                <div className="glass-panel p-6">
                    <h3 className="font-bold text-white mb-6">Current Month: Budget vs Actual</h3>
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-6 mt-4">
                        {reportData.budget_vs_actual.map((cat, idx) => {
                            const pct = cat.budget > 0 ? (cat.actual / cat.budget) * 100 : 0;
                            const isOver = cat.budget > 0 && cat.actual > cat.budget;
                            return (
                                <div key={idx} className="bg-black/20 p-4 rounded-xl border border-white/5">
                                    <div className="flex justify-between items-end mb-2">
                                        <p className="font-bold text-white">{cat.category}</p>
                                        <p className="font-mono text-sm text-textMuted">
                                            <span className={isOver ? 'text-red-400 font-bold' : 'text-white'}>{cat.actual.toFixed(2)}</span> / {cat.budget > 0 ? cat.budget.toFixed(2) : '-'}
                                        </p>
                                    </div>
                                    {cat.budget > 0 && (
                                        <div className="w-full bg-white/10 rounded-full h-1.5 mt-2">
                                            <div 
                                                className={`h-1.5 rounded-full ${isOver ? 'bg-red-500' : 'bg-primary'}`}
                                                style={{ width: `${Math.min(100, pct)}%` }}
                                            ></div>
                                        </div>
                                    )}
                                </div>
                            );
                        })}
                    </div>
                </div>

                <div className="glass-panel p-6 h-[400px]">
                    <h3 className="font-bold text-white mb-6">Expense Trend (Monthly)</h3>
                    <ResponsiveContainer width="100%" height="100%">
                        <BarChart data={reportData.monthly_trend} margin={{ top: 5, right: 20, bottom: 5, left: 0 }}>
                            <CartesianGrid strokeDasharray="3 3" stroke="#334155" vertical={false} />
                            <XAxis dataKey="month" stroke="#94a3b8" fontSize={12} tickFormatter={(val) => new Date(val).toLocaleDateString([], {month:'short', year:'numeric'})} />
                            <YAxis stroke="#94a3b8" fontSize={12} tickFormatter={(v) => `${v/1000}k`} />
                            <RechartsTooltip formatter={(value) => `${parseFloat(value).toFixed(2)} EGP`} labelFormatter={(val) => new Date(val).toLocaleDateString([], {month:'long', year:'numeric'})} contentStyle={{ backgroundColor: '#1e293b', borderColor: '#334155', color: '#fff' }} />
                            <Bar dataKey="total" fill="#ef4444" radius={[4, 4, 0, 0]} barSize={40} />
                        </BarChart>
                    </ResponsiveContainer>
                </div>
            </div>
        );
    };

    return (
        <div className="p-6 space-y-6 min-h-screen flex flex-col">
            <PageHeader 
                title="Financial Reports" 
                subtitle="High-level aggregations and analytics for Cafe performance."
                icon={FiPieChart}
                action={
                    <div className="flex gap-3 bg-black/40 p-1.5 rounded-lg border border-white/5">
                        <input 
                            type="date" className="input text-sm bg-transparent border-none w-36 outline-none text-textMuted" 
                            title="Date From"
                            value={dateRange.date_from} onChange={e => setDateRange({...dateRange, date_from: e.target.value})}
                        />
                        <span className="text-textMuted self-center">to</span>
                        <input 
                            type="date" className="input text-sm bg-transparent border-none w-36 outline-none text-textMuted" 
                            title="Date To"
                            value={dateRange.date_to} onChange={e => setDateRange({...dateRange, date_to: e.target.value})}
                        />
                    </div>
                }
            />

            {/* Tab Navigation */}
            <div className="flex gap-2 overflow-x-auto pb-2 scrollbar-none">
                {TABS.map(tab => (
                    <button
                        key={tab.id}
                        onClick={() => setActiveTab(tab.id)}
                        className={`flex items-center gap-2 px-5 py-3 rounded-xl whitespace-nowrap transition-all duration-300 font-medium ${
                            activeTab === tab.id 
                            ? 'bg-primary text-white shadow-lg shadow-primary/20 border border-primary/50' 
                            : 'bg-black/20 text-textMuted hover:bg-white/5 border border-transparent'
                        }`}
                    >
                        {tab.icon} {tab.label}
                    </button>
                ))}
            </div>

            {/* Content Area */}
            <div className="flex-1">
                {isLoading ? (
                    <div className="h-64 flex items-center justify-center">
                        <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-primary"></div>
                    </div>
                ) : (
                    <>
                        {activeTab === 'pnl' && renderPnL()}
                        {activeTab === 'cashflow' && renderCashFlow()}
                        {activeTab === 'tax' && renderTax()}
                        {activeTab === 'sales_analysis' && renderSales()}
                        {activeTab === 'expense_analysis' && renderExpenses()}
                    </>
                )}
            </div>
        </div>
    );
}

import React, { useState, useEffect, useMemo } from 'react';
import { toast } from 'react-hot-toast';
import { FiPlus, FiMinus, FiDollarSign, FiAlertTriangle, FiList } from 'react-icons/fi';
import { financeApi } from '../../../api/financeApi';
import useAuthStore from '../../../store/authStore';
import DataTable from '../../../components/DataTable';
import PageHeader from '../../../components/PageHeader';

export default function PettyCash() {
    const { user } = useAuthStore();
    
    const [fund, setFund] = useState(null);
    const [transactions, setTransactions] = useState([]);
    const [isLoading, setIsLoading] = useState(true);

    // Form Modals
    const [spendOpen, setSpendOpen] = useState(false);
    const [replenishOpen, setReplenishOpen] = useState(false);
    const [isSubmitting, setIsSubmitting] = useState(false);

    const [formData, setFormData] = useState({
        amount: '',
        purpose: '',
        reference: ''
    });

    useEffect(() => {
        fetchData();
    }, []);

    const fetchData = async () => {
        setIsLoading(true);
        try {
            // Get user's branch fund (assuming 1st for now if array)
            const fundsRes = await financeApi.getPettyCashFunds();
            const currentFund = fundsRes.data[0]; 
            if (currentFund) {
                setFund(currentFund);
                const txRes = await financeApi.getPettyCashTransactions({ fund: currentFund.id });
                setTransactions(txRes.data);
            }
        } catch (error) {
            toast.error("Failed to fetch petty cash data");
        } finally {
            setIsLoading(false);
        }
    };

    const handleTransaction = async (type) => {
        if (!formData.amount || parseFloat(formData.amount) <= 0) return toast.error("Enter a valid amount");
        if (!formData.purpose.trim()) return toast.error("Purpose is required");
        if (type === 'spend' && parseFloat(formData.amount) > parseFloat(fund.current_balance)) {
            return toast.error("Amount exceeds current balance");
        }

        setIsSubmitting(true);
        const tid = toast.loading(`${type === 'spend' ? 'Spending' : 'Replenishing'}...`);
        try {
            await financeApi.createPettyCashTransaction({
                fund: fund.id,
                transaction_type: type,
                amount: parseFloat(formData.amount),
                purpose: formData.purpose,
                reference: formData.reference
            });
            toast.success(`Transaction successful`, { id: tid });
            if (type === 'spend') setSpendOpen(false);
            else setReplenishOpen(false);
            setFormData({ amount: '', purpose: '', reference: '' });
            fetchData();
        } catch (error) {
            toast.error(error.response?.data?.error || "Transaction failed", { id: tid });
        } finally {
            setIsSubmitting(false);
        }
    };

    const columns = useMemo(() => [
        {
            header: 'Date & Time',
            accessorFn: row => new Date(row.created_at).toLocaleString([], { dateStyle: 'short', timeStyle: 'short' })
        },
        {
            header: 'Type',
            accessorKey: 'transaction_type',
            cell: info => {
                const type = info.getValue();
                return <span className={`px-2 py-1 rounded text-xs font-bold ${
                    type === 'replenish' ? 'bg-green-500/20 text-green-400' : 'bg-orange-500/20 text-orange-400'
                }`}>
                    {type.toUpperCase()}
                </span>;
            }
        },
        {
            header: 'Amount',
            accessorKey: 'amount',
            cell: info => {
                const type = info.row.original.transaction_type;
                const val = parseFloat(info.getValue());
                return <span className={`font-mono font-bold ${type === 'replenish' ? 'text-green-400' : 'text-orange-400'}`}>
                    {type === 'replenish' ? '+' : '-'}{val.toFixed(2)}
                </span>;
            }
        },
        { header: 'Purpose', accessorKey: 'purpose', cell: info => <span className="text-sm">{info.getValue()}</span> },
        { header: 'Reference', accessorFn: row => row.reference || '-', cell: info => <span className="font-mono text-xs text-textMuted">{info.getValue()}</span> },
        {
            header: 'Balance After',
            accessorKey: 'running_balance',
            cell: info => <span className="font-mono text-white">{parseFloat(info.getValue()).toFixed(2)}</span>
        },
        { header: 'Performed By', accessorFn: row => row.performed_by_name || '-' }
    ], []);

    const formatMoney = (val) => `${parseFloat(val || 0).toFixed(2)} EGP`;

    if (isLoading) return <div className="p-6">Loading...</div>;

    if (!fund) {
        return (
            <div className="p-6">
                <div className="glass-panel p-8 text-center bg-red-500/10 border-red-500/20">
                    <FiAlertTriangle className="w-12 h-12 text-red-500 mx-auto mb-4" />
                    <h2 className="text-xl font-bold text-white mb-2">No Petty Cash Fund Found</h2>
                    <p className="text-textMuted">Please ask an administrator to set up a petty cash fund for this branch.</p>
                </div>
            </div>
        );
    }

    const pct = fund.float_amount > 0 ? (fund.current_balance / fund.float_amount) * 100 : 0;
    const isLow = pct < 20;

    return (
        <div className="p-6 space-y-6 animate-fade-in">
            <PageHeader 
                title="Petty Cash Management" 
                subtitle={`Branch: ${fund.branch_name}`}
                icon={FiDollarSign}
            />

            {/* Fund Dashboard */}
            <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                <div className={`col-span-1 glass-panel p-6 ${isLow ? 'border-red-500/50 shadow-[0_0_15px_rgba(239,68,68,0.15)] bg-red-500/5' : ''}`}>
                    <div className="flex justify-between items-start mb-6">
                        <div>
                            <h3 className="text-textMuted text-sm font-medium uppercase tracking-wider mb-1">Current Balance</h3>
                            <div className="flex items-baseline gap-2">
                                <span className={`text-5xl font-black font-mono tracking-tighter ${isLow ? 'text-red-400' : 'text-white'}`}>
                                    {formatMoney(fund.current_balance)}
                                </span>
                            </div>
                        </div>
                        {isLow && <FiAlertTriangle className="text-red-500 w-8 h-8 animate-pulse" />}
                    </div>

                    <div className="space-y-2 mb-6 text-sm">
                        <div className="flex justify-between mt-4">
                            <span className="text-textMuted">Authorised Float</span>
                            <span className="font-mono text-white">{formatMoney(fund.float_amount)}</span>
                        </div>
                        <div className="w-full bg-black/40 rounded-full h-2">
                            <div 
                                className={`h-2 rounded-full ${isLow ? 'bg-red-500' : 'bg-primary'}`}
                                style={{ width: `${Math.min(100, pct)}%` }}
                            ></div>
                        </div>
                    </div>

                    <div className="grid grid-cols-2 gap-3 mt-6">
                        <button 
                            onClick={() => setSpendOpen(true)}
                            className="bg-orange-500/20 hover:bg-orange-500/30 border border-orange-500/50 text-orange-400 font-bold py-3 rounded-xl transition-all flex justify-center items-center gap-2"
                        >
                            <FiMinus /> Spend
                        </button>
                        <button 
                            onClick={() => setReplenishOpen(true)}
                            className="bg-green-500/20 hover:bg-green-500/30 border border-green-500/50 text-green-400 font-bold py-3 rounded-xl transition-all flex justify-center items-center gap-2"
                        >
                            <FiPlus /> Replenish
                        </button>
                    </div>
                </div>

                <div className="col-span-1 md:col-span-2 glass-panel p-6">
                    <h3 className="text-lg font-bold text-white mb-4 flex items-center gap-2">
                        <FiList className="text-primary" /> 
                        <span>Transaction Ledger</span>
                    </h3>
                    <div className="overflow-x-auto h-[300px] scrollbar-thin scrollbar-thumb-white/10 scrollbar-track-transparent pr-2">
                        <table className="w-full text-sm text-left">
                            <thead className="text-xs text-textMuted uppercase bg-black/20 sticky top-0 z-10 backdrop-blur-md">
                                <tr>
                                    <th className="px-4 py-3 rounded-tl-lg">Date</th>
                                    <th className="px-4 py-3">Type</th>
                                    <th className="px-4 py-3">Amount</th>
                                    <th className="px-4 py-3">Purpose</th>
                                    <th className="px-4 py-3">Ref</th>
                                    <th className="px-4 py-3 rounded-tr-lg text-right">Balance</th>
                                </tr>
                            </thead>
                            <tbody>
                                {transactions.map((tx) => {
                                    const isReplenish = tx.transaction_type === 'replenish';
                                    return (
                                        <tr key={tx.id} className="border-b border-white/5 hover:bg-white/5 transition-colors">
                                            <td className="px-4 py-3 text-textMuted">
                                                {new Date(tx.created_at).toLocaleDateString()} <span className="text-[10px]">{new Date(tx.created_at).toLocaleTimeString([], {hour:'2-digit', minute:'2-digit'})}</span>
                                            </td>
                                            <td className="px-4 py-3">
                                                <span className={`px-2 py-1 rounded text-[10px] font-bold uppercase tracking-wider ${
                                                    isReplenish ? 'bg-green-500/10 text-green-400' : 'bg-orange-500/10 text-orange-400'
                                                }`}>
                                                    {tx.transaction_type}
                                                </span>
                                            </td>
                                            <td className={`px-4 py-3 font-mono font-bold ${isReplenish ? 'text-green-400' : 'text-orange-400'}`}>
                                                {isReplenish ? '+' : '-'}{parseFloat(tx.amount).toFixed(2)}
                                            </td>
                                            <td className="px-4 py-3 text-xs max-w-[150px] truncate" title={tx.purpose}>{tx.purpose}</td>
                                            <td className="px-4 py-3 text-xs font-mono text-textMuted">{tx.reference || '-'}</td>
                                            <td className="px-4 py-3 text-right font-mono font-bold text-white">{parseFloat(tx.running_balance).toFixed(2)}</td>
                                        </tr>
                                    );
                                })}
                                {transactions.length === 0 && (
                                    <tr><td colSpan="6" className="text-center py-8 text-textMuted">No transactions recorded yet.</td></tr>
                                )}
                            </tbody>
                        </table>
                    </div>
                </div>
            </div>

            {/* SPEND MODAL */}
            {spendOpen && (
                <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/60 backdrop-blur-sm">
                    <form onSubmit={(e) => { e.preventDefault(); handleTransaction('spend'); }} className="bg-[#1e293b] rounded-2xl w-full max-w-sm border border-orange-500/30 overflow-hidden shadow-2xl">
                        <div className="p-5 border-b border-white/10 flex items-center gap-2 bg-[#0f172a]">
                            <FiMinus className="text-orange-400 text-xl" />
                            <h3 className="font-bold text-white text-lg">Spend Petty Cash</h3>
                        </div>
                        <div className="p-6 space-y-4">
                            <div>
                                <label className="block text-sm font-medium text-textMuted mb-1">Amount (EGP) *</label>
                                <input required type="number" step="0.01" max={fund.current_balance} autoFocus
                                    className="input w-full font-mono text-orange-400 text-lg" 
                                    value={formData.amount} onChange={e => setFormData({...formData, amount: e.target.value})}
                                />
                                <p className="text-xs text-textMuted mt-1 text-right">Max: {fund.current_balance} EGP</p>
                            </div>
                            <div>
                                <label className="block text-sm font-medium text-textMuted mb-1">Purpose *</label>
                                <input required type="text" className="input w-full" placeholder="e.g. Minor repairs, ice"
                                    value={formData.purpose} onChange={e => setFormData({...formData, purpose: e.target.value})}
                                />
                            </div>
                            <div>
                                <label className="block text-sm font-medium text-textMuted mb-1">Receipt Ref # (Optional)</label>
                                <input type="text" className="input w-full font-mono text-sm" placeholder="e.g. RCP-12345"
                                    value={formData.reference} onChange={e => setFormData({...formData, reference: e.target.value})}
                                />
                            </div>
                        </div>
                        <div className="p-5 border-t border-white/10 bg-[#0f172a] flex justify-end gap-3">
                            <button type="button" onClick={() => setSpendOpen(false)} className="px-4 py-2 rounded-lg text-textMuted hover:bg-white/5 transition-colors">Cancel</button>
                            <button type="submit" disabled={isSubmitting} className="px-5 py-2 rounded-lg bg-orange-500 hover:bg-orange-600 text-white font-bold transition-colors shadow-lg shadow-orange-500/20">Record Spend</button>
                        </div>
                    </form>
                </div>
            )}

            {/* REPLENISH MODAL */}
            {replenishOpen && (
                <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/60 backdrop-blur-sm">
                    <form onSubmit={(e) => { e.preventDefault(); handleTransaction('replenish'); }} className="bg-[#1e293b] rounded-2xl w-full max-w-sm border border-green-500/30 overflow-hidden shadow-2xl">
                        <div className="p-5 border-b border-white/10 flex items-center gap-2 bg-[#0f172a]">
                            <FiPlus className="text-green-400 text-xl" />
                            <h3 className="font-bold text-white text-lg">Replenish Fund</h3>
                        </div>
                        <div className="p-6 space-y-4">
                            <div>
                                <label className="block text-sm font-medium text-textMuted mb-1">Amount (EGP) *</label>
                                <input required type="number" step="0.01" autoFocus
                                    className="input w-full font-mono text-green-400 text-lg" 
                                    defaultValue={Math.max(0, parseFloat(fund.float_amount) - parseFloat(fund.current_balance))}
                                    onChange={e => setFormData({...formData, amount: e.target.value})}
                                />
                                <p className="text-xs text-textMuted mt-1 text-right">Suggested: {Math.max(0, parseFloat(fund.float_amount) - parseFloat(fund.current_balance)).toFixed(2)} EGP</p>
                            </div>
                            <div>
                                <label className="block text-sm font-medium text-textMuted mb-1">Source / Purpose *</label>
                                <input required type="text" className="input w-full" placeholder="e.g. Bank withdrawal"
                                    value={formData.purpose} onChange={e => setFormData({...formData, purpose: e.target.value})}
                                />
                            </div>
                            <div>
                                <label className="block text-sm font-medium text-textMuted mb-1">Bank Ref # (Optional)</label>
                                <input type="text" className="input w-full font-mono text-sm" placeholder="e.g. TR-998877"
                                    value={formData.reference} onChange={e => setFormData({...formData, reference: e.target.value})}
                                />
                            </div>
                        </div>
                        <div className="p-5 border-t border-white/10 bg-[#0f172a] flex justify-end gap-3">
                            <button type="button" onClick={() => setReplenishOpen(false)} className="px-4 py-2 rounded-lg text-textMuted hover:bg-white/5 transition-colors">Cancel</button>
                            <button type="submit" disabled={isSubmitting} className="px-5 py-2 rounded-lg bg-green-500 hover:bg-green-600 text-white font-bold transition-colors shadow-lg shadow-green-500/20">Add Funds</button>
                        </div>
                    </form>
                </div>
            )}
        </div>
    );
}

import React, { useState, useEffect, useMemo } from 'react';
import { toast } from 'react-hot-toast';
import { FiSearch, FiFilter, FiDownload, FiXCircle, FiRefreshCw, FiDollarSign } from 'react-icons/fi';
import { financeApi } from '../../../api/financeApi';
import useAuthStore from '../../../store/authStore';
import DataTable from '../../../components/DataTable';
import ConfirmModal from '../../../components/ConfirmModal';
import PageHeader from '../../../components/PageHeader';

export default function SalesJournal() {
    const { user } = useAuthStore();
    const canVoidRefund = ['super_admin', 'manager'].includes(user?.role);
    
    const [transactions, setTransactions] = useState([]);
    const [summary, setSummary] = useState(null);
    const [isLoading, setIsLoading] = useState(true);

    // Filters
    const [filters, setFilters] = useState({
        search: '',
        transaction_type: '',
        date_from: '',
        date_to: ''
    });

    // Modals
    const [voidItem, setVoidItem] = useState(null);
    const [voidReason, setVoidReason] = useState('');
    
    const [refundItem, setRefundItem] = useState(null);
    const [refundAmount, setRefundAmount] = useState('');
    const [refundReason, setRefundReason] = useState('');

    useEffect(() => {
        fetchData();
    }, [filters]);

    const fetchData = async () => {
        setIsLoading(true);
        try {
            const [txRes, sumRes] = await Promise.all([
                financeApi.getTransactions(filters),
                financeApi.getTransactionSummary()
            ]);
            setTransactions(txRes.data);
            setSummary(sumRes.data);
        } catch (error) {
            toast.error("Failed to fetch journal data");
        } finally {
            setIsLoading(false);
        }
    };

    const handleVoid = async () => {
        if (!voidReason.trim()) return toast.error("Void reason is required.");
        const tid = toast.loading("Processing void...");
        try {
            await financeApi.voidTransaction(voidItem.id, { reason: voidReason });
            toast.success("Transaction voided successfully", { id: tid });
            setVoidItem(null);
            setVoidReason('');
            fetchData();
        } catch (error) {
            toast.error(error.response?.data?.error || "Failed to void transaction", { id: tid });
        }
    };

    const handleRefund = async () => {
        if (!refundAmount || parseFloat(refundAmount) <= 0) return toast.error("Enter a valid refund amount");
        if (!refundReason.trim()) return toast.error("Refund reason is required.");
        
        const tid = toast.loading("Processing refund...");
        try {
            await financeApi.createRefund({
                original_transaction: refundItem.id,
                amount: parseFloat(refundAmount),
                reason: refundReason
            });
            toast.success("Refund processed successfully", { id: tid });
            setRefundItem(null);
            setRefundAmount('');
            setRefundReason('');
            fetchData();
        } catch (error) {
            // Check if validation error (e.g. exceeds original amount)
            const errDetail = error.response?.data?.non_field_errors?.[0] || error.response?.data?.detail || "Failed to process refund";
            toast.error(errDetail, { id: tid });
        }
    };

    const columns = useMemo(() => [
        {
            header: 'Time',
            accessorFn: row => new Date(row.created_at).toLocaleString([], { dateStyle: 'short', timeStyle: 'short' })
        },
        {
            header: 'Transaction #',
            accessorKey: 'transaction_number',
            cell: info => <span className="font-mono text-xs text-textMuted">{info.getValue()}</span>
        },
        {
            header: 'Type',
            accessorKey: 'transaction_type',
            cell: info => {
                const type = info.getValue();
                const isVoided = info.row.original.is_voided;
                if (isVoided) return <span className="px-2 py-1 rounded text-xs font-bold bg-red-500/20 text-red-400 line-through -ml-2">VOIDED</span>;
                
                return <span className={`px-2 py-1 rounded text-xs font-bold ${
                    type === 'sale' ? 'bg-green-500/20 text-green-400' :
                    type === 'refund' ? 'bg-orange-500/20 text-orange-400' :
                    'bg-red-500/20 text-red-400'
                }`}>
                    {type.toUpperCase()}
                </span>;
            }
        },
        {
            header: 'Order Ref',
            accessorFn: row => row.order_number || '-',
            cell: info => <span className="font-mono text-xs">{info.getValue()}</span>
        },
        {
            header: 'Amount',
            accessorKey: 'net_amount',
            cell: info => {
                const val = parseFloat(info.getValue());
                return <span className={`font-mono font-bold ${val > 0 ? 'text-green-400' : 'text-red-400'}`}>
                    {val > 0 ? '+' : ''}{val.toFixed(2)}
                </span>;
            }
        },
        {
            header: 'Payment Method',
            accessorFn: row => row.payment_method ? row.payment_method.replace('_', ' ').toUpperCase() : '-',
            cell: info => <span className="text-xs">{info.getValue()}</span>
        },
        {
            header: 'Cashier',
            accessorFn: row => row.cashier_name || '-'
        },
        {
            id: 'actions',
            header: 'Actions',
            cell: info => {
                const row = info.row.original;
                if (!canVoidRefund) return null;
                if (row.transaction_type !== 'sale' || row.is_voided) return null;

                return (
                    <div className="flex gap-2">
                        <button 
                            onClick={() => setRefundItem(row)}
                            className="p-1.5 bg-orange-500/20 text-orange-400 hover:bg-orange-500/30 rounded transition-colors"
                            title="Issue Refund"
                        >
                            <FiRefreshCw className="w-4 h-4" />
                        </button>
                        <button 
                            onClick={() => setVoidItem(row)}
                            className="p-1.5 bg-red-500/20 text-red-400 hover:bg-red-500/30 rounded transition-colors"
                            title="Void Transaction"
                        >
                            <FiXCircle className="w-4 h-4" />
                        </button>
                    </div>
                );
            }
        }
    ], [canVoidRefund]);

    const formatMoney = (val) => `${parseFloat(val || 0).toFixed(2)} EGP`;

    return (
        <div className="p-6 space-y-6 animate-fade-in">
            <PageHeader 
                title="Sales Journal" 
                subtitle="Complete log of all financial transactions, refunds, and voids."
                icon={FiDollarSign}
            />

            {/* Summary Cards */}
            {summary && (
                <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
                    <div className="glass-panel p-5 border-l-4 border-green-500">
                        <p className="text-textMuted text-sm font-medium">Gross Sales</p>
                        <p className="text-2xl font-bold text-white mt-1">{formatMoney(summary.total_sales)}</p>
                    </div>
                    <div className="glass-panel p-5 border-l-4 border-orange-500">
                        <p className="text-textMuted text-sm font-medium">Total Refunds</p>
                        <p className="text-2xl font-bold text-white mt-1">{formatMoney(summary.total_refunds)}</p>
                    </div>
                    <div className="glass-panel p-5 border-l-4 border-red-500">
                        <p className="text-textMuted text-sm font-medium">Total Voids</p>
                        <p className="text-2xl font-bold text-white mt-1">{formatMoney(summary.total_voids)}</p>
                    </div>
                    <div className="glass-panel p-5 border-l-4 border-primary bg-primary/5">
                        <p className="text-primary text-sm font-bold tracking-wide">NET REVENUE</p>
                        <p className="text-3xl font-black text-white mt-1">{formatMoney(summary.net_revenue)}</p>
                    </div>
                </div>
            )}

            {/* Filters */}
            <div className="glass-panel p-4 flex flex-wrap gap-4 items-end">
                <div className="flex-1 min-w-[200px]">
                    <label className="block text-xs text-textMuted mb-1">Search Ref #</label>
                    <div className="relative">
                        <FiSearch className="absolute left-3 top-1/2 -translate-y-1/2 text-textMuted" />
                        <input 
                            type="text" 
                            className="input w-full pl-9" 
                            placeholder="TXN-... or ORD-..."
                            value={filters.search}
                            onChange={(e) => setFilters(prev => ({ ...prev, search: e.target.value }))}
                        />
                    </div>
                </div>
                <div className="w-40">
                    <label className="block text-xs text-textMuted mb-1">Type</label>
                    <select 
                        className="input w-full text-sm"
                        value={filters.transaction_type}
                        onChange={(e) => setFilters(prev => ({ ...prev, transaction_type: e.target.value }))}
                    >
                        <option value="">All Types</option>
                        <option value="sale">Sale</option>
                        <option value="refund">Refund</option>
                        <option value="void">Void</option>
                    </select>
                </div>
                <div className="w-40">
                    <label className="block text-xs text-textMuted mb-1">Date From</label>
                    <input 
                        type="date" className="input w-full text-sm"
                        value={filters.date_from} onChange={(e) => setFilters(prev => ({ ...prev, date_from: e.target.value }))}
                    />
                </div>
                <div className="w-40">
                    <label className="block text-xs text-textMuted mb-1">Date To</label>
                    <input 
                        type="date" className="input w-full text-sm"
                        value={filters.date_to} onChange={(e) => setFilters(prev => ({ ...prev, date_to: e.target.value }))}
                    />
                </div>
                <button 
                    onClick={() => setFilters({ search: '', transaction_type: '', date_from: '', date_to: '' })}
                    className="btn bg-white/5 hover:bg-white/10 text-white flex gap-2 items-center"
                >
                    <FiFilter /> Clear
                </button>
            </div>

            <DataTable 
                columns={columns} 
                data={transactions} 
                isLoading={isLoading}
                hideSearch={true}
            />

            {/* VOID MODAL */}
            {voidItem && (
                <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/60 backdrop-blur-sm">
                    <div className="bg-[#1e293b] rounded-2xl w-full max-w-sm border border-red-500/30 overflow-hidden shadow-2xl">
                        <div className="p-5 border-b border-white/10 flex items-center gap-2 bg-[#0f172a]">
                            <FiXCircle className="text-red-400 text-xl" />
                            <h3 className="font-bold text-white text-lg">Void Transaction</h3>
                        </div>
                        <div className="p-6 space-y-4">
                            <div className="bg-red-500/10 text-red-400 p-3 rounded-lg text-sm border border-red-500/20">
                                You are about to void transaction <strong>{voidItem.transaction_number}</strong> for {formatMoney(voidItem.net_amount)}. This will reverse the revenue.
                            </div>
                            <div>
                                <label className="block text-sm font-medium text-textMuted mb-1">Reason for Void *</label>
                                <textarea 
                                    className="input w-full min-h-[80px]" placeholder="Required for audit logs..."
                                    value={voidReason} onChange={e => setVoidReason(e.target.value)}
                                    autoFocus
                                />
                            </div>
                        </div>
                        <div className="p-5 border-t border-white/10 bg-[#0f172a] flex justify-end gap-3">
                            <button onClick={() => setVoidItem(null)} className="px-4 py-2 rounded-lg text-textMuted hover:bg-white/5 transition-colors">Cancel</button>
                            <button onClick={handleVoid} className="px-4 py-2 rounded-lg bg-red-500 hover:bg-red-600 text-white font-bold transition-colors shadow-lg shadow-red-500/20">Confirm Void</button>
                        </div>
                    </div>
                </div>
            )}

            {/* REFUND MODAL */}
            {refundItem && (
                <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/60 backdrop-blur-sm">
                    <div className="bg-[#1e293b] rounded-2xl w-full max-w-sm border border-orange-500/30 overflow-hidden shadow-2xl">
                        <div className="p-5 border-b border-white/10 flex items-center gap-2 bg-[#0f172a]">
                            <FiRefreshCw className="text-orange-400 text-xl" />
                            <h3 className="font-bold text-white text-lg">Issue Refund</h3>
                        </div>
                        <div className="p-6 space-y-4">
                            <div className="bg-orange-500/10 text-orange-400 p-3 rounded-lg text-sm border border-orange-500/20">
                                Max available refund: <strong>{formatMoney(refundItem.net_amount)}</strong>
                            </div>
                            <div>
                                <label className="block text-sm font-medium text-textMuted mb-1">Refund Amount (EGP)</label>
                                <input 
                                    type="number" step="0.01" max={parseFloat(refundItem.net_amount)}
                                    className="input w-full font-mono text-orange-400 text-lg" 
                                    value={refundAmount} onChange={e => setRefundAmount(e.target.value)}
                                    autoFocus
                                />
                            </div>
                            <div>
                                <label className="block text-sm font-medium text-textMuted mb-1">Reason for Refund *</label>
                                <input 
                                    type="text" className="input w-full" placeholder="e.g. Customer complaint"
                                    value={refundReason} onChange={e => setRefundReason(e.target.value)}
                                />
                            </div>
                        </div>
                        <div className="p-5 border-t border-white/10 bg-[#0f172a] flex justify-end gap-3">
                            <button onClick={() => setRefundItem(null)} className="px-4 py-2 rounded-lg text-textMuted hover:bg-white/5 transition-colors">Cancel</button>
                            <button onClick={handleRefund} className="px-4 py-2 rounded-lg bg-orange-500 hover:bg-orange-600 text-white font-bold transition-colors shadow-lg shadow-orange-500/20">Process Refund</button>
                        </div>
                    </div>
                </div>
            )}
        </div>
    );
}

import React, { useState, useEffect, useMemo } from 'react';
import { FiPlus, FiEdit2, FiTrash2, FiFolder, FiChevronRight, FiChevronDown, FiImage, FiSearch, FiSave, FiX } from 'react-icons/fi';
import { inventoryApi } from '../../api/inventoryApi';
import toast from 'react-hot-toast';
import ConfirmModal from '../../components/ConfirmModal';
export default function Categories() {
    const [categories, setCategories] = useState([]);
    const [loading, setLoading] = useState(true);
    const [searchQuery, setSearchQuery] = useState('');
    
    // Modal State
    const [isModalOpen, setIsModalOpen] = useState(false);
    const [editingCategory, setEditingCategory] = useState(null);
    const [formData, setFormData] = useState({
        name: '',
        name_ar: '',
        description: '',
        parent: '',
        is_active: true,
        order: 0
    });
    
    // UI states
    const [expandedNodeIds, setExpandedNodeIds] = useState(new Set());
    const [deleteModalOpen, setDeleteModalOpen] = useState(false);
    const [categoryToDelete, setCategoryToDelete] = useState(null);

    useEffect(() => {
        fetchCategories();
    }, []);

    const fetchCategories = async () => {
        try {
            setLoading(true);
            const { data } = await inventoryApi.getCategories();
            // Data is plain flat array, we will build tree dynamically
            setCategories(data);
        } catch (error) {
            toast.error("Failed to fetch categories");
        } finally {
            setLoading(false);
        }
    };

    const buildCategoryTree = (cats) => {
        const catMap = {};
        const roots = [];
        cats.forEach(c => catMap[c.id] = { ...c, children: [] });
        cats.forEach(c => {
            if (c.parent) {
                if (catMap[c.parent]) catMap[c.parent].children.push(catMap[c.id]);
            } else {
                roots.push(catMap[c.id]);
            }
        });
        
        // Sort by order then name
        const sortNodes = (nodes) => {
            nodes.sort((a, b) => a.order - b.order || a.name.localeCompare(b.name));
            nodes.forEach(n => sortNodes(n.children));
        };
        sortNodes(roots);
        return roots;
    };

    const filteredTree = useMemo(() => {
        if (!searchQuery) return buildCategoryTree(categories);
        const lowerQ = searchQuery.toLowerCase();
        // If searching, just flatten and return matches for now to keep it simple
        const matches = categories.filter(c => c.name.toLowerCase().includes(lowerQ) || (c.name_ar && c.name_ar.toLowerCase().includes(lowerQ)));
        // Return them as a flat list but formatted like roots
        return matches.map(m => ({ ...m, children: [] }));
    }, [categories, searchQuery]);

    const toggleNode = (id, e) => {
        e.stopPropagation();
        setExpandedNodeIds(prev => {
            const next = new Set(prev);
            if (next.has(id)) next.delete(id);
            else next.add(id);
            return next;
        });
    };

    const handleOpenModal = (category = null, parentId = null) => {
        if (category) {
            setEditingCategory(category);
            setFormData({
                name: category.name,
                name_ar: category.name_ar || '',
                description: category.description || '',
                parent: category.parent || '',
                is_active: category.is_active,
                order: category.order || 0
            });
        } else {
            setEditingCategory(null);
            setFormData({
                name: '',
                name_ar: '',
                description: '',
                parent: parentId || '',
                is_active: true,
                order: 0
            });
        }
        setIsModalOpen(true);
    };

    const handleSubmit = async (e) => {
        e.preventDefault();
        const toastId = toast.loading(editingCategory ? "Updating category..." : "Creating category...");
        
        // Remove empty strings for parent so it sends null
        const submitData = { ...formData };
        if (!submitData.parent) submitData.parent = null;

        try {
            if (editingCategory) {
                await inventoryApi.updateCategory(editingCategory.id, submitData);
                toast.success("Category updated", { id: toastId });
            } else {
                await inventoryApi.createCategory(submitData);
                toast.success("Category created", { id: toastId });
            }
            fetchCategories();
            setIsModalOpen(false);
        } catch (error) {
            toast.error(error.response?.data?.detail || "Action failed", { id: toastId });
        }
    };

    const handleDelete = async () => {
        if (!categoryToDelete) return;
        const toastId = toast.loading("Deleting category...");
        try {
            await inventoryApi.deleteCategory(categoryToDelete.id);
            toast.success("Category deleted", { id: toastId });
            fetchCategories();
        } catch (error) {
            toast.error(error.response?.data?.detail || "Failed to delete. It might be in use.", { id: toastId });
        } finally {
            setDeleteModalOpen(false);
            setCategoryToDelete(null);
        }
    };

    const CategoryNode = ({ node, level = 0 }) => {
        const isExpanded = expandedNodeIds.has(node.id) || !!searchQuery;
        const hasChildren = node.children && node.children.length > 0;
        
        return (
            <div className="flex flex-col">
                <div 
                    className={`
                        flex items-center justify-between p-3 border-b border-white/5 hover:bg-white/5 transition-colors group
                        ${level === 0 ? 'bg-white/5 font-medium' : ''}
                    `}
                    style={{ paddingLeft: `${(level * 24) + 12}px` }}
                >
                    <div className="flex items-center space-x-3">
                        {hasChildren ? (
                            <button onClick={(e) => toggleNode(node.id, e)} className="p-1 text-textMuted hover:text-white rounded">
                                {isExpanded ? <FiChevronDown /> : <FiChevronRight />}
                            </button>
                        ) : (
                            <div className="w-6" /> // spacer
                        )}
                        
                        <div className="w-8 h-8 rounded bg-white/10 flex items-center justify-center shrink-0">
                            {node.image ? (
                                <img src={node.image} alt="cat" className="w-full h-full object-cover rounded" />
                            ) : (
                                <FiFolder className="text-textMuted" />
                            )}
                        </div>
                        
                        <div>
                            <div className="flex items-center space-x-2">
                                <span className={!node.is_active ? 'text-textMuted line-through' : 'text-white'}>{node.name}</span>
                                {node.name_ar && <span className="text-xs px-2 py-0.5 rounded bg-white/10 text-textMuted">{node.name_ar}</span>}
                            </div>
                            <div className="text-xs text-textMuted">
                                {node.children.length} subcategories
                            </div>
                        </div>
                    </div>

                    <div className="flex items-center space-x-2 opacity-0 group-hover:opacity-100 transition-opacity">
                        <button 
                            onClick={() => handleOpenModal(null, node.id)}
                            className="p-1.5 text-xs bg-primary/20 text-primary hover:bg-primary hover:text-white rounded transition-colors flex items-center space-x-1"
                            title="Add Subcategory"
                        >
                            <FiPlus /> <span>Sub</span>
                        </button>
                        <button 
                            onClick={() => handleOpenModal(node)}
                            className="p-1.5 text-textMuted hover:text-white bg-white/5 hover:bg-white/10 rounded transition-colors"
                        >
                            <FiEdit2 />
                        </button>
                        <button 
                            onClick={() => { setCategoryToDelete(node); setDeleteModalOpen(true); }}
                            className="p-1.5 text-red-400 hover:text-white bg-red-400/10 hover:bg-red-500 rounded transition-colors"
                        >
                            <FiTrash2 />
                        </button>
                    </div>
                </div>
                
                {isExpanded && hasChildren && (
                    <div className="flex flex-col">
                        {node.children.map(child => (
                            <CategoryNode key={child.id} node={child} level={level + 1} />
                        ))}
                    </div>
                )}
            </div>
        );
    };

    // Get flat options for the Parent dropdown, avoiding circular references by ignoring self and children
    const getDropdownOptions = () => {
        const flatList = [];
        const processNode = (nodes, level = 0) => {
            for (const n of nodes) {
                // If editing, don't show self or descendants to prevent circular
                if (editingCategory && n.id === editingCategory.id) continue;
                
                flatList.push({ id: n.id, name: `${'—'.repeat(level)} ${n.name}` });
                processNode(n.children, level + 1);
            }
        };
        processNode(buildCategoryTree(categories));
        return flatList;
    };

    return (
        <div className="space-y-6">
            <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4">
                <div>
                    <h1 className="text-2xl font-bold text-white">Menu Categories</h1>
                    <p className="text-textMuted text-sm mt-1">Manage infinite levels of categories and subcategories</p>
                </div>
                <button 
                    onClick={() => handleOpenModal()}
                    className="btn btn-primary flex items-center space-x-2"
                >
                    <FiPlus /> <span>New Category</span>
                </button>
            </div>

            <div className="glass-panel p-6">
                <div className="flex justify-between items-center mb-6">
                    <div className="relative w-full max-w-sm">
                        <FiSearch className="absolute left-3 top-1/2 -translate-y-1/2 text-textMuted" />
                        <input
                            type="text"
                            placeholder="Search categories..."
                            value={searchQuery}
                            onChange={(e) => setSearchQuery(e.target.value)}
                            className="input w-full pl-10"
                        />
                    </div>
                </div>

                {loading ? (
                    <div className="flex items-center justify-center py-20">
                        <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-primary"></div>
                    </div>
                ) : (
                    <div className="rounded-xl border border-white/10 overflow-hidden bg-black/20">
                        {filteredTree.length === 0 ? (
                            <div className="p-8 text-center text-textMuted">
                                <div className="inline-flex items-center justify-center w-12 h-12 rounded-full bg-white/5 mb-4">
                                    <FiFolder className="w-6 h-6" />
                                </div>
                                <p>No categories found</p>
                            </div>
                        ) : (
                            <div className="flex flex-col">
                                {filteredTree.map(rootNode => (
                                    <CategoryNode key={rootNode.id} node={rootNode} level={0} />
                                ))}
                            </div>
                        )}
                    </div>
                )}
            </div>

            {/* Form Modal */}
            {isModalOpen && (
                <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/60 backdrop-blur-sm animate-fade-in">
                    <div className="glass-panel w-full max-w-lg overflow-hidden flex flex-col max-h-[90vh]">
                        <div className="p-6 border-b border-white/10 flex justify-between items-center shrink-0">
                            <h2 className="text-xl font-semibold text-white">
                                {editingCategory ? 'Edit Category' : 'New Category'}
                            </h2>
                            <button onClick={() => setIsModalOpen(false)} className="text-textMuted hover:text-white">
                                <FiX className="w-6 h-6" />
                            </button>
                        </div>
                        
                        <div className="p-6 overflow-y-auto">
                            <form id="categoryForm" onSubmit={handleSubmit} className="space-y-4">
                                
                                <div>
                                    <label className="block text-sm font-medium text-textMuted mb-2">Parent Category</label>
                                    <select 
                                        value={formData.parent}
                                        onChange={(e) => setFormData({...formData, parent: e.target.value})}
                                        className="input w-full"
                                    >
                                        <option value="">None (Top Level)</option>
                                        {getDropdownOptions().map(opt => (
                                            <option key={opt.id} value={opt.id}>{opt.name}</option>
                                        ))}
                                    </select>
                                </div>

                                <div className="grid grid-cols-2 gap-4">
                                    <div>
                                        <label className="block text-sm font-medium text-textMuted mb-2">Name (English) *</label>
                                        <input 
                                            type="text" 
                                            required
                                            value={formData.name}
                                            onChange={(e) => setFormData({...formData, name: e.target.value})}
                                            className="input w-full"
                                            placeholder="e.g. Hot Drinks"
                                        />
                                    </div>
                                    <div>
                                        <label className="block text-sm font-medium text-textMuted mb-2">Name (Arabic)</label>
                                        <input 
                                            type="text" 
                                            value={formData.name_ar}
                                            onChange={(e) => setFormData({...formData, name_ar: e.target.value})}
                                            className="input w-full text-right"
                                            dir="rtl"
                                            placeholder="مشروبات ساخنة"
                                        />
                                    </div>
                                </div>

                                <div>
                                    <label className="block text-sm font-medium text-textMuted mb-2">Description</label>
                                    <textarea 
                                        value={formData.description}
                                        onChange={(e) => setFormData({...formData, description: e.target.value})}
                                        className="input w-full h-20 resize-none"
                                        placeholder="Optional description..."
                                    />
                                </div>

                                <div className="grid grid-cols-2 gap-4">
                                    <div>
                                        <label className="block text-sm font-medium text-textMuted mb-2">Display Order</label>
                                        <input 
                                            type="number" 
                                            value={formData.order}
                                            onChange={(e) => setFormData({...formData, order: parseInt(e.target.value) || 0})}
                                            className="input w-full"
                                        />
                                    </div>
                                    <div className="flex items-center mt-8">
                                        <label className="flex items-center space-x-3 cursor-pointer">
                                            <input 
                                                type="checkbox"
                                                checked={formData.is_active}
                                                onChange={(e) => setFormData({...formData, is_active: e.target.checked})}
                                                className="w-5 h-5 rounded border-white/20 bg-black/20 text-primary focus:ring-primary focus:ring-offset-gray-900"
                                            />
                                            <span className="text-textMain font-medium">Active</span>
                                        </label>
                                    </div>
                                </div>
                            </form>
                        </div>
                        
                        <div className="p-6 border-t border-white/10 flex justify-end gap-3 shrink-0">
                            <button type="button" onClick={() => setIsModalOpen(false)} className="btn hover:bg-white/5">
                                Cancel
                            </button>
                            <button type="submit" form="categoryForm" className="btn btn-primary flex items-center space-x-2">
                                <FiSave /> <span>Save</span>
                            </button>
                        </div>
                    </div>
                </div>
            )}

            {/* Delete Confirmation Modal */}
            <ConfirmModal 
                isOpen={deleteModalOpen}
                title="Delete Category"
                message={`Are you sure you want to delete ${categoryToDelete?.name}? Subcategories and linked products might be affected.`}
                onConfirm={handleDelete}
                onCancel={() => setDeleteModalOpen(false)}
                confirmText="Delete Category"
                isDestructive={true}
            />
        </div>
    );
}

import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { FiTrendingDown, FiAlertCircle, FiDollarSign, FiBox, FiPlus } from 'react-icons/fi';
import { inventoryApi } from '../../api/inventoryApi';
import { purchasingApi } from '../../api/purchasingApi';
import useSettingsStore from '../../store/settingsStore';

const InventoryDashboard = () => {
    const [metrics, setMetrics] = useState({
        totalMaterials: 0,
        lowStockItems: 0,
        pendingPOs: 0,
        recentMovements: []
    });
    const [isLoading, setIsLoading] = useState(true);
    const navigate = useNavigate();

    const { settings } = useSettingsStore();

    useEffect(() => {
        const fetchDashboardData = async () => {
            try {
                const [matsRes, lowStockRes, poRes, movesRes] = await Promise.all([
                    inventoryApi.getMaterials(),
                    inventoryApi.getLowStock(),
                    purchasingApi.getOrders(),
                    inventoryApi.getMovements({ limit: 5 }) // Assuming backend supports pagination limits
                ]);

                // Calculate some frontend metrics
                const pendingOrders = poRes.data.filter(po => ['draft', 'confirmed', 'partially_received'].includes(po.status));

                setMetrics({
                    totalMaterials: matsRes.data.length,
                    lowStockItems: lowStockRes.data.data.length, // Nested because of custom action format
                    pendingPOs: pendingOrders.length,
                    recentMovements: movesRes.data.results || movesRes.data.slice(0, 5) // Fallback if no pagination wrapper
                });
            } catch (error) {
                console.error("Dashboard feed error:", error);
            } finally {
                setIsLoading(false);
            }
        };

        fetchDashboardData();
    }, []);

    const StatCard = ({ title, value, icon: Icon, colorClass }) => (
        <div className="glass-panel p-6 flex items-center space-x-4">
            <div className={`p-4 rounded-xl ${colorClass}`}>
                <Icon className="w-8 h-8" />
            </div>
            <div>
                <p className="text-sm font-medium text-textMuted uppercase tracking-wider">{title}</p>
                <div className="flex items-baseline space-x-2">
                    <h3 className="text-3xl font-bold text-white mt-1">{value}</h3>
                </div>
            </div>
        </div>
    );

    if (isLoading) {
        return (
            <div className="p-6">
                <div className="h-8 w-64 bg-white/5 rounded animate-pulse mb-8"></div>
                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
                    {[1, 2, 3, 4].map(i => <div key={i} className="h-32 bg-white/5 rounded-xl animate-pulse"></div>)}
                </div>
            </div>
        );
    }

    return (
        <div className="p-6 max-w-7xl mx-auto space-y-8">
            <div>
                <h1 className="text-3xl font-bold bg-clip-text text-transparent bg-gradient-to-r from-primary to-accent">
                    Inventory Overview
                </h1>
                <p className="text-textMuted mt-1">Real-time metrics and alerts for your stock.</p>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
                <StatCard 
                    title="Tracked Items" 
                    value={metrics.totalMaterials} 
                    icon={FiBox} 
                    colorClass="bg-blue-500/20 text-blue-400" 
                />
                <StatCard 
                    title="Low Stock Alerts" 
                    value={metrics.lowStockItems} 
                    icon={FiAlertCircle} 
                    colorClass="bg-red-500/20 text-red-400" 
                />
                <StatCard 
                    title="Active Orders" 
                    value={metrics.pendingPOs} 
                    icon={FiTrendingDown} 
                    colorClass="bg-yellow-500/20 text-yellow-400" 
                />
                <StatCard 
                    title="Total Value" 
                    value="---" // Would require a specific backend endpoint to calculate precisely
                    icon={FiDollarSign} 
                    colorClass="bg-green-500/20 text-green-400" 
                />
            </div>

            <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
                {/* Recent Activity Log */}
                <div className="lg:col-span-2 glass-panel p-6">
                    <h2 className="text-xl font-bold text-white mb-6">Recent Stock Movements</h2>
                    <div className="space-y-4">
                        {metrics.recentMovements.length === 0 ? (
                            <p className="text-textMuted text-center py-8">No recent activity detected.</p>
                        ) : metrics.recentMovements.map(movement => (
                            <div key={movement.id} className="flex items-center justify-between p-4 bg-white/5 rounded-lg">
                                <div className="flex items-center space-x-4">
                                    <div className={`p-2 rounded-full ${
                                        movement.movement_type === 'purchase' || movement.movement_type === 'manual_adjustment' && parseFloat(movement.quantity) > 0
                                            ? 'bg-green-500/20 text-green-400' 
                                            : 'bg-red-500/20 text-red-400'
                                    }`}>
                                        <FiTrendingDown className={`w-5 h-5 ${
                                            movement.movement_type === 'purchase' || movement.movement_type === 'manual_adjustment' && parseFloat(movement.quantity) > 0 
                                                ? 'rotate-180' 
                                                : ''
                                            }`} 
                                        />
                                    </div>
                                    <div>
                                        <p className="font-semibold text-white">{movement.raw_material_name}</p>
                                        <p className="text-xs text-textMuted flex items-center space-x-2">
                                            <span className="uppercase tracking-wider">{movement.movement_type.replace('_', ' ')}</span>
                                            <span>•</span>
                                            <span>{new Date(movement.created_at).toLocaleString()}</span>
                                        </p>
                                    </div>
                                </div>
                                <div className="text-right">
                                    <p className={`font-bold font-mono ${
                                        movement.movement_type === 'purchase' || movement.movement_type === 'manual_adjustment' && parseFloat(movement.quantity) > 0
                                            ? 'text-green-400' 
                                            : 'text-red-400'
                                    }`}>
                                        {parseFloat(movement.quantity) > 0 ? '+' : ''}{parseFloat(movement.quantity)}
                                    </p>
                                </div>
                            </div>
                        ))}
                    </div>
                </div>

                {/* Quick Actions */}
                <div className="space-y-6">
                    <div className="glass-panel p-6">
                        <h2 className="text-xl font-bold text-white mb-4">Quick Actions</h2>
                        <div className="space-y-3">
                            <button 
                                onClick={() => navigate('/inventory/waste')}
                                className="w-full text-left px-4 py-3 bg-white/5 hover:bg-white/10 rounded-lg transition-colors flex items-center justify-between group"
                            >
                                <span className="font-medium text-white">Log Waste</span>
                                <FiPlus className="text-textMuted group-hover:text-primary transition-colors" />
                            </button>
                            <button 
                                onClick={() => navigate('/inventory/counts')}
                                className="w-full text-left px-4 py-3 bg-white/5 hover:bg-white/10 rounded-lg transition-colors flex items-center justify-between group"
                            >
                                <span className="font-medium text-white">Start Physical Count</span>
                                <FiPlus className="text-textMuted group-hover:text-primary transition-colors" />
                            </button>
                        </div>
                    </div>
                </div>
            </div>
        </div>
    );
};

export default InventoryDashboard;

import React, { useState, useEffect, useMemo } from 'react';
import { useForm, useFieldArray } from 'react-hook-form';
import { yupResolver } from '@hookform/resolvers/yup';
import * as yup from 'yup';
import toast from 'react-hot-toast';
import { FiPlus, FiTrash2, FiEye, FiCheckCircle } from 'react-icons/fi';
import DataTable from '../../components/DataTable';
import ConfirmModal from '../../components/ConfirmModal';
import { inventoryApi } from '../../api/inventoryApi';

const countSchema = yup.object().shape({
  notes: yup.string(),
  items: yup.array().of(
    yup.object().shape({
      raw_material: yup.string().required('Material is required'),
      counted_quantity: yup.number().min(0, 'Cannot be negative').required('Required'),
    })
  ).min(1, 'At least one item is required')
});

const PhysicalCounts = () => {
    const [counts, setCounts] = useState([]);
    const [materials, setMaterials] = useState([]);
    const [isLoading, setIsLoading] = useState(true);
    
    // Modals
    const [isCreateModalOpen, setIsCreateModalOpen] = useState(false);
    const [viewCount, setViewCount] = useState(null);
    const [confirmAction, setConfirmAction] = useState({ open: false, count: null });

    const { register, control, handleSubmit, reset, formState: { errors } } = useForm({
        resolver: yupResolver(countSchema),
        defaultValues: { items: [] }
    });

    const { fields, append, remove, replace } = useFieldArray({
        control,
        name: "items"
    });

    const fetchData = async () => {
        setIsLoading(true);
        try {
            const [countsRes, matRes] = await Promise.all([
                inventoryApi.getCounts(),
                inventoryApi.getMaterials()
            ]);
            setCounts(countsRes.data);
            setMaterials(matRes.data);
        } catch (error) {
            toast.error('Failed to load physical counts');
        } finally {
            setIsLoading(false);
        }
    };

    useEffect(() => {
        fetchData();
    }, []);

    const handlePreFill = () => {
        // Pre-fill the count form with ALL active materials, initializing current stock
        const allItems = materials.filter(m => m.is_active).map(m => ({
            raw_material: m.id,
            counted_quantity: parseFloat(m.current_stock) || 0
        }));
        replace(allItems);
    };

    const onSubmit = async (data) => {
        try {
            await inventoryApi.createCount(data);
            toast.success('Physical count drafted. Review it before completion.');
            setIsCreateModalOpen(false);
            fetchData();
        } catch (error) {
             toast.error('Failed to draft physical count');
        }
    };

    const handleComplete = async () => {
        try {
            await inventoryApi.completeCount(confirmAction.count.id);
            toast.success('Physical count completed. Variances logged and stock updated.');
            setConfirmAction({ open: false, count: null });
            setViewCount(null);
            fetchData();
        } catch (e) {
            toast.error(e.response?.data?.error || `Failed to complete count`);
            setConfirmAction({ open: false, count: null });
        }
    };

    const columns = useMemo(() => [
        {
            header: 'Date Counted',
            accessorFn: row => new Date(row.count_date).toLocaleDateString(),
            cell: info => <span className="font-semibold">{info.getValue()}</span>
        },
        {
            header: 'Status',
            accessorKey: 'status',
            cell: info => {
                const status = info.getValue();
                return (
                    <span className={`px-2 py-1 rounded-full text-xs font-medium uppercase tracking-wider ${status === 'completed' ? 'bg-green-500/20 text-green-400' : 'bg-yellow-500/20 text-yellow-400'}`}>
                        {status}
                    </span>
                )
            }
        },
        {
            header: 'Items Counted',
            accessorFn: row => row.items?.length || 0,
        },
        {
            header: 'Conducted By',
            accessorKey: 'conducted_by_name',
        },
        {
            header: 'Actions',
            id: 'actions',
            cell: info => (
                <button 
                    onClick={(e) => { e.stopPropagation(); setViewCount(info.row.original); }}
                    className="p-1.5 bg-white/5 text-white rounded hover:bg-white/10 transition-colors"
                >
                    <FiEye className="w-4 h-4" />
                </button>
            )
        }
    ], []);

    return (
        <div className="p-6">
            <div className="flex justify-between items-center mb-6">
                <h1 className="text-2xl font-bold text-white">Physical Counts (Reconciliation)</h1>
                <button 
                    onClick={() => {
                        reset({ items: [] });
                        setIsCreateModalOpen(true);
                        setTimeout(handlePreFill, 50); // Pre-fill with all items
                    }}
                    className="bg-primary hover:bg-primary/90 text-white px-4 py-2 rounded-lg font-medium transition-colors flex items-center space-x-2"
                >
                    <FiPlus className="w-5 h-5" />
                    <span>Start Full Count</span>
                </button>
            </div>

            <DataTable 
                columns={columns} 
                data={counts} 
                isLoading={isLoading}
                searchPlaceholder="Search counts..."
            />

            {/* Create Count Modal */}
            {isCreateModalOpen && (
                <div className="fixed inset-0 z-50 flex items-center justify-center p-4">
                    <div className="fixed inset-0 bg-black/60 backdrop-blur-sm" onClick={() => setIsCreateModalOpen(false)}></div>
                    <div className="relative glass-panel w-full max-w-4xl p-6 max-h-[90vh] flex flex-col">
                        <h2 className="text-xl font-bold text-white mb-2">Step 1: Record Physical Stock</h2>
                        <p className="text-textMuted text-sm mb-6">
                            Enter the exact quantities currently sitting on your shelves. 
                            The system will save this as a <strong>'Draft'</strong> so you can review the differences (variances) and approve them before your inventory is permanently adjusted.
                        </p>
                        
                        <form onSubmit={handleSubmit(onSubmit)} className="space-y-4 flex-1 flex flex-col overflow-hidden">
                            <div>
                                <label className="block text-sm font-medium text-textMuted mb-1">Notes / Area Covered</label>
                                <input {...register('notes')} className="form-input" placeholder="e.g. Fridge A & Dry Storage" />
                            </div>

                            <div className="flex-1 overflow-y-auto border border-white/10 rounded-lg p-4 bg-white/5 mt-4">
                                <div className="space-y-3">
                                    <div className="grid grid-cols-12 gap-2 text-xs font-semibold text-textMuted uppercase tracking-wider px-2 sticky top-0 bg-[#16213e] py-2 z-10">
                                        <div className="col-span-1">#</div>
                                        <div className="col-span-5">Material</div>
                                        <div className="col-span-3 text-center">System Stock</div>
                                        <div className="col-span-3 text-center">Actual Counted</div>
                                    </div>
                                    {fields.map((field, index) => {
                                        const material = materials.find(m => m.id === field.raw_material);
                                        return (
                                            <div key={field.id} className="grid grid-cols-12 gap-4 items-center p-2 border-b border-white/5 last:border-0 hover:bg-white/5 transition-colors">
                                                <div className="col-span-1 text-textMuted text-sm">{index + 1}</div>
                                                <div className="col-span-5">
                                                    <select {...register(`items.${index}.raw_material`)} className="form-input text-sm py-1" style={{ pointerEvents: 'none', appearance: 'none' }} tabIndex="-1" readOnly>
                                                        {materials.map(m => (
                                                            <option key={m.id} value={m.id}>{m.name}</option>
                                                        ))}
                                                    </select>
                                                </div>
                                                <div className="col-span-3 text-center font-mono text-textMuted text-sm">
                                                    {parseFloat(material?.current_stock || 0)} {material?.unit?.abbreviation}
                                                </div>
                                                <div className="col-span-3">
                                                    <input type="number" step="0.001" {...register(`items.${index}.counted_quantity`)} className="form-input text-center font-bold text-accent" />
                                                </div>
                                            </div>
                                        )
                                    })}
                                </div>
                            </div>

                            <div className="flex justify-between items-center pt-4 mt-4">
                                <button type="button" onClick={() => append({ raw_material: '', counted_quantity: 0 })} className="text-sm text-primary hover:text-primary/80 flex items-center space-x-1">
                                    <FiPlus /> <span>Add Unlisted Item</span>
                                </button>
                                <div className="flex space-x-3">
                                    <button type="button" onClick={() => setIsCreateModalOpen(false)} className="px-5 py-2 rounded-lg text-textMuted hover:bg-white/5 transition-colors">
                                        Discard
                                    </button>
                                    <button type="submit" className="bg-primary hover:bg-primary/90 text-white px-6 py-2 rounded-lg font-medium shadow-lg transition-all">
                                        Save for Review (Draft)
                                    </button>
                                </div>
                            </div>
                        </form>
                    </div>
                </div>
            )}

            {/* View Count Modal */}
            {viewCount && (
                <div className="fixed inset-0 z-50 flex items-center justify-center p-4">
                    <div className="fixed inset-0 bg-black/60 backdrop-blur-sm" onClick={() => setViewCount(null)}></div>
                    <div className="relative glass-panel w-full max-w-3xl p-6">
                        <div className="flex justify-between items-start mb-6">
                            <div>
                                <h2 className="text-2xl font-bold text-white tracking-tight">Step 2: Variance Review</h2>
                                <p className="text-textMuted mt-1">Conducted By: {viewCount.conducted_by_name} on {new Date(viewCount.count_date).toLocaleDateString()}</p>
                            </div>
                            <span className={`px-3 py-1 rounded-full uppercase tracking-wider text-xs font-bold ${viewCount.status === 'completed' ? 'bg-green-500/20 text-green-400' : 'bg-yellow-500/20 text-yellow-400'}`}>
                                {viewCount.status}
                            </span>
                        </div>
                        
                        <div className="glass-panel p-4 mb-6 max-h-[50vh] overflow-y-auto">
                            <table className="w-full text-left text-sm">
                                <thead className="sticky top-0 bg-[#16213e]">
                                    <tr className="border-b border-white/10 text-textMuted">
                                        <th className="pb-2 font-medium">Material</th>
                                        <th className="pb-2 font-medium text-center">System Qty</th>
                                        <th className="pb-2 font-medium text-center">Actual Count</th>
                                        <th className="pb-2 font-medium text-right">Variance</th>
                                    </tr>
                                </thead>
                                <tbody className="divide-y divide-white/5">
                                    {viewCount.items?.map(item => {
                                        const sys = parseFloat(item.system_quantity);
                                        const actual = parseFloat(item.counted_quantity);
                                        const variance = parseFloat(item.variance);
                                        return (
                                            <tr key={item.id}>
                                                <td className="py-3 text-white">{item.raw_material_name}</td>
                                                <td className="py-3 text-center text-textMuted">{sys}</td>
                                                <td className="py-3 text-center font-bold">{actual}</td>
                                                <td className={`py-3 text-right font-bold ${variance < 0 ? 'text-red-400' : variance > 0 ? 'text-green-400' : 'text-textMuted'}`}>
                                                    {variance > 0 ? '+' : ''}{variance}
                                                </td>
                                            </tr>
                                        )
                                    })}
                                </tbody>
                            </table>
                        </div>

                        <div className="flex justify-between items-center pt-4 border-t border-white/10">
                            <div>
                                {viewCount.status === 'draft' && (
                                    <button 
                                        onClick={() => setConfirmAction({ open: true, count: viewCount })} 
                                        className="px-4 py-2 bg-primary/20 text-primary border border-primary/30 hover:bg-primary/30 rounded-lg flex items-center space-x-2 transition-colors font-medium"
                                    >
                                        <FiCheckCircle /> <span>Approve & Apply to Inventory</span>
                                    </button>
                                )}
                            </div>
                            <button onClick={() => setViewCount(null)} className="px-5 py-2 bg-white/5 hover:bg-white/10 text-white rounded-lg transition-colors">
                                Close
                            </button>
                        </div>
                    </div>
                </div>
            )}

            <ConfirmModal 
                isOpen={confirmAction.open}
                title="Approve Inventory Variances"
                message="Are you sure you want to APPLY these changes? Your system stock will be immediately adjusted up or down to match your physical count. This cannot be undone."
                onConfirm={handleComplete}
                onCancel={() => setConfirmAction({ open: false, count: null })}
                confirmText="Apply Changes"
            />
        </div>
    );
};

export default PhysicalCounts;

import React, { useState, useEffect } from 'react';
import { 
    FiX, FiTrendingUp, FiActivity, FiDollarSign, FiShoppingBag, FiCalendar 
} from 'react-icons/fi';
import { 
    LineChart, Line, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, 
    BarChart, Bar, Cell
} from 'recharts';
import { inventoryApi } from '../../api/inventoryApi';
import useSettingsStore from '../../store/settingsStore';
import { format, subDays } from 'date-fns';

export default function ProductAnalyticsModal({ product, onClose }) {
    const { settings } = useSettingsStore();
    const currency = settings?.currency || '$';
    const [data, setData] = useState(null);
    const [isLoading, setIsLoading] = useState(true);
    const [dateRange, setDateRange] = useState('30days'); // 7days, 30days, all

    useEffect(() => {
        if (product) fetchAnalytics();
    }, [product, dateRange]);

    const fetchAnalytics = async () => {
        setIsLoading(true);
        try {
            const params = {};
            if (dateRange !== 'all') {
                const days = dateRange === '7days' ? 7 : 30;
                params.start_date = format(subDays(new Date(), days), 'yyyy-MM-dd');
            }
            
            const res = await inventoryApi.getProductAnalytics(product.id, params);
            setData(res.data);
        } catch (error) {
            console.error("Failed to load analytics", error);
        } finally {
            setIsLoading(false);
        }
    };

    if (!product) return null;

    const COLORS = {
        'dine_in': '#3b82f6',
        'takeaway': '#10b981',
        'delivery': '#f59e0b'
    };

    return (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/60 backdrop-blur-sm px-4">
            <div className="glass-panel w-full max-w-4xl max-h-[90vh] flex flex-col overflow-hidden animate-fade-in-up">
                
                {/* Header */}
                <div className="flex items-center justify-between p-6 border-b border-white/10 shrink-0">
                    <div>
                        <h2 className="text-xl font-bold text-white flex items-center space-x-2">
                            <FiActivity className="text-primary" />
                            <span>Analytics: {product.name}</span>
                        </h2>
                        <p className="text-sm text-textMuted mt-1">Performance and sales metrics</p>
                    </div>
                    <button onClick={onClose} className="p-2 bg-white/5 hover:bg-white/10 rounded-full transition-colors">
                        <FiX className="w-5 h-5 text-textMuted hover:text-white" />
                    </button>
                </div>

                {/* Content */}
                <div className="p-6 overflow-y-auto custom-scrollbar flex-1 bg-gradient-to-b from-transparent to-black/20">
                    
                    {/* Filters */}
                    <div className="flex justify-end mb-6">
                        <div className="flex bg-black/20 rounded-lg p-1 border border-white/5">
                            <button 
                                onClick={() => setDateRange('7days')}
                                className={`px-4 py-1.5 text-sm rounded-md transition-colors ${dateRange === '7days' ? 'bg-primary text-white shadow-lg' : 'text-textMuted hover:text-white'}`}
                            >
                                Last 7 Days
                            </button>
                            <button 
                                onClick={() => setDateRange('30days')}
                                className={`px-4 py-1.5 text-sm rounded-md transition-colors ${dateRange === '30days' ? 'bg-primary text-white shadow-lg' : 'text-textMuted hover:text-white'}`}
                            >
                                Last 30 Days
                            </button>
                            <button 
                                onClick={() => setDateRange('all')}
                                className={`px-4 py-1.5 text-sm rounded-md transition-colors ${dateRange === 'all' ? 'bg-primary text-white shadow-lg' : 'text-textMuted hover:text-white'}`}
                            >
                                All Time
                            </button>
                        </div>
                    </div>

                    {isLoading ? (
                        <div className="flex flex-col items-center justify-center py-20">
                            <div className="w-10 h-10 border-4 border-primary border-t-transparent rounded-full animate-spin mb-4"></div>
                            <p className="text-textMuted">Crunching numbers...</p>
                        </div>
                    ) : !data ? (
                        <div className="text-center py-20 text-textMuted">No data available</div>
                    ) : (
                        <div className="space-y-6 animate-fade-in">
                            
                            {/* Summary Cards */}
                            <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                                <div className="bg-black/20 border border-white/10 p-5 rounded-2xl relative overflow-hidden group">
                                    <div className="absolute top-0 right-0 p-4 opacity-10 group-hover:opacity-20 transition-opacity">
                                        <FiShoppingBag className="w-16 h-16 text-primary" />
                                    </div>
                                    <p className="text-sm font-medium text-textMuted mb-1">Total Quantity Sold</p>
                                    <h3 className="text-3xl font-bold text-white relative z-10">{data.total_quantity} <span className="text-base font-normal text-textMuted">units</span></h3>
                                </div>
                                <div className="bg-gradient-to-br from-green-500/10 to-transparent border border-green-500/20 p-5 rounded-2xl relative overflow-hidden group">
                                    <div className="absolute top-0 right-0 p-4 opacity-10 group-hover:opacity-20 transition-opacity">
                                        <FiDollarSign className="w-16 h-16 text-green-500" />
                                    </div>
                                    <p className="text-sm font-medium text-green-400 mb-1">Total Gross Revenue</p>
                                    <h3 className="text-3xl font-bold text-white relative z-10">{currency}{(data.total_revenue || 0).toFixed(2)}</h3>
                                </div>
                                <div className="bg-gradient-to-br from-blue-500/10 to-transparent border border-blue-500/20 p-5 rounded-2xl relative overflow-hidden group">
                                    <div className="absolute top-0 right-0 p-4 opacity-10 group-hover:opacity-20 transition-opacity">
                                        <FiTrendingUp className="w-16 h-16 text-blue-500" />
                                    </div>
                                    <p className="text-sm font-medium text-blue-400 mb-1">Estimated Net Profit</p>
                                    <h3 className="text-3xl font-bold text-white relative z-10">{currency}{(data.net_profit || 0).toFixed(2)}</h3>
                                    {product.cost_price === 0 && (
                                        <p className="text-xs text-yellow-500 mt-1 mt-2">Cost price is currently set to 0</p>
                                    )}
                                </div>
                            </div>

                            <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
                                {/* Sales Trend Chart */}
                                <div className="lg:col-span-2 glass-panel p-5 rounded-2xl border-white/5">
                                    <h3 className="text-white font-bold mb-6 flex items-center"><FiCalendar className="mr-2 text-textMuted"/> Sales Trend</h3>
                                    <div className="h-64">
                                        {data.sales_trend?.length > 0 ? (
                                            <ResponsiveContainer width="100%" height="100%">
                                                <LineChart data={data.sales_trend} margin={{ top: 5, right: 20, bottom: 5, left: 0 }}>
                                                    <CartesianGrid strokeDasharray="3 3" stroke="rgba(255,255,255,0.05)" vertical={false} />
                                                    <XAxis 
                                                        dataKey="date" 
                                                        stroke="#64748b" 
                                                        fontSize={12} 
                                                        tickMargin={10} 
                                                        axisLine={false} 
                                                        tickLine={false}
                                                    />
                                                    <YAxis 
                                                        yAxisId="left"
                                                        stroke="#64748b" 
                                                        fontSize={12} 
                                                        tickMargin={10}
                                                        axisLine={false}
                                                        tickLine={false}
                                                    />
                                                    <Tooltip 
                                                        contentStyle={{ backgroundColor: '#1e293b', borderColor: 'rgba(255,255,255,0.1)', borderRadius: '0.5rem', color: '#fff' }}
                                                        itemStyle={{ color: '#fff' }}
                                                    />
                                                    <Line 
                                                        yAxisId="left" 
                                                        type="monotone" 
                                                        dataKey="quantity" 
                                                        name="Qty Sold" 
                                                        stroke="#3b82f6" 
                                                        strokeWidth={3}
                                                        dot={{ r: 4, strokeWidth: 2, fill: '#1e293b' }} 
                                                        activeDot={{ r: 6, strokeWidth: 0 }} 
                                                    />
                                                </LineChart>
                                            </ResponsiveContainer>
                                        ) : (
                                            <div className="h-full flex items-center justify-center text-textMuted border border-dashed border-white/5 rounded-xl bg-white/5">
                                                No timeline data for this period
                                            </div>
                                        )}
                                    </div>
                                </div>

                                {/* Order Types Breakdown */}
                                <div className="glass-panel p-5 rounded-2xl border-white/5">
                                    <h3 className="text-white font-bold mb-6">Channel Breakdown</h3>
                                    <div className="h-64">
                                        {data.type_breakdown?.length > 0 ? (
                                            <ResponsiveContainer width="100%" height="100%">
                                                <BarChart data={data.type_breakdown} layout="vertical" margin={{ top: 0, right: 20, left: 10, bottom: 0 }}>
                                                    <CartesianGrid strokeDasharray="3 3" stroke="rgba(255,255,255,0.05)" horizontal={false} />
                                                    <XAxis type="number" hide />
                                                    <YAxis 
                                                        dataKey="order__order_type" 
                                                        type="category" 
                                                        axisLine={false} 
                                                        tickLine={false} 
                                                        tick={{fill: '#e2e8f0', fontSize: 12}}
                                                        width={70}
                                                        tickFormatter={(val) => val.charAt(0).toUpperCase() + val.slice(1).replace('_', '-')}
                                                    />
                                                    <Tooltip 
                                                        cursor={{fill: 'rgba(255,255,255,0.05)'}}
                                                        contentStyle={{ backgroundColor: '#1e293b', borderColor: 'rgba(255,255,255,0.1)', borderRadius: '0.5rem' }}
                                                    />
                                                    <Bar dataKey="count" name="Orders" radius={[0, 4, 4, 0]} barSize={20}>
                                                        {data.type_breakdown.map((entry, index) => (
                                                            <Cell key={`cell-${index}`} fill={COLORS[entry.order__order_type] || '#8b5cf6'} />
                                                        ))}
                                                    </Bar>
                                                </BarChart>
                                            </ResponsiveContainer>
                                        ) : (
                                            <div className="h-full flex items-center justify-center text-textMuted border border-dashed border-white/5 rounded-xl bg-white/5 text-center px-4">
                                                No channel data available
                                            </div>
                                        )}
                                    </div>
                                </div>
                            </div>
                        </div>
                    )}
                </div>
            </div>
        </div>
    );
}

import React, { useState, useEffect, useMemo } from 'react';
import { useForm, Controller } from 'react-hook-form';
import Select from 'react-select';
import { yupResolver } from '@hookform/resolvers/yup';
import * as yup from 'yup';
import toast from 'react-hot-toast';
import { 
    FiPlus, FiEdit2, FiTrash2, FiCoffee, FiUploadCloud, 
    FiArrowLeft, FiSettings, FiTag, FiLayers, FiBox, FiClock, FiStar, FiCalendar, FiDownload, FiX, FiCheck, FiActivity
} from 'react-icons/fi';
import { inventoryApi } from '../../api/inventoryApi';
import useSettingsStore from '../../store/settingsStore';
import DataTable from '../../components/DataTable';
import ConfirmModal from '../../components/ConfirmModal';
import ProductAnalyticsModal from './ProductAnalyticsModal';

const selectStyles = {
    control: (base, state) => ({
        ...base,
        background: 'rgba(255, 255, 255, 0.05)',
        borderColor: state.isFocused ? '#3b82f6' : 'rgba(255, 255, 255, 0.1)',
        color: '#fff',
        minHeight: '40px',
        boxShadow: 'none',
        borderRadius: '0.5rem',
        '&:hover': { borderColor: 'rgba(255, 255, 255, 0.2)' }
    }),
    menu: (base) => ({
        ...base,
        background: '#1e293b',
        border: '1px solid rgba(255, 255, 255, 0.1)',
        zIndex: 100
    }),
    option: (base, state) => ({
        ...base,
        background: state.isSelected ? 'rgba(59, 130, 246, 0.3)' : state.isFocused ? 'rgba(59, 130, 246, 0.1)' : 'transparent',
        color: state.isSelected ? '#fff' : '#cbd5e1',
        cursor: 'pointer',
        '&:active': { background: 'rgba(59, 130, 246, 0.4)' }
    }),
    singleValue: (base) => ({ ...base, color: '#fff' }),
    input: (base) => ({ ...base, color: '#fff' })
};

export default function Products() {
    const [view, setView] = useState('list'); // 'list' | 'builder'
    const [products, setProducts] = useState([]);
    const [categories, setCategories] = useState([]);
    const [recipes, setRecipes] = useState([]);
    const [rawMaterials, setRawMaterials] = useState([]);
    const [isLoading, setIsLoading] = useState(true);
    const [editingProduct, setEditingProduct] = useState(null);
    const { settings } = useSettingsStore();

    // Delete Modal
    const [deleteConfirmOpen, setDeleteConfirmOpen] = useState(false);
    const [productToDelete, setProductToDelete] = useState(null);
    
    // Import Modal
    const [importModalOpen, setImportModalOpen] = useState(false);

    // Analytics Modal
    const [analyticsProduct, setAnalyticsProduct] = useState(null);

    useEffect(() => {
        fetchData();
    }, []);

    const fetchData = async () => {
        setIsLoading(true);
        try {
            const [prodRes, catRes, recipesRes, materialsRes] = await Promise.all([
                inventoryApi.getProducts(),
                inventoryApi.getCategories(),
                inventoryApi.getRecipes(),
                inventoryApi.getMaterials()
            ]);
            setProducts(prodRes.data);
            setCategories(catRes.data);
            setRecipes(recipesRes.data);
            setRawMaterials(materialsRes.data);
        } catch (error) {
            toast.error("Failed to fetch initial data");
        } finally {
            setIsLoading(false);
        }
    };

    const confirmDelete = async () => {
        try {
            await inventoryApi.deleteProduct(productToDelete.id);
            toast.success("Product deleted");
            setDeleteConfirmOpen(false);
            fetchData();
        } catch (error) {
            toast.error("Failed to delete product (It might be currently used)");
        }
    };

    const columns = useMemo(() => [
        {
            header: 'Item',
            accessorFn: row => row.name,
            cell: info => (
                <div className="flex items-center space-x-3">
                    {info.row.original.image ? (
                        <img src={info.row.original.image} alt="product" className="w-10 h-10 rounded-lg object-cover border border-white/10" />
                    ) : (
                        <div className="w-10 h-10 rounded-lg bg-primary/20 flex items-center justify-center border border-primary/30">
                            <FiCoffee className="w-5 h-5 text-primary" />
                        </div>
                    )}
                    <div>
                        <p className="font-bold text-white leading-tight">{info.row.original.name}</p>
                        {info.row.original.name_ar && <p className="text-xs text-textMuted mt-0.5">{info.row.original.name_ar}</p>}
                    </div>
                </div>
            )
        },
        {
            header: 'Category',
            accessorFn: row => row.category_name,
            cell: info => <span className="uppercase text-xs tracking-wider bg-white/5 px-2 py-1 rounded">{info.getValue() || 'Uncategorized'}</span>
        },
        {
            header: 'Selling Price',
            accessorFn: row => `${settings?.currency || '$'}${parseFloat(row.price).toFixed(2)}`,
            cell: info => <span className="font-mono text-green-400 font-bold">{info.getValue()}</span>
        },
        {
            header: 'Status',
            accessorKey: 'availability_status',
            cell: info => {
                const map = {
                    'available': { label: 'Available', color: 'bg-green-500/20 text-green-400' },
                    'out_of_stock': { label: 'Out of Stock', color: 'bg-orange-500/20 text-orange-400' },
                    'hidden': { label: 'Hidden', color: 'bg-gray-500/20 text-gray-400' },
                };
                const status = map[info.getValue()] || map['hidden'];
                return (
                    <span className={`px-2 py-1 rounded-full text-xs font-medium ${status.color}`}>
                        {status.label}
                    </span>
                );
            }
        },
        {
            header: 'Actions',
            id: 'actions',
            cell: info => (
                <div className="flex space-x-2">
                    <button 
                        onClick={(e) => { 
                            e.stopPropagation(); 
                            setAnalyticsProduct(info.row.original);
                        }}
                        className="p-1.5 bg-blue-500/20 text-blue-400 hover:bg-blue-500/30 rounded transition-colors"
                        title="View Analytics"
                    >
                        <FiActivity className="w-4 h-4" />
                    </button>
                    <button 
                        onClick={(e) => { 
                            e.stopPropagation(); 
                            setEditingProduct(info.row.original);
                            setView('builder');
                        }}
                        className="p-1.5 bg-white/5 hover:bg-white/10 text-white rounded transition-colors"
                    >
                        <FiEdit2 className="w-4 h-4" />
                    </button>
                    <button 
                        onClick={(e) => { 
                            e.stopPropagation(); 
                            setProductToDelete(info.row.original);
                            setDeleteConfirmOpen(true);
                        }}
                        className="p-1.5 bg-red-500/20 text-red-400 rounded hover:bg-red-500/30 transition-colors"
                    >
                        <FiTrash2 className="w-4 h-4" />
                    </button>
                </div>
            )
        }
    ], [settings]);

    return (
        <div className="p-6">
            {view === 'list' ? (
                <>
                    <div className="flex justify-between items-center mb-6">
                        <div>
                             <h1 className="text-2xl font-bold text-white">Menu Products</h1>
                             <p className="text-sm text-textMuted mt-1">Manage core items, pricing tiers, and meal combos.</p>
                        </div>
                        <div className="flex items-center space-x-3">
                            <button 
                                onClick={() => setImportModalOpen(true)}
                                className="bg-[#1e293b] hover:bg-[#1e293b]/80 border border-white/10 text-white px-4 py-2 rounded-lg font-medium transition-colors flex items-center space-x-2"
                            >
                                <FiUploadCloud className="w-5 h-5 text-primary" />
                                <span>Bulk Import</span>
                            </button>
                            <button 
                                onClick={() => { setEditingProduct(null); setView('builder'); }}
                                className="bg-primary hover:bg-primary/90 text-white px-4 py-2 rounded-lg font-medium transition-colors flex items-center space-x-2 shadow-lg shadow-primary/20"
                            >
                                <FiPlus className="w-5 h-5" />
                                <span>New Product</span>
                            </button>
                        </div>
                    </div>

                    <DataTable 
                        columns={columns} 
                        data={products} 
                        isLoading={isLoading}
                        searchPlaceholder="Search products by name or category..."
                    />

                    {analyticsProduct && (
                        <ProductAnalyticsModal 
                            product={analyticsProduct} 
                            onClose={() => setAnalyticsProduct(null)} 
                        />
                    )}
                </>
            ) : (
                <ProductBuilder 
                    product={editingProduct} 
                    categories={categories}
                    allProducts={products}
                    recipes={recipes}
                    rawMaterials={rawMaterials}
                    currency={settings?.currency || '$'}
                    onBack={() => { setView('list'); fetchData(); }}
                />
            )}

            <ConfirmModal 
                isOpen={deleteConfirmOpen}
                title="Delete Product"
                message={`Are you sure you want to delete this product? This action cannot be undone.`}
                onConfirm={confirmDelete}
                onCancel={() => setDeleteConfirmOpen(false)}
                confirmText="Delete Product"
                isDestructive={true}
            />

            {/* Bulk Import Modal */}
            <ImportProductsModal 
                isOpen={importModalOpen} 
                onClose={() => setImportModalOpen(false)} 
                onSuccess={() => { setImportModalOpen(false); fetchData(); }} 
            />
        </div>
    );
}

// -------------------------------------------------------------
// BULK IMPORT MODAL (Two-Step process)
// -------------------------------------------------------------
const ImportProductsModal = ({ isOpen, onClose, onSuccess }) => {
    const [step, setStep] = useState(1);
    const [file, setFile] = useState(null);
    const [isProcessing, setIsProcessing] = useState(false);
    const [previewData, setPreviewData] = useState([]);

    if (!isOpen) return null;

    const resetModal = () => {
        setStep(1);
        setFile(null);
        setPreviewData([]);
        onClose();
    };

    const handleDownloadTemplate = async () => {
        try {
            const toastId = toast.loading("Downloading template...");
            const response = await inventoryApi.exportProductsTemplate();
            const url = window.URL.createObjectURL(new Blob([response.data]));
            const link = document.createElement('a');
            link.href = url;
            link.setAttribute('download', 'products_template.xlsx');
            document.body.appendChild(link);
            link.click();
            link.remove();
            toast.success("Template downloaded", { id: toastId });
        } catch (error) {
            toast.error("Failed to download template");
        }
    };

    const handlePreview = async () => {
        if (!file) return toast.error("Please select an Excel file first");
        
        const formData = new FormData();
        formData.append('file', file);
        
        setIsProcessing(true);
        const toastId = toast.loading("Parsing Excel file...");
        
        try {
            const response = await inventoryApi.importBulkProducts(formData);
            if (response.data.success && response.data.data.length > 0) {
                toast.success("File parsed! Please review the data.", { id: toastId });
                setPreviewData(response.data.data);
                setStep(2);
            } else {
                toast.error("No valid data found in the file", { id: toastId });
            }
        } catch (error) {
            toast.error(error.response?.data?.detail || "Failed to parse the file.", { id: toastId });
        } finally {
            setIsProcessing(false);
        }
    };

    const handleConfirmImport = async () => {
        setIsProcessing(true);
        const toastId = toast.loading("Importing products...");
        try {
            const response = await inventoryApi.confirmBulkProducts(previewData);
            if (response.data.success) {
                toast.success(response.data.message, { id: toastId });
                if (response.data.errors?.length > 0) {
                    toast.error(`Some rows failed: ${response.data.errors.length} errors. Check console.`, { duration: 5000 });
                    console.warn("Import Errors:", response.data.errors);
                }
                onSuccess();
                resetModal();
            } else {
                toast.error(response.data.detail || "Import failed", { id: toastId });
            }
        } catch (error) {
            toast.error(error.response?.data?.detail || "Import failed during saving.", { id: toastId });
        } finally {
            setIsProcessing(false);
        }
    };

    const handleCellChange = (rowIndex, field, value) => {
        const newData = [...previewData];
        newData[rowIndex][field] = value;
        setPreviewData(newData);
    };

    return (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/60 backdrop-blur-sm animate-fade-in-up">
            <div className={`bg-[#1e293b] rounded-2xl border border-white/10 shadow-2xl overflow-hidden flex flex-col transition-all duration-300 ${step === 2 ? 'w-full max-w-5xl' : 'w-full max-w-md'}`}>
                <div className="p-5 border-b border-white/10 flex justify-between items-center bg-[#0f172a] shrink-0">
                    <h3 className="text-xl font-black text-white flex items-center space-x-2">
                        <FiUploadCloud className="text-primary" /> 
                        <span>{step === 1 ? 'Bulk Import' : 'Review & Edit Data'}</span>
                    </h3>
                    <button onClick={resetModal} className="text-textMuted hover:text-white bg-white/5 p-2 rounded-lg transition-colors">
                        <FiX />
                    </button>
                </div>
                
                {step === 1 ? (
                    <>
                        <div className="p-6 space-y-6">
                            <div className="bg-primary/10 border border-primary/20 rounded-xl p-4 flex flex-col items-center justify-center text-center">
                                <p className="text-sm text-white font-medium mb-3">1. Download the Excel template</p>
                                <button 
                                    onClick={handleDownloadTemplate}
                                    className="bg-primary/20 hover:bg-primary/30 text-primary border border-primary/30 px-4 py-2 rounded-lg text-sm font-bold flex items-center space-x-2 transition-colors"
                                >
                                    <FiDownload /> <span>Download Template.xlsx</span>
                                </button>
                                <p className="text-xs text-textMuted mt-3">Fill in your product details exactly as structured in the downloaded file.</p>
                            </div>

                            <div className="border border-white/10 rounded-xl p-4 flex flex-col items-center justify-center text-center">
                                <p className="text-sm text-white font-medium mb-3">2. Upload filled Excel file</p>
                                <div className="w-full relative">
                                    <input 
                                        type="file" 
                                        accept=".xlsx, .xls" 
                                        onChange={(e) => setFile(e.target.files[0])}
                                        className="absolute inset-0 w-full h-full opacity-0 cursor-pointer z-10"
                                    />
                                    <div className={`w-full py-4 rounded-lg border-2 border-dashed transition-colors flex flex-col items-center justify-center ${file ? 'border-green-500/50 bg-green-500/10' : 'border-white/20 bg-white/5 hover:border-primary/50'}`}>
                                        <FiUploadCloud className={`w-6 h-6 mb-2 ${file ? 'text-green-400' : 'text-textMuted'}`} />
                                        <span className={`text-sm font-bold ${file ? 'text-green-400' : 'text-textMuted'}`}>
                                            {file ? file.name : 'Click to browse or drag file here'}
                                        </span>
                                    </div>
                                </div>
                            </div>
                        </div>

                        <div className="p-5 border-t border-white/10 bg-[#0f172a]">
                            <button 
                                onClick={handlePreview}
                                disabled={!file || isProcessing}
                                className="w-full bg-primary hover:bg-primary/90 disabled:opacity-50 text-white font-black py-3 rounded-xl shadow-[0_0_15px_rgba(59,130,246,0.3)] transition-all flex justify-center items-center space-x-2"
                            >
                                {isProcessing ? (
                                    <div className="animate-spin rounded-full h-5 w-5 border-b-2 border-white"></div>
                                ) : (
                                    <>
                                        <span>Preview Data</span> <FiArrowLeft className="rotate-180" />
                                    </>
                                )}
                            </button>
                        </div>
                    </>
                ) : (
                    <>
                        <div className="p-6 overflow-y-auto max-h-[70vh]">
                            <table className="w-full text-left text-sm whitespace-nowrap">
                                <thead>
                                    <tr className="border-b border-white/10 text-textMuted">
                                        <th className="pb-3 px-2 font-medium">Name (EN)</th>
                                        <th className="pb-3 px-2 font-medium">Name (AR)</th>
                                        <th className="pb-3 px-2 font-medium">Cat. ID</th>
                                        <th className="pb-3 px-2 font-medium">Price</th>
                                        <th className="pb-3 px-2 font-medium">Cost Price</th>
                                        <th className="pb-3 px-2 font-medium min-w-[200px]">Description</th>
                                    </tr>
                                </thead>
                                <tbody>
                                    {previewData.map((row, idx) => (
                                        <tr key={row.id} className="border-b border-white/5 hover:bg-white/5 transition-colors">
                                            <td className="p-2">
                                                <input type="text" value={row.name} onChange={(e) => handleCellChange(idx, 'name', e.target.value)} className="input py-1 px-2 w-full text-sm" />
                                            </td>
                                            <td className="p-2">
                                                <input type="text" value={row.name_ar} onChange={(e) => handleCellChange(idx, 'name_ar', e.target.value)} className="input py-1 px-2 w-full text-sm" dir="rtl" />
                                            </td>
                                            <td className="p-2">
                                                <input type="text" value={row.cat_id} onChange={(e) => handleCellChange(idx, 'cat_id', e.target.value)} className="input py-1 px-2 w-16 text-sm text-center" />
                                            </td>
                                            <td className="p-2">
                                                <input type="number" step="0.01" value={row.price} onChange={(e) => handleCellChange(idx, 'price', e.target.value)} className="input py-1 px-2 w-24 text-sm" />
                                            </td>
                                            <td className="p-2">
                                                <input type="number" step="0.01" value={row.cost_price} onChange={(e) => handleCellChange(idx, 'cost_price', e.target.value)} className="input py-1 px-2 w-24 text-sm" />
                                            </td>
                                            <td className="p-2">
                                                <input type="text" value={row.description} onChange={(e) => handleCellChange(idx, 'description', e.target.value)} className="input py-1 px-2 w-full text-sm" />
                                            </td>
                                        </tr>
                                    ))}
                                </tbody>
                            </table>
                        </div>
                        <div className="p-5 border-t border-white/10 bg-[#0f172a] flex justify-between items-center">
                            <button onClick={() => setStep(1)} className="btn hover:bg-white/5 text-textMuted flex items-center space-x-2">
                                <FiArrowLeft /> <span>Back to Upload</span>
                            </button>
                            <button 
                                onClick={handleConfirmImport}
                                disabled={isProcessing}
                                className="bg-green-500 hover:bg-green-600 disabled:opacity-50 text-white px-6 py-2.5 rounded-xl font-bold flex items-center space-x-2 transition-colors shadow-lg shadow-green-500/20"
                            >
                                {isProcessing ? (
                                    <div className="animate-spin rounded-full h-5 w-5 border-b-2 border-white"></div>
                                ) : (
                                    <>
                                        <FiCheck /> <span>Confirm & Import {previewData.length} Products</span>
                                    </>
                                )}
                            </button>
                        </div>
                    </>
                )}
            </div>
        </div>
    );
};

// -------------------------------------------------------------
// PRODUCT BUILDER (MULTI-TAB)
// -------------------------------------------------------------
const ProductBuilder = ({ product, categories, allProducts, recipes, rawMaterials, currency, onBack }) => {
    const [activeTab, setActiveTab] = useState('basic');
    const [imageFile, setImageFile] = useState(null);
    const [isSaving, setIsSaving] = useState(false);

    // Form Data overriding specific defaults
    const [formData, setFormData] = useState({
        name: product?.name || '',
        name_ar: product?.name_ar || '',
        description: product?.description || '',
        category: product?.category || '',
        price: product?.price || 0,
        price_takeaway: product?.price_takeaway || '',
        price_delivery: product?.price_delivery || '',
        cost_price: product?.cost_price || 0,
        linked_raw_material: product?.linked_raw_material || '',
        availability_status: product?.availability_status || 'available',
        preparation_time: product?.preparation_time || 5, // minutes
        is_popular: product?.is_popular || false,
        is_seasonal: product?.is_seasonal || false,
        season_start_date: product?.season_start_date || '',
        season_end_date: product?.season_end_date || '',
    });

    const [variations, setVariations] = useState(
        (product?.variations || []).map(v => ({ ...v, _localId: Math.random().toString(36).substr(2, 9) }))
    );
    const [deletedVariations, setDeletedVariations] = useState([]);

    const [comboItems, setComboItems] = useState(
        (product?.combo_items || []).map(c => ({ ...c, _localId: Math.random().toString(36).substr(2, 9) }))
    );
    const [deletedComboItems, setDeletedComboItems] = useState([]);

    const catOptions = buildCategoryOptions(categories);

    function buildCategoryOptions(cats) {
        // Flatten categories for react-select, showing hierarchical names gracefully
        const flatList = [];
        const catMap = {};
        cats.forEach(c => catMap[c.id] = { ...c, children: [] });
        const roots = [];
        cats.forEach(c => {
            if (c.parent) { if (catMap[c.parent]) catMap[c.parent].children.push(catMap[c.id]); }
            else { roots.push(catMap[c.id]); }
        });

        const processNode = (nodes, prefix = '') => {
            nodes.sort((a,b) => a.order - b.order || a.name.localeCompare(b.name));
            nodes.forEach(n => {
                flatList.push({ value: n.id, label: `${prefix}${n.name}` });
                processNode(n.children, prefix + '— ');
            });
        };
        processNode(roots);
        return flatList;
    }

    const handleChange = (e) => {
        const { name, value, type, checked } = e.target;
        setFormData(prev => ({
            ...prev,
            [name]: type === 'checkbox' ? checked : value
        }));
    };

    const handleSave = async () => {
        if (!formData.name || !formData.category || formData.price === '') {
            toast.error("Name, Category, and Price are required.");
            return;
        }

        setIsSaving(true);
        const toastId = toast.loading("Saving product details...");

        try {
            // 1. Save Base Product
            const pData = new FormData();
            Object.keys(formData).forEach(key => {
                if (formData[key] !== '' && formData[key] !== null) {
                    pData.append(key, formData[key]);
                } else if (key === 'linked_raw_material' && formData[key] === '') {
                    // Send an empty string explicitely so DRF clears the foreign key
                    pData.append(key, '');
                }
            });
            if (imageFile) {
                pData.append('image', imageFile);
            }

            let savedProduct;
            if (product?.id) {
                const res = await inventoryApi.updateProduct(product.id, pData);
                savedProduct = res.data;
            } else {
                const res = await inventoryApi.createProduct(pData);
                savedProduct = res.data;
            }

            // 2. Process Variations
            // Delete removed
            for (const id of deletedVariations) {
                await inventoryApi.deleteVariation(id);
            }
            // Add / Edit current
            for (const v of variations) {
                const payload = {
                    product: savedProduct.id,
                    size_name: v.size_name,
                    price: v.price || 0,
                    price_takeaway: v.price_takeaway || null,
                    price_delivery: v.price_delivery || null,
                    cost_price: v.cost_price || 0,
                    is_active: true
                };
                if (v.id) {
                    await inventoryApi.updateVariation(v.id, payload);
                } else {
                    await inventoryApi.createVariation(payload);
                }
            }

            // 3. Process Combos
            for (const id of deletedComboItems) {
                await inventoryApi.deleteComboItem(id);
            }
            for (const c of comboItems) {
                const payload = {
                    parent_combo: savedProduct.id,
                    child_product: c.child_product,
                    quantity: c.quantity || 1,
                    extra_price: c.extra_price || 0
                };
                if (c.id) {
                    await inventoryApi.updateComboItem(c.id, payload);
                } else {
                    await inventoryApi.createComboItem(payload);
                }
            }

            toast.success("Menu Builder Saved Successfully!", { id: toastId });
            onBack();
        } catch (error) {
            toast.error(error.response?.data?.detail || "Failed to save entire product configuration.", { id: toastId });
        } finally {
            setIsSaving(false);
        }
    };

    return (
        <div className="space-y-6 animate-fade-in-up">
            <div className="flex items-center space-x-4 mb-6">
                <button onClick={onBack} className="p-2 bg-white/5 hover:bg-white/10 rounded-full transition-colors text-textMuted hover:text-white">
                    <FiArrowLeft className="w-5 h-5" />
                </button>
                <div>
                    <h1 className="text-2xl font-bold text-white">{product ? 'Menu Builder: ' + product.name : 'New Menu Item'}</h1>
                    <p className="text-textMuted text-sm">Configure multi-tab details</p>
                </div>
            </div>

            <div className="flex flex-col lg:flex-row gap-6 items-start">
                
                {/* Tabs Sidebar */}
                <div className="w-full lg:w-48 xl:w-64 flex lg:flex-col space-x-2 lg:space-x-0 lg:space-y-2 overflow-x-auto pb-2 lg:pb-0 shrink-0">
                    <TabBtn active={activeTab === 'basic'} onClick={() => setActiveTab('basic')} icon={<FiTag />} label="Basic Info" />
                    <TabBtn active={activeTab === 'pricing'} onClick={() => setActiveTab('pricing')} icon={<FiBox />} label="Pricing & Sizes" />
                    <TabBtn active={activeTab === 'recipes'} onClick={() => setActiveTab('recipes')} icon={<FiCoffee />} label="Recipes & Cost" />
                    <TabBtn active={activeTab === 'combos'} onClick={() => setActiveTab('combos')} icon={<FiLayers />} label="Combo Meals" />
                    <TabBtn active={activeTab === 'settings'} onClick={() => setActiveTab('settings')} icon={<FiSettings />} label="Settings" />
                </div>

                {/* Content Area */}
                <div className="flex-1 glass-panel p-6 w-full lg:min-h-[500px] flex flex-col justify-between">
                    <div className="space-y-6">
                        {activeTab === 'basic' && (
                            <div className="space-y-6">
                                <h3 className="text-lg font-bold text-white mb-4 border-b border-white/10 pb-2">Basic Information</h3>
                                <div className="flex flex-col sm:flex-row gap-6">
                                    <div className="w-full sm:w-48 h-48 border-2 border-dashed border-white/10 hover:border-primary/50 rounded-xl flex flex-col items-center justify-center cursor-pointer relative overflow-hidden group shrink-0 transition-colors">
                                        <input type="file" accept="image/*" onChange={e => e.target.files?.[0] && setImageFile(e.target.files[0])} className="absolute inset-0 opacity-0 cursor-pointer z-10" />
                                        {imageFile ? (
                                            <img src={URL.createObjectURL(imageFile)} alt="Preview" className="w-full h-full object-cover absolute inset-0" />
                                        ) : product?.image ? (
                                            <img src={product.image} alt="Current" className="w-full h-full object-cover absolute inset-0" />
                                        ) : (
                                            <>
                                                <FiUploadCloud className="w-8 h-8 text-textMuted mb-2 group-hover:text-primary transition-colors" />
                                                <span className="text-sm font-medium">Upload Image</span>
                                                <span className="text-xs text-textMuted mt-1 px-4 text-center">PNG, JPG up to 2MB</span>
                                            </>
                                        )}
                                    </div>
                                    <div className="flex-1 space-y-4">
                                        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                                            <div>
                                                <label className="block text-sm font-medium text-textMuted mb-1">Name (EN) *</label>
                                                <input required type="text" name="name" value={formData.name} onChange={handleChange} className="input w-full" placeholder="Caramel Macchiato" />
                                            </div>
                                            <div>
                                                <label className="block text-sm font-medium text-textMuted mb-1">Name (AR)</label>
                                                <input type="text" name="name_ar" value={formData.name_ar} onChange={handleChange} className="input w-full text-right" dir="rtl" placeholder="كراميل ميكاتو" />
                                            </div>
                                        </div>
                                        <div>
                                            <label className="block text-sm font-medium text-textMuted mb-1">Menu Category *</label>
                                            <Select 
                                                options={catOptions} 
                                                styles={selectStyles}
                                                value={catOptions.find(o => o.value === formData.category)}
                                                onChange={v => setFormData({ ...formData, category: v.value })}
                                            />
                                        </div>
                                        <div>
                                            <label className="block text-sm font-medium text-textMuted mb-1">Public Description</label>
                                            <textarea name="description" value={formData.description} onChange={handleChange} className="input w-full min-h-[80px]" placeholder="Delicious notes..."></textarea>
                                        </div>
                                    </div>
                                </div>
                            </div>
                        )}

                        {activeTab === 'pricing' && (
                            <div className="space-y-8">
                                <div>
                                    <h3 className="text-lg font-bold text-white border-b border-white/10 pb-2 mb-4">Base Pricing</h3>
                                    <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
                                        <div>
                                            <label className="block text-sm font-medium text-textMuted mb-1">Selling Price ({currency}) *</label>
                                            <input required type="number" step="0.01" name="price" value={formData.price} onChange={handleChange} className="input w-full text-green-400 font-mono" />
                                        </div>
                                        <div>
                                            <label className="block text-sm font-medium text-textMuted mb-1">Takeaway Over. ({currency})</label>
                                            <input type="number" step="0.01" name="price_takeaway" value={formData.price_takeaway} onChange={handleChange} className="input w-full" placeholder="Optional" />
                                        </div>
                                        <div>
                                            <label className="block text-sm font-medium text-textMuted mb-1">Delivery Over. ({currency})</label>
                                            <input type="number" step="0.01" name="price_delivery" value={formData.price_delivery} onChange={handleChange} className="input w-full" placeholder="Optional" />
                                        </div>
                                        <div>
                                            <label className="block text-sm font-medium text-textMuted mb-1">Cost Price ({currency})</label>
                                            <input type="number" step="0.01" name="cost_price" value={formData.cost_price} onChange={handleChange} className="input w-full text-red-400 font-mono" />
                                        </div>
                                    </div>
                                </div>

                                <div>
                                    <div className="flex items-center justify-between border-b border-white/10 pb-2 mb-4">
                                        <h3 className="text-lg font-bold text-white">Size Variations</h3>
                                        <button 
                                            onClick={() => setVariations([...variations, { _localId: Date.now().toString(), size_name: '', price: 0 }])}
                                            className="btn btn-sm bg-white/5 hover:bg-white/10 text-xs flex items-center space-x-1"
                                        >
                                            <FiPlus /> <span>Add Size</span>
                                        </button>
                                    </div>
                                    {variations.length === 0 ? (
                                        <p className="text-textMuted text-sm italic">No variations enabled. The base pricing above will be used exclusively.</p>
                                    ) : (
                                        <div className="space-y-3">
                                            {variations.map((v, index) => (
                                                <div key={v._localId} className="flex flex-wrap items-center gap-3 bg-black/20 p-3 rounded-lg border border-white/5">
                                                    <div className="flex-1 min-w-[120px]">
                                                        <label className="text-xs text-textMuted block mb-1">Size Name (e.g. Large)</label>
                                                        <input type="text" value={v.size_name || ''} onChange={e => {
                                                            const n = [...variations]; n[index].size_name = e.target.value; setVariations(n);
                                                        }} className="input w-full text-sm py-1.5" />
                                                    </div>
                                                    <div className="w-24">
                                                        <label className="text-xs text-textMuted block mb-1">Price</label>
                                                        <input type="number" step="0.01" value={v.price || ''} onChange={e => {
                                                            const n = [...variations]; n[index].price = e.target.value; setVariations(n);
                                                        }} className="input w-full text-sm py-1.5 font-mono text-green-400" />
                                                    </div>
                                                    <div className="w-24">
                                                        <label className="text-xs text-textMuted block mb-1">Cost</label>
                                                        <input type="number" step="0.01" value={v.cost_price || ''} onChange={e => {
                                                            const n = [...variations]; n[index].cost_price = e.target.value; setVariations(n);
                                                        }} className="input w-full text-sm py-1.5 font-mono text-red-400" />
                                                    </div>
                                                    <button onClick={() => {
                                                        const n = [...variations];
                                                        if (n[index].id) setDeletedVariations([...deletedVariations, n[index].id]);
                                                        n.splice(index, 1);
                                                        setVariations(n);
                                                    }} className="mt-5 p-2 text-red-400 hover:bg-red-400/10 rounded transition-colors">
                                                        <FiTrash2 className="w-4 h-4" />
                                                    </button>
                                                </div>
                                            ))}
                                            <p className="text-xs text-textMuted mt-2 px-2">Note: POS will prompt for size selection if variations exist.</p>
                                        </div>
                                    )}
                                </div>
                            </div>
                        )}

                        {activeTab === 'combos' && (
                            <div className="space-y-6">
                                <div className="flex items-center justify-between border-b border-white/10 pb-2 mb-4">
                                    <div>
                                        <h3 className="text-lg font-bold text-white">Meal Combos</h3>
                                        <p className="text-xs text-textMuted mt-1">Select child products that make up this meal deal.</p>
                                    </div>
                                    <button 
                                        onClick={() => setComboItems([...comboItems, { _localId: Date.now().toString(), child_product: '', quantity: 1, extra_price: 0 }])}
                                        className="btn btn-sm bg-primary/20 hover:bg-primary/30 text-primary flex items-center space-x-1"
                                    >
                                        <FiPlus /> <span>Add Combo Item</span>
                                    </button>
                                </div>

                                {comboItems.length === 0 ? (
                                    <div className="text-center py-10 bg-black/20 rounded-xl border border-white/5 border-dashed">
                                        <FiLayers className="w-8 h-8 mx-auto text-textMuted mb-2" />
                                        <p className="text-textMuted">This is a standard product. Add items here to turn it into a Bundle/Meal.</p>
                                    </div>
                                ) : (
                                    <div className="space-y-3">
                                        {comboItems.map((c, index) => (
                                            <div key={c._localId} className="flex flex-wrap items-center gap-3 bg-black/20 p-3 rounded-lg border border-white/5">
                                                <div className="flex-1 min-w-[200px]">
                                                    <label className="text-xs text-textMuted block mb-1">Child Product</label>
                                                    <select 
                                                        value={c.child_product || ''} 
                                                        onChange={e => {
                                                            const n = [...comboItems]; n[index].child_product = e.target.value; setComboItems(n);
                                                        }} 
                                                        className="input w-full text-sm py-1.5"
                                                    >
                                                        <option value="">Select product...</option>
                                                        {allProducts.filter(ap => ap.id !== product?.id).map((p) => (
                                                            <option key={p.id} value={p.id}>{p.name}</option>
                                                        ))}
                                                    </select>
                                                </div>
                                                <div className="w-20">
                                                    <label className="text-xs text-textMuted block mb-1">Quantity</label>
                                                    <input type="number" min="1" value={c.quantity || 1} onChange={e => {
                                                        const n = [...comboItems]; n[index].quantity = parseInt(e.target.value); setComboItems(n);
                                                    }} className="input w-full text-sm py-1.5" />
                                                </div>
                                                <div className="w-32">
                                                    <label className="text-xs text-textMuted block mb-1">Added {currency} (Optional)</label>
                                                    <input type="number" step="0.01" value={c.extra_price || ''} onChange={e => {
                                                        const n = [...comboItems]; n[index].extra_price = e.target.value; setComboItems(n);
                                                    }} className="input w-full text-sm py-1.5" />
                                                </div>
                                                <button onClick={() => {
                                                    const n = [...comboItems];
                                                    if (n[index].id) setDeletedComboItems([...deletedComboItems, n[index].id]);
                                                    n.splice(index, 1);
                                                    setComboItems(n);
                                                }} className="mt-5 p-2 text-red-400 hover:bg-red-400/10 rounded transition-colors">
                                                    <FiTrash2 className="w-4 h-4" />
                                                </button>
                                            </div>
                                        ))}
                                    </div>
                                )}
                            </div>
                        )}

                        {activeTab === 'recipes' && (
                            <div className="space-y-6">
                                <div className="flex items-center justify-between border-b border-white/10 pb-2 mb-4">
                                    <div>
                                        <h3 className="text-lg font-bold text-white">Recipes & Cost Tracking</h3>
                                        <p className="text-xs text-textMuted mt-1">Manage sub-recipes for this base item and its variations.</p>
                                    </div>
                                    <button 
                                        onClick={() => window.open('/dashboard/inventory', '_blank')}
                                        className="btn btn-sm bg-primary/20 hover:bg-primary/30 text-primary flex items-center space-x-1"
                                    >
                                        <FiPlus /> <span>Manage Recipes</span>
                                    </button>
                                </div>

                                {!product?.id ? (
                                    <div className="text-center py-10 bg-black/20 rounded-xl border border-white/5 border-dashed">
                                        <FiCoffee className="w-8 h-8 mx-auto text-textMuted mb-2" />
                                        <p className="text-textMuted text-sm">You must save this product first before linking recipes.</p>
                                    </div>
                                ) : (
                                    <div className="space-y-4">
                                        {(() => {
                                            const prodRecipes = recipes.filter(r => r.product === product.id);
                                            
                                            if (prodRecipes.length === 0) {
                                                return (
                                                    <div className="text-center py-10 bg-black/20 rounded-xl border border-warning/20 border-dashed text-yellow-500">
                                                        <FiCoffee className="w-8 h-8 mx-auto mb-2 opacity-50" />
                                                        <p className="font-medium">No recipes found for this product.</p>
                                                        <p className="text-xs opacity-70 mt-1">Cost is completely manually set until you build a recipe.</p>
                                                    </div>
                                                );
                                            }

                                            return prodRecipes.map(recipe => {
                                                const costPerYield = parseFloat(recipe.total_cost) / parseFloat(recipe.yield_quantity);
                                                return (
                                                    <div key={recipe.id} className="bg-black/20 p-4 rounded-xl border border-white/10 flex flex-col md:flex-row gap-4 items-start md:items-center justify-between transition-all hover:bg-white/5">
                                                        <div className="flex items-start space-x-3">
                                                            <div className="p-3 bg-primary/20 text-primary rounded-lg border border-primary/20 shrink-0">
                                                                <FiCoffee className="w-5 h-5" />
                                                            </div>
                                                            <div>
                                                                <h4 className="font-bold text-white text-md">
                                                                    {recipe.variation_name ? `Size: ${recipe.variation_name}` : 'Base Recipe'}
                                                                </h4>
                                                                <p className="text-xs text-textMuted mt-1">
                                                                    {recipe.ingredients?.length || 0} ingredients used. Yields {parseFloat(recipe.yield_quantity).toFixed(2)} units.
                                                                </p>
                                                            </div>
                                                        </div>
                                                        <div className="bg-[#0f172a] px-4 py-2 rounded-lg border border-white/5 whitespace-nowrap">
                                                            <p className="text-xs text-textMuted font-medium mb-0.5">Calculated Cost</p>
                                                            <p className="text-lg font-mono text-red-400 font-bold">{currency}{costPerYield.toFixed(2)}</p>
                                                        </div>
                                                    </div>
                                                );
                                            });
                                        })()}
                                    </div>
                                )}
                            </div>
                        )}

                        {activeTab === 'settings' && (
                            <div className="space-y-8">
                                <div>
                                    <h3 className="text-lg font-bold text-white border-b border-white/10 pb-2 mb-4">Inventory & Tracking</h3>
                                    <div className="bg-primary/10 border border-primary/20 p-4 rounded-xl">
                                        <label className="block text-sm font-bold text-white mb-2">Direct Retail Link</label>
                                        <p className="text-xs text-textMuted mb-3">If this is a simple item (e.g. Water Bottle) that does NOT have a recipe, select the mapped Inventory Material below. Selling this product will deduct 1 unit from that material's stock automatically.</p>
                                        <select name="linked_raw_material" value={formData.linked_raw_material || ''} onChange={handleChange} className="input w-full bg-[#0f172a]">
                                            <option value="">-- No Direct Link (Requires Recipe) --</option>
                                            {rawMaterials.map(rm => (
                                                <option key={rm.id} value={rm.id}>{rm.name} ({rm.unit_abbreviation || ''})</option>
                                            ))}
                                        </select>
                                    </div>
                                </div>

                                <div>
                                    <h3 className="text-lg font-bold text-white border-b border-white/10 pb-2 mb-4">Availability & Status</h3>
                                    <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                                        <div>
                                            <label className="block text-sm font-medium text-textMuted mb-2">POS Status</label>
                                            <select name="availability_status" value={formData.availability_status} onChange={handleChange} className="input w-full">
                                                <option value="available">Available (Active on POS)</option>
                                                <option value="out_of_stock">Out of Stock (Shows but disabled)</option>
                                                <option value="hidden">Hidden (Archived/Invisible)</option>
                                            </select>
                                        </div>
                                        <div className="flex items-center space-x-3 pt-6">
                                            <input type="checkbox" id="is_popular" name="is_popular" checked={formData.is_popular} onChange={handleChange} className="w-5 h-5 rounded border-white/20 bg-black/20 text-yellow-500 focus:ring-yellow-500" />
                                            <label htmlFor="is_popular" className="font-medium text-white flex items-center space-x-2 cursor-pointer">
                                                <FiStar className="text-yellow-500 fill-current" /> <span>Mark as Popular (Highlights on POS)</span>
                                            </label>
                                        </div>
                                    </div>
                                </div>

                                <div>
                                    <h3 className="text-lg font-bold text-white border-b border-white/10 pb-2 mb-4">Preparation & Operations</h3>
                                    <div className="w-full md:w-1/2">
                                        <label className="block text-sm font-medium text-textMuted mb-2 flex items-center space-x-2">
                                            <FiClock /> <span>Est. Preparation Time (Minutes)</span>
                                        </label>
                                        <input type="number" min="0" name="preparation_time" value={formData.preparation_time} onChange={handleChange} className="input w-full" />
                                        <p className="text-xs text-textMuted mt-1">Helps kitchen display system (KDS) manage queues.</p>
                                    </div>
                                </div>

                                <div>
                                    <h3 className="text-lg font-bold text-white border-b border-white/10 pb-2 mb-4">Seasonality (Optional)</h3>
                                    <div className="flex items-center space-x-3 mb-4">
                                        <input type="checkbox" id="is_seasonal" name="is_seasonal" checked={formData.is_seasonal} onChange={handleChange} className="w-5 h-5 rounded border-white/20 bg-black/20 text-primary focus:ring-primary" />
                                        <label htmlFor="is_seasonal" className="font-medium text-white flex items-center space-x-2 cursor-pointer">
                                            <FiCalendar className="text-primary" /> <span>Seasonal Item</span>
                                        </label>
                                    </div>
                                    {formData.is_seasonal && (
                                        <div className="grid grid-cols-1 md:grid-cols-2 gap-4 p-4 bg-white/5 rounded-lg border border-white/10">
                                            <div>
                                                <label className="block text-sm font-medium text-textMuted mb-1">Season Start Date</label>
                                                <input type="date" name="season_start_date" value={formData.season_start_date} onChange={handleChange} className="input w-full" />
                                            </div>
                                            <div>
                                                <label className="block text-sm font-medium text-textMuted mb-1">Season End Date</label>
                                                <input type="date" name="season_end_date" value={formData.season_end_date} onChange={handleChange} className="input w-full" />
                                            </div>
                                        </div>
                                    )}
                                </div>
                            </div>
                        )}
                    </div>

                    {/* Footer Actions */}
                    <div className="pt-6 mt-8 border-t border-white/10 flex justify-end">
                        <button onClick={handleSave} disabled={isSaving} className="btn btn-primary flex items-center space-x-2 px-8 py-3 text-lg w-full sm:w-auto justify-center shadow-lg shadow-primary/20">
                            {isSaving ? (
                                <div className="animate-spin rounded-full h-5 w-5 border-b-2 border-white"></div>
                            ) : (
                                <><span>Save Product Data</span></>
                            )}
                        </button>
                    </div>
                </div>
            </div>
        </div>
    );
};

// Helper for tabs
const TabBtn = ({ active, onClick, icon, label }) => (
    <button 
        onClick={onClick}
        className={`flex items-center space-x-3 px-4 py-3 rounded-lg font-medium transition-all text-sm w-full lg:w-full shrink-0 ${active ? 'bg-primary text-white shadow-lg shadow-primary/20 scale-100' : 'text-textMuted hover:bg-white/5 hover:text-white'}`}
    >
        {icon} <span>{label}</span>
    </button>
);

import React, { useState, useEffect, useMemo } from 'react';
import { useForm, Controller } from 'react-hook-form';
import Select from 'react-select';
import { yupResolver } from '@hookform/resolvers/yup';
import * as yup from 'yup';
import toast from 'react-hot-toast';
import { 
    FiPlus, FiEdit2, FiTrash2, FiAlertTriangle, FiUploadCloud, 
    FiArrowLeft, FiDownload, FiX, FiCheck 
} from 'react-icons/fi';
import DataTable from '../../components/DataTable';
import ConfirmModal from '../../components/ConfirmModal';
import { inventoryApi } from '../../api/inventoryApi';
import useSettingsStore from '../../store/settingsStore';

const materialSchema = yup.object().shape({
  name: yup.string().required('Name is required'),
  category: yup.string().required('Category is required'),
  unit: yup.string().required('Unit is required'),
  minimum_stock: yup.number().min(0, 'Must be positive').required('Minimum stock is required'),
  reorder_quantity: yup.number().min(0, 'Must be positive').required('Reorder quantity is required'),
  cost_per_unit: yup.number().min(0, 'Must be positive').required('Cost per unit is required'),
  expiry_tracked: yup.boolean()
});

const RawMaterials = () => {
  const [materials, setMaterials] = useState([]);
  const [units, setUnits] = useState([]);
  const [isLoading, setIsLoading] = useState(true);
  
  // Modal state
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [importModalOpen, setImportModalOpen] = useState(false);
  const [editingMaterial, setEditingMaterial] = useState(null);
  
  // Delete confirm state
  const [deleteConfirmOpen, setDeleteConfirmOpen] = useState(false);
  const [materialToDelete, setMaterialToDelete] = useState(null);

  const { settings } = useSettingsStore();

  const { register, control, handleSubmit, reset, formState: { errors } } = useForm({
    resolver: yupResolver(materialSchema)
  });

  const categoryOptions = [
    { value: 'dairy', label: 'Dairy' },
    { value: 'beverages', label: 'Beverages' },
    { value: 'dry_goods', label: 'Dry Goods' },
    { value: 'packaging', label: 'Packaging' },
    { value: 'fresh_produce', label: 'Fresh Produce' },
    { value: 'cleaning', label: 'Cleaning & Maintenance' },
    { value: 'other', label: 'Other' },
  ];

  const selectStyles = {
    control: (base, state) => ({
      ...base,
      background: 'rgba(255, 255, 255, 0.05)',
      borderColor: state.isFocused ? '#3b82f6' : 'rgba(255, 255, 255, 0.1)',
      color: '#fff',
      minHeight: '40px',
      boxShadow: 'none',
      borderRadius: '0.5rem',
      cursor: 'pointer',
      '&:hover': { borderColor: 'rgba(255, 255, 255, 0.2)' }
    }),
    menu: (base) => ({
      ...base,
      background: '#1e293b',
      border: '1px solid rgba(255, 255, 255, 0.1)',
      borderRadius: '0.5rem',
      zIndex: 100
    }),
    option: (base, state) => ({
      ...base,
      background: state.isSelected ? 'rgba(59, 130, 246, 0.3)' : state.isFocused ? 'rgba(59, 130, 246, 0.1)' : 'transparent',
      color: state.isSelected ? '#fff' : '#cbd5e1',
      cursor: 'pointer',
      '&:active': { background: 'rgba(59, 130, 246, 0.4)' }
    }),
    singleValue: (base) => ({ ...base, color: '#fff' }),
    input: (base) => ({ ...base, color: '#fff' })
  };

  const fetchData = async () => {
    setIsLoading(true);
    try {
      const [matRes, unitRes] = await Promise.all([
        inventoryApi.getMaterials(),
        inventoryApi.getUnits()
      ]);
      setMaterials(matRes.data);
      setUnits(unitRes.data);
    } catch (error) {
      toast.error('Failed to load inventory data');
    } finally {
      setIsLoading(false);
    }
  };

  useEffect(() => {
    fetchData();
  }, []);

  const openAddModal = () => {
    setEditingMaterial(null);
    reset({
        name: '',
        category: 'other',
        unit: units[0]?.id || '',
        minimum_stock: 0,
        reorder_quantity: 0,
        cost_per_unit: 0,
        expiry_tracked: false
    });
    setIsModalOpen(true);
  };

  const openEditModal = (material) => {
    setEditingMaterial(material);
    reset({
      name: material.name,
      category: material.category,
      unit: material.unit.id || material.unit, // Handle nested or flat serializer
      minimum_stock: parseFloat(material.minimum_stock),
      reorder_quantity: parseFloat(material.reorder_quantity),
      cost_per_unit: parseFloat(material.cost_per_unit),
      expiry_tracked: material.expiry_tracked
    });
    setIsModalOpen(true);
  };

  const onSubmit = async (data) => {
    try {
      if (editingMaterial) {
        await inventoryApi.updateMaterial(editingMaterial.id, data);
        toast.success('Material updated successfully');
      } else {
        await inventoryApi.createMaterial(data);
        toast.success('Material created successfully');
      }
      setIsModalOpen(false);
      fetchData();
    } catch (error) {
      toast.error(error.response?.data?.error || 'Failed to save material');
    }
  };

  const confirmDelete = async () => {
    try {
      await inventoryApi.deleteMaterial(materialToDelete.id);
      toast.success('Material deleted successfully');
      setDeleteConfirmOpen(false);
      fetchData();
    } catch (error) {
      toast.error('Cannot delete material. It might be in use.');
      setDeleteConfirmOpen(false);
    }
  };

  const columns = useMemo(() => [
    {
      header: 'Name',
      accessorKey: 'name',
    },
    {
      header: 'Category',
      accessorKey: 'category',
      cell: info => <span className="capitalize">{info.getValue().replace('_', ' ')}</span>
    },
    {
      header: 'Current Stock',
      accessorFn: row => `${parseFloat(row.current_stock)} ${row.unit?.abbreviation || ''}`,
      cell: info => {
        const row = info.row.original;
        const current = parseFloat(row.current_stock);
        const min = parseFloat(row.minimum_stock);
        const isLow = current <= min;
        return (
            <div className={`flex items-center space-x-2 ${isLow ? 'text-red-400 font-medium' : ''}`}>
                {isLow && <FiAlertTriangle className="w-4 h-4" />}
                <span>{info.getValue()}</span>
            </div>
        )
      }
    },
    {
      header: 'Unit Cost',
      accessorFn: row => `${settings?.currency || '$'}${parseFloat(row.cost_per_unit).toFixed(2)}`,
    },
    {
      header: 'Actions',
      id: 'actions',
      cell: info => (
        <div className="flex space-x-2">
          <button 
            onClick={(e) => { e.stopPropagation(); openEditModal(info.row.original); }}
            className="p-1.5 bg-blue-500/20 text-blue-400 rounded hover:bg-blue-500/30 transition-colors"
          >
            <FiEdit2 className="w-4 h-4" />
          </button>
          <button 
            onClick={(e) => { 
                e.stopPropagation(); 
                setMaterialToDelete(info.row.original);
                setDeleteConfirmOpen(true);
            }}
            className="p-1.5 bg-red-500/20 text-red-400 rounded hover:bg-red-500/30 transition-colors"
          >
            <FiTrash2 className="w-4 h-4" />
          </button>
        </div>
      )
    }
  ], [units, settings]);

  return (
    <div className="p-6">
      <div className="flex justify-between items-center mb-6">
        <h1 className="text-2xl font-bold text-white">Raw Materials</h1>
        <div className="flex items-center space-x-3">
            <button 
              onClick={() => setImportModalOpen(true)}
              className="bg-[#1e293b] hover:bg-[#2dd4bf]/20 text-white border border-white/10 hover:border-[#2dd4bf]/50 px-4 py-2 rounded-lg font-medium transition-all flex items-center space-x-2"
            >
              <FiUploadCloud className="w-5 h-5 text-[#2dd4bf]" />
              <span>Bulk Import</span>
            </button>
            <button 
              onClick={openAddModal}
              className="bg-primary hover:bg-primary/90 text-white px-4 py-2 rounded-lg font-medium transition-colors flex items-center space-x-2 shadow-lg shadow-primary/20"
            >
              <FiPlus className="w-5 h-5" />
              <span>Add Material</span>
            </button>
        </div>
      </div>

      <DataTable 
        columns={columns} 
        data={materials} 
        isLoading={isLoading}
        searchPlaceholder="Search materials..."
      />

      {/* Material Modal */}
      {isModalOpen && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4">
          <div className="fixed inset-0 bg-black/60 backdrop-blur-sm" onClick={() => setIsModalOpen(false)}></div>
          <div className="relative glass-panel w-full max-w-lg p-6 max-h-[90vh] overflow-y-auto">
            <h2 className="text-xl font-bold text-white mb-4">
              {editingMaterial ? 'Edit Material' : 'Add New Material'}
            </h2>
            
            <form onSubmit={handleSubmit(onSubmit)} className="space-y-4">
              <div className="grid grid-cols-2 gap-4">
                  <div className="col-span-2">
                    <label className="block text-sm font-medium text-textMuted mb-1">Name</label>
                    <input {...register('name')} className="form-input" placeholder="e.g. Arabica Coffee Beans" />
                    {errors.name && <span className="text-red-400 text-xs">{errors.name.message}</span>}
                  </div>
                  
                  <div>
                    <label className="block text-sm font-medium text-textMuted mb-1">Category</label>
                    <Controller
                      name="category"
                      control={control}
                      render={({ field }) => (
                        <Select
                          {...field}
                          options={categoryOptions}
                          styles={selectStyles}
                          placeholder="Search Category..."
                          value={categoryOptions.find(c => c.value === field.value)}
                          onChange={val => field.onChange(val.value)}
                        />
                      )}
                    />
                  </div>

                  <div>
                    <label className="block text-sm font-medium text-textMuted mb-1">Base Unit</label>
                    <Controller
                      name="unit"
                      control={control}
                      render={({ field }) => (
                        <Select
                          {...field}
                          options={units.map(u => ({ value: u.id, label: `${u.name} (${u.abbreviation})` }))}
                          styles={selectStyles}
                          placeholder="Search Unit..."
                          value={units.map(u => ({ value: u.id, label: `${u.name} (${u.abbreviation})` })).find(u => u.value === field.value)}
                          onChange={val => field.onChange(val.value)}
                        />
                      )}
                    />
                    {errors.unit && <span className="text-red-400 text-xs">{errors.unit.message}</span>}
                  </div>

                  <div>
                    <label className="block text-sm font-medium text-textMuted mb-1">Min Stock Alert</label>
                    <input type="number" step="0.001" {...register('minimum_stock')} className="form-input" />
                    {errors.minimum_stock && <span className="text-red-400 text-xs">{errors.minimum_stock.message}</span>}
                  </div>

                  <div>
                    <label className="block text-sm font-medium text-textMuted mb-1">Reorder Quantity</label>
                    <input type="number" step="0.001" {...register('reorder_quantity')} className="form-input" />
                  </div>

                  <div>
                    <label className="block text-sm font-medium text-textMuted mb-1">Base Cost ({settings?.currency || '$'})</label>
                    <input type="number" step="0.01" {...register('cost_per_unit')} className="form-input" />
                  </div>

                  <div className="flex items-center space-x-2 mt-6">
                    <input type="checkbox" {...register('expiry_tracked')} id="expiry_tracked" className="w-4 h-4 rounded bg-white/5 border-white/10 text-primary focus:ring-primary focus:ring-offset-background" />
                    <label htmlFor="expiry_tracked" className="text-sm font-medium text-textMuted">Track Expiry Dates (FIFO)</label>
                  </div>
              </div>

              <div className="flex justify-end space-x-3 pt-4 border-t border-white/10">
                <button type="button" onClick={() => setIsModalOpen(false)} className="px-4 py-2 rounded-lg text-textMuted hover:bg-white/5 transition-colors">
                  Cancel
                </button>
                <button type="submit" className="bg-primary hover:bg-primary/90 text-white px-4 py-2 rounded-lg transition-colors">
                  Save Material
                </button>
              </div>
            </form>
          </div>
        </div>
      )}

      <ConfirmModal 
        isOpen={deleteConfirmOpen}
        title="Delete Material"
        message={`Are you sure you want to delete ${materialToDelete?.name}? This action cannot be undone and may fail if stock exists.`}
        onConfirm={confirmDelete}
        onCancel={() => setDeleteConfirmOpen(false)}
        confirmText="Delete"
        isDestructive={true}
      />

      {/* Bulk Import Modal */}
      <ImportRawMaterialsModal 
          isOpen={importModalOpen} 
          onClose={() => setImportModalOpen(false)} 
          onSuccess={() => { setImportModalOpen(false); fetchData(); }} 
      />
    </div>
  );
};

// -------------------------------------------------------------
// BULK IMPORT MODAL (Two-Step process)
// -------------------------------------------------------------
const ImportRawMaterialsModal = ({ isOpen, onClose, onSuccess }) => {
    const [step, setStep] = useState(1);
    const [file, setFile] = useState(null);
    const [isProcessing, setIsProcessing] = useState(false);
    const [previewData, setPreviewData] = useState([]);

    if (!isOpen) return null;

    const resetModal = () => {
        setStep(1);
        setFile(null);
        setPreviewData([]);
        onClose();
    };

    const handleDownloadTemplate = async () => {
        try {
            const toastId = toast.loading("Downloading template...");
            const response = await inventoryApi.exportMaterialsTemplate();
            const url = window.URL.createObjectURL(new Blob([response.data]));
            const link = document.createElement('a');
            link.href = url;
            link.setAttribute('download', 'materials_template.xlsx');
            document.body.appendChild(link);
            link.click();
            link.remove();
            toast.success("Template downloaded", { id: toastId });
        } catch (error) {
            toast.error("Failed to download template");
        }
    };

    const handlePreview = async () => {
        if (!file) return toast.error("Please select an Excel file first");
        
        const formData = new FormData();
        formData.append('file', file);
        
        setIsProcessing(true);
        const toastId = toast.loading("Parsing Excel file...");
        
        try {
            const response = await inventoryApi.previewBulkMaterials(formData);
            if (response.data.success && response.data.data.length > 0) {
                toast.success("File parsed! Please review the data.", { id: toastId });
                setPreviewData(response.data.data);
                setStep(2);
            } else {
                toast.error("No valid data found in the file", { id: toastId });
            }
        } catch (error) {
            toast.error(error.response?.data?.detail || "Failed to parse the file.", { id: toastId });
        } finally {
            setIsProcessing(false);
        }
    };

    const handleConfirmImport = async () => {
        setIsProcessing(true);
        const toastId = toast.loading("Importing materials...");
        try {
            const response = await inventoryApi.confirmBulkMaterials(previewData);
            if (response.data.success) {
                toast.success(response.data.message, { id: toastId });
                if (response.data.errors?.length > 0) {
                    toast.error(`Some rows failed: ${response.data.errors.length} errors. Check console.`, { duration: 5000 });
                    console.warn("Import Errors:", response.data.errors);
                }
                onSuccess();
                resetModal();
            } else {
                toast.error(response.data.detail || "Import failed", { id: toastId });
            }
        } catch (error) {
            toast.error(error.response?.data?.detail || "Import failed during saving.", { id: toastId });
        } finally {
            setIsProcessing(false);
        }
    };

    const handleCellChange = (rowIndex, field, value) => {
        const newData = [...previewData];
        newData[rowIndex][field] = value;
        setPreviewData(newData);
    };

    return (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/60 backdrop-blur-sm animate-fade-in-up">
            <div className={`bg-[#1e293b] rounded-2xl border border-white/10 shadow-2xl overflow-hidden flex flex-col transition-all duration-300 ${step === 2 ? 'w-full max-w-6xl' : 'w-full max-w-md'}`}>
                <div className="p-5 border-b border-white/10 flex justify-between items-center bg-[#0f172a] shrink-0">
                    <h3 className="text-xl font-black text-white flex items-center space-x-2">
                        <FiUploadCloud className="text-[#2dd4bf]" /> 
                        <span>{step === 1 ? 'Bulk Import Materials' : 'Review & Edit Materials Data'}</span>
                    </h3>
                    <button onClick={resetModal} className="text-textMuted hover:text-white bg-white/5 p-2 rounded-lg transition-colors">
                        <FiX />
                    </button>
                </div>
                
                {step === 1 ? (
                    <>
                        <div className="p-6 space-y-6">
                            <div className="bg-[#2dd4bf]/10 border border-[#2dd4bf]/20 rounded-xl p-4 flex flex-col items-center justify-center text-center">
                                <p className="text-sm text-white font-medium mb-3">1. Download the Excel template</p>
                                <button 
                                    onClick={handleDownloadTemplate}
                                    className="bg-[#2dd4bf]/20 hover:bg-[#2dd4bf]/30 text-[#2dd4bf] border border-[#2dd4bf]/30 px-4 py-2 rounded-lg text-sm font-bold flex items-center space-x-2 transition-colors"
                                >
                                    <FiDownload /> <span>Download Template.xlsx</span>
                                </button>
                                <p className="text-xs text-textMuted mt-3">Fill in your material details exactly as structured in the downloaded file.</p>
                            </div>

                            <div className="border border-white/10 rounded-xl p-4 flex flex-col items-center justify-center text-center">
                                <p className="text-sm text-white font-medium mb-3">2. Upload filled Excel file</p>
                                <div className="w-full relative">
                                    <input 
                                        type="file" 
                                        accept=".xlsx, .xls" 
                                        onChange={(e) => setFile(e.target.files[0])}
                                        className="absolute inset-0 w-full h-full opacity-0 cursor-pointer z-10"
                                    />
                                    <div className={`w-full py-4 rounded-lg border-2 border-dashed transition-colors flex flex-col items-center justify-center ${file ? 'border-green-500/50 bg-green-500/10' : 'border-white/20 bg-white/5 hover:border-[#2dd4bf]/50'}`}>
                                        <FiUploadCloud className={`w-6 h-6 mb-2 ${file ? 'text-green-400' : 'text-textMuted'}`} />
                                        <span className={`text-sm font-bold ${file ? 'text-green-400' : 'text-textMuted'}`}>
                                            {file ? file.name : 'Click to browse or drag file here'}
                                        </span>
                                    </div>
                                </div>
                            </div>
                        </div>

                        <div className="p-5 border-t border-white/10 bg-[#0f172a]">
                            <button 
                                onClick={handlePreview}
                                disabled={!file || isProcessing}
                                className="w-full bg-[#2dd4bf] hover:bg-[#2dd4bf]/90 disabled:opacity-50 text-[#0f172a] font-black py-3 rounded-xl shadow-[0_0_15px_rgba(45,212,191,0.3)] transition-all flex justify-center items-center space-x-2"
                            >
                                {isProcessing ? (
                                    <div className="animate-spin rounded-full h-5 w-5 border-b-2 border-[#0f172a]"></div>
                                ) : (
                                    <>
                                        <span>Preview Data</span> <FiArrowLeft className="rotate-180" />
                                    </>
                                )}
                            </button>
                        </div>
                    </>
                ) : (
                    <>
                        <div className="p-6 overflow-y-auto max-h-[70vh]">
                            <table className="w-full text-left text-sm whitespace-nowrap">
                                <thead>
                                    <tr className="border-b border-white/10 text-textMuted">
                                        <th className="pb-3 px-2 font-medium">Name (EN)</th>
                                        <th className="pb-3 px-2 font-medium">Name (AR)</th>
                                        <th className="pb-3 px-2 font-medium">Category</th>
                                        <th className="pb-3 px-2 font-medium">Unit ID</th>
                                        <th className="pb-3 px-2 font-medium">Cost Price</th>
                                        <th className="pb-3 px-2 font-medium">Current Stock</th>
                                        <th className="pb-3 px-2 font-medium">Min Stock</th>
                                        <th className="pb-3 px-2 font-medium">Reorder Qty</th>
                                        <th className="pb-3 px-2 font-medium">Barcode</th>
                                    </tr>
                                </thead>
                                <tbody>
                                    {previewData.map((row, idx) => (
                                        <tr key={row.id} className="border-b border-white/5 hover:bg-white/5 transition-colors">
                                            <td className="p-2">
                                                <input type="text" value={row.name} onChange={(e) => handleCellChange(idx, 'name', e.target.value)} className="input py-1 px-2 w-full text-sm" />
                                            </td>
                                            <td className="p-2">
                                                <input type="text" value={row.name_ar} onChange={(e) => handleCellChange(idx, 'name_ar', e.target.value)} className="input py-1 px-2 w-full text-sm" dir="rtl" />
                                            </td>
                                            <td className="p-2">
                                                <input type="text" value={row.category} onChange={(e) => handleCellChange(idx, 'category', e.target.value)} className="input py-1 px-2 w-24 text-sm" />
                                            </td>
                                            <td className="p-2">
                                                <input type="text" value={row.unit_id} onChange={(e) => handleCellChange(idx, 'unit_id', e.target.value)} className="input py-1 px-2 w-20 text-sm text-center" />
                                            </td>
                                            <td className="p-2">
                                                <input type="number" step="0.01" value={row.cost_price} onChange={(e) => handleCellChange(idx, 'cost_price', e.target.value)} className="input py-1 px-2 w-24 text-sm" />
                                            </td>
                                            <td className="p-2">
                                                <input type="number" step="0.01" value={row.current_stock} onChange={(e) => handleCellChange(idx, 'current_stock', e.target.value)} className="input py-1 px-2 w-24 text-sm" />
                                            </td>
                                            <td className="p-2">
                                                <input type="number" step="0.01" value={row.minimum_stock} onChange={(e) => handleCellChange(idx, 'minimum_stock', e.target.value)} className="input py-1 px-2 w-24 text-sm" />
                                            </td>
                                            <td className="p-2">
                                                <input type="number" step="0.01" value={row.reorder_quantity} onChange={(e) => handleCellChange(idx, 'reorder_quantity', e.target.value)} className="input py-1 px-2 w-24 text-sm" />
                                            </td>
                                            <td className="p-2">
                                                <input type="text" value={row.barcode} onChange={(e) => handleCellChange(idx, 'barcode', e.target.value)} className="input py-1 px-2 w-32 text-sm" />
                                            </td>
                                        </tr>
                                    ))}
                                </tbody>
                            </table>
                        </div>
                        <div className="p-5 border-t border-white/10 bg-[#0f172a] flex justify-between items-center">
                            <button onClick={() => setStep(1)} className="btn hover:bg-white/5 text-textMuted flex items-center space-x-2">
                                <FiArrowLeft /> <span>Back to Upload</span>
                            </button>
                            <button 
                                onClick={handleConfirmImport}
                                disabled={isProcessing}
                                className="bg-green-500 hover:bg-green-600 disabled:opacity-50 text-white px-6 py-2.5 rounded-xl font-bold flex items-center space-x-2 transition-colors shadow-lg shadow-green-500/20"
                            >
                                {isProcessing ? (
                                    <div className="animate-spin rounded-full h-5 w-5 border-b-2 border-white"></div>
                                ) : (
                                    <>
                                        <FiCheck /> <span>Confirm & Import {previewData.length} Materials</span>
                                    </>
                                )}
                            </button>
                        </div>
                    </>
                )}
            </div>
        </div>
    );
};

export default RawMaterials;

import React, { useState, useEffect, useMemo } from 'react';
import { DragDropContext, Droppable, Draggable } from '@hello-pangea/dnd';
import { useForm, Controller, useFieldArray } from 'react-hook-form';
import Select from 'react-select';
import { yupResolver } from '@hookform/resolvers/yup';
import * as yup from 'yup';
import toast from 'react-hot-toast';
import { FiPlus, FiTrash2, FiEye, FiSettings, FiSearch, FiLayers } from 'react-icons/fi';
import { MdDragIndicator } from 'react-icons/md';
import DataTable from '../../components/DataTable';
import { inventoryApi } from '../../api/inventoryApi';
import useSettingsStore from '../../store/settingsStore';
import ConfirmModal from '../../components/ConfirmModal';

const recipeSchema = yup.object().shape({
    product: yup.string().required('Product is required'),
    yield_quantity: yup.number().positive('Must be positive').required('Yield quantity is required'),
    preparation_time: yup.number().min(0, 'Cannot be negative').required('Prep time is required'),
    notes: yup.string().nullable(),
    ingredients: yup.array().of(
        yup.object().shape({
            raw_material: yup.string().required('Ingredient is required'),
            quantity: yup.number().min(0.001, 'Quantity must be > 0').required('Required'),
            unit: yup.number().required('Unit is required')
        })
    ).min(1, 'At least one ingredient is required')
});

const selectStyles = {
    control: (base, state) => ({
        ...base,
        background: 'rgba(255, 255, 255, 0.05)',
        borderColor: state.isFocused ? '#3b82f6' : 'rgba(255, 255, 255, 0.1)',
        color: '#fff',
        minHeight: '38px',
        boxShadow: 'none',
        borderRadius: '0.5rem',
        cursor: 'pointer',
        fontSize: '0.875rem',
        '&:hover': { borderColor: 'rgba(255, 255, 255, 0.2)' }
    }),
    menu: (base) => ({
        ...base,
        background: '#1e293b',
        border: '1px solid rgba(255, 255, 255, 0.1)',
        borderRadius: '0.5rem',
        zIndex: 100
    }),
    option: (base, state) => ({
        ...base,
        background: state.isSelected ? 'rgba(59, 130, 246, 0.3)' : state.isFocused ? 'rgba(59, 130, 246, 0.1)' : 'transparent',
        color: state.isSelected ? '#fff' : '#cbd5e1',
        cursor: 'pointer',
        fontSize: '0.875rem',
        '&:active': { background: 'rgba(59, 130, 246, 0.4)' }
    }),
    singleValue: (base) => ({ ...base, color: '#fff' }),
    input: (base) => ({ ...base, color: '#fff' })
};

const Recipes = () => {
    const [recipes, setRecipes] = useState([]);
    const [products, setProducts] = useState([]);
    const [variations, setVariations] = useState([]);
    const [materials, setMaterials] = useState([]);
    const [units, setUnits] = useState([]);
    const [isLoading, setIsLoading] = useState(true);
    
    // UI State
    const [isBuilderOpen, setIsBuilderOpen] = useState(false);
    const [editingRecipe, setEditingRecipe] = useState(null);
    const [materialSearch, setMaterialSearch] = useState('');
    const [deleteConfirmOpen, setDeleteConfirmOpen] = useState(false);
    const [recipeToDelete, setRecipeToDelete] = useState(null);
    const [viewRecipe, setViewRecipe] = useState(null);

    const { settings } = useSettingsStore();

    const { register, control, handleSubmit, reset, watch, setValue, formState: { errors } } = useForm({
        resolver: yupResolver(recipeSchema),
        defaultValues: { ingredients: [], yield_quantity: 1, preparation_time: 5 }
    });

    const { fields, append, remove, move } = useFieldArray({
        control,
        name: "ingredients"
    });

    const watchIngredients = watch("ingredients");

    const fetchData = async () => {
        setIsLoading(true);
        try {
            const [recipesRes, prodRes, varRes, matRes, unitsRes] = await Promise.all([
                inventoryApi.getRecipes(),
                inventoryApi.getProducts(),
                inventoryApi.getVariations(),
                inventoryApi.getMaterials(),
                inventoryApi.getUnits()
            ]);
            setRecipes(recipesRes.data);
            setProducts(prodRes.data);
            setVariations(varRes.data);
            setMaterials(matRes.data);
            setUnits(unitsRes.data);
        } catch (error) {
            toast.error('Failed to load recipe data');
        } finally {
            setIsLoading(false);
        }
    };

    useEffect(() => {
        fetchData();
    }, []);

    const filteredMaterials = useMemo(() => {
        if (!materialSearch) return materials;
        return materials.filter(m => m.name.toLowerCase().includes(materialSearch.toLowerCase()));
    }, [materials, materialSearch]);

    // Drag and Drop Handlers
    const onDragEnd = (result) => {
        const { source, destination, draggableId } = result;

        if (!destination) return;

        // Reordering within the recipe ingredients list
        if (source.droppableId === 'recipe-ingredients' && destination.droppableId === 'recipe-ingredients') {
            move(source.index, destination.index);
            return;
        }

        // Dragging a new material from the sidebar to the recipe
        if (source.droppableId === 'sidebar-materials' && destination.droppableId === 'recipe-ingredients') {
            const material = materials.find(m => m.id === draggableId);
            if (material) {
                // Prevent duplicate raw_materials, just highlight if exists, or allow multiple (we allow multiple for complex recipes but usually it's one)
                // We'll append it
                append({
                    raw_material: material.id,
                    quantity: 1,
                    unit: material.unit, // default to its base unit
                    _tempName: material.name, // Just for UI display before save
                    _tempCost: material.cost_per_unit
                });
            }
        }
    };

    const openBuilder = (recipe = null) => {
        setEditingRecipe(recipe);
        if (recipe) {
            // Need to map the existing ingredients into the form format
            reset({
                product: recipe.variation ? recipe.variation : recipe.product,
                yield_quantity: recipe.yield_quantity,
                preparation_time: recipe.preparation_time,
                notes: recipe.notes || '',
                ingredients: recipe.ingredients.map(ing => ({
                    raw_material: ing.raw_material,
                    quantity: ing.quantity,
                    unit: ing.unit,
                    _tempName: ing.raw_material_name,
                    _tempCost: ing.cost // Pre-calculated from backend
                }))
            });
        } else {
            reset({
                product: '',
                yield_quantity: 1,
                preparation_time: 5,
                notes: '',
                ingredients: []
            });
        }
        setIsBuilderOpen(true);
    };

    const onSubmit = async (data) => {
        try {
            // Clean up temporary UI fields
            const payload = {
                ...data,
                ingredients: data.ingredients.map(ing => ({
                    raw_material: ing.raw_material,
                    quantity: parseFloat(ing.quantity),
                    unit: ing.unit
                }))
            };

            if (editingRecipe) {
                await inventoryApi.updateRecipe(editingRecipe.id, payload);
                toast.success('Recipe updated successfully');
            } else {
                await inventoryApi.createRecipe(payload);
                toast.success('Recipe created successfully');
            }
            setIsBuilderOpen(false);
            fetchData();
        } catch (error) {
            console.error("Recipe Save Error:", error.response?.data || error.message);
            const data = error.response?.data;
            const errMsg = data?.product?.[0] || 
                           data?.non_field_errors?.[0] || 
                           data?.detail || 
                           error.message ||
                           'Failed to save recipe';
            toast.error(errMsg);
        }
    };

    const confirmDelete = async () => {
        try {
            await inventoryApi.deleteRecipe(recipeToDelete.id);
            toast.success('Recipe deleted successfully');
            setDeleteConfirmOpen(false);
            fetchData();
        } catch (error) {
            toast.error('Failed to delete recipe');
        }
    };

    const columns = useMemo(() => [
        {
            header: 'Target Product',
            accessorKey: 'target_name', // Updated to use the new backend serializer field
            cell: info => <span className="font-bold text-white">{info.getValue() || 'Unknown Product'}</span>
        },
        {
            header: 'Prep Time',
            accessorKey: 'preparation_time',
            cell: info => <span className="text-textMuted">{info.getValue()} mins</span>
        },
        {
            header: 'Target Yield',
            accessorKey: 'yield_quantity',
            cell: info => <span className="font-mono text-accent">{parseFloat(info.getValue()).toFixed(2)} units</span>
        },
        {
            header: 'Item Cost Structure',
            accessorKey: 'total_cost',
            cell: info => (
                <div className="flex flex-col">
                    <span className="font-mono text-red-400 font-bold">{settings?.currency || '$'}{parseFloat(info.getValue()).toFixed(2)} total</span>
                    <span className="text-xs text-textMuted mt-0.5">
                        {settings?.currency || '$'}{(parseFloat(info.getValue()) / parseFloat(info.row.original.yield_quantity)).toFixed(2)} per yield unit
                    </span>
                </div>
            )
        },
        {
            header: 'Actions',
            id: 'actions',
            cell: info => (
                <div className="flex space-x-2">
                    <button 
                        onClick={() => setViewRecipe(info.row.original)}
                        className="p-1.5 bg-white/5 hover:bg-white/10 text-white rounded transition-colors"
                        title="View Recipe Formula"
                    >
                        <FiEye className="w-4 h-4" />
                    </button>
                    <button 
                        onClick={() => openBuilder(info.row.original)}
                        className="p-1.5 bg-white/5 hover:bg-white/10 text-white rounded transition-colors"
                        title="Edit Recipe"
                    >
                        <FiSettings className="w-4 h-4" />
                    </button>
                    <button 
                        onClick={() => {
                            setRecipeToDelete(info.row.original);
                            setDeleteConfirmOpen(true);
                        }}
                        className="p-1.5 bg-red-500/20 text-red-400 rounded hover:bg-red-500/30 transition-colors"
                    >
                        <FiTrash2 className="w-4 h-4" />
                    </button>
                </div>
            )
        }
    ], [settings]);

    return (
        <div className="p-6">
            <div className="flex justify-between items-center mb-6">
                <div>
                     <h1 className="text-2xl font-bold text-white">Recipe Engineering</h1>
                     <p className="text-sm text-textMuted mt-1">Design formulas linking Raw Materials to Menu Items to auto-deduct stock upon sales.</p>
                </div>
                <button 
                    onClick={() => openBuilder()}
                    className="bg-primary hover:bg-primary/90 text-white px-4 py-2 rounded-lg font-medium transition-colors flex items-center space-x-2 shadow-lg shadow-primary/20"
                >
                    <FiLayers className="w-5 h-5" />
                    <span>Launch Recipe Builder</span>
                </button>
            </div>

            <DataTable 
                columns={columns} 
                data={recipes} 
                isLoading={isLoading}
                searchPlaceholder="Search recipes by product..."
            />

            {/* Drag & Drop Recipe Builder Modal */}
            {isBuilderOpen && (
                <div className="fixed inset-0 z-50 flex items-center justify-center p-4">
                    <div className="fixed inset-0 bg-black/80 backdrop-blur-md" onClick={() => setIsBuilderOpen(false)}></div>
                    <div className="relative bg-[#1e293b] w-full max-w-6xl h-[85vh] rounded-2xl flex flex-col shadow-2xl border border-white/10 overflow-hidden">
                        
                        {/* Header */}
                        <div className="px-6 py-4 border-b border-white/10 flex justify-between items-center bg-[#0f172a]">
                            <div>
                                <h2 className="text-xl font-bold text-white tracking-wide">
                                    {editingRecipe ? 'Edit Recipe Formula' : 'Recipe Builder Studio'}
                                </h2>
                                <p className="text-xs text-primary font-medium mt-1 uppercase tracking-wider">Drag & Drop Required</p>
                            </div>
                            <div className="flex space-x-3">
                                <button type="button" onClick={() => setIsBuilderOpen(false)} className="px-5 py-2 rounded-lg text-textMuted hover:bg-white/5 transition-colors font-medium">
                                    Discard Changes
                                </button>
                                <button onClick={handleSubmit(onSubmit)} className="bg-primary hover:bg-primary/90 text-white px-6 py-2 rounded-lg transition-colors font-bold shadow-lg shadow-primary/20">
                                    {editingRecipe ? 'Save Formula' : 'Initialize Recipe'}
                                </button>
                            </div>
                        </div>

                        {/* Builder Body */}
                        <div className="flex-1 flex overflow-hidden">
                            <DragDropContext onDragEnd={onDragEnd}>
                                
                                {/* Left Sidebar: Materials Palette */}
                                <div className="w-80 border-r border-white/10 bg-[#162032] flex flex-col">
                                    <div className="p-4 border-b border-white/10">
                                        <div className="relative">
                                            <FiSearch className="absolute left-3 top-1/2 transform -translate-y-1/2 text-textMuted" />
                                            <input 
                                                type="text" 
                                                placeholder="Search materials..." 
                                                value={materialSearch}
                                                onChange={(e) => setMaterialSearch(e.target.value)}
                                                className="w-full bg-[#0f172a] border border-white/10 rounded-lg pl-9 pr-3 py-2 text-sm text-white focus:outline-none focus:border-primary transition-colors"
                                            />
                                        </div>
                                    </div>
                                    
                                    <Droppable droppableId="sidebar-materials" isDropDisabled={true}>
                                        {(provided) => (
                                            <div 
                                                ref={provided.innerRef} 
                                                {...provided.droppableProps}
                                                className="flex-1 overflow-y-auto p-4 space-y-2 custom-scrollbar"
                                            >
                                                {filteredMaterials.map((mat, index) => (
                                                    <Draggable key={mat.id} draggableId={mat.id} index={index}>
                                                        {(provided, snapshot) => (
                                                            <div
                                                                ref={provided.innerRef}
                                                                {...provided.draggableProps}
                                                                {...provided.dragHandleProps}
                                                                className={`
                                                                    p-3 rounded-lg border border-white/10 flex items-center space-x-3 transition-colors user-select-none
                                                                    ${snapshot.isDragging ? 'bg-primary/20 border-primary shadow-xl shadow-primary/20 z-50' : 'bg-[#1e293b] hover:border-white/20'}
                                                                `}
                                                            >
                                                                <div className="w-8 h-8 rounded bg-white/5 flex items-center justify-center shrink-0">
                                                                    <MdDragIndicator className="text-textMuted" />
                                                                </div>
                                                                <div className="overflow-hidden">
                                                                    <p className="text-sm font-semibold text-white truncate">{mat.name}</p>
                                                                    <p className="text-xs text-textMuted mt-0.5 truncate">Base: {mat.unit_abbreviation} • {settings?.currency || '$'}{mat.cost_per_unit}</p>
                                                                </div>
                                                            </div>
                                                        )}
                                                    </Draggable>
                                                ))}
                                                {provided.placeholder}
                                            </div>
                                        )}
                                    </Droppable>
                                </div>

                                {/* Right Area: Recipe Canvas */}
                                <div className="flex-1 flex flex-col overflow-y-auto bg-[#0f172a]">
                                    
                                    {/* Recipe Settings Header */}
                                    <div className="p-6 border-b border-white/10 bg-[#1e293b] grid grid-cols-3 gap-6">
                                        <div className="col-span-1">
                                            <label className="block text-sm font-medium text-textMuted mb-1.5">Target Product (Menu Item) *</label>
                                            <Controller
                                                name="product"
                                                control={control}
                                                render={({ field: { onChange, value, ref } }) => {
                                                    // Map base products
                                                    const productOptions = products
                                                        .filter(p => p.availability_status === 'available')
                                                        .map(p => ({ value: p.id, label: p.name, type: 'product' }));
                                                        
                                                    // Map variations (sizes)
                                                    const variationOptions = variations
                                                        .filter(v => v.is_active)
                                                        .map(v => {
                                                            const baseProduct = products.find(p => p.id === v.product);
                                                            return { 
                                                                value: v.id, 
                                                                label: `${baseProduct ? baseProduct.name : 'Unknown'} - ${v.size_name}`,
                                                                type: 'variation' 
                                                            };
                                                        });
                                                        
                                                    const combinedOptions = [...productOptions, ...variationOptions];

                                                    return (
                                                        <Select
                                                            ref={ref}
                                                            options={combinedOptions}
                                                            styles={selectStyles}
                                                            placeholder="Select Product to link..."
                                                            value={combinedOptions.find(c => c.value === value) || ''}
                                                            onChange={val => onChange(val ? val.value : '')}
                                                            isClearable
                                                        />
                                                    );
                                                }}
                                            />
                                            {errors.product && <span className="text-red-400 text-xs mt-1 block">{errors.product.message}</span>}
                                        </div>

                                        <div>
                                            <label className="block text-sm font-medium text-textMuted mb-1.5">Yield Quantity *</label>
                                            <div className="relative">
                                                <input type="number" step="0.01" {...register('yield_quantity')} className="form-input w-full font-mono text-accent" />
                                                <span className="absolute right-3 top-1/2 -translate-y-1/2 text-textMuted text-xs uppercase">Units</span>
                                            </div>
                                            {errors.yield_quantity && <span className="text-red-400 text-xs mt-1 block">{errors.yield_quantity.message}</span>}
                                        </div>

                                        <div>
                                            <label className="block text-sm font-medium text-textMuted mb-1.5">Prep Time (Avg) *</label>
                                            <div className="relative">
                                                <input type="number" {...register('preparation_time')} className="form-input w-full font-mono text-accent" />
                                                <span className="absolute right-3 top-1/2 -translate-y-1/2 text-textMuted text-xs uppercase">Mins</span>
                                            </div>
                                            {errors.preparation_time && <span className="text-red-400 text-xs mt-1 block">{errors.preparation_time.message}</span>}
                                        </div>
                                    </div>

                                    {/* Drop Canvas */}
                                    <div className="flex-1 p-6 flex flex-col">
                                        <div className="flex justify-between items-center mb-4">
                                            <h3 className="text-lg font-bold text-white flex items-center"><FiLayers className="mr-2 text-primary"/> Formula Ingredients</h3>
                                            <span className="text-xs font-medium px-2.5 py-1 bg-primary/20 text-primary rounded-full border border-primary/20">
                                                {fields.length} Components
                                            </span>
                                        </div>

                                        <Droppable droppableId="recipe-ingredients">
                                            {(provided, snapshot) => (
                                                <div
                                                    ref={provided.innerRef}
                                                    {...provided.droppableProps}
                                                    className={`
                                                        flex-1 rounded-xl border-2 border-dashed transition-all p-4 overflow-y-auto min-h-[300px]
                                                        ${snapshot.isDraggingOver ? 'border-primary bg-primary/5' : 'border-white/10 bg-white/5'}
                                                        ${errors.ingredients?.root ? 'border-red-500/50 bg-red-500/5' : ''}
                                                    `}
                                                >
                                                    {fields.length === 0 && !snapshot.isDraggingOver && (
                                                        <div className="h-full flex flex-col items-center justify-center text-textMuted opacity-60">
                                                            <FiPlus className="w-12 h-12 mb-3 text-white/20" />
                                                            <p className="font-medium text-lg">Empty Formula</p>
                                                            <p className="text-sm">Drag raw materials from the sidebar here to formulate.</p>
                                                        </div>
                                                    )}

                                                    {fields.map((item, index) => {
                                                        const materialId = watchIngredients[index]?.raw_material;
                                                        const matData = materials.find(m => m.id === materialId) || {};
                                                        const displayName = item._tempName || matData.name || 'Unknown Material';

                                                        return (
                                                            <Draggable key={item.id} draggableId={item.id} index={index}>
                                                                {(provided, snapshot) => (
                                                                    <div
                                                                        ref={provided.innerRef}
                                                                        {...provided.draggableProps}
                                                                        className={`
                                                                            mb-3 p-4 rounded-xl border flex flex-col md:flex-row md:items-center space-y-4 md:space-y-0 md:space-x-4
                                                                            ${snapshot.isDragging ? 'bg-[#1e293b] border-primary shadow-2xl' : 'bg-[#162032] border-white/10 hover:border-white/20'}
                                                                        `}
                                                                    >
                                                                        <div {...provided.dragHandleProps} className="p-2 -ml-2 text-textMuted hover:text-white cursor-grab active:cursor-grabbing">
                                                                            <MdDragIndicator className="w-5 h-5" />
                                                                        </div>
                                                                        
                                                                        <div className="w-full md:w-1/3">
                                                                            <p className="font-bold text-white tracking-wide">{displayName}</p>
                                                                            <p className="text-xs text-textMuted font-mono mt-1">ID: {materialId.substring(0,8)}... </p>
                                                                            <input type="hidden" {...register(`ingredients.${index}.raw_material`)} />
                                                                        </div>

                                                                        <div className="flex-1 grid grid-cols-2 gap-4">
                                                                            <div>
                                                                                <label className="block text-[10px] uppercase tracking-wider text-textMuted mb-1 font-semibold">Consumption Qty</label>
                                                                                <input 
                                                                                    type="number" 
                                                                                    step="0.0001" 
                                                                                    {...register(`ingredients.${index}.quantity`)} 
                                                                                    className="form-input w-full font-mono text-accent text-sm py-1.5" 
                                                                                />
                                                                                {errors.ingredients?.[index]?.quantity && <span className="text-red-400 text-[10px]">{errors.ingredients[index].quantity.message}</span>}
                                                                            </div>
                                                                            <div>
                                                                                <label className="block text-[10px] uppercase tracking-wider text-textMuted mb-1 font-semibold">Unit of Measure</label>
                                                                                <Controller
                                                                                    name={`ingredients.${index}.unit`}
                                                                                    control={control}
                                                                                    render={({ field }) => (
                                                                                        <Select
                                                                                            {...field}
                                                                                            options={units.map(u => ({ value: u.id, label: `${u.name} (${u.abbreviation})` }))}
                                                                                            styles={{...selectStyles, control: (b, s) => ({...selectStyles.control(b,s), minHeight: '34px'})}}
                                                                                            value={units.map(u => ({ value: u.id, label: `${u.name} (${u.abbreviation})` })).find(u => u.value === field.value)}
                                                                                            onChange={val => field.onChange(val.value)}
                                                                                        />
                                                                                    )}
                                                                                />
                                                                            </div>
                                                                        </div>

                                                                        <button 
                                                                            type="button" 
                                                                            onClick={() => remove(index)}
                                                                            className="w-10 h-10 shrink-0 flex items-center justify-center rounded-lg bg-red-500/10 text-red-400 hover:bg-red-500/20 transition-colors self-end md:self-auto"
                                                                        >
                                                                            <FiTrash2 />
                                                                        </button>
                                                                    </div>
                                                                )}
                                                            </Draggable>
                                                        )
                                                    })}
                                                    {provided.placeholder}
                                                </div>
                                            )}
                                        </Droppable>
                                        {errors.ingredients?.root && <span className="text-red-400 text-sm mt-3 font-medium bg-red-500/10 p-3 rounded-lg block border border-red-500/20">{errors.ingredients.root.message}</span>}
                                        
                                        <div className="mt-4">
                                             <label className="block text-sm font-medium text-textMuted mb-1.5">Preparation Instructions / Notes (Optional)</label>
                                             <textarea {...register('notes')} className="form-input w-full min-h-[60px] text-sm" placeholder="e.g. Blend until smooth. Add ice last."></textarea>
                                        </div>
                                    </div>
                                </div>
                            </DragDropContext>
                        </div>
                    </div>
                </div>
            )}

            {/* View Recipe Modal (Read-Only) */}
            {viewRecipe && (
                 <div className="fixed inset-0 z-50 flex items-center justify-center p-4">
                    <div className="fixed inset-0 bg-black/60 backdrop-blur-sm" onClick={() => setViewRecipe(null)}></div>
                    <div className="relative glass-panel w-full max-w-2xl p-0 overflow-hidden">
                        <div className="bg-[#1e293b] p-6 border-b border-white/10">
                            <h2 className="text-2xl font-bold text-white">{viewRecipe.product_name} Recipe</h2>
                            <div className="flex space-x-6 mt-3 text-sm">
                                <span className="text-primary font-mono bg-primary/10 px-3 py-1 rounded-full border border-primary/20">Yield: {parseFloat(viewRecipe.yield_quantity)}</span>
                                <span className="text-textMuted bg-white/5 px-3 py-1 rounded-full border border-white/10">Prep: {viewRecipe.preparation_time} mins</span>
                                <span className="text-red-400 font-mono font-bold bg-red-500/10 px-3 py-1 rounded-full border border-red-500/20">Cost: {settings?.currency}{parseFloat(viewRecipe.total_cost).toFixed(2)}</span>
                            </div>
                        </div>
                        <div className="p-6 bg-[#0f172a] max-h-[60vh] overflow-y-auto">
                            <h3 className="text-sm uppercase tracking-widest text-textMuted font-bold mb-4">Required Ingredients</h3>
                            <div className="space-y-2">
                                {viewRecipe.ingredients.map((ing, idx) => (
                                    <div key={idx} className="flex justify-between items-center bg-white/5 border border-white/10 p-3 rounded-lg">
                                        <div>
                                            <p className="font-bold text-white">{ing.raw_material_name}</p>
                                        </div>
                                        <div className="text-right">
                                            <p className="font-mono text-accent text-lg">{parseFloat(ing.quantity)} <span className="text-sm text-textMuted">{ing.unit_abbreviation}</span></p>
                                            <p className="text-xs text-red-400 font-mono">Cost: {settings?.currency}{parseFloat(ing.cost).toFixed(2)}</p>
                                        </div>
                                    </div>
                                ))}
                            </div>
                            {viewRecipe.notes && (
                                <div className="mt-6 p-4 bg-[#1e293b] rounded-lg border border-white/10">
                                    <h3 className="text-sm uppercase tracking-widest text-textMuted font-bold mb-2">Instructions</h3>
                                    <p className="text-sm text-white whitespace-pre-wrap leading-relaxed">{viewRecipe.notes}</p>
                                </div>
                            )}
                        </div>
                        <div className="p-4 bg-[#1e293b] border-t border-white/10 flex justify-end">
                            <button onClick={() => setViewRecipe(null)} className="px-6 py-2 bg-white/10 hover:bg-white/20 text-white rounded-lg transition-colors font-medium">Close</button>
                        </div>
                    </div>
                </div>
            )}

            <ConfirmModal 
                isOpen={deleteConfirmOpen}
                title="Delete Recipe Formula"
                message={`Are you sure you want to delete the recipe for "${recipeToDelete?.product_name}"? This action cannot be undone.`}
                onConfirm={confirmDelete}
                onCancel={() => setDeleteConfirmOpen(false)}
                confirmText="Delete Recipe"
                isDestructive={true}
            />
        </div>
    );
};

export default Recipes;

import React, { useState, useEffect, useMemo } from 'react';
import { useForm, Controller } from 'react-hook-form';
import Select from 'react-select';
import { yupResolver } from '@hookform/resolvers/yup';
import * as yup from 'yup';
import toast from 'react-hot-toast';
import { FiPlus, FiEdit2, FiTrash2, FiRepeat } from 'react-icons/fi';
import { inventoryApi } from '../../api/inventoryApi';
import DataTable from '../../components/DataTable';
import ConfirmModal from '../../components/ConfirmModal';

const conversionSchema = yup.object().shape({
    from_unit: yup.number().required('From Unit is required'),
    to_unit: yup.number().required('To Unit is required'),
    multiplier: yup.number().positive('Must be positive').required('Multiplier is required'),
});

const selectStyles = {
    control: (base, state) => ({
        ...base,
        background: 'rgba(255, 255, 255, 0.05)',
        borderColor: state.isFocused ? '#3b82f6' : 'rgba(255, 255, 255, 0.1)',
        color: '#fff',
        minHeight: '40px',
        boxShadow: 'none',
        borderRadius: '0.5rem',
        '&:hover': { borderColor: 'rgba(255, 255, 255, 0.2)' }
    }),
    menu: (base) => ({
        ...base,
        background: '#1e293b',
        border: '1px solid rgba(255, 255, 255, 0.1)',
        zIndex: 100
    }),
    option: (base, state) => ({
        ...base,
        background: state.isSelected ? 'rgba(59, 130, 246, 0.3)' : state.isFocused ? 'rgba(59, 130, 246, 0.1)' : 'transparent',
        color: state.isSelected ? '#fff' : '#cbd5e1',
        cursor: 'pointer',
        '&:active': { background: 'rgba(59, 130, 246, 0.4)' }
    }),
    singleValue: (base) => ({ ...base, color: '#fff' }),
    input: (base) => ({ ...base, color: '#fff' })
};

const UnitConversions = () => {
    const [conversions, setConversions] = useState([]);
    const [units, setUnits] = useState([]);
    const [isLoading, setIsLoading] = useState(true);
    const [isModalOpen, setIsModalOpen] = useState(false);
    const [editingConversion, setEditingConversion] = useState(null);
    const [deleteConfirmOpen, setDeleteConfirmOpen] = useState(false);
    const [conversionToDelete, setConversionToDelete] = useState(null);

    const { register, control, handleSubmit, reset, setValue, formState: { errors } } = useForm({
        resolver: yupResolver(conversionSchema)
    });

    const fetchData = async () => {
        setIsLoading(true);
        try {
            const [convRes, unitRes] = await Promise.all([
                inventoryApi.getConversions(),
                inventoryApi.getUnits()
            ]);
            setConversions(convRes.data);
            setUnits(unitRes.data);
        } catch (error) {
            toast.error("Failed to fetch unit conversions");
        } finally {
            setIsLoading(false);
        }
    };

    useEffect(() => {
        fetchData();
    }, []);

    const openAddModal = () => {
        setEditingConversion(null);
        reset({ from_unit: '', to_unit: '', multiplier: '' });
        setIsModalOpen(true);
    };

    const openEditModal = (conversion) => {
        setEditingConversion(conversion);
        // Note: The conversion object likely has from_unit and to_unit as scalar IDs, but verify this based on your API response
        setValue('from_unit', conversion.from_unit);
        setValue('to_unit', conversion.to_unit);
        setValue('multiplier', conversion.multiplier);
        setIsModalOpen(true);
    };

    const onSubmit = async (data) => {
        try {
            if (editingConversion) {
                await inventoryApi.updateConversion(editingConversion.id, data);
                toast.success("Conversion updated successfully");
            } else {
                await inventoryApi.createConversion(data);
                toast.success("Conversion rule created");
            }
            setIsModalOpen(false);
            fetchData();
        } catch (error) {
             toast.error(error.response?.data?.non_field_errors?.[0] || "Failed to save conversion");
        }
    };

    const confirmDelete = async () => {
        try {
            await inventoryApi.deleteConversion(conversionToDelete.id);
            toast.success("Conversion deleted");
            setDeleteConfirmOpen(false);
            fetchData();
        } catch (error) {
            toast.error("Failed to delete conversion");
        }
    };

    const columns = useMemo(() => [
        {
            header: 'From Unit (Base)',
            accessorKey: 'from_unit_name',
            cell: info => <span className="font-semibold text-white">{info.getValue()} ({info.row.original.from_unit_abbreviation})</span>
        },
        {
            header: 'Multiplier',
            accessorKey: 'multiplier',
            cell: info => <span className="font-mono text-accent">x {info.getValue()}</span>
        },
        {
            header: 'To Unit (Target)',
            accessorKey: 'to_unit_name',
            cell: info => <span className="font-semibold text-white">{info.getValue()} ({info.row.original.to_unit_abbreviation})</span>
        },
        {
            header: 'Formula Example',
            id: 'formula',
            cell: info => (
                <div className="text-sm text-textMuted bg-white/5 px-3 py-1.5 rounded inline-flex items-center space-x-2">
                    <span>1 {info.row.original.from_unit_abbreviation}</span>
                    <FiRepeat className="w-3 h-3" />
                    <span>{parseFloat(info.row.original.multiplier)} {info.row.original.to_unit_abbreviation}</span>
                </div>
            )
        },
        {
            header: 'Actions',
            id: 'actions',
            cell: info => (
                <div className="flex space-x-2">
                    <button 
                        onClick={(e) => { e.stopPropagation(); openEditModal(info.row.original); }}
                        className="p-1.5 bg-white/5 hover:bg-white/10 text-white rounded transition-colors"
                    >
                        <FiEdit2 className="w-4 h-4" />
                    </button>
                    <button 
                        onClick={(e) => { 
                            e.stopPropagation(); 
                            setConversionToDelete(info.row.original);
                            setDeleteConfirmOpen(true);
                        }}
                        className="p-1.5 bg-red-500/20 text-red-400 rounded hover:bg-red-500/30 transition-colors"
                    >
                        <FiTrash2 className="w-4 h-4" />
                    </button>
                </div>
            )
        }
    ], [units]);

    return (
        <div className="p-6">
            <div className="flex justify-between items-center mb-6">
                <div>
                     <h1 className="text-2xl font-bold text-white">Unit Conversions</h1>
                     <p className="text-sm text-textMuted mt-1">Define rules for converting bulk units (e.g., KGs) into prep units (e.g., Grams).</p>
                </div>
                <button 
                    onClick={openAddModal}
                    className="bg-primary hover:bg-primary/90 text-white px-4 py-2 rounded-lg font-medium transition-colors flex items-center space-x-2 shadow-lg shadow-primary/20"
                >
                    <FiPlus className="w-5 h-5" />
                    <span>Add Rule</span>
                </button>
            </div>

            <DataTable 
                columns={columns} 
                data={conversions} 
                isLoading={isLoading}
                searchPlaceholder="Search conversions..."
            />

            {/* Modal */}
            {isModalOpen && (
                <div className="fixed inset-0 z-50 flex items-center justify-center p-4">
                    <div className="fixed inset-0 bg-black/60 backdrop-blur-sm" onClick={() => setIsModalOpen(false)}></div>
                    <div className="relative glass-panel w-full max-w-lg p-6">
                        <h2 className="text-xl font-bold text-white mb-6">
                            {editingConversion ? 'Edit Conversion' : 'New Conversion Rule'}
                        </h2>
                        
                        <form onSubmit={handleSubmit(onSubmit)} className="space-y-5">
                            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                                <div>
                                    <label className="block text-sm font-medium text-textMuted mb-2">From Unit (Base)</label>
                                    <Controller
                                        name="from_unit"
                                        control={control}
                                        render={({ field }) => (
                                            <Select
                                                {...field}
                                                options={units.map(u => ({ value: u.id, label: `${u.name} (${u.abbreviation})` }))}
                                                styles={selectStyles}
                                                placeholder="e.g. Kilogram"
                                                value={units.map(u => ({ value: u.id, label: `${u.name} (${u.abbreviation})` })).find(u => u.value === field.value)}
                                                onChange={val => field.onChange(val.value)}
                                            />
                                        )}
                                    />
                                    {errors.from_unit && <span className="text-red-400 text-xs mt-1 block">{errors.from_unit.message}</span>}
                                </div>

                                <div>
                                    <label className="block text-sm font-medium text-textMuted mb-2">To Unit (Target)</label>
                                    <Controller
                                        name="to_unit"
                                        control={control}
                                        render={({ field }) => (
                                            <Select
                                                {...field}
                                                options={units.map(u => ({ value: u.id, label: `${u.name} (${u.abbreviation})` }))}
                                                styles={selectStyles}
                                                placeholder="e.g. Grams"
                                                value={units.map(u => ({ value: u.id, label: `${u.name} (${u.abbreviation})` })).find(u => u.value === field.value)}
                                                onChange={val => field.onChange(val.value)}
                                            />
                                        )}
                                    />
                                    {errors.to_unit && <span className="text-red-400 text-xs mt-1 block">{errors.to_unit.message}</span>}
                                </div>
                            </div>

                            <div className="p-4 bg-primary/10 border border-primary/20 rounded-lg">
                                <label className="block text-sm font-medium text-primary mb-2">Multiplier</label>
                                <div className="flex items-center space-x-3">
                                    <span className="text-white whitespace-nowrap">1 Base =</span>
                                    <div className="flex-1">
                                        <input 
                                            type="number" 
                                            step="0.00001" 
                                            {...register('multiplier')} 
                                            className="form-input w-full font-mono text-accent text-lg" 
                                            placeholder="e.g. 1000"
                                        />
                                    </div>
                                    <span className="text-white whitespace-nowrap">Targets</span>
                                </div>
                                {errors.multiplier && <span className="text-red-400 text-xs mt-1 block">{errors.multiplier.message}</span>}
                                <p className="text-xs text-textMuted mt-2">Example: If converting Kilograms to Grams, multiplier is 1000. If converting Boxes (of 12) to Pieces, multiplier is 12.</p>
                            </div>

                            <div className="flex justify-end space-x-3 pt-4 border-t border-white/10">
                                <button type="button" onClick={() => setIsModalOpen(false)} className="px-4 py-2 rounded-lg text-textMuted hover:bg-white/5 transition-colors">
                                    Cancel
                                </button>
                                <button type="submit" className="bg-primary hover:bg-primary/90 text-white px-6 py-2 rounded-lg transition-colors font-medium shadow-lg">
                                    Save Rule
                                </button>
                            </div>
                        </form>
                    </div>
                </div>
            )}

            <ConfirmModal 
                isOpen={deleteConfirmOpen}
                title="Delete Conversion Rule"
                message={`Are you sure you want to delete this conversion rule? Recipes relying on this specific conversion may fail to calculate costs correctly.`}
                onConfirm={confirmDelete}
                onCancel={() => setDeleteConfirmOpen(false)}
                confirmText="Delete Rule"
                isDestructive={true}
            />
        </div>
    );
};

export default UnitConversions;

import React, { useState, useEffect, useMemo } from 'react';
import { useForm } from 'react-hook-form';
import { yupResolver } from '@hookform/resolvers/yup';
import * as yup from 'yup';
import toast from 'react-hot-toast';
import { FiPlus, FiTrash2, FiEdit2 } from 'react-icons/fi';
import DataTable from '../../components/DataTable';
import ConfirmModal from '../../components/ConfirmModal';
import { inventoryApi } from '../../api/inventoryApi';

const unitSchema = yup.object().shape({
  name: yup.string().required('Unit name is required'),
  abbreviation: yup.string().required('Abbreviation is required').max(10, 'Max 10 chars')
});

const Units = () => {
    const [units, setUnits] = useState([]);
    const [isLoading, setIsLoading] = useState(true);
    
    const [isModalOpen, setIsModalOpen] = useState(false);
    const [editingUnit, setEditingUnit] = useState(null);
    const [deleteConfirmOpen, setDeleteConfirmOpen] = useState(false);
    const [unitToDelete, setUnitToDelete] = useState(null);

    const { register, handleSubmit, reset, formState: { errors } } = useForm({
        resolver: yupResolver(unitSchema)
    });

    const fetchUnits = async () => {
        setIsLoading(true);
        try {
            const res = await inventoryApi.getUnits();
            setUnits(res.data);
        } catch (error) {
            toast.error('Failed to load units');
        } finally {
            setIsLoading(false);
        }
    };

    useEffect(() => {
        fetchUnits();
    }, []);

    const openAddModal = () => {
        setEditingUnit(null);
        reset({ name: '', abbreviation: '' });
        setIsModalOpen(true);
    };

    const openEditModal = (unit) => {
        setEditingUnit(unit);
        reset({ name: unit.name, abbreviation: unit.abbreviation });
        setIsModalOpen(true);
    };

    const onSubmit = async (data) => {
        try {
            if (editingUnit) {
                await inventoryApi.updateUnit(editingUnit.id, data);
                toast.success('Unit updated successfully');
            } else {
                await inventoryApi.createUnit(data);
                toast.success('Unit created successfully');
            }
            setIsModalOpen(false);
            fetchUnits();
        } catch (error) {
            toast.error('Failed to save unit');
        }
    };

    const confirmDelete = async () => {
        try {
            await inventoryApi.deleteUnit(unitToDelete.id);
            toast.success('Unit deleted successfully');
            setDeleteConfirmOpen(false);
            fetchUnits();
        } catch (error) {
            toast.error('Cannot delete unit. It might be used by existing materials.');
            setDeleteConfirmOpen(false);
        }
    };

    const columns = useMemo(() => [
        {
            header: 'Unit Name',
            accessorKey: 'name',
            cell: info => <span className="font-semibold text-white">{info.getValue()}</span>
        },
        {
            header: 'Abbreviation',
            accessorKey: 'abbreviation',
            cell: info => <span className="font-mono bg-white/10 px-2 py-1 rounded text-sm">{info.getValue()}</span>
        },
        {
            header: 'Actions',
            id: 'actions',
            cell: info => (
                <div className="flex space-x-2">
                    <button 
                        onClick={(e) => { e.stopPropagation(); openEditModal(info.row.original); }}
                        className="p-1.5 bg-blue-500/20 text-blue-400 rounded hover:bg-blue-500/30 transition-colors"
                    >
                        <FiEdit2 className="w-4 h-4" />
                    </button>
                    <button 
                        onClick={(e) => { 
                            e.stopPropagation(); 
                            setUnitToDelete(info.row.original);
                            setDeleteConfirmOpen(true);
                        }}
                        className="p-1.5 bg-red-500/20 text-red-400 rounded hover:bg-red-500/30 transition-colors"
                    >
                        <FiTrash2 className="w-4 h-4" />
                    </button>
                </div>
            )
        }
    ], []);

    return (
        <div className="p-6">
            <div className="flex justify-between items-center mb-6">
                <div>
                    <h1 className="text-2xl font-bold text-white">Measurement Units</h1>
                    <p className="text-textMuted text-sm">Manage units used for tracking inventory quantities (kg, ml, box)</p>
                </div>
                <button 
                    onClick={openAddModal}
                    className="bg-primary hover:bg-primary/90 text-white px-4 py-2 rounded-lg font-medium transition-colors flex items-center space-x-2 shadow-lg shadow-primary/20"
                >
                    <FiPlus className="w-5 h-5" />
                    <span>Add Unit</span>
                </button>
            </div>

            <DataTable 
                columns={columns} 
                data={units} 
                isLoading={isLoading}
                searchPlaceholder="Search units..."
            />

            {isModalOpen && (
                <div className="fixed inset-0 z-50 flex items-center justify-center p-4">
                    <div className="fixed inset-0 bg-black/60 backdrop-blur-sm" onClick={() => setIsModalOpen(false)}></div>
                    <div className="relative glass-panel w-full max-w-sm p-6">
                        <h2 className="text-xl font-bold text-white mb-4">
                            {editingUnit ? 'Edit Unit' : 'Add Unit'}
                        </h2>
                        
                        <form onSubmit={handleSubmit(onSubmit)} className="space-y-4">
                            <div>
                                <label className="block text-sm font-medium text-textMuted mb-1">Unit Name *</label>
                                <input {...register('name')} className="form-input" placeholder="e.g. Kilogram" />
                                {errors.name && <span className="text-red-400 text-xs">{errors.name.message}</span>}
                            </div>
                            <div>
                                <label className="block text-sm font-medium text-textMuted mb-1">Abbreviation *</label>
                                <input {...register('abbreviation')} className="form-input" placeholder="e.g. kg" />
                                {errors.abbreviation && <span className="text-red-400 text-xs">{errors.abbreviation.message}</span>}
                            </div>
                            
                            <div className="flex justify-end space-x-3 pt-4 border-t border-white/10 mt-6">
                                <button type="button" onClick={() => setIsModalOpen(false)} className="px-4 py-2 rounded-lg text-textMuted hover:bg-white/5 transition-colors">
                                    Cancel
                                </button>
                                <button type="submit" className="bg-primary hover:bg-primary/90 text-white px-4 py-2 rounded-lg transition-colors">
                                    Save
                                </button>
                            </div>
                        </form>
                    </div>
                </div>
            )}

            <ConfirmModal 
                isOpen={deleteConfirmOpen}
                title="Delete Unit"
                message={`Are you sure you want to delete the unit "${unitToDelete?.name}"?`}
                onConfirm={confirmDelete}
                onCancel={() => setDeleteConfirmOpen(false)}
                confirmText="Delete"
                isDestructive={true}
            />
        </div>
    );
};

export default Units;

import React, { useState, useEffect, useMemo } from 'react';
import { useForm, Controller } from 'react-hook-form';
import Select from 'react-select';
import { yupResolver } from '@hookform/resolvers/yup';
import * as yup from 'yup';
import toast from 'react-hot-toast';
import { FiPlus, FiTrash2 } from 'react-icons/fi';
import DataTable from '../../components/DataTable';
import { inventoryApi } from '../../api/inventoryApi';
import useSettingsStore from '../../store/settingsStore';

const wasteSchema = yup.object().shape({
  raw_material: yup.string().required('Material is required'),
  quantity: yup.number().min(0.01, 'Quantity must be > 0').required('Required'),
  reason: yup.string().required('Reason is required'),
  notes: yup.string()
});

const WasteLogs = () => {
    const [logs, setLogs] = useState([]);
    const [materials, setMaterials] = useState([]);
    const [isLoading, setIsLoading] = useState(true);
    const [isCreateModalOpen, setIsCreateModalOpen] = useState(false);

    const { settings } = useSettingsStore();

    const selectStyles = {
        control: (base, state) => ({
            ...base,
            background: 'rgba(255, 255, 255, 0.05)',
            borderColor: state.isFocused ? '#3b82f6' : 'rgba(255, 255, 255, 0.1)',
            color: '#fff',
            minHeight: '40px',
            boxShadow: 'none',
            borderRadius: '0.5rem',
            '&:hover': { borderColor: 'rgba(255, 255, 255, 0.2)' }
        }),
        menu: (base) => ({
            ...base,
            background: '#1e293b',
            border: '1px solid rgba(255, 255, 255, 0.1)',
            zIndex: 100
        }),
        option: (base, state) => ({
            ...base,
            background: state.isSelected ? 'rgba(59, 130, 246, 0.3)' : state.isFocused ? 'rgba(59, 130, 246, 0.1)' : 'transparent',
            color: state.isSelected ? '#fff' : '#cbd5e1',
            cursor: 'pointer',
            '&:active': { background: 'rgba(59, 130, 246, 0.4)' }
        }),
        singleValue: (base) => ({ ...base, color: '#fff' }),
        input: (base) => ({ ...base, color: '#fff' })
    };

    const { register, control, handleSubmit, reset, formState: { errors } } = useForm({
        resolver: yupResolver(wasteSchema)
    });

    const fetchData = async () => {
        setIsLoading(true);
        try {
            const [logsRes, matRes] = await Promise.all([
                inventoryApi.getWasteLogs(),
                inventoryApi.getMaterials()
            ]);
            setLogs(logsRes.data);
            setMaterials(matRes.data);
        } catch (error) {
            toast.error('Failed to load waste logs');
        } finally {
            setIsLoading(false);
        }
    };

    useEffect(() => {
        fetchData();
    }, []);

    const onSubmit = async (data) => {
        try {
            await inventoryApi.createWasteLog(data);
            toast.success('Waste log recorded successfully. Stock adjusted.');
            setIsCreateModalOpen(false);
            fetchData();
        } catch (error) {
             toast.error(error.response?.data?.error || 'Failed to record waste');
        }
    };

    const columns = useMemo(() => [
        {
            header: 'Date',
            accessorFn: row => new Date(row.date_logged).toLocaleString(),
        },
        {
            header: 'Material',
            accessorKey: 'raw_material_name',
            cell: info => <span className="font-semibold">{info.getValue()}</span>
        },
        {
            header: 'Quantity Discarded',
            accessorFn: row => `${parseFloat(row.quantity)} ${row.unit_abbreviation || ''}`,
            cell: info => <span className="text-red-400 font-bold">{info.getValue()}</span>
        },
        {
            header: 'Calculated Cost',
            accessorFn: row => `${settings?.currency || '$'}${parseFloat(row.financial_impact).toFixed(2)}`,
            cell: info => <span className="font-mono text-textMuted">{info.getValue()}</span>
        },
        {
            header: 'Reason',
            accessorKey: 'reason',
            cell: info => <span className="uppercase text-xs tracking-wider">{info.getValue().replace('_', ' ')}</span>
        },
        {
            header: 'Logged By',
            accessorKey: 'logged_by_name',
        }
    ], [settings]);

    return (
        <div className="p-6">
            <div className="flex justify-between items-center mb-6">
                <h1 className="text-2xl font-bold text-white">Waste & Spoilage Logs</h1>
                <button 
                    onClick={() => {
                        reset({ raw_material: '', quantity: '', reason: 'expired', notes: '' });
                        setIsCreateModalOpen(true);
                    }}
                    className="bg-red-500/20 text-red-400 hover:bg-red-500/30 border border-red-500/30 px-4 py-2 rounded-lg font-medium transition-colors flex items-center space-x-2"
                >
                    <FiTrash2 className="w-5 h-5" />
                    <span>Log Waste</span>
                </button>
            </div>

            <DataTable 
                columns={columns} 
                data={logs} 
                isLoading={isLoading}
                searchPlaceholder="Search logs..."
            />

            {/* Create Waste Modal */}
            {isCreateModalOpen && (
                <div className="fixed inset-0 z-50 flex items-center justify-center p-4">
                    <div className="fixed inset-0 bg-black/60 backdrop-blur-sm" onClick={() => setIsCreateModalOpen(false)}></div>
                    <div className="relative glass-panel w-full max-w-md p-6">
                        <h2 className="text-xl font-bold text-red-400 mb-2">Record Waste / Spoilage</h2>
                        <p className="text-textMuted text-sm mb-6">Logging this will permanently deduct stock from the inventory.</p>
                        
                        <form onSubmit={handleSubmit(onSubmit)} className="space-y-4">
                            <div>
                                <label className="block text-sm font-medium text-textMuted mb-1">Material *</label>
                                <Controller
                                    name="raw_material"
                                    control={control}
                                    render={({ field }) => (
                                        <Select
                                            {...field}
                                            options={materials.filter(m => m.is_active).map(m => ({ value: m.id, label: `${m.name} (Max: ${m.current_stock})` }))}
                                            styles={selectStyles}
                                            placeholder="Search Material..."
                                            value={materials.map(m => ({ value: m.id, label: `${m.name} (Max: ${m.current_stock})` })).find(m => m.value === field.value)}
                                            onChange={val => field.onChange(val.value)}
                                        />
                                    )}
                                />
                                {errors.raw_material && <span className="text-red-400 text-xs">{errors.raw_material.message}</span>}
                            </div>
                            
                            <div className="grid grid-cols-2 gap-4">
                                <div>
                                    <label className="block text-sm font-medium text-textMuted mb-1">Quantity Lost</label>
                                    <input type="number" step="0.001" {...register('quantity')} className="form-input" />
                                    {errors.quantity && <span className="text-red-400 text-xs">{errors.quantity.message}</span>}
                                </div>
                                <div>
                                    <label className="block text-sm font-medium text-textMuted mb-1">Reason</label>
                                    <select {...register('reason')} className="form-input">
                                        <option value="expired">Expired</option>
                                        <option value="damaged">Damaged / Dropped</option>
                                        <option value="quality_issue">Quality Issue</option>
                                        <option value="theft">Theft / Unaccounted</option>
                                        <option value="other">Other</option>
                                    </select>
                                    {errors.reason && <span className="text-red-400 text-xs">{errors.reason.message}</span>}
                                </div>
                            </div>
                            
                            <div>
                                <label className="block text-sm font-medium text-textMuted mb-1">Additional Notes</label>
                                <textarea {...register('notes')} className="form-input" rows="2" placeholder="e.g. Found damaged in the walk-in fridge"></textarea>
                            </div>

                            <div className="flex justify-end space-x-3 pt-4 border-t border-white/10 mt-6">
                                <button type="button" onClick={() => setIsCreateModalOpen(false)} className="px-4 py-2 rounded-lg text-textMuted hover:bg-white/5 transition-colors">
                                    Cancel
                                </button>
                                <button type="submit" className="bg-red-500/20 text-red-500 hover:bg-red-500/30 border border-red-500/30 px-4 py-2 rounded-lg transition-colors font-medium">
                                    Deduct Stock
                                </button>
                            </div>
                        </form>
                    </div>
                </div>
            )}
        </div>
    );
};

export default WasteLogs;

import React, { useState, useEffect, useCallback, useRef } from 'react';
import { posApi } from '../../api/posApi';
import { settingsApi } from '../../api/settingsApi';
import useSettingsStore from '../../store/settingsStore';
import useAuthStore from '../../store/authStore';
import toast from 'react-hot-toast';
import { format } from 'date-fns';
import {
    AreaChart, Area, BarChart, Bar, XAxis, YAxis, CartesianGrid,
    Tooltip, ResponsiveContainer, Legend
} from 'recharts';
import {
    FiSearch, FiFilter, FiX, FiEye, FiTrash2, FiEdit2, FiPrinter,
    FiCheckCircle, FiClock, FiXCircle, FiPlus, FiRefreshCw,
    FiShoppingBag, FiDollarSign, FiTrendingUp, FiAlertTriangle
} from 'react-icons/fi';
import { printReceipt } from '../pos/ReceiptPrinter';

// ---------- Helper Components ----------

const StatusBadge = ({ status }) => {
    const config = {
        completed: { color: 'bg-emerald-500/15 text-emerald-400 border-emerald-500/30', icon: <FiCheckCircle className="w-3 h-3" />, label: 'Completed' },
        pending:   { color: 'bg-amber-500/15 text-amber-400 border-amber-500/30',   icon: <FiClock className="w-3 h-3" />,       label: 'Pending'   },
        cancelled: { color: 'bg-red-500/15 text-red-400 border-red-500/30',         icon: <FiXCircle className="w-3 h-3" />,     label: 'Cancelled' },
    };
    const { color, icon, label } = config[status] || config.pending;
    return (
        <span className={`inline-flex items-center gap-1.5 px-2.5 py-1 rounded-full text-xs font-bold border ${color}`}>
            {icon}{label}
        </span>
    );
};

const TypeBadge = ({ type }) => {
    const config = {
        dine_in:  { color: 'bg-blue-500/15 text-blue-400',   label: 'Dine-In'  },
        takeaway: { color: 'bg-purple-500/15 text-purple-400', label: 'Takeaway' },
        delivery: { color: 'bg-orange-500/15 text-orange-400', label: 'Delivery' },
    };
    const { color, label } = config[type] || { color: 'bg-slate-500/15 text-slate-400', label: type };
    return (
        <span className={`inline-flex items-center px-2 py-0.5 rounded text-xs font-semibold ${color}`}>
            {label}
        </span>
    );
};

// ---------- Main Page Component ----------

const OrdersPage = () => {
    const { settings } = useSettingsStore();
    const { user } = useAuthStore();
    const currency = settings?.currency || 'EGP';

    // Role-based access — roles from authentication/models.py:
    // super_admin | manager | cashier | waiter | barista | chef | delivery_driver
    const userRole = user?.role || '';
    const canManage = ['super_admin', 'manager'].includes(userRole); // edit + cancel
    // All authenticated staff can reprint receipts

    // Data state
    const [orders, setOrders] = useState([]);
    const [summary, setSummary] = useState(null);
    const [cancelReasons, setCancelReasons] = useState([]);
    const [isLoading, setIsLoading] = useState(true);
    const [totalCount, setTotalCount] = useState(0);

    // Filter state
    const [search, setSearch] = useState('');
    const [filterStatus, setFilterStatus] = useState('');
    const [filterType, setFilterType] = useState('');
    const [filterPaid, setFilterPaid] = useState('');
    const [filterDateFrom, setFilterDateFrom] = useState('');
    const [filterDateTo, setFilterDateTo] = useState('');
    const [showFilters, setShowFilters] = useState(false);

    // Modal state
    const [selectedOrder, setSelectedOrder] = useState(null);
    const [showDetailModal, setShowDetailModal] = useState(false);
    const [showCancelModal, setShowCancelModal] = useState(false);
    const [cancelTargetId, setCancelTargetId] = useState(null);
    const [selectedCancelReason, setSelectedCancelReason] = useState('');
    const [customCancelReason, setCustomCancelReason] = useState('');
    const [isCancelling, setIsCancelling] = useState(false);

    // Edit state
    const [showEditModal, setShowEditModal] = useState(false);
    const [editTarget, setEditTarget] = useState(null);
    const [editNotes, setEditNotes] = useState('');
    const [isEditing, setIsEditing] = useState(false);

    const searchTimeout = useRef(null);

    const fetchOrders = useCallback(async () => {
        setIsLoading(true);
        try {
            const params = {};
            if (search) params.search = search;
            if (filterStatus) params.status = filterStatus;
            if (filterType) params.order_type = filterType;
            if (filterPaid) params.is_paid = filterPaid;
            if (filterDateFrom) params.date_from = filterDateFrom;
            if (filterDateTo) params.date_to = filterDateTo;

            const res = await posApi.getOrders(params);
            const data = Array.isArray(res.data) ? res.data : (res.data.results || []);
            setOrders(data);
            setTotalCount(data.length);
        } catch (err) {
            toast.error('Failed to load orders');
        } finally {
            setIsLoading(false);
        }
    }, [search, filterStatus, filterType, filterPaid, filterDateFrom, filterDateTo]);

    const fetchSummary = async () => {
        try {
            const res = await posApi.getOrdersSummary();
            setSummary(res.data);
        } catch (_) {}
    };

    const fetchCancelReasons = async () => {
        try {
            const res = await settingsApi.getCancelReasons();
            setCancelReasons(res.data.filter(r => r.is_active));
        } catch (_) {}
    };

    useEffect(() => {
        fetchSummary();
        fetchCancelReasons();
    }, []);

    useEffect(() => {
        if (searchTimeout.current) clearTimeout(searchTimeout.current);
        searchTimeout.current = setTimeout(() => fetchOrders(), 300);
        return () => clearTimeout(searchTimeout.current);
    }, [fetchOrders]);

    const activeFiltersCount = [filterStatus, filterType, filterPaid, filterDateFrom, filterDateTo].filter(Boolean).length;

    const handleClearFilters = () => {
        setFilterStatus('');
        setFilterType('');
        setFilterPaid('');
        setFilterDateFrom('');
        setFilterDateTo('');
    };

    const openCancelModal = (id) => {
        setCancelTargetId(id);
        setSelectedCancelReason('');
        setCustomCancelReason('');
        setShowCancelModal(true);
    };

    const handleCancelOrder = async () => {
        const reason = selectedCancelReason === '__custom__' ? customCancelReason : selectedCancelReason;
        if (!reason.trim()) {
            toast.error('Please select or type a cancellation reason');
            return;
        }
        setIsCancelling(true);
        try {
            await posApi.cancelOrder(cancelTargetId, reason);
            toast.success('Order cancelled');
            setShowCancelModal(false);
            fetchOrders();
            fetchSummary();
        } catch (err) {
            toast.error(err.response?.data?.error || 'Failed to cancel order');
        } finally {
            setIsCancelling(false);
        }
    };

    const openEditModal = (order) => {
        setEditTarget(order);
        setEditNotes(order.notes || '');
        setShowEditModal(true);
    };

    const handleSaveEdit = async () => {
        if (!editTarget) return;
        setIsEditing(true);
        try {
            await posApi.updateOrder(editTarget.id, { notes: editNotes });
            toast.success('Order updated');
            setShowEditModal(false);
            fetchOrders();
        } catch (err) {
            toast.error('Failed to update order');
        } finally {
            setIsEditing(false);
        }
    };

    // Reprint receipt for any historical order — available to ALL roles
    const handlePrint = (order) => {
        printReceipt({
            order,
            cart: [],  // order.items will be used (already has full data from GET /orders/)
            subtotal:      parseFloat(order.subtotal        || 0),
            taxInfo:       parseFloat(order.tax_amount      || 0),
            serviceCharge: parseFloat(order.service_charge  || 0),
            discountInfo:  parseFloat(order.discount_amount || 0),
            total:         parseFloat(order.total_amount    || 0),
            payments:      order.payments || [],
            remainingBalance: 0,
        });
    };

    // ---------- Chart Data Preparation ----------
    const dailyChartData = (summary?.daily || []).map(d => ({
        day: format(new Date(d.day), 'dd MMM'),
        Revenue: parseFloat(d.revenue || 0).toFixed(0),
        Orders: d.count || 0,
    }));

    const typeChartData = summary ? [
        { name: 'Dine-In', value: summary.by_type?.dine_in || 0 },
        { name: 'Takeaway', value: summary.by_type?.takeaway || 0 },
        { name: 'Delivery', value: summary.by_type?.delivery || 0 },
    ] : [];

    return (
        <div className="p-6 space-y-6">

            {/* ---- PAGE HEADER ---- */}
            <div className="flex justify-between items-center">
                <div>
                    <h1 className="text-3xl font-black text-textMain">Orders</h1>
                    <p className="text-textMuted mt-1">Manage and review all transactions</p>
                </div>
                <button
                    onClick={() => { fetchOrders(); fetchSummary(); }}
                    className="flex items-center gap-2 px-4 py-2 bg-surface border border-slate-200 dark:border-white/10 rounded-xl text-textMuted hover:text-textMain transition-colors text-sm font-semibold"
                >
                    <FiRefreshCw className="w-4 h-4" /> Refresh
                </button>
            </div>

            {/* ---- STATS CARDS ---- */}
            {summary && (
                <div className="grid grid-cols-1 sm:grid-cols-2 xl:grid-cols-4 gap-4">
                    <StatCard icon={<FiShoppingBag />} label="Total Orders" value={summary.total_orders} color="blue" />
                    <StatCard icon={<FiDollarSign />} label="Total Revenue" value={`${currency} ${parseFloat(summary.total_revenue || 0).toFixed(2)}`} color="emerald" />
                    <StatCard icon={<FiClock />} label="Pending" value={summary.pending_orders} color="amber" />
                    <StatCard icon={<FiAlertTriangle />} label="Cancelled" value={summary.cancelled_orders} color="red" />
                </div>
            )}

            {/* ---- CHARTS ---- */}
            {dailyChartData.length > 0 && (
                <div className="grid grid-cols-1 xl:grid-cols-3 gap-4">
                    {/* Revenue Area Chart */}
                    <div className="xl:col-span-2 bg-surface border border-slate-200 dark:border-white/10 rounded-2xl p-5">
                        <h3 className="text-textMain font-bold mb-4">Revenue (Last 30 Days)</h3>
                        <ResponsiveContainer width="100%" height={200}>
                            <AreaChart data={dailyChartData}>
                                <defs>
                                    <linearGradient id="revenueGrad" x1="0" y1="0" x2="0" y2="1">
                                        <stop offset="5%" stopColor="#3b82f6" stopOpacity={0.3} />
                                        <stop offset="95%" stopColor="#3b82f6" stopOpacity={0} />
                                    </linearGradient>
                                </defs>
                                <CartesianGrid strokeDasharray="3 3" stroke="rgba(255,255,255,0.05)" />
                                <XAxis dataKey="day" tick={{ fill: '#94a3b8', fontSize: 11 }} axisLine={false} tickLine={false} />
                                <YAxis tick={{ fill: '#94a3b8', fontSize: 11 }} axisLine={false} tickLine={false} />
                                <Tooltip contentStyle={{ background: '#1e293b', border: 'none', borderRadius: '10px', color: '#fff' }} />
                                <Area type="monotone" dataKey="Revenue" stroke="#3b82f6" strokeWidth={2} fill="url(#revenueGrad)" />
                            </AreaChart>
                        </ResponsiveContainer>
                    </div>

                    {/* Orders by Type Bar Chart */}
                    <div className="bg-surface border border-slate-200 dark:border-white/10 rounded-2xl p-5">
                        <h3 className="text-textMain font-bold mb-4">Order Mix</h3>
                        <ResponsiveContainer width="100%" height={200}>
                            <BarChart data={typeChartData} barSize={28}>
                                <CartesianGrid strokeDasharray="3 3" stroke="rgba(255,255,255,0.05)" />
                                <XAxis dataKey="name" tick={{ fill: '#94a3b8', fontSize: 11 }} axisLine={false} tickLine={false} />
                                <YAxis tick={{ fill: '#94a3b8', fontSize: 11 }} axisLine={false} tickLine={false} />
                                <Tooltip contentStyle={{ background: '#1e293b', border: 'none', borderRadius: '10px', color: '#fff' }} />
                                <Bar dataKey="value" name="Orders" fill="#6366f1" radius={[6, 6, 0, 0]} />
                            </BarChart>
                        </ResponsiveContainer>
                    </div>
                </div>
            )}

            {/* ---- FILTER BAR ---- */}
            <div className="bg-surface border border-slate-200 dark:border-white/10 rounded-2xl p-4 space-y-3">
                <div className="flex gap-3">
                    <div className="relative flex-1">
                        <FiSearch className="absolute left-3 top-1/2 -translate-y-1/2 text-textMuted w-4 h-4" />
                        <input
                            type="text"
                            placeholder="Search by order #, customer name or phone..."
                            value={search}
                            onChange={(e) => setSearch(e.target.value)}
                            className="w-full bg-background text-textMain border border-slate-200 dark:border-white/10 rounded-xl py-2.5 pl-10 pr-4 focus:outline-none focus:border-primary text-sm"
                        />
                        {search && (
                            <button onClick={() => setSearch('')} className="absolute right-3 top-1/2 -translate-y-1/2 text-textMuted hover:text-textMain">
                                <FiX className="w-4 h-4" />
                            </button>
                        )}
                    </div>
                    <button
                        onClick={() => setShowFilters(!showFilters)}
                        className={`flex items-center gap-2 px-4 py-2.5 rounded-xl text-sm font-bold border transition-colors ${showFilters || activeFiltersCount > 0 ? 'bg-primary text-white border-primary' : 'bg-background border-slate-200 dark:border-white/10 text-textMuted hover:text-textMain'}`}
                    >
                        <FiFilter className="w-4 h-4" />
                        Filters {activeFiltersCount > 0 && <span className="bg-white/20 text-white text-xs px-1.5 py-0.5 rounded-full">{activeFiltersCount}</span>}
                    </button>
                    {activeFiltersCount > 0 && (
                        <button onClick={handleClearFilters} className="text-sm text-red-400 hover:text-red-300 font-semibold px-3">
                            Clear All
                        </button>
                    )}
                </div>

                {showFilters && (
                    <div className="grid grid-cols-2 md:grid-cols-3 xl:grid-cols-5 gap-3 pt-3 border-t border-slate-200 dark:border-white/10">
                        <select value={filterStatus} onChange={e => setFilterStatus(e.target.value)} className="input text-sm">
                            <option value="">All Statuses</option>
                            <option value="pending">Pending</option>
                            <option value="completed">Completed</option>
                            <option value="cancelled">Cancelled</option>
                        </select>
                        <select value={filterType} onChange={e => setFilterType(e.target.value)} className="input text-sm">
                            <option value="">All Types</option>
                            <option value="dine_in">Dine-In</option>
                            <option value="takeaway">Takeaway</option>
                            <option value="delivery">Delivery</option>
                        </select>
                        <select value={filterPaid} onChange={e => setFilterPaid(e.target.value)} className="input text-sm">
                            <option value="">All Payment</option>
                            <option value="true">Paid</option>
                            <option value="false">Unpaid</option>
                        </select>
                        <div>
                            <label className="block text-xs text-textMuted mb-1">Date From</label>
                            <input type="date" value={filterDateFrom} onChange={e => setFilterDateFrom(e.target.value)} className="input text-sm w-full" />
                        </div>
                        <div>
                            <label className="block text-xs text-textMuted mb-1">Date To</label>
                            <input type="date" value={filterDateTo} onChange={e => setFilterDateTo(e.target.value)} className="input text-sm w-full" />
                        </div>
                    </div>
                )}
            </div>

            {/* ---- ORDERS TABLE ---- */}
            <div className="bg-surface border border-slate-200 dark:border-white/10 rounded-2xl overflow-hidden">
                <div className="p-4 border-b border-slate-200 dark:border-white/10 flex justify-between items-center">
                    <span className="text-textMain font-bold">
                        {isLoading ? 'Loading...' : `${totalCount} Orders`}
                    </span>
                </div>

                <div className="overflow-x-auto">
                    <table className="w-full text-sm">
                        <thead className="bg-background text-textMuted text-xs uppercase tracking-wide">
                            <tr>
                                <th className="px-4 py-3 text-left">Order #</th>
                                <th className="px-4 py-3 text-left">Date</th>
                                <th className="px-4 py-3 text-left">Type</th>
                                <th className="px-4 py-3 text-left">Customer</th>
                                <th className="px-4 py-3 text-center">Items</th>
                                <th className="px-4 py-3 text-right">Total</th>
                                <th className="px-4 py-3 text-center">Status</th>
                                <th className="px-4 py-3 text-center">Paid</th>
                                <th className="px-4 py-3 text-right">Actions</th>
                            </tr>
                        </thead>
                        <tbody className="divide-y divide-slate-100 dark:divide-white/5">
                            {isLoading ? (
                                <tr>
                                    <td colSpan={9} className="py-16 text-center text-textMuted">
                                        <div className="animate-pulse">Loading orders...</div>
                                    </td>
                                </tr>
                            ) : orders.length === 0 ? (
                                <tr>
                                    <td colSpan={9} className="py-16 text-center text-textMuted">
                                        <FiShoppingBag className="w-12 h-12 mx-auto mb-3 opacity-30" />
                                        <p>No orders found matching your filters.</p>
                                    </td>
                                </tr>
                            ) : (
                                orders.map(order => (
                                    <tr key={order.id} className="hover:bg-background/50 transition-colors">
                                        <td className="px-4 py-3">
                                            <span className="font-mono text-primary text-xs font-bold">{order.order_number}</span>
                                        </td>
                                        <td className="px-4 py-3 text-textMuted text-xs">
                                            {format(new Date(order.created_at), 'dd/MM/yy HH:mm')}
                                        </td>
                                        <td className="px-4 py-3">
                                            <TypeBadge type={order.order_type} />
                                        </td>
                                        <td className="px-4 py-3 text-textMain">
                                            {order.customer_name || order.customer_phone || <span className="text-textMuted italic">—</span>}
                                        </td>
                                        <td className="px-4 py-3 text-center text-textMuted">{order.items?.length || 0}</td>
                                        <td className="px-4 py-3 text-right font-mono font-bold text-textMain">
                                            {parseFloat(order.total_amount).toFixed(2)}
                                        </td>
                                        <td className="px-4 py-3 text-center">
                                            <StatusBadge status={order.status} />
                                        </td>
                                        <td className="px-4 py-3 text-center">
                                            <span className={`text-xs font-bold px-2 py-0.5 rounded-full ${order.is_paid ? 'bg-emerald-500/15 text-emerald-400' : 'bg-slate-500/15 text-slate-400'}`}>
                                                {order.is_paid ? '✓ Paid' : 'Unpaid'}
                                            </span>
                                        </td>
                                        <td className="px-4 py-3">
                                            <div className="flex items-center justify-end gap-1">
                                                {/* View — all roles */}
                                                <button
                                                    onClick={() => { setSelectedOrder(order); setShowDetailModal(true); }}
                                                    className="p-1.5 rounded-lg text-textMuted hover:text-primary hover:bg-primary/10 transition-colors"
                                                    title="View Details"
                                                >
                                                    <FiEye className="w-4 h-4" />
                                                </button>

                                                {/* Print — all roles */}
                                                <button
                                                    onClick={() => handlePrint(order)}
                                                    className="p-1.5 rounded-lg text-textMuted hover:text-blue-400 hover:bg-blue-400/10 transition-colors"
                                                    title="Reprint Receipt"
                                                >
                                                    <FiPrinter className="w-4 h-4" />
                                                </button>

                                                {/* Edit + Cancel — manager / super_admin only */}
                                                {canManage && order.status !== 'cancelled' && (
                                                    <>
                                                        <button
                                                            onClick={() => openEditModal(order)}
                                                            className="p-1.5 rounded-lg text-textMuted hover:text-amber-400 hover:bg-amber-400/10 transition-colors"
                                                            title="Edit Order"
                                                        >
                                                            <FiEdit2 className="w-4 h-4" />
                                                        </button>
                                                        <button
                                                            onClick={() => openCancelModal(order.id)}
                                                            className="p-1.5 rounded-lg text-textMuted hover:text-red-400 hover:bg-red-400/10 transition-colors"
                                                            title="Cancel Order"
                                                        >
                                                            <FiTrash2 className="w-4 h-4" />
                                                        </button>
                                                    </>
                                                )}

                                                {order.status === 'cancelled' && order.cancel_reason && (
                                                    <span className="text-[10px] text-red-400 italic max-w-[80px] truncate" title={order.cancel_reason}>
                                                        "{order.cancel_reason}"
                                                    </span>
                                                )}
                                            </div>
                                        </td>
                                    </tr>
                                ))
                            )}
                        </tbody>
                    </table>
                </div>
            </div>

            {/* ---- ORDER DETAIL MODAL ---- */}
            {showDetailModal && selectedOrder && (
                <div className="fixed inset-0 z-50 flex items-center justify-center p-4">
                    <div className="absolute inset-0 bg-black/60 backdrop-blur-sm" onClick={() => setShowDetailModal(false)} />
                    <div className="relative bg-surface w-full max-w-2xl rounded-2xl border border-slate-200 dark:border-white/10 shadow-2xl flex flex-col max-h-[90vh] animate-fade-in-up">
                        <div className="p-5 border-b border-slate-200 dark:border-white/10 flex justify-between items-center bg-background rounded-t-2xl shrink-0">
                            <div>
                                <h3 className="text-xl font-black text-textMain">{selectedOrder.order_number}</h3>
                                <p className="text-textMuted text-sm mt-0.5">
                                    {format(new Date(selectedOrder.created_at), 'dd MMMM yyyy — HH:mm')}
                                </p>
                            </div>
                            <div className="flex items-center gap-3">
                                <StatusBadge status={selectedOrder.status} />
                                <button
                                    onClick={() => handlePrint(selectedOrder)}
                                    className="flex items-center gap-1.5 px-3 py-1.5 bg-blue-500/15 hover:bg-blue-500/25 text-blue-400 rounded-lg text-xs font-bold transition-colors"
                                    title="Reprint Receipt"
                                >
                                    <FiPrinter className="w-3.5 h-3.5" /> Print
                                </button>
                                <button onClick={() => setShowDetailModal(false)} className="text-textMuted hover:text-textMain bg-slate-200 dark:bg-white/5 p-2 rounded-lg">
                                    <FiX />
                                </button>
                            </div>
                        </div>
                        <div className="flex-1 overflow-y-auto p-6 space-y-5">
                            {/* Meta */}
                            <div className="grid grid-cols-2 gap-3 text-sm">
                                <div className="bg-background rounded-xl p-3">
                                    <p className="text-textMuted text-xs mb-1">Order Type</p>
                                    <TypeBadge type={selectedOrder.order_type} />
                                </div>
                                <div className="bg-background rounded-xl p-3">
                                    <p className="text-textMuted text-xs mb-1">Cashier</p>
                                    <p className="text-textMain font-bold">{selectedOrder.waiter_name || '—'}</p>
                                </div>
                                <div className="bg-background rounded-xl p-3">
                                    <p className="text-textMuted text-xs mb-1">Customer</p>
                                    <p className="text-textMain font-bold">{selectedOrder.customer_name || '—'}</p>
                                    {selectedOrder.customer_phone && <p className="text-textMuted text-xs">{selectedOrder.customer_phone}</p>}
                                </div>
                                <div className="bg-background rounded-xl p-3">
                                    <p className="text-textMuted text-xs mb-1">Table</p>
                                    <p className="text-textMain font-bold">{selectedOrder.table_number || '—'}</p>
                                </div>
                            </div>

                            {selectedOrder.cancel_reason && (
                                <div className="bg-red-500/10 border border-red-500/20 rounded-xl p-3">
                                    <p className="text-red-400 font-bold text-xs mb-1">Cancellation Reason</p>
                                    <p className="text-textMain text-sm">{selectedOrder.cancel_reason}</p>
                                </div>
                            )}

                            {/* Items */}
                            <div>
                                <h4 className="text-textMain font-bold mb-3 text-sm">Order Items</h4>
                                <div className="space-y-2">
                                    {selectedOrder.items?.map((item, i) => (
                                        <div key={i} className="flex justify-between items-center bg-background rounded-xl p-3 text-sm">
                                            <div>
                                                <p className="text-textMain font-semibold">{item.product_name}</p>
                                                {item.modifiers_details?.length > 0 && (
                                                    <p className="text-textMuted text-xs mt-0.5">{item.modifiers_details.map(m => m.name).join(', ')}</p>
                                                )}
                                                {item.special_instructions && (
                                                    <p className="text-yellow-400/70 text-xs italic mt-0.5">"{item.special_instructions}"</p>
                                                )}
                                            </div>
                                            <div className="text-right">
                                                <p className="text-textMuted text-xs">{item.quantity}x</p>
                                                <p className="text-textMain font-mono font-bold">{parseFloat(item.total_price).toFixed(2)}</p>
                                            </div>
                                        </div>
                                    ))}
                                </div>
                            </div>

                            {/* Totals */}
                            <div className="bg-background rounded-xl p-4 space-y-2 text-sm font-mono">
                                <div className="flex justify-between text-textMuted">
                                    <span>Subtotal</span><span>{parseFloat(selectedOrder.subtotal).toFixed(2)}</span>
                                </div>
                                {parseFloat(selectedOrder.tax_amount) > 0 && (
                                    <div className="flex justify-between text-textMuted">
                                        <span>Tax</span><span>{parseFloat(selectedOrder.tax_amount).toFixed(2)}</span>
                                    </div>
                                )}
                                {parseFloat(selectedOrder.service_charge) > 0 && (
                                    <div className="flex justify-between text-textMuted">
                                        <span>Service</span><span>{parseFloat(selectedOrder.service_charge).toFixed(2)}</span>
                                    </div>
                                )}
                                {parseFloat(selectedOrder.discount_amount) > 0 && (
                                    <div className="flex justify-between text-emerald-400">
                                        <span>Discount</span><span>-{parseFloat(selectedOrder.discount_amount).toFixed(2)}</span>
                                    </div>
                                )}
                                <div className="flex justify-between text-textMain font-black text-lg pt-2 border-t border-slate-200 dark:border-white/10">
                                    <span>Total</span><span>{currency} {parseFloat(selectedOrder.total_amount).toFixed(2)}</span>
                                </div>
                            </div>

                            {/* Payments */}
                            {selectedOrder.payments?.length > 0 && (
                                <div>
                                    <h4 className="text-textMain font-bold mb-3 text-sm">Payments</h4>
                                    <div className="space-y-2">
                                        {selectedOrder.payments.map((p, i) => (
                                            <div key={i} className="flex justify-between items-center bg-background rounded-xl p-3 text-sm">
                                                <span className="text-textMain capitalize">{p.payment_method?.replace('_', ' ')}</span>
                                                <span className="text-emerald-400 font-mono font-bold">{parseFloat(p.amount).toFixed(2)}</span>
                                            </div>
                                        ))}
                                    </div>
                                </div>
                            )}
                        </div>
                    </div>
                </div>
            )}

            {/* ---- CANCEL MODAL ---- */}
            {showCancelModal && (
                <div className="fixed inset-0 z-50 flex items-center justify-center p-4">
                    <div className="absolute inset-0 bg-black/60 backdrop-blur-sm" onClick={() => setShowCancelModal(false)} />
                    <div className="relative bg-surface w-full max-w-md rounded-2xl border border-slate-200 dark:border-white/10 shadow-2xl animate-fade-in-up">
                        <div className="p-5 border-b border-white/10 flex justify-between items-center bg-background rounded-t-2xl">
                            <div className="flex items-center gap-3">
                                <div className="w-10 h-10 rounded-xl bg-red-500/15 flex items-center justify-center">
                                    <FiTrash2 className="text-red-400 w-5 h-5" />
                                </div>
                                <div>
                                    <h3 className="text-textMain font-black">Cancel Order</h3>
                                    <p className="text-textMuted text-xs">Select a reason to confirm</p>
                                </div>
                            </div>
                            <button onClick={() => setShowCancelModal(false)} className="text-textMuted hover:text-textMain p-2"><FiX /></button>
                        </div>
                        <div className="p-6 space-y-4">
                            <p className="text-textMuted text-sm">Why is this order being cancelled?</p>
                            <div className="space-y-2">
                                {cancelReasons.map(r => (
                                    <button
                                        key={r.id}
                                        onClick={() => setSelectedCancelReason(r.label)}
                                        className={`w-full text-left px-4 py-3 rounded-xl border text-sm font-semibold transition-all ${selectedCancelReason === r.label ? 'bg-red-500/15 border-red-500/40 text-red-400' : 'bg-background border-slate-200 dark:border-white/10 text-textMuted hover:border-red-400/30 hover:text-textMain'}`}
                                    >
                                        {r.label}
                                    </button>
                                ))}
                                <button
                                    onClick={() => setSelectedCancelReason('__custom__')}
                                    className={`w-full text-left px-4 py-3 rounded-xl border text-sm font-semibold transition-all ${selectedCancelReason === '__custom__' ? 'bg-slate-500/15 border-slate-500/40 text-textMain' : 'bg-background border-slate-200 dark:border-white/10 text-textMuted hover:border-white/20'}`}
                                >
                                    Other (type your reason)
                                </button>
                            </div>
                            {selectedCancelReason === '__custom__' && (
                                <textarea
                                    value={customCancelReason}
                                    onChange={e => setCustomCancelReason(e.target.value)}
                                    placeholder="Describe the reason for cancellation..."
                                    className="w-full bg-background border border-slate-200 dark:border-white/10 text-textMain rounded-xl p-3 text-sm focus:outline-none focus:border-red-400 h-24 resize-none"
                                />
                            )}
                        </div>
                        <div className="p-5 border-t border-white/10 bg-background rounded-b-2xl flex gap-3">
                            <button onClick={() => setShowCancelModal(false)} className="flex-1 py-3 bg-surface border border-slate-200 dark:border-white/10 text-textMuted hover:text-textMain rounded-xl font-bold text-sm transition-colors">
                                Keep Order
                            </button>
                            <button
                                onClick={handleCancelOrder}
                                disabled={isCancelling || (!selectedCancelReason || (selectedCancelReason === '__custom__' && !customCancelReason.trim()))}
                                className="flex-1 py-3 bg-red-600 hover:bg-red-700 disabled:opacity-50 text-white rounded-xl font-black text-sm transition-colors"
                            >
                                {isCancelling ? 'Cancelling...' : 'Confirm Cancel'}
                            </button>
                        </div>
                    </div>
                </div>
            )}

            {/* ---- EDIT MODAL ---- */}
            {showEditModal && editTarget && (
                <div className="fixed inset-0 z-50 flex items-center justify-center p-4">
                    <div className="absolute inset-0 bg-black/60 backdrop-blur-sm" onClick={() => setShowEditModal(false)} />
                    <div className="relative bg-surface w-full max-w-md rounded-2xl border border-slate-200 dark:border-white/10 shadow-2xl animate-fade-in-up">
                        <div className="p-5 border-b border-white/10 bg-background rounded-t-2xl flex justify-between items-center">
                            <div>
                                <h3 className="text-textMain font-black">Edit Order</h3>
                                <p className="text-textMuted text-xs">{editTarget.order_number}</p>
                            </div>
                            <button onClick={() => setShowEditModal(false)} className="text-textMuted hover:text-textMain p-2"><FiX /></button>
                        </div>
                        <div className="p-6 space-y-4">
                            <div>
                                <label className="block text-xs font-bold text-textMuted mb-2">Order Notes</label>
                                <textarea
                                    value={editNotes}
                                    onChange={e => setEditNotes(e.target.value)}
                                    placeholder="Add or update notes for this order..."
                                    className="w-full bg-background border border-slate-200 dark:border-white/10 text-textMain rounded-xl p-3 text-sm focus:outline-none focus:border-primary h-28 resize-none"
                                />
                            </div>
                        </div>
                        <div className="p-5 border-t border-white/10 bg-background rounded-b-2xl flex gap-3">
                            <button onClick={() => setShowEditModal(false)} className="flex-1 py-3 bg-surface border border-slate-200 dark:border-white/10 text-textMuted hover:text-textMain rounded-xl font-bold text-sm">
                                Cancel
                            </button>
                            <button
                                onClick={handleSaveEdit}
                                disabled={isEditing}
                                className="flex-1 py-3 bg-primary hover:bg-primary/90 disabled:opacity-50 text-white rounded-xl font-black text-sm"
                            >
                                {isEditing ? 'Saving...' : 'Save Changes'}
                            </button>
                        </div>
                    </div>
                </div>
            )}
        </div>
    );
};

// ---------- Stat Card Sub-Component ----------
const StatCard = ({ icon, label, value, color }) => {
    const colors = {
        blue: 'bg-blue-500/15 text-blue-400',
        emerald: 'bg-emerald-500/15 text-emerald-400',
        amber: 'bg-amber-500/15 text-amber-400',
        red: 'bg-red-500/15 text-red-400',
    };
    return (
        <div className="bg-surface border border-slate-200 dark:border-white/10 rounded-2xl p-5 flex items-center gap-4">
            <div className={`w-12 h-12 rounded-xl flex items-center justify-center text-xl shrink-0 ${colors[color]}`}>
                {icon}
            </div>
            <div>
                <p className="text-textMuted text-xs font-semibold">{label}</p>
                <p className="text-textMain font-black text-xl mt-0.5">{value}</p>
            </div>
        </div>
    );
};

export default OrdersPage;

import React, { useState, useEffect, useRef } from 'react';
import { posApi } from '../../api/posApi';
import toast from 'react-hot-toast';
import { FiPlus, FiSave, FiTrash2, FiMaximize, FiUsers, FiInfo, FiLayers } from 'react-icons/fi';
import ConfirmModal from '../../components/ConfirmModal';

const FloorPlan = () => {
    const [tables, setTables] = useState([]);
    const [isLoading, setIsLoading] = useState(true);
    const [isEditMode, setIsEditMode] = useState(false);
    const [selectedTable, setSelectedTable] = useState(null);
    
    const [deleteModalOpen, setDeleteModalOpen] = useState(false);
    const [tableToDelete, setTableToDelete] = useState(null);
    const [isEditingDetails, setIsEditingDetails] = useState(false);
    const [editData, setEditData] = useState({ number: '', capacity: '' });
    
    // Dragging state
    const [draggingId, setDraggingId] = useState(null);
    const floorRef = useRef(null);

    useEffect(() => {
        fetchTables();
    }, []);

    const fetchTables = async () => {
        setIsLoading(true);
        try {
            const response = await posApi.getTables();
            setTables(response.data);
        } catch (error) {
            toast.error("Failed to load floor plan");
        } finally {
            setIsLoading(false);
        }
    };

    const handleSaveLayout = async () => {
        const toastId = toast.loading("Saving layout...");
        try {
            // Update all tables sequentially (or send bulk update if API supported it)
            // For now, sequentially since amount of tables is usually small < 100
            for (const table of tables) {
                await posApi.updateTable(table.id, {
                    position_x: Math.round(table.position_x),
                    position_y: Math.round(table.position_y)
                });
            }
            toast.success("Layout saved successfully", { id: toastId });
            setIsEditMode(false);
            setSelectedTable(null);
        } catch (error) {
            toast.error("Failed to save layout", { id: toastId });
        }
    };
    
    // Fallback patch for API if not fully implemented in API wrapper
    const updateTableData = async (id, data) => {
        try {
            await posApi.updateOrder(id, data); // We named it incorrectly in posApi, wait it's not even there. Let me use axios
        } catch(e) {}
    }

    const handlePointerDown = (e, tableId) => {
        if (!isEditMode) {
            setSelectedTable(tables.find(t => t.id === tableId));
            return;
        }
        
        e.preventDefault();
        setDraggingId(tableId);
        setSelectedTable(tables.find(t => t.id === tableId));
    };

    const handlePointerMove = (e) => {
        if (!draggingId || !floorRef.current) return;
        
        const rect = floorRef.current.getBoundingClientRect();
        // Calculate new X/Y relative to the container
        let newX = e.clientX - rect.left - 40; // 40 is half of table width
        let newY = e.clientY - rect.top - 40;  // 40 is half of table height
        
        // Boundaries
        newX = Math.max(0, Math.min(newX, rect.width - 80));
        newY = Math.max(0, Math.min(newY, rect.height - 80));
        
        // Collision detection: Prevent overlapping with other tables (80x80 pixels)
        const TABLE_SIZE = 80;
        const SPACING = 10; // Optional spacing between tables
        let hasCollision = false;
        
        for (const table of tables) {
            if (table.id === draggingId) continue;
            
            // Allow small overlap margin before blocking
            const isColliding = 
                newX < table.position_x + TABLE_SIZE + SPACING &&
                newX + TABLE_SIZE + SPACING > table.position_x &&
                newY < table.position_y + TABLE_SIZE + SPACING &&
                newY + TABLE_SIZE + SPACING > table.position_y;
                
            if (isColliding) {
                hasCollision = true;
                break;
            }
        }
        
        // If there's a collision, don't update the coordinates (create a "wall" effect)
        if (!hasCollision) {
            setTables(prev => prev.map(t => 
                t.id === draggingId ? { ...t, position_x: newX, position_y: newY } : t
            ));
        }
    };

    const handlePointerUp = () => {
        if (draggingId) {
            setDraggingId(null);
        }
    };

    useEffect(() => {
        if (draggingId) {
            window.addEventListener('pointermove', handlePointerMove);
            window.addEventListener('pointerup', handlePointerUp);
        }
        return () => {
            window.removeEventListener('pointermove', handlePointerMove);
            window.removeEventListener('pointerup', handlePointerUp);
        };
    }, [draggingId]);

    const getStatusColor = (status) => {
        switch (status) {
            case 'available': return 'bg-emerald-500/20 border-emerald-500 text-emerald-400 shadow-[0_0_15px_rgba(16,185,129,0.3)]';
            case 'occupied': return 'bg-red-500/20 border-red-500 text-red-400 shadow-[0_0_15px_rgba(239,68,68,0.3)]';
            case 'reserved': return 'bg-blue-500/20 border-blue-500 text-blue-400 shadow-[0_0_15px_rgba(59,130,246,0.3)]';
            case 'needs_cleaning': return 'bg-yellow-500/20 border-yellow-500 text-yellow-400 shadow-[0_0_15px_rgba(234,179,8,0.3)]';
            default: return 'bg-gray-500/20 border-gray-500 text-gray-400';
        }
    };

    const handleUpdateTableStatus = async (id, newStatus) => {
        if (isEditMode) return;
        try {
            await posApi.updateTableStatus(id, newStatus);
            setTables(prev => prev.map(t => t.id === id ? { ...t, status: newStatus } : t));
            if (selectedTable?.id === id) {
                setSelectedTable(prev => ({ ...prev, status: newStatus }));
            }
            toast.success("Status updated");
        } catch (error) {
            toast.error("Failed to update status");
        }
    };

    const handleDeleteTable = async () => {
        if (!tableToDelete) return;
        const toastId = toast.loading("Deleting table...");
        try {
            await posApi.deleteTable(tableToDelete);
            setTables(prev => prev.filter(t => t.id !== tableToDelete));
            if (selectedTable?.id === tableToDelete) setSelectedTable(null);
            toast.success("Table deleted", { id: toastId });
        } catch (error) {
            toast.error("Failed to delete table", { id: toastId });
        } finally {
            setDeleteModalOpen(false);
            setTableToDelete(null);
        }
    };

    // Form logic for new/edit table
    const [formData, setFormData] = useState({ number: '', capacity: 4 });
    const [isAddingTable, setIsAddingTable] = useState(false);
    
    // Bulk generation logic
    const [bulkCount, setBulkCount] = useState(10);
    const [isBulkGenerating, setIsBulkGenerating] = useState(false);
    
    const handleBulkGenerate = async (e) => {
        e.preventDefault();
        const count = Math.min(35, Math.max(1, parseInt(bulkCount) || 1));
        
        setIsBulkGenerating(true);
        const toastId = toast.loading(`Generating ${count} tables...`);
        
        try {
            const currentCount = tables.length;
            const addedTables = [];
            
            let spawnX = 100;
            let spawnY = 100;
            const TABLE_SIZE = 80;
            const SPACING = 20;
            
            for (let i = 0; i < count; i++) {
                // Find empty spot for each
                while (true) {
                    let collision = false;
                    const allTables = [...tables, ...addedTables];
                    for (const table of allTables) {
                        const isColliding = 
                            spawnX < table.position_x + TABLE_SIZE + SPACING &&
                            spawnX + TABLE_SIZE + SPACING > table.position_x &&
                            spawnY < table.position_y + TABLE_SIZE + SPACING &&
                            spawnY + TABLE_SIZE + SPACING > table.position_y;
                            
                        if (isColliding) {
                            collision = true;
                            break;
                        }
                    }
                    if (!collision) break;
                    
                    spawnX += TABLE_SIZE + SPACING;
                    if (spawnX > 600) { 
                        spawnX = 100;
                        spawnY += TABLE_SIZE + SPACING;
                    }
                }

                // API call sequentially
                const response = await posApi.createTable({
                    number: `T-${currentCount + i + 1}`,
                    capacity: 4,
                    position_x: spawnX,
                    position_y: spawnY,
                    status: 'available'
                });
                addedTables.push(response.data);
            }
            
            setTables(prev => [...prev, ...addedTables]);
            toast.success(`Generated ${count} tables!`, { id: toastId });
        } catch (error) {
            toast.error("Error bulk generating tables.", { id: toastId });
        } finally {
            setIsBulkGenerating(false);
            setBulkCount(10);
        }
    };
    
    const handleAddTable = async (e) => {
        e.preventDefault();
        if (!formData.number) return toast.error("Table number is required");
        
        setIsAddingTable(true);
        const toastId = toast.loading("Adding table...");
        
        // Find an empty spot for the new table
        const TABLE_SIZE = 80;
        const SPACING = 20;
        let spawnX = 100;
        let spawnY = 100;
        
        while (true) {
            let collision = false;
            for (const table of tables) {
                const isColliding = 
                    spawnX < table.position_x + TABLE_SIZE + SPACING &&
                    spawnX + TABLE_SIZE + SPACING > table.position_x &&
                    spawnY < table.position_y + TABLE_SIZE + SPACING &&
                    spawnY + TABLE_SIZE + SPACING > table.position_y;
                    
                if (isColliding) {
                    collision = true;
                    break;
                }
            }
            
            if (!collision) break;
            
            spawnX += TABLE_SIZE + SPACING;
            if (spawnX > 600) { 
                spawnX = 100;
                spawnY += TABLE_SIZE + SPACING;
            }
            if (spawnY > 2000) break; // Safety fallback
        }

        try {
            const response = await posApi.createTable({
                number: formData.number,
                capacity: formData.capacity,
                position_x: spawnX,
                position_y: spawnY,
                status: 'available'
            });
            
            setTables([...tables, response.data]);
            setFormData({ number: '', capacity: 4 });
            toast.success(`Table ${response.data.number} added!`, { id: toastId });
        } catch (error) {
            let errMsg = "Failed to add table";
            const detail = error.response?.data?.detail;
            if (typeof detail === 'string') {
                errMsg = detail;
            } else if (typeof detail === 'object' && detail !== null) {
                errMsg = Object.values(detail).flat().join(', ');
            }
            toast.error(errMsg, { id: toastId });
        } finally {
            setIsAddingTable(false);
        }
    };

    const handleSaveTableMetadata = async (e) => {
        e.preventDefault();
        if (!selectedTable) return;
        
        const toastId = toast.loading("Updating table...");
        try {
            const data = {
                number: editData.number,
                capacity: parseInt(editData.capacity) || 1
            };
            const response = await posApi.updateTable(selectedTable.id, data);
            
            // Update local state
            setTables(prev => prev.map(t => t.id === selectedTable.id ? { ...t, ...response.data } : t));
            setSelectedTable(prev => ({ ...prev, ...response.data }));
            
            setIsEditingDetails(false);
            toast.success("Table updated successfully", { id: toastId });
        } catch (error) {
            let errMsg = "Failed to update table";
            const detail = error.response?.data?.detail;
            if (typeof detail === 'string') errMsg = detail;
            else if (typeof detail === 'object' && detail !== null) errMsg = Object.values(detail).flat().join(', ');
            
            toast.error(errMsg, { id: toastId });
        }
    };

    const handleAutoArrange = () => {
        if (!floorRef.current || tables.length === 0) return;
        
        const rect = floorRef.current.getBoundingClientRect();
        const TABLE_SIZE = 80;
        const SPACING = 40; // generous spacing
        
        // Calculate how many tables can fit in one row
        // Subtract some padding from container width
        const availableWidth = rect.width - 40; 
        const cols = Math.max(1, Math.floor(availableWidth / (TABLE_SIZE + SPACING)));
        
        // Sort tables logically by number (trying to extract digits if possible)
        const sortedTables = [...tables].sort((a, b) => {
            const numA = parseInt(a.number.replace(/\D/g, '')) || 0;
            const numB = parseInt(b.number.replace(/\D/g, '')) || 0;
            if (numA !== numB) return numA - numB;
            return a.number.localeCompare(b.number);
        });
        
        const startX = 60;
        const startY = 60;
        
        const newTables = sortedTables.map((table, index) => {
            const row = Math.floor(index / cols);
            const col = index % cols;
            
            return {
                ...table,
                position_x: startX + col * (TABLE_SIZE + SPACING),
                position_y: startY + row * (TABLE_SIZE + SPACING)
            };
        });
        
        setTables(newTables);
        toast.success("Tables arranged!");
    };

    return (
        <div className="h-screen flex bg-[#0f172a] overflow-hidden p-6 gap-6">
            
            {/* LIFT SIDE: FLOOR CANVAS */}
            <div className="flex-1 flex flex-col h-full glass-panel border border-white/10 rounded-3xl overflow-hidden relative shadow-2xl">
                
                {/* Header Toolbar */}
                <div className="p-4 border-b border-white/10 bg-white/5 flex justify-between items-center backdrop-blur-md z-10">
                    <div className="flex items-center space-x-3">
                        <div className="p-2 bg-primary/20 rounded-lg text-primary">
                            <FiLayers className="w-6 h-6" />
                        </div>
                        <div>
                            <h2 className="text-xl font-black text-white leading-tight">Floor Plan</h2>
                            <p className="text-xs text-textMuted">Live Table Management</p>
                        </div>
                    </div>
                    
                    <div className="flex space-x-3">
                        {isEditMode ? (
                            <>
                                <button 
                                    onClick={() => { fetchTables(); setIsEditMode(false); setSelectedTable(null); }}
                                    className="px-4 py-2 bg-white/10 hover:bg-white/20 text-white rounded-lg text-sm font-bold transition-all"
                                >
                                    Cancel
                                </button>
                                <button 
                                    onClick={handleSaveLayout}
                                    className="px-4 py-2 bg-primary hover:bg-primary/90 text-white rounded-lg text-sm font-bold shadow-[0_0_15px_rgba(59,130,246,0.4)] flex items-center space-x-2 transition-all"
                                >
                                    <FiSave /> <span>Save Layout</span>
                                </button>
                            </>
                        ) : (
                            <button 
                                onClick={() => { setIsEditMode(true); setSelectedTable(null); }}
                                className="px-4 py-2 bg-white/5 border border-white/10 hover:bg-white/10 hover:border-white/20 text-white rounded-lg text-sm font-bold flex items-center space-x-2 transition-all"
                            >
                                <FiMaximize /> <span>Edit Layout</span>
                            </button>
                        )}
                    </div>
                </div>

                {/* The Canvas */}
                <div 
                    ref={floorRef}
                    className="flex-1 relative bg-[#0B1121] overflow-hidden"
                    style={{ backgroundImage: 'radial-gradient(circle at 2px 2px, rgba(255,255,255,0.05) 1px, transparent 0)', backgroundSize: '40px 40px' }}
                >
                    {tables.map(table => (
                        <div
                            key={table.id}
                            onPointerDown={(e) => handlePointerDown(e, table.id)}
                            className={`absolute flex flex-col items-center justify-center rounded-2xl border-2 transition-all select-none
                                ${getStatusColor(table.status)}
                                ${selectedTable?.id === table.id ? 'ring-2 ring-white scale-110 z-20' : 'z-10'}
                                ${isEditMode ? 'cursor-grab active:cursor-grabbing hover:brightness-125' : 'cursor-pointer hover:scale-105'}
                                ${draggingId === table.id ? 'opacity-80 scale-105 shadow-2xl' : ''}
                            `}
                            style={{
                                width: '80px',
                                height: '80px',
                                left: `${table.position_x}px`,
                                top: `${table.position_y}px`,
                                touchAction: 'none' // Important for pointer events on touch devices
                            }}
                        >
                            <span className="text-xl font-black">{table.number}</span>
                            <div className="flex items-center text-[10px] opacity-80 mt-1 font-bold">
                                <FiUsers className="mr-1" /> {table.capacity}
                            </div>
                        </div>
                    ))}
                    
                    {!isLoading && tables.length === 0 && (
                        <div className="absolute inset-0 flex items-center justify-center text-white/30 font-bold">
                            No tables found. Enter edit mode to create some.
                        </div>
                    )}
                </div>
                
                {/* Legend */}
                {!isEditMode && (
                    <div className="absolute bottom-4 left-4 right-4 flex justify-between items-center bg-[#0f172a]/80 backdrop-blur-md rounded-xl p-3 border border-white/10 text-xs font-bold shadow-lg">
                        <div className="flex items-center text-white/60"><FiInfo className="mr-2" /> Live Status</div>
                        <div className="flex space-x-4">
                            <span className="flex items-center text-emerald-400"><span className="w-3 h-3 rounded-full bg-emerald-500 mr-2 shadow-[0_0_8px_rgba(16,185,129,0.8)]"></span>Available</span>
                            <span className="flex items-center text-red-400"><span className="w-3 h-3 rounded-full bg-red-500 mr-2 shadow-[0_0_8px_rgba(239,68,68,0.8)]"></span>Occupied</span>
                            <span className="flex items-center text-blue-400"><span className="w-3 h-3 rounded-full bg-blue-500 mr-2 shadow-[0_0_8px_rgba(59,130,246,0.8)]"></span>Reserved</span>
                            <span className="flex items-center text-yellow-400"><span className="w-3 h-3 rounded-full bg-yellow-500 mr-2 shadow-[0_0_8px_rgba(234,179,8,0.8)]"></span>Needs Cleaning</span>
                        </div>
                    </div>
                )}
            </div>

            {/* RIGHT SIDE: TABLE INSPECTOR */}
            <div className={`w-80 glass-panel border border-white/10 rounded-3xl shadow-2xl flex flex-col transition-all duration-300 transform origin-right ${selectedTable || isEditMode ? 'scale-x-100 opacity-100' : 'scale-x-0 w-0 opacity-0 overflow-hidden'}`}>
                {isEditMode ? (
                    // Edit Mode Tools
                    <div className="p-6 flex flex-col h-full overflow-hidden">
                        <h3 className="text-lg font-black text-white mb-6 border-b border-white/10 pb-4 flex items-center">
                            <FiMaximize className="mr-2 text-primary" /> Builder Tools
                        </h3>
                        
                        <div className="flex-1 text-center">
                           <p className="text-sm text-textMuted mb-6">Drag and drop tables on the canvas to update their physical positions.</p>
                           
                           <button 
                               onClick={handleAutoArrange}
                               className="w-full py-3 mb-6 bg-white/5 border border-white/10 hover:bg-white/10 hover:border-white/20 text-white rounded-xl font-bold text-sm flex items-center justify-center space-x-2 transition-all shadow-lg"
                           >
                               <FiLayers /> <span>Auto Arrange Grid</span>
                           </button>
                           
                           {/* Bulk Generate Form */}
                           <form onSubmit={handleBulkGenerate} className="border border-white/10 bg-white/5 rounded-xl p-4 text-left mb-6">
                               <h4 className="font-bold text-white mb-4 text-sm flex items-center justify-between">
                                   <span>Bulk Generate</span>
                                   <span className="text-[10px] text-textMuted bg-[#0f172a] px-2 py-1 rounded">Max 35</span>
                               </h4>
                               <div className="space-y-3 mb-4">
                                   <div>
                                       <label className="text-[10px] text-textMuted uppercase font-bold tracking-wider mb-1 block">Number of Tables</label>
                                       <input 
                                           type="number"
                                           min="1"
                                           max="35"
                                           className="w-full bg-[#0f172a] border border-white/10 rounded-lg p-2 text-white text-sm focus:outline-none focus:border-primary"
                                           value={bulkCount}
                                           onChange={e => setBulkCount(e.target.value)}
                                           required
                                       />
                                   </div>
                               </div>
                               <button 
                                   type="submit" 
                                   disabled={isBulkGenerating}
                                   className="w-full py-2 bg-emerald-500/20 hover:bg-emerald-500/30 text-emerald-400 border border-emerald-500/50 rounded-lg font-bold text-sm shadow-[0_0_10px_rgba(16,185,129,0.2)] disabled:opacity-50 transition-all"
                               >
                                   {isBulkGenerating ? 'Generating...' : 'Generate Tables'}
                               </button>
                           </form>
                           
                           {/* Would add full Create Table form here calling POST /pos/tables/ */}
                           <form onSubmit={handleAddTable} className="border border-white/10 bg-white/5 rounded-xl p-4 text-left">
                               <h4 className="font-bold text-white mb-4 text-sm">Add New Table</h4>
                               
                               <div className="space-y-3 mb-4">
                                   <div>
                                       <label className="text-[10px] text-textMuted uppercase font-bold tracking-wider mb-1 block">Table Number/Name</label>
                                       <input 
                                           className="w-full bg-[#0f172a] border border-white/10 rounded-lg p-2 text-white text-sm focus:outline-none focus:border-primary"
                                           placeholder="e.g. T1, Balcony-3"
                                           value={formData.number}
                                           onChange={e => setFormData({...formData, number: e.target.value})}
                                           required
                                       />
                                   </div>
                                   <div>
                                       <label className="text-[10px] text-textMuted uppercase font-bold tracking-wider mb-1 block">Seat Capacity</label>
                                       <input 
                                           type="number"
                                           min="1"
                                           className="w-full bg-[#0f172a] border border-white/10 rounded-lg p-2 text-white text-sm focus:outline-none focus:border-primary"
                                           value={formData.capacity}
                                           onChange={e => setFormData({...formData, capacity: e.target.value})}
                                           required
                                       />
                                   </div>
                               </div>

                               <button 
                                   type="submit" 
                                   disabled={isAddingTable}
                                   className="w-full py-2 bg-primary hover:bg-primary/90 text-white rounded-lg font-bold text-sm shadow-[0_0_10px_rgba(59,130,246,0.3)] disabled:opacity-50 flex items-center justify-center transition-all"
                               >
                                   <FiPlus className="mr-2" /> {isAddingTable ? 'Adding...' : 'Quick Add Table'}
                               </button>
                           </form>
                        </div>
                    </div>
                ) : (
                    // View Mode / Inspector
                    selectedTable && (
                        <div className="p-6 flex flex-col h-full">
                            <div className="flex justify-between items-start mb-6 pb-4 border-b border-white/10">
                                <div className="flex-1 mr-4">
                                    {isEditingDetails ? (
                                        <form onSubmit={handleSaveTableMetadata} className="space-y-3">
                                            <div>
                                                <input 
                                                    autoFocus
                                                    className="w-full bg-[#0f172a] border border-white/10 rounded-lg p-2 text-white text-sm focus:outline-none focus:border-primary font-black"
                                                    value={editData.number}
                                                    onChange={e => setEditData({...editData, number: e.target.value})}
                                                    required
                                                />
                                            </div>
                                            <div className="flex items-center space-x-2">
                                                <FiUsers className="text-textMuted" />
                                                <input 
                                                    type="number"
                                                    min="1"
                                                    className="w-full bg-[#0f172a] border border-white/10 rounded-lg p-2 text-white text-sm focus:outline-none focus:border-primary"
                                                    value={editData.capacity}
                                                    onChange={e => setEditData({...editData, capacity: e.target.value})}
                                                    required
                                                />
                                            </div>
                                            <div className="flex space-x-2">
                                                <button type="submit" className="flex-1 py-1.5 bg-primary/20 text-primary hover:bg-primary/30 rounded text-xs font-bold transition-all">Save</button>
                                                <button type="button" onClick={() => setIsEditingDetails(false)} className="flex-1 py-1.5 bg-white/5 text-white/50 hover:bg-white/10 rounded text-xs font-bold transition-all">Cancel</button>
                                            </div>
                                        </form>
                                    ) : (
                                        <div 
                                            className="group cursor-pointer p-1 -m-1 rounded hover:bg-white/5 transition-all"
                                            onClick={() => {
                                                setEditData({ number: selectedTable.number, capacity: selectedTable.capacity });
                                                setIsEditingDetails(true);
                                            }}
                                        >
                                            <div className="flex justify-between items-center">
                                                <h3 className="text-2xl font-black text-white group-hover:text-primary transition-colors">Table {selectedTable.number}</h3>
                                                <span className="opacity-0 group-hover:opacity-100 text-xs text-primary transition-opacity">Edit</span>
                                            </div>
                                            <p className="text-textMuted text-sm font-bold mt-1 inline-flex items-center">
                                                <FiUsers className="mr-1" /> {selectedTable.capacity} Seats
                                            </p>
                                        </div>
                                    )}
                                </div>
                                <div className={`px-3 py-1 rounded-full text-xs font-bold border uppercase tracking-wider ${getStatusColor(selectedTable.status).replace(' shadow-[0_0_15px_rgba(16,185,129,0.3)]', '').replace(' shadow-[0_0_15px_rgba(239,68,68,0.3)]', '').replace(' shadow-[0_0_15px_rgba(59,130,246,0.3)]', '').replace(' shadow-[0_0_15px_rgba(234,179,8,0.3)]', '')}`}>
                                    {selectedTable.status.replace('_', ' ')}
                                </div>
                            </div>

                            <div className="space-y-6 flex-1 flex flex-col">
                                <div>
                                    <h4 className="text-xs font-bold text-textMuted uppercase tracking-wider mb-3">Quick Actions</h4>
                                    <div className="grid grid-cols-2 gap-2">
                                        <button 
                                            onClick={() => handleUpdateTableStatus(selectedTable.id, 'available')}
                                            className={`py-2 rounded-lg text-xs font-bold transition-all ${selectedTable.status === 'available' ? 'bg-emerald-500/20 text-emerald-400 border border-emerald-500/50' : 'bg-white/5 text-textMuted hover:bg-white/10 hover:text-white'}`}
                                        >
                                            Available
                                        </button>
                                        <button 
                                            onClick={() => handleUpdateTableStatus(selectedTable.id, 'occupied')}
                                            className={`py-2 rounded-lg text-xs font-bold transition-all ${selectedTable.status === 'occupied' ? 'bg-red-500/20 text-red-400 border border-red-500/50' : 'bg-white/5 text-textMuted hover:bg-white/10 hover:text-white'}`}
                                        >
                                            Occupied
                                        </button>
                                        <button 
                                            onClick={() => handleUpdateTableStatus(selectedTable.id, 'reserved')}
                                            className={`py-2 rounded-lg text-xs font-bold transition-all ${selectedTable.status === 'reserved' ? 'bg-blue-500/20 text-blue-400 border border-blue-500/50' : 'bg-white/5 text-textMuted hover:bg-white/10 hover:text-white'}`}
                                        >
                                            Reserved
                                        </button>
                                        <button 
                                            onClick={() => handleUpdateTableStatus(selectedTable.id, 'needs_cleaning')}
                                            className={`py-2 rounded-lg text-xs font-bold transition-all ${selectedTable.status === 'needs_cleaning' ? 'bg-yellow-500/20 text-yellow-400 border border-yellow-500/50' : 'bg-white/5 text-textMuted hover:bg-white/10 hover:text-white'}`}
                                        >
                                            Clean
                                        </button>
                                    </div>
                                </div>
                                
                                {selectedTable.status === 'occupied' && (
                                    <div className="bg-primary/10 border border-primary/20 rounded-xl p-4 text-center mt-4">
                                        <p className="text-white font-bold mb-2">Active Order</p>
                                        <button className="w-full py-2 bg-primary hover:bg-primary/90 text-white rounded-lg text-sm font-bold shadow-[0_0_15px_rgba(59,130,246,0.3)] transition-all">
                                            View Order
                                        </button>
                                    </div>
                                )}
                                
                                <div className="mt-auto pt-6">
                                    <button 
                                        onClick={() => {
                                            setTableToDelete(selectedTable.id);
                                            setDeleteModalOpen(true);
                                        }}
                                        className="w-full py-2 bg-red-500/10 hover:bg-red-500/20 text-red-500 border border-red-500/30 rounded-lg text-sm font-bold flex items-center justify-center space-x-2 transition-all"
                                    >
                                        <FiTrash2 /> <span>Delete Table</span>
                                    </button>
                                </div>
                            </div>
                        </div>
                    )
                )}
            </div>
            
            <ConfirmModal 
                isOpen={deleteModalOpen}
                onClose={() => setDeleteModalOpen(false)}
                onConfirm={handleDeleteTable}
                title="Delete Table"
                message={`Are you sure you want to delete this table?`}
                confirmText="Delete"
                isDangerous={true}
            />
        </div>
    );
};

export default FloorPlan;

