import React, { useState, useEffect } from 'react';
import { posApi } from '../../api/posApi';
import toast from 'react-hot-toast';
import { FiClock, FiCheck, FiFilter, FiAlertCircle } from 'react-icons/fi';
import { formatDistanceToNow } from 'date-fns';
import useSettingsStore from '../../store/settingsStore';

const KDS = () => {
    const [items, setItems] = useState([]);
    const [isLoading, setIsLoading] = useState(true);
    const [stationFilter, setStationFilter] = useState(''); // '' means all
    const [statusFilter, setStatusFilter] = useState('pending,preparing'); // active items only by default
    
    // Auto-refresh interval
    const REFRESH_INTERVAL = 10000; // 10 seconds

    useEffect(() => {
        fetchKDSItems();
        const interval = setInterval(fetchKDSItems, REFRESH_INTERVAL);
        return () => clearInterval(interval);
    }, [stationFilter, statusFilter]);

    const fetchKDSItems = async () => {
        try {
            const response = await posApi.getKDSItems(stationFilter, statusFilter);
            setItems(response.data);
            setIsLoading(false);
        } catch (error) {
            console.error("Failed to load KDS items", error);
            // Don't toast error on auto-refresh to avoid spam
            if (isLoading) toast.error("Failed to connect to KDS");
        }
    };

    const handleBumpStatus = async (itemId, currentStatus) => {
        const nextStatusMap = {
            'pending': 'preparing',
            'preparing': 'ready',
            'ready': 'delivered' // or hidden
        };
        
        const newStatus = nextStatusMap[currentStatus];
        if (!newStatus) return;

        // Optimistic update
        setItems(prev => prev.map(item => 
            item.id === itemId 
                ? { ...item, status: newStatus } 
                : item
        ));

        try {
            await posApi.bumpItemStatus(itemId, newStatus);
            // Re-fetch to ensure sync
            fetchKDSItems();
        } catch (error) {
            toast.error("Failed to bump ticket state");
            fetchKDSItems(); // Revert on failure
        }
    };

    const getStatusColor = (status) => {
        switch (status) {
            case 'pending': return 'bg-yellow-500/20 border-yellow-500/50 text-yellow-400';
            case 'preparing': return 'bg-blue-500/20 border-blue-500/50 text-blue-400';
            case 'ready': return 'bg-emerald-500/20 border-emerald-500/50 text-emerald-400';
            default: return 'bg-gray-500/20 border-gray-500/50 text-gray-400';
        }
    };
    
    // Group items by Order for better ticket visualization
    // We get a flat list of items, so let's group them by order
    const groupedOrders = items.reduce((acc, item) => {
        if (!acc[item.order]) {
            acc[item.order] = {
                order_id: item.order,
                order_name: item.order_number || `Order #${item.order}`,
                table: item.table_number ? `Table ${item.table_number}` : 'Takeaway/Delivery',
                order_type: item.order_type || 'Unknown',
                created_at: item.created_at, // Use the oldest item's created_at for the whole ticket
                items: []
            };
        }
        acc[item.order].items.push(item);
        
        // Update ticket creation time if we find an older item
        if (new Date(item.created_at) < new Date(acc[item.order].created_at)) {
            acc[item.order].created_at = item.created_at;
        }
        
        return acc;
    }, {});
    
    const tickets = Object.values(groupedOrders).sort((a, b) => new Date(a.created_at) - new Date(b.created_at));

    // Calculate urgency
    const getUrgencyColor = (createdAt) => {
        const minutesOld = (new Date() - new Date(createdAt)) / 60000;
        if (minutesOld > 15) return 'border-red-500 shadow-[0_0_15px_rgba(239,68,68,0.3)] animate-pulse';
        if (minutesOld > 10) return 'border-yellow-500 shadow-[0_0_15px_rgba(234,179,8,0.2)]';
        return 'border-white/10 shadow-lg';
    };

    const formatTime = (isoString) => {
        try {
            return formatDistanceToNow(new Date(isoString), { addSuffix: true }).replace('about ', '');
        } catch (e) {
            return 'Just now';
        }
    };

    return (
        <div className="h-screen flex flex-col bg-[#0B1121] overflow-hidden">
            
            {/* Header / Navbar */}
            <div className="h-16 bg-[#0f172a] border-b border-white/10 flex items-center justify-between px-6 shrink-0 z-10 shadow-xl">
                <div className="flex items-center space-x-4">
                    <h1 className="text-2xl font-black text-white px-2 py-1 bg-gradient-to-r from-red-500 to-orange-500 rounded-md">KDS</h1>
                    <span className="text-textMuted font-bold text-sm hidden md:inline-block">Kitchen Display System</span>
                </div>
                
                <div className="flex items-center space-x-4">
                    {/* Station Filter */}
                    <div className="flex items-center space-x-2 bg-white/5 rounded-lg border border-white/10 p-1">
                        <FiFilter className="text-textMuted ml-2" />
                        <select 
                            value={stationFilter}
                            onChange={(e) => setStationFilter(e.target.value)}
                            className="bg-transparent text-white font-bold text-sm focus:outline-none p-2 w-32"
                        >
                            <option value="" className="text-black">All Stations</option>
                            <option value="hot" className="text-black">Hot Kitchen</option>
                            <option value="cold" className="text-black">Cold / Drinks</option>
                            <option value="dessert" className="text-black">Dessert</option>
                        </select>
                    </div>
                </div>
            </div>

            {/* Board Canvas */}
            <div className="flex-1 p-6 overflow-x-auto overflow-y-hidden flex space-x-6 custom-scrollbar h-full">
                
                {isLoading ? (
                    <div className="w-full h-full flex items-center justify-center">
                        <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-primary"></div>
                    </div>
                ) : tickets.length === 0 ? (
                    <div className="w-full h-full flex flex-col items-center justify-center text-white/30 space-y-4">
                        <FiCheck className="w-24 h-24 opacity-20" />
                        <h2 className="text-2xl font-black">All Caught Up!</h2>
                        <p className="font-bold">No active tickets for this station.</p>
                    </div>
                ) : (
                    tickets.map(ticket => (
                        <div 
                            key={ticket.order_id} 
                            className={`w-80 shrink-0 h-full flex flex-col bg-[#1e293b] rounded-2xl border-2 transition-all duration-500 ${getUrgencyColor(ticket.created_at)}`}
                        >
                            {/* Ticket Header */}
                            <div className="p-4 border-b border-white/10 bg-[#0f172a] rounded-t-xl shrink-0">
                                <div className="flex justify-between items-start mb-2">
                                    <h3 className="text-xl font-black text-white">{ticket.order_name}</h3>
                                    <span className={`px-2 py-1 rounded text-xs font-bold font-mono ${
                                        ticket.order_type === 'dine_in' ? 'bg-blue-500/20 text-blue-400' : 
                                        ticket.order_type === 'takeaway' ? 'bg-yellow-500/20 text-yellow-400' : 
                                        'bg-purple-500/20 text-purple-400'
                                    }`}>
                                        {ticket.order_type.replace('_', ' ').toUpperCase()}
                                    </span>
                                </div>
                                
                                <div className="flex justify-between items-center text-sm font-bold mt-2">
                                    <span className="text-white/80">{ticket.table}</span>
                                    <span className="text-red-400 flex items-center font-mono bg-red-500/10 px-2 py-0.5 rounded">
                                        <FiClock className="mr-1" /> {formatTime(ticket.created_at)}
                                    </span>
                                </div>
                            </div>
                            
                            {/* Ticket Items List */}
                            <div className="flex-1 overflow-y-auto p-4 custom-scrollbar space-y-3">
                                {ticket.items.map((item, idx) => (
                                    <div 
                                        key={item.id} 
                                        onClick={() => handleBumpStatus(item.id, item.status)}
                                        className={`group relative overflow-hidden p-3 rounded-xl border border-white/10 cursor-pointer transition-all ${
                                            item.status === 'ready' ? 'opacity-50 grayscale hover:grayscale-0' : 'hover:border-primary/50 hover:bg-white/5'
                                        }`}
                                    >
                                        <div className="flex justify-between items-start">
                                            <div className="flex items-start space-x-3 flex-1">
                                                <div className="text-lg font-black text-white bg-white/10 w-8 h-8 flex items-center justify-center rounded-lg mt-0.5">
                                                    {item.quantity}
                                                </div>
                                                <div className="flex-1 pr-2">
                                                    <h4 className={`text-base font-bold text-white leading-tight ${item.status === 'ready' ? 'line-through' : ''}`}>
                                                        {item.product_name}
                                                    </h4>
                                                    
                                                    {/* Modifiers parsing if injected */}
                                                    {item.modifiers && item.modifiers.length > 0 && (
                                                        <ul className="mt-1 space-y-0.5">
                                                            {item.modifiers.map((mod, i) => (
                                                                <li key={i} className="text-xs text-yellow-500/80 font-bold block">+ {mod.name || mod}</li>
                                                            ))}
                                                        </ul>
                                                    )}
                                                    
                                                    {item.notes && (
                                                        <p className="text-xs text-red-300 font-bold italic mt-1.5 p-1.5 bg-red-900/30 rounded border border-red-900/50">
                                                            "{item.notes}"
                                                        </p>
                                                    )}
                                                </div>
                                            </div>
                                        </div>
                                        
                                        {/* Status Tag Overlay Hook */}
                                        <div className="absolute bottom-2 right-2">
                                            <span className={`px-2 py-0.5 rounded text-[10px] font-black uppercase tracking-wider ${getStatusColor(item.status)}`}>
                                                {item.status}
                                            </span>
                                        </div>
                                        
                                        {/* Bump Action Hover Overlay */}
                                        {item.status !== 'ready' && (
                                            <div className="absolute inset-y-0 right-0 w-12 bg-primary flex flex-col items-center justify-center text-white opacity-0 group-hover:opacity-100 transition-opacity transform translate-x-4 group-hover:translate-x-0">
                                                <FiCheck className="w-5 h-5 mb-1" />
                                                <span className="text-[10px] font-black uppercase">BUMP</span>
                                            </div>
                                        )}
                                    </div>
                                ))}
                            </div>
                            
                            {/* Ticket Footer Action */}
                            <div className="p-3 border-t border-white/10 bg-[#0f172a] rounded-b-xl shrink-0">
                                <button 
                                    className="w-full py-2.5 rounded-lg border border-white/10 text-white/70 font-bold text-sm hover:bg-white/5 transition-colors"
                                    onClick={() => {
                                        // Complete all items in ticket
                                        ticket.items.forEach(item => {
                                            if (item.status !== 'ready') handleBumpStatus(item.id, item.status);
                                        });
                                    }}
                                >
                                    Bump Entire Ticket
                                </button>
                            </div>
                        </div>
                    ))
                )}
            </div>
            
        </div>
    );
};

export default KDS;

import React, { useState, useEffect } from 'react';
import { posApi } from '../../api/posApi';
import useAuthStore from '../../store/authStore';
import toast from 'react-hot-toast';
import { FiShoppingCart, FiSearch, FiX, FiCheck, FiCoffee, FiPlus, FiMinus, FiCreditCard, FiClock, FiLayers, FiUserCheck, FiGift, FiTrash2, FiEdit2 } from 'react-icons/fi';
import ConfirmModal from '../../components/ConfirmModal';
import { customersApi } from '../../api/customersApi';
import useSettingsStore from '../../store/settingsStore';
import { printReceipt } from './ReceiptPrinter';

const POSDashboard = () => {
    const { user } = useAuthStore();
    const { settings } = useSettingsStore();
    const [products, setProducts] = useState([]);
    const [categories, setCategories] = useState([]);
    const [activeCategory, setActiveCategory] = useState('all');
    const [searchQuery, setSearchQuery] = useState('');
    const [isLoading, setIsLoading] = useState(true);
    
    // Cart State
    const [cart, setCart] = useState([]);
    const [orderType, setOrderType] = useState('takeaway');
    const [selectedTable, setSelectedTable] = useState(null);
    const [tables, setTables] = useState([]);
    
    // Modifiers & Variations State
    const [modifierModalOpen, setModifierModalOpen] = useState(false);
    const [selectedProductForMod, setSelectedProductForMod] = useState(null);
    const [selectedVariation, setSelectedVariation] = useState(null); 
    const [currentModifiers, setCurrentModifiers] = useState([]); 
    const [specialInstructions, setSpecialInstructions] = useState('');

    // Checkout & Payments State
    const [checkoutModalOpen, setCheckoutModalOpen] = useState(false);
    const [payments, setPayments] = useState([]); // {method, amount}
    const [paymentAmountInput, setPaymentAmountInput] = useState('');
    const [selectedPaymentMethod, setSelectedPaymentMethod] = useState('cash');

    // Customer & Loyalty State
    const [customerPhone, setCustomerPhone] = useState('');
    const [attachedCustomer, setAttachedCustomer] = useState(null);
    const [pointsToRedeem, setPointsToRedeem] = useState('');
    const [isSearchingCustomer, setIsSearchingCustomer] = useState(false);
    
    // Quick Add Customer Data
    const [showAddCustomerModal, setShowAddCustomerModal] = useState(false);
    const [newCustomerData, setNewCustomerData] = useState({ first_name: '', last_name: '', phone: '' });

    // Open Orders / Drafts State
    const [activeOrderId, setActiveOrderId] = useState(null);
    const [activeOrderTotal, setActiveOrderTotal] = useState(0);
    const [showDraftsModal, setShowDraftsModal] = useState(false);
    const [draftOrders, setDraftOrders] = useState([]);
    
    // No print state needed - printReceipt() opens its own window

    useEffect(() => {
        fetchProducts();
        fetchTables();
    }, []);

    const fetchProducts = async () => {
        setIsLoading(true);
        try {
            const response = await posApi.getProducts();
            setProducts(response.data);
            
            // Extract unique categories using category_name
            const cats = [...new Set(response.data.map(p => p.category_name || 'Uncategorized'))];
            setCategories(['all', ...cats]);
        } catch (error) {
            toast.error("Failed to load products");
        } finally {
            setIsLoading(false);
        }
    };
    
    const fetchTables = async () => {
        try {
            const response = await posApi.getTables();
            setTables(response.data.filter(t => t.status === 'available'));
        } catch (error) {
            console.error("Failed to load tables", error);
        }
    };

    const handleSearchCustomer = async () => {
        if (!customerPhone) return;
        setIsSearchingCustomer(true);
        try {
            const res = await customersApi.getCustomers({ search: customerPhone });
            if (res.data && res.data.length > 0) {
                const cust = res.data[0];
                setAttachedCustomer(cust);
                toast.success(`Attached ${cust.first_name} ${cust.last_name || ''}`);
                
                // Birthday Alert
                if (cust.date_of_birth) {
                    const dob = new Date(cust.date_of_birth);
                    const today = new Date();
                    if (dob.getMonth() === today.getMonth() && dob.getDate() === today.getDate()) {
                        toast('🎂 It is their birthday today!', { icon: '🎉', duration: 5000 });
                    }
                }
            } else {
                setNewCustomerData({ first_name: '', last_name: '', phone: customerPhone });
                setShowAddCustomerModal(true);
            }
        } catch (err) {
            toast.error('Error searching customer');
        } finally {
            setIsSearchingCustomer(false);
        }
    };

    const handleCreateCustomer = async () => {
        if (!newCustomerData.first_name || !newCustomerData.phone) {
            toast.error('Name and Phone are required');
            return;
        }
        try {
            const res = await customersApi.createCustomer(newCustomerData);
            setAttachedCustomer(res.data);
            toast.success('Customer Created & Attached!');
            setShowAddCustomerModal(false);
        } catch (err) {
            toast.error('Failed to create customer');
        }
    };

    const fetchDraftOrders = async () => {
        try {
            const res = await posApi.getOrders();
            setDraftOrders(res.data.filter(o => o.status === 'pending'));
        } catch (error) {
            console.error(error);
        }
    };

    const loadDraftOrder = (order) => {
        setActiveOrderId(order.id);
        setActiveOrderTotal(order.total_amount);
        setOrderType(order.order_type);
        setSelectedTable(order.table || null);
        if (order.customer) {
            customersApi.getCustomer(order.customer).then(res => setAttachedCustomer(res.data)).catch(() => {});
        }
        // Direct to payment — cart stays empty, pays by stored total
        setCart([]);
        setPayments([]);
        setPaymentAmountInput(order.total_amount);
        setSelectedPaymentMethod('cash');
        setShowDraftsModal(false);
        setCheckoutModalOpen(true);
    };

    // Load a draft INTO the cart for full editing (add/remove items, then re-save or pay)
    const loadDraftForEditing = async (order) => {
        const toastId = toast.loading('Loading order for editing...');
        try {
            // Fetch the full order with nested items to rebuild the cart
            const res = await posApi.getOrder(order.id);
            const fullOrder = res.data;

            // Rebuild cart items from the saved order items
            // We need full product objects — fetch them from the existing products list
            const cartItems = (fullOrder.items || []).map(item => ({
                // Minimal product object needed by the cart and calculations
                product: {
                    id:   item.product,
                    name: item.product_name,
                    price: parseFloat(item.unit_price),
                    modifier_groups: [],
                    variations: [],
                },
                quantity:             item.quantity,
                unit_price:           parseFloat(item.unit_price),
                total_price:          parseFloat(item.total_price),
                modifiers:            (item.modifiers_details || []).map(m => m.id),
                modifiersObjects:     item.modifiers_details || [],
                special_instructions: item.special_instructions || '',
                cartKey: `${item.product}-${Date.now()}-${Math.random()}`,
            }));

            setCart(cartItems);
            setActiveOrderId(fullOrder.id);
            setActiveOrderTotal(fullOrder.total_amount);
            setOrderType(fullOrder.order_type);
            setSelectedTable(fullOrder.table || null);
            setPayments([]);
            setPaymentAmountInput('');

            if (fullOrder.customer) {
                customersApi.getCustomer(fullOrder.customer)
                    .then(r => setAttachedCustomer(r.data))
                    .catch(() => {});
            } else {
                setAttachedCustomer(null);
            }

            setShowDraftsModal(false);
            toast.success(`Editing order ${fullOrder.order_number}`, { id: toastId });
        } catch (err) {
            toast.error('Failed to load order for editing', { id: toastId });
        }
    };

    const handleProductClick = (product) => {
        const hasModifiers = product.modifier_groups && product.modifier_groups.length > 0;
        const hasVariations = product.variations && product.variations.length > 0;
        
        if (hasModifiers || hasVariations) {
            // Open modal to select size and modifiers
            setSelectedProductForMod(product);
            setCurrentModifiers([]);
            setSpecialInstructions('');
            
            // Auto-select first variation if exists to prevent errors
            if (hasVariations) {
                setSelectedVariation(product.variations[0]);
            } else {
                setSelectedVariation(null);
            }
            
            setModifierModalOpen(true);
        } else {
            // Add straight to cart
            addToCart(product, null, [], '');
        }
    };

    const addToCart = (product, variation, modifiers = [], instructions = '') => {
        // Calculate unit price with modifiers and variation
        let modifiersPrice = 0;
        let selectedModsObjects = [];
        
        modifiers.forEach(modId => {
            product.modifier_groups?.forEach(group => {
                const mod = group.modifiers.find(m => m.id === modId);
                if (mod) {
                    modifiersPrice += parseFloat(mod.extra_price || 0);
                    selectedModsObjects.push(mod);
                }
            });
        });
        
        // Base price comes from variation if selected, else base product price
        let basePrice = variation ? parseFloat(variation.price) : parseFloat(product.price);
        
        // Add combo extra prices if any (Combos are static for now)
        let comboExtraPrice = 0;
        if (product.combo_items && product.combo_items.length > 0) {
           comboExtraPrice = product.combo_items.reduce((sum, item) => sum + parseFloat(item.extra_price || 0), 0);
        }

        const unitPrice = basePrice + modifiersPrice + comboExtraPrice;

        // Check if identical item already in cart (same product + variation + modifiers + instructions)
        const existingItemIndex = cart.findIndex(item => 
            item.product.id === product.id && 
            item.variation?.id === variation?.id &&
            JSON.stringify(item.modifiers.sort()) === JSON.stringify(modifiers.sort()) &&
            item.special_instructions === instructions
        );

        if (existingItemIndex > -1) {
            const newCart = [...cart];
            newCart[existingItemIndex].quantity += 1;
            newCart[existingItemIndex].total_price = newCart[existingItemIndex].quantity * unitPrice;
            setCart(newCart);
        } else {
            const newItem = {
                id: Date.now().toString(), // local frontend ID
                product: product,
                variation: variation,
                quantity: 1,
                modifiers: modifiers,
                modifiersObjects: selectedModsObjects,
                special_instructions: instructions,
                unit_price: unitPrice,
                total_price: unitPrice
            };
            setCart([...cart, newItem]);
        }
        
        setModifierModalOpen(false);
    };

    const updateCartQuantity = (index, delta) => {
        const newCart = [...cart];
        const newQty = newCart[index].quantity + delta;
        
        if (newQty <= 0) {
            newCart.splice(index, 1);
        } else {
            newCart[index].quantity = newQty;
            newCart[index].total_price = newQty * newCart[index].unit_price;
        }
        setCart(newCart);
    };

    const filteredProducts = products.filter(p => {
        const catName = p.category_name || 'Uncategorized';
        const matchesCat = activeCategory === 'all' || catName === activeCategory;
        const matchesSearch = p.name.toLowerCase().includes(searchQuery.toLowerCase()) || 
                              (p.name_ar && p.name_ar.toLowerCase().includes(searchQuery.toLowerCase()));
        return matchesCat && matchesSearch;
    });
    
    const subtotal = cart.reduce((sum, item) => sum + item.total_price, 0);
    
    // Tax Calculation Based on Settings
    const taxRate = settings?.tax_rate ? (parseFloat(settings.tax_rate) / 100) : 0.14;
    const isTaxInclusive = settings?.tax_inclusive === true;
    
    let baseTaxableAmount = subtotal;
    let estimatedTax = 0;

    if (isTaxInclusive) {
        // Subtotal already includes tax: Tax = Subtotal - (Subtotal / (1 + TaxRate))
        baseTaxableAmount = subtotal / (1 + taxRate);
        estimatedTax = subtotal - baseTaxableAmount;
    } else {
        // Subtotal does not include tax: Tax = Subtotal * TaxRate
        estimatedTax = subtotal * taxRate;
    }

    // Service Charge Calculation
    const serviceChargeRate = settings?.service_charge_rate ? (parseFloat(settings.service_charge_rate) / 100) : 0.12;
    const serviceCharge = orderType === 'dine_in' ? subtotal * serviceChargeRate : 0; 
    
    // Loyalty Discount
    const loyaltyDiscount = pointsToRedeem ? (parseFloat(pointsToRedeem) * 0.5) : 0;
    
    // Total (If tax is inclusive, tax is already in subtotal, so we don't add it again)
    const totalWithoutTaxAddition = isTaxInclusive ? subtotal : (subtotal + estimatedTax);
    const total = Math.max(0, totalWithoutTaxAddition + serviceCharge - loyaltyDiscount);

    // Split Payments Logic
    const remainingBalance = Math.max(0, (activeOrderId ? parseFloat(activeOrderTotal) : total) - payments.reduce((sum, p) => sum + p.amount, 0));

    const handleCheckout = () => {
        if (!activeOrderId) {
            if (cart.length === 0) {
                toast.error("Cart is empty");
                return;
            }
            if (orderType === 'dine_in' && !selectedTable) {
                toast.error("Please select a table for Dine-In orders");
                return;
            }
            setPaymentAmountInput(total.toFixed(2));
        }
        
        setPayments([]);
        setSelectedPaymentMethod('cash');
        setCheckoutModalOpen(true);
    };

    const handleSendToKitchen = async () => {
        if (cart.length === 0) {
            toast.error("Cart is empty");
            return;
        }
        if (orderType === 'dine_in' && !selectedTable) {
            toast.error("Please select a table for Dine-In orders");
            return;
        }

        const orderData = {
            order_type: orderType,
            customer: attachedCustomer ? attachedCustomer.id : null,
            table: selectedTable || null,
            subtotal: subtotal.toFixed(2),
            tax_amount: estimatedTax.toFixed(2),
            service_charge: serviceCharge.toFixed(2),
            discount_amount: loyaltyDiscount.toFixed(2),
            total_amount: total.toFixed(2),
            items: cart.map(item => ({
                product: item.product.id,
                quantity: item.quantity,
                modifiers: item.modifiers || [],
                special_instructions: item.special_instructions || ''
            }))
        };

        const isEditingDraft = !!activeOrderId;
        const toastId = toast.loading(isEditingDraft ? "Updating Draft Order..." : "Saving Order...");
        try {
            if (isEditingDraft) {
                // PATCH the existing draft with the new items list
                await posApi.updateOrder(activeOrderId, orderData);
                toast.success("Draft Updated!", { id: toastId });
            } else {
                await posApi.createOrder(orderData);
                toast.success("Order Saved & Sent to Kitchen!", { id: toastId });
            }
            // Reset POS state
            setCart([]);
            setSelectedTable(null);
            setAttachedCustomer(null);
            setCustomerPhone('');
            setPointsToRedeem('');
            setActiveOrderId(null);
            setActiveOrderTotal(0);
            fetchTables();
        } catch (error) {
            toast.error(error.response?.data?.error || error.response?.data?.detail || "Failed to save order", { id: toastId });
        }
    };

    const handleAddPayment = () => {
        const amt = parseFloat(paymentAmountInput);
        if (isNaN(amt) || amt <= 0.01) return;
        if (amt > remainingBalance + 0.01) {
            toast.error("Payment exceeds remaining balance");
            return;
        }
        
        if (selectedPaymentMethod === 'tab' && !attachedCustomer) {
            toast.error("Customer must be attached to use Tab payment");
            return;
        }

        setPayments([...payments, { method: selectedPaymentMethod, amount: amt }]);
        setPaymentAmountInput(Math.max(0, remainingBalance - amt).toFixed(2));
    };

    const handleRemovePayment = (index) => {
        const newPayments = [...payments];
        newPayments.splice(index, 1);
        setPayments(newPayments);
        const newRem = Math.max(0, total - newPayments.reduce((sum, p) => sum + p.amount, 0));
        setPaymentAmountInput(newRem.toFixed(2));
    };

    const submitOrder = async (shouldPrint = false) => {
        if (remainingBalance > 0.01) {
            toast.error("Balance must be completely paid off.");
            return;
        }

        const toastId = toast.loading("Processing Payment...");
        
        try {
            let orderIdToPay = activeOrderId;
            let finalizedOrderData = null;
            
            // If paying a brand new cart order, create it first
            if (!orderIdToPay) {
                const orderData = {
                    order_type: orderType,
                    customer: attachedCustomer ? attachedCustomer.id : null,
                    table: selectedTable || null,
                    subtotal: subtotal.toFixed(2),
                    tax_amount: estimatedTax.toFixed(2),
                    service_charge: serviceCharge.toFixed(2),
                    discount_amount: loyaltyDiscount.toFixed(2),
                    total_amount: total.toFixed(2),
                    items: cart.map(item => ({
                        product: item.product.id,
                        quantity: item.quantity,
                        modifiers: item.modifiers,
                        special_instructions: item.special_instructions
                    }))
                };
                const res = await posApi.createOrder(orderData);
                orderIdToPay = res.data.id;
                finalizedOrderData = res.data;
            } else {
                // If it was a draft, we need it to print. Let's fetch it if not currently held purely in frontend memory.
                const res = await posApi.getOrders();
                finalizedOrderData = res.data.find(o => o.id === orderIdToPay);
            }

            await posApi.processPayment(orderIdToPay, {
                payments: payments,
                redeemed_points: pointsToRedeem ? parseInt(pointsToRedeem) : 0
            });
            
            toast.success("Order Complete!", { id: toastId });
            
            // Trigger Print Flow — call directly before state reset so all values are captured
            if (shouldPrint && finalizedOrderData) {
                printReceipt({
                    order: finalizedOrderData,
                    cart: [...cart],
                    subtotal,
                    taxInfo: estimatedTax,
                    serviceCharge,
                    discountInfo: loyaltyDiscount,
                    total,
                    payments: [...payments],
                    remainingBalance,
                });
            }

            // Reset all state
            setCart([]);
            setSelectedTable(null);
            setAttachedCustomer(null);
            setCustomerPhone('');
            setPointsToRedeem('');
            setCheckoutModalOpen(false);
            setActiveOrderId(null);
            setActiveOrderTotal(0);
            fetchTables(); 
        } catch (error) {
            toast.error(error.response?.data?.error || error.response?.data?.detail || "Failed to process order", { id: toastId });
        }
    };

    const renderModifierContent = () => {
        if (!selectedProductForMod) return null;
        
        return (
            <div className="p-6 overflow-y-auto custom-scrollbar space-y-6">
                
                {/* Size Variations */}
                {selectedProductForMod.variations?.length > 0 && (
                    <div className="bg-white/5 border border-white/10 rounded-xl overflow-hidden">
                        <div className="px-4 py-3 bg-[#0f172a] border-b border-white/5">
                            <h4 className="font-bold text-white text-sm">Select Size *</h4>
                        </div>
                        <div className="p-3 grid grid-cols-3 gap-3">
                            {selectedProductForMod.variations.map(variation => (
                                <button
                                    key={variation.id}
                                    onClick={() => setSelectedVariation(variation)}
                                    className={`py-3 px-2 rounded-lg border flex flex-col items-center justify-center transition-all ${
                                        selectedVariation?.id === variation.id
                                        ? 'bg-primary/20 border-primary text-textMain'
                                        : 'bg-surface border-transparent text-textMuted hover:bg-white/10 hover:text-textMain'
                                    }`}
                                >
                                    <span className="font-bold text-sm mb-1">{variation.size_name}</span>
                                    <span className="font-mono text-xs">{settings?.currency || '$'}{variation.price}</span>
                                </button>
                            ))}
                        </div>
                    </div>
                )}

                {/* Modifiers */}
                {selectedProductForMod.modifier_groups?.map(group => (
                    <div key={group.id} className="bg-white/5 border border-white/10 rounded-xl overflow-hidden">
                        <div className="px-4 py-2 bg-background border-b border-white/5 flex justify-between items-center">
                            <h4 className="font-bold text-textMain text-sm">{group.name}</h4>
                            <span className="text-[10px] text-textMuted uppercase tracking-wider bg-white/5 px-2 py-0.5 rounded">
                                {group.max_choices === 1 ? 'Choose 1' : `Choose up to ${group.max_choices || 'Any'}`}
                            </span>
                        </div>
                        <div className="p-2 space-y-1">
                            {group.modifiers.map(mod => {
                                const isSelected = currentModifiers.includes(mod.id);
                                return (
                                    <button 
                                        key={mod.id}
                                        onClick={() => {
                                            if (group.max_choices === 1) {
                                                const groupModIds = group.modifiers.map(m => m.id);
                                                const newMods = currentModifiers.filter(id => !groupModIds.includes(id));
                                                setCurrentModifiers([...newMods, mod.id]);
                                            } else {
                                                if (isSelected) {
                                                    setCurrentModifiers(currentModifiers.filter(id => id !== mod.id));
                                                } else {
                                                    const selectedInGroup = currentModifiers.filter(id => group.modifiers.map(m=>m.id).includes(id));
                                                    if (group.max_choices === 0 || selectedInGroup.length < group.max_choices) {
                                                        setCurrentModifiers([...currentModifiers, mod.id]);
                                                    } else {
                                                        toast.error(`Maximum ${group.max_choices} choices allowed for ${group.name}`);
                                                    }
                                                }
                                            }
                                        }}
                                        className={`w-full flex justify-between items-center p-3 rounded-lg text-sm transition-all border ${
                                            isSelected 
                                            ? 'bg-primary/20 border-primary text-textMain shadow-[inset_0_0_10px_rgba(59,130,246,0.2)]' 
                                            : 'bg-surface border-transparent text-textMuted hover:bg-white/5 hover:text-textMain'
                                        }`}
                                    >
                                        <span>{mod.name}</span>
                                        {parseFloat(mod.extra_price) > 0 && (
                                            <span className="font-mono text-xs shadow-sm bg-black/30 px-2 py-1 rounded text-primary">+{settings?.currency || '$'}{mod.extra_price}</span>
                                        )}
                                    </button>
                                )
                            })}
                        </div>
                    </div>
                ))}
                
                {/* Special Instructions */}
                <div>
                    <label className="block text-sm font-bold text-textMain mb-2">Special Instructions</label>
                    <textarea 
                        className="w-full bg-background text-textMain border border-white/10 rounded-xl p-3 focus:outline-none focus:border-primary focus:ring-1 focus:ring-primary h-24 text-sm resize-none"
                        placeholder="e.g. Extra hot, no foam..."
                        value={specialInstructions}
                        onChange={(e) => setSpecialInstructions(e.target.value)}
                    ></textarea>
                </div>
            </div>
        );
    }

    return (
        <div className="h-screen flex bg-background overflow-hidden">
                {/* LIFT SIDE: PRODUCT GRID */}
            <div className="flex-1 flex flex-col h-full bg-surface rounded-tr-3xl">
                <div className="p-6 pb-0 tracking-tight shrink-0">
                    <div className="flex justify-between items-center mb-6">
                        <h1 className="text-3xl font-black text-textMain">New Order</h1>
                        <div className="relative w-64">
                            <FiSearch className="absolute left-4 top-1/2 -translate-y-1/2 text-textMuted w-5 h-5" />
                            <input 
                                type="text"
                                placeholder="Search products..."
                                value={searchQuery}
                                onChange={(e) => setSearchQuery(e.target.value)}
                                className="w-full bg-background text-textMain rounded-full py-3 pl-12 pr-4 border border-slate-200 dark:border-white/10 dark:border-white/5 focus:border-primary focus:ring-1 focus:ring-primary transition-colors focus:outline-none placeholder-textMuted"
                            />
                        </div>
                    </div>

                    <div className="flex space-x-3 overflow-x-auto pb-4 custom-scrollbar hide-scrollbar">
                        {categories.map(cat => (
                            <button
                                key={cat}
                                onClick={() => setActiveCategory(cat)}
                                className={`px-6 py-3 rounded-full font-bold whitespace-nowrap transition-all ${
                                    activeCategory === cat 
                                    ? 'bg-primary text-gray-900 shadow-lg shadow-primary/30 scale-105' 
                                    : 'bg-background text-textMuted border border-slate-200 dark:border-white/10 dark:border-white/5 hover:border-slate-400 dark:hover:border-white/20'
                                }`}
                            >
                                {cat === 'all' ? 'All Items' : cat.toUpperCase()}
                            </button>
                        ))}
                    </div>
                </div>

                <div className="flex-1 p-6 overflow-y-auto custom-scrollbar">
                    {isLoading ? (
                        <div className="flex items-center justify-center h-full">
                            <p className="text-textMuted animate-pulse">Loading menu...</p>
                        </div>
                    ) : (
                        <div className="grid grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 2xl:grid-cols-5 gap-4 content-start">
                            {filteredProducts.map(product => (
                                <button
                                    key={product.id}
                                    onClick={() => handleProductClick(product)}
                                    className="bg-background border border-slate-200 dark:border-white/10 dark:border-white/5 rounded-2xl p-4 flex flex-col items-center justify-center text-center hover:bg-slate-50 dark:hover:bg-white/5 dark:hover:bg-[#16213e] hover:border-primary/50 hover:shadow-[0_0_20px_rgba(59,130,246,0.15)] transition-all group relative overflow-hidden h-40"
                                >
                                    {/* Indicators for Combos and Options */}
                                    <div className="absolute top-3 right-3 flex space-x-1">
                                        {product.is_popular && <span className="w-2 h-2 rounded-full bg-yellow-500 shadow-[0_0_5px_rgba(234,179,8,0.5)]"></span>}
                                        {product.combo_items?.length > 0 && <span className="w-2 h-2 rounded-full bg-purple-500 shadow-[0_0_5px_rgba(168,85,247,0.5)]"></span>}
                                    </div>

                                    {product.image ? (
                                        <img src={product.image} alt={product.name} className="w-14 h-14 rounded-full object-cover mb-3 group-hover:scale-110 transition-transform opacity-90 border border-slate-200 dark:border-white/10" />
                                    ) : (
                                        <div className="w-12 h-12 bg-slate-100 dark:bg-white/5 rounded-full flex items-center justify-center mb-3 group-hover:scale-110 transition-transform">
                                            {product.combo_items?.length > 0 ? (
                                                <FiLayers className="w-6 h-6 text-purple-400" />
                                            ) : (
                                                <FiCoffee className="w-6 h-6 text-primary/70 group-hover:text-primary" />
                                            )}
                                        </div>
                                    )}

                                    <h3 className="font-bold text-textMain mb-1 line-clamp-2 leading-tight text-sm">{product.name}</h3>
                                    
                                    <div className="mt-auto pt-2 w-full flex items-center justify-center space-x-2">
                                        {product.variations?.length > 0 ? (
                                            <p className="font-mono text-primary text-xs font-bold border border-primary/20 px-2 py-0.5 rounded-full">
                                                from {settings?.currency || '$'}{Math.min(...product.variations.map(v => v.price))}
                                            </p>
                                        ) : (
                                            <p className="font-mono text-green-400 font-bold text-sm">
                                                {settings?.currency || '$'}{product.price}
                                            </p>
                                        )}
                                    </div>
                                    
                                </button>
                            ))}
                            {filteredProducts.length === 0 && (
                                <div className="col-span-full py-20 text-center text-textMuted">
                                    No products found matching your search.
                                </div>
                            )}
                        </div>
                    )}
                </div>
            </div>

            {/* RIGHT SIDE: CART PANEL */}
            <div className="w-96 bg-background h-full flex flex-col border-l border-slate-200 dark:border-white/10 dark:border-white/5 shadow-[-10px_0_30px_rgba(0,0,0,0.1)] dark:shadow-[-10px_0_30px_rgba(0,0,0,0.5)] z-10 shrink-0">
                <div className="p-6 border-b border-slate-200 dark:border-white/10 flex items-center justify-between shrink-0">
                    <h2 className="text-xl font-black text-textMain flex items-center">
                        <FiShoppingCart className="mr-3 text-primary" /> Current Order
                    </h2>
                    <div className="flex gap-2">
                        <button onClick={() => { fetchDraftOrders(); setShowDraftsModal(true); }} className="text-xs font-bold text-amber-400 hover:text-amber-300 bg-amber-400/10 px-3 py-1.5 rounded-md transition-colors flex items-center">
                           <FiClock className="mr-1" /> Open Tables
                        </button>
                        <button onClick={() => { setCart([]); setActiveOrderId(null); setActiveOrderTotal(0); setPointsToRedeem(''); }} className="text-xs font-bold text-red-400 hover:text-red-300 bg-red-400/10 px-3 py-1.5 rounded-md transition-colors">Clear</button>
                    </div>
                </div>

                {activeOrderId ? (
                    <div className="px-6 py-3 bg-amber-500/20 text-amber-400 text-sm font-bold flex justify-between items-center border-b border-white/5 shrink-0">
                        <span className="flex items-center gap-2"><FiClock className="animate-pulse" /> Paying Open Order</span>
                        <span className="font-mono bg-amber-500/20 px-2 rounded">#{activeOrderId.split('-')[0]}</span>
                    </div>
                ) : (
                    <div className="px-6 py-4 flex space-x-2 border-b border-white/5 bg-white/5 shrink-0">
                        {['dine_in', 'takeaway', 'delivery'].map(type => (
                            <button
                                key={type}
                                onClick={() => {
                                    setOrderType(type);
                                    if (type !== 'dine_in') setSelectedTable(null);
                                }}
                                className={`flex-1 py-2 rounded-lg text-xs font-bold uppercase tracking-wider transition-all ${
                                    orderType === type 
                                    ? 'bg-primary text-white shadow-md' 
                                    : 'bg-surface text-textMuted hover:bg-surface border border-slate-200 dark:border-white/10'
                                }`}
                            >
                                {type.replace('_', ' ')}
                            </button>
                        ))}
                    </div>
                )}
                
                {!activeOrderId && orderType === 'dine_in' && (
                    <div className="px-6 py-3 border-b border-white/5 bg-yellow-500/5 shrink-0">
                        <select 
                            value={selectedTable || ''} 
                            onChange={(e) => setSelectedTable(e.target.value)}
                            className="w-full bg-surface text-textMain border border-yellow-500/30 rounded-lg p-2 focus:outline-none focus:border-yellow-500 text-sm font-bold"
                        >
                            <option value="">-- Select Table --</option>
                            {tables.filter(t => t.status === 'available').map(t => (
                                <option key={t.id} value={t.id}>Table {t.number} ({t.capacity} seats)</option>
                            ))}
                        </select>
                    </div>
                )}
                
                {/* Customer CRM Attachment Block */}
                <div className="px-6 py-3 border-b border-white/5 bg-surface/50 shrink-0">
                    {!attachedCustomer ? (
                        <div className="flex gap-2">
                            <input 
                                type="text" 
                                placeholder="Customer Phone (e.g. 010...)"
                                value={customerPhone}
                                onChange={(e) => setCustomerPhone(e.target.value)}
                                className="flex-1 bg-background text-textMain border border-slate-200 dark:border-white/10 rounded-lg px-3 py-1.5 focus:outline-none focus:border-primary text-xs"
                            />
                            <button 
                                onClick={handleSearchCustomer}
                                disabled={isSearchingCustomer || !customerPhone}
                                className="px-3 py-1.5 bg-blue-600 hover:bg-blue-700 disabled:opacity-50 text-white text-xs font-bold w-[70px] rounded-lg flex justify-center items-center"
                            >
                                {isSearchingCustomer ? '...' : 'Search'}
                            </button>
                        </div>
                    ) : (
                        <div className="space-y-2">
                            <div className="flex justify-between items-center text-xs text-white">
                                <div className="flex items-center gap-2">
                                    <FiUserCheck className="text-green-400" />
                                    <span className="font-bold">{attachedCustomer.first_name}</span>
                                </div>
                                <button onClick={() => { setAttachedCustomer(null); setPointsToRedeem(''); }} className="text-red-400 hover:text-red-300">
                                    Remove
                                </button>
                            </div>
                            
                            {/* Loyalty Points display */}
                            {attachedCustomer.loyalty_account && (
                                <div className="bg-[#0f172a] rounded-lg p-2 border border-white/5 flex flex-col gap-2">
                                    <div className="flex justify-between text-xs items-center">
                                        <span className="text-textMuted flex items-center gap-1"><FiGift /> Points:</span>
                                        <strong className="text-yellow-400">{attachedCustomer.loyalty_account.points_balance} pts</strong>
                                    </div>
                                    <div className="flex items-center gap-2">
                                        <input 
                                            type="number" 
                                            placeholder="Redeem points?" 
                                            value={pointsToRedeem}
                                            onChange={(e) => setPointsToRedeem(e.target.value)}
                                            max={attachedCustomer.loyalty_account.points_balance}
                                            className="w-full bg-[#1e293b] text-white border border-white/10 rounded px-2 py-1 flex-1 text-xs focus:outline-none focus:border-yellow-500"
                                        />
                                    </div>
                                </div>
                            )}
                        </div>
                    )}
                </div>

                <div className="flex-1 overflow-y-auto p-4 custom-scrollbar space-y-3">
                    {cart.map((item, index) => (
                        <div key={item.id} className="bg-surface/50 border border-slate-200 dark:border-white/10 dark:border-white/5 rounded-xl p-3 flex group relative overflow-hidden transition-colors hover:bg-surface">
                            <div className="flex-1 pr-4">
                                <div className="flex items-center space-x-2">
                                    <h4 className="font-bold text-textMain text-sm leading-snug">{item.product.name}</h4>
                                    {item.variation && (
                                        <span className="bg-primary/20 text-primary text-[10px] px-1.5 py-0.5 rounded font-bold uppercase">{item.variation.size_name}</span>
                                    )}
                                </div>
                                
                                <div className="space-y-0.5 mt-1">
                                    {item.product.combo_items?.map(ci => (
                                        <p key={ci.id} className="text-[10px] text-purple-400 italic block">✦ {ci.quantity}x {ci.child_product_name}</p>
                                    ))}
                                    {item.modifiersObjects?.map(m => (
                                        <p key={m.id} className="text-[10px] text-textMuted block">+ {m.name}</p>
                                    ))}
                                    {item.special_instructions && (
                                        <p className="text-[10px] text-yellow-500/70 italic block">"{item.special_instructions}"</p>
                                    )}
                                </div>
                                
                                <p className="font-mono text-green-400 text-xs font-bold mt-1.5">{settings?.currency || '$'}{item.unit_price.toFixed(2)}</p>
                            </div>
                            <div className="flex flex-col items-center justify-between border-l border-slate-200 dark:border-white/10 dark:border-white/5 pl-3">
                                <button onClick={() => updateCartQuantity(index, 1)} className="w-7 h-7 bg-slate-200 dark:bg-white/10 hover:bg-slate-300 dark:hover:bg-white/20 rounded-md flex items-center justify-center text-textMain transition-colors">
                                    <FiPlus className="w-3 h-3" />
                                </button>
                                <span className="font-black text-textMain text-sm">{item.quantity}</span>
                                <button onClick={() => updateCartQuantity(index, -1)} className="w-7 h-7 bg-slate-200 dark:bg-white/10 hover:bg-slate-300 dark:hover:bg-white/20 hover:text-red-400 rounded-md flex items-center justify-center text-textMain transition-colors">
                                    <FiMinus className="w-3 h-3" />
                                </button>
                            </div>
                        </div>
                    ))}
                    
                    {cart.length === 0 && (
                        <div className="h-full flex flex-col items-center justify-center text-textMuted space-y-4 opacity-50">
                            <FiShoppingCart className="w-16 h-16" />
                            <p>No items in cart</p>
                        </div>
                    )}
                </div>

                <div className="bg-surface border-t border-slate-200 dark:border-white/10 p-6 shadow-[0_-10px_30px_rgba(0,0,0,0.1)] dark:shadow-[0_-10px_30px_rgba(0,0,0,0.3)] z-20 shrink-0">
                    <div className="space-y-2 mb-4 text-sm">
                        <div className="flex justify-between text-textMuted">
                            <span>Subtotal</span>
                            <span className="font-mono">{settings?.currency || '$'}{subtotal.toFixed(2)}</span>
                        </div>
                        <div className="flex justify-between text-textMuted">
                            <span>{settings?.tax_label || 'Tax'} ({settings?.tax_rate || 14}%{isTaxInclusive ? ' Incl' : ''})</span>
                            <span className="font-mono">{settings?.currency || '$'}{estimatedTax.toFixed(2)}</span>
                        </div>
                        {orderType === 'dine_in' && (
                           <div className="flex justify-between text-textMuted">
                               <span>Service ({settings?.service_charge_rate || 12}%)</span>
                               <span className="font-mono">{settings?.currency || '$'}{serviceCharge.toFixed(2)}</span>
                           </div>
                        )}
                        {loyaltyDiscount > 0 && (
                            <div className="flex justify-between text-green-400">
                                <span>Points Discount</span>
                                <span className="font-mono">-{settings?.currency || '$'}{loyaltyDiscount.toFixed(2)}</span>
                            </div>
                        )}
                        <div className="flex justify-between text-textMain font-black text-xl pt-2 border-t border-slate-200 dark:border-white/10">
                            <span>Total</span>
                            <span className="text-primary font-mono">{settings?.currency || '$'}{total.toFixed(2)}</span>
                        </div>
                    </div>
                    
                    <div className="flex gap-2">
                        {(!activeOrderId) && (
                            <button 
                                onClick={handleSendToKitchen}
                                disabled={cart.length === 0 || orderType !== 'dine_in' || (orderType === 'dine_in' && !selectedTable)}
                                className="w-1/3 bg-slate-100 dark:bg-white/5 hover:bg-slate-200 dark:hover:bg-white/10 text-textMain font-bold py-4 rounded-xl shadow-lg border border-slate-200 dark:border-white/10 flex flex-col items-center justify-center space-y-1 transition-colors disabled:opacity-50 disabled:cursor-not-allowed"
                            >
                                <FiClock className="w-5 h-5 text-amber-400" />
                                <span className="text-xs">Hold Order</span>
                            </button>
                        )}
                        
                        <button 
                            onClick={handleCheckout}
                            disabled={(cart.length === 0 && !activeOrderId) || (orderType === 'dine_in' && !selectedTable && !activeOrderId)}
                            className={`${activeOrderId ? 'w-full' : 'w-2/3'} bg-gradient-to-r from-green-500 to-emerald-600 hover:from-green-400 hover:to-emerald-500 disabled:opacity-50 disabled:cursor-not-allowed text-white font-black text-lg py-4 rounded-xl shadow-[0_0_20px_rgba(16,185,129,0.3)] transition-all transform active:scale-[0.98] flex items-center justify-center space-x-2`}
                        >
                            <FiCheck className="w-6 h-6" />
                            <span>Checkout / Pay</span>
                        </button>
                    </div>
                </div>
            </div>

            {/* MODIFIER MODAL */}
            {modifierModalOpen && selectedProductForMod && (
                <div className="fixed inset-0 z-50 flex items-center justify-center p-4">
                    <div className="absolute inset-0 bg-black/60 backdrop-blur-sm" onClick={() => setModifierModalOpen(false)}></div>
                    <div className="relative bg-surface w-full max-w-lg rounded-2xl border border-slate-200 dark:border-white/10 shadow-2xl flex flex-col max-h-[90vh] animate-fade-in-up">
                        <div className="p-5 border-b border-slate-200 dark:border-white/10 flex justify-between items-center bg-background rounded-t-2xl shrink-0">
                            <div>
                                <h3 className="text-xl font-black text-textMain">Customize Order</h3>
                                <p className="text-primary font-bold mt-1 text-sm">{selectedProductForMod.name}</p>
                            </div>
                            <button onClick={() => setModifierModalOpen(false)} className="text-textMuted hover:text-textMain bg-slate-200 dark:bg-white/5 p-2 rounded-lg transition-colors"><FiX /></button>
                        </div>
                        
                        {renderModifierContent()}
                        
                        <div className="p-5 border-t border-slate-200 dark:border-white/10 bg-background rounded-b-2xl shrink-0">
                            <button 
                                onClick={() => addToCart(selectedProductForMod, selectedVariation, currentModifiers, specialInstructions)}
                                className="w-full bg-primary hover:bg-primary/90 text-white font-black py-4 rounded-xl shadow-[0_0_15px_rgba(59,130,246,0.5)] transition-all"
                            >
                                Add to Order - {settings?.currency || '$'}{(() => {
                                    let modPrice = currentModifiers.reduce((sum, modId) => {
                                        let price = 0;
                                        selectedProductForMod.modifier_groups?.forEach(g => {
                                            const mod = g.modifiers.find(m => m.id === modId);
                                            if (mod) price = parseFloat(mod.extra_price || 0);
                                        });
                                        return sum + price;
                                    }, 0);
                                    let base = selectedVariation ? parseFloat(selectedVariation.price) : parseFloat(selectedProductForMod.price);
                                    let comboEx = (selectedProductForMod.combo_items||[]).reduce((s, c) => s + parseFloat(c.extra_price||0), 0);
                                    return (base + modPrice + comboEx).toFixed(2);
                                })()}
                            </button>
                        </div>
                    </div>
                </div>
            )}
            
            {/* CHECKOUT MODAL */}
            {checkoutModalOpen && (
                <div className="fixed inset-0 z-50 flex items-center justify-center p-4">
                    <div className="absolute inset-0 bg-black/60 backdrop-blur-sm" onClick={() => setCheckoutModalOpen(false)}></div>
                    <div className="relative bg-surface w-full max-w-2xl rounded-2xl border border-slate-200 dark:border-white/10 shadow-2xl flex flex-col max-h-[90vh] animate-fade-in-up overflow-hidden">
                        <div className="p-5 border-b border-slate-200 dark:border-white/10 flex justify-between items-center bg-background shrink-0">
                            <div>
                                <h3 className="text-2xl font-black text-textMain flex items-center gap-2">
                                    <FiCreditCard className="text-primary" /> Checkout
                                </h3>
                                <p className="text-textMuted mt-1">Balance Due: <span className="text-primary font-mono font-bold">{settings?.currency || '$'}{total.toFixed(2)}</span></p>
                            </div>
                            <button onClick={() => setCheckoutModalOpen(false)} className="text-textMuted hover:text-textMain bg-slate-200 dark:bg-white/5 p-2 rounded-lg transition-colors"><FiX className="w-6 h-6" /></button>
                        </div>
                        
                        <div className="flex-1 overflow-y-auto p-6 space-y-6">
                            
                            {/* Outstanding Balance Banner */}
                            <div className={`p-4 rounded-xl border flex justify-between items-center ${remainingBalance > 0 ? 'bg-amber-500/10 border-amber-500/30' : 'bg-emerald-500/10 border-emerald-500/30'}`}>
                                <span className={`font-bold ${remainingBalance > 0 ? 'text-amber-400' : 'text-emerald-400'}`}>Remaining Balance</span>
                                <span className={`text-2xl font-black font-mono ${remainingBalance > 0 ? 'text-amber-400' : 'text-emerald-400'}`}>
                                    {settings?.currency || '$'}{remainingBalance.toFixed(2)}
                                </span>
                            </div>

                            {/* Add Payment Form */}
                            {remainingBalance > 0 && (
                                <div className="bg-background p-4 rounded-xl border border-slate-200 dark:border-white/10 dark:border-white/5 space-y-4">
                                    <h4 className="text-textMain font-bold mb-2 text-sm">Add Payment</h4>
                                    
                                    <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 gap-2">
                                        {[
                                            { id: 'cash', label: 'Cash', color: 'bg-green-600' },
                                            { id: 'card', label: 'Card', color: 'bg-blue-600' },
                                            { id: 'fawry', label: 'Fawry', color: 'bg-yellow-600' },
                                            { id: 'instapay', label: 'InstaPay', color: 'bg-purple-600' },
                                            { id: 'vodafone_cash', label: 'VF Cash', color: 'bg-red-600' },
                                            { id: 'tab', label: 'Customer Tab', color: 'bg-slate-600' },
                                        ].map(pm => (
                                            <button
                                                key={pm.id}
                                                onClick={() => setSelectedPaymentMethod(pm.id)}
                                                className={`py-2 px-3 rounded-lg text-xs font-bold transition-all ${
                                                    selectedPaymentMethod === pm.id 
                                                    ? `${pm.color} text-white shadow-lg` 
                                                    : 'bg-surface text-textMuted hover:bg-slate-200 dark:hover:bg-[#1e293b]/70 border border-slate-200 dark:border-white/10 dark:border-white/5'
                                                }`}
                                            >
                                                {pm.label}
                                            </button>
                                        ))}
                                    </div>

                                    <div className="flex gap-3 items-end pt-2">
                                        <div className="flex-1">
                                            <label className="block text-xs text-textMuted mb-1">Amount ({settings?.currency || '$'})</label>
                                            <input 
                                                type="number"
                                                value={paymentAmountInput}
                                                onChange={(e) => setPaymentAmountInput(e.target.value)}
                                                max={remainingBalance}
                                                className="w-full bg-surface text-textMain border border-slate-200 dark:border-white/10 rounded-lg px-4 py-3 focus:outline-none focus:border-primary font-mono text-lg"
                                            />
                                        </div>
                                        <button 
                                            onClick={handleAddPayment}
                                            disabled={!paymentAmountInput || parseFloat(paymentAmountInput) <= 0}
                                            className="bg-primary hover:bg-primary/90 disabled:opacity-50 text-white font-bold py-3 px-6 rounded-lg transition-colors flex items-center"
                                        >
                                            <FiPlus className="mr-2" /> Add
                                        </button>
                                    </div>
                                </div>
                            )}

                            {/* Captured Payments List */}
                            {payments.length > 0 && (
                                <div className="space-y-3">
                                    <h4 className="text-textMain font-bold text-sm">Tendered Payments</h4>
                                    <div className="space-y-2">
                                        {payments.map((p, index) => (
                                            <div key={index} className="flex justify-between items-center bg-surface p-3 rounded-lg border border-slate-200 dark:border-white/10 dark:border-white/5">
                                                <div className="flex items-center gap-3">
                                                    <span className="w-8 h-8 rounded-full bg-slate-200 dark:bg-white/5 flex items-center justify-center text-textMuted text-xs font-bold uppercase">
                                                        {p.method.substring(0, 2)}
                                                    </span>
                                                    <div>
                                                        <p className="text-textMain font-bold capitalize text-sm">{p.method.replace('_', ' ')}</p>
                                                    </div>
                                                </div>
                                                <div className="flex items-center gap-4">
                                                    <span className="text-green-400 font-mono font-bold">
                                                        {settings?.currency || '$'}{p.amount.toFixed(2)}
                                                    </span>
                                                    <button onClick={() => handleRemovePayment(index)} className="text-red-400 hover:text-red-300 p-1">
                                                        <FiTrash2 className="w-4 h-4" />
                                                    </button>
                                                </div>
                                            </div>
                                        ))}
                                    </div>
                                </div>
                            )}

                        </div>
                        
                        <div className="p-5 border-t border-slate-200 dark:border-white/10 bg-background shrink-0 flex gap-4">
                            <button 
                                onClick={() => submitOrder(false)}
                                disabled={remainingBalance > 0.01}
                                className={`w-1/2 font-black py-4 rounded-xl transition-all shadow-lg flex items-center justify-center space-x-2 ${
                                    remainingBalance <= 0.01 
                                    ? 'bg-slate-200 dark:bg-white/10 hover:bg-slate-300 dark:hover:bg-white/20 text-textMain shadow-inner' 
                                    : 'bg-slate-200 dark:bg-white/5 text-textMuted dark:text-white/30 cursor-not-allowed'
                                }`}
                            >
                                <FiCheck className="w-5 h-5" />
                                <span>Save Only</span>
                            </button>
                            
                            <button 
                                onClick={() => submitOrder(true)}
                                disabled={remainingBalance > 0.01}
                                className={`w-1/2 font-black py-4 rounded-xl transition-all shadow-lg flex items-center justify-center space-x-2 ${
                                    remainingBalance <= 0.01 
                                    ? 'bg-gradient-to-r from-green-500 to-emerald-600 hover:from-green-400 hover:to-emerald-500 text-white shadow-[0_0_20px_rgba(16,185,129,0.3)]' 
                                    : 'bg-slate-200 dark:bg-white/5 text-textMuted dark:text-white/30 cursor-not-allowed'
                                }`}
                            >
                                <FiCheck className="w-6 h-6" />
                                <span>Save & Print Receipt</span>
                            </button>
                        </div>
                    </div>
                </div>
            )}

            {/* QUICK ADD CUSTOMER MODAL */}
            {showAddCustomerModal && (
                <div className="fixed inset-0 z-50 flex items-center justify-center p-4">
                    <div className="absolute inset-0 bg-black/60 backdrop-blur-sm" onClick={() => setShowAddCustomerModal(false)}></div>
                    <div className="relative bg-surface w-full max-w-md rounded-2xl border border-slate-200 dark:border-white/10 shadow-2xl flex flex-col max-h-[90vh] animate-fade-in-up">
                        <div className="p-5 border-b border-slate-200 dark:border-white/10 flex justify-between items-center bg-background rounded-t-2xl shrink-0">
                            <h3 className="text-xl font-black text-textMain flex items-center gap-2">
                                <FiUserCheck className="text-blue-400" /> New Customer
                            </h3>
                            <button onClick={() => setShowAddCustomerModal(false)} className="text-textMuted hover:text-textMain bg-slate-200 dark:bg-white/5 p-2 rounded-lg transition-colors"><FiX /></button>
                        </div>
                        <div className="p-6 space-y-4">
                            <div>
                                <label className="block text-xs font-bold text-textMuted mb-1">Phone Number *</label>
                                <input 
                                    type="text"
                                    value={newCustomerData.phone}
                                    onChange={(e) => setNewCustomerData({...newCustomerData, phone: e.target.value})}
                                    className="w-full bg-background border border-slate-200 dark:border-white/10 text-textMain rounded-lg px-4 py-3 focus:outline-none focus:border-blue-500"
                                />
                            </div>
                            <div>
                                <label className="block text-xs font-bold text-textMuted mb-1">First Name *</label>
                                <input 
                                    type="text"
                                    value={newCustomerData.first_name}
                                    onChange={(e) => setNewCustomerData({...newCustomerData, first_name: e.target.value})}
                                    className="w-full bg-background border border-slate-200 dark:border-white/10 text-textMain rounded-lg px-4 py-3 focus:outline-none focus:border-blue-500"
                                />
                            </div>
                            <div>
                                <label className="block text-xs font-bold text-textMuted mb-1">Last Name</label>
                                <input 
                                    type="text"
                                    value={newCustomerData.last_name}
                                    onChange={(e) => setNewCustomerData({...newCustomerData, last_name: e.target.value})}
                                    className="w-full bg-background border border-slate-200 dark:border-white/10 text-textMain rounded-lg px-4 py-3 focus:outline-none focus:border-blue-500"
                                />
                            </div>
                        </div>
                        <div className="p-5 border-t border-slate-200 dark:border-white/10 bg-background rounded-b-2xl">
                            <button 
                                onClick={handleCreateCustomer}
                                className="w-full bg-blue-600 hover:bg-blue-700 text-white font-bold py-3 rounded-xl transition-all shadow-lg"
                            >
                                Quick Add & Attach
                            </button>
                        </div>
                    </div>
                </div>
            )}

            {/* OPEN TABLES / DRAFTS MODAL */}
            {showDraftsModal && (
                <div className="fixed inset-0 z-50 flex items-center justify-center p-4">
                    <div className="absolute inset-0 bg-black/60 backdrop-blur-sm" onClick={() => setShowDraftsModal(false)}></div>
                    <div className="relative bg-surface w-full max-w-4xl rounded-2xl border border-slate-200 dark:border-white/10 shadow-2xl flex flex-col max-h-[90vh] animate-fade-in-up">
                        <div className="p-5 border-b border-slate-200 dark:border-white/10 flex justify-between items-center bg-background rounded-t-2xl shrink-0">
                            <h3 className="text-xl font-black text-textMain flex items-center gap-2">
                                <FiClock className="text-amber-400" /> Open Tables & Drafts
                            </h3>
                            <button onClick={() => setShowDraftsModal(false)} className="text-textMuted hover:text-textMain bg-slate-200 dark:bg-white/5 p-2 rounded-lg transition-colors"><FiX /></button>
                        </div>
                        <div className="p-6 overflow-y-auto custom-scrollbar flex-1 bg-background">
                            {draftOrders.length === 0 ? (
                                <div className="text-center text-textMuted py-10">No open orders found.</div>
                            ) : (
                                <div className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-3 gap-4">
                                    {draftOrders.map(order => (
                                        <div key={order.id} className="bg-surface rounded-xl border border-slate-200 dark:border-white/10 dark:border-white/5 p-5 hover:border-amber-400/50 transition-colors flex flex-col h-full relative overflow-hidden">
                                            <div className="absolute top-0 left-0 w-1 h-full bg-amber-500"></div>
                                            <div className="flex justify-between items-start mb-3">
                                                <div>
                                                    <h4 className="font-bold text-textMain text-lg">
                                                        {order.table ? `Table ${order.table_number}` : `Draft #${order.id.split('-')[0]}`}
                                                    </h4>
                                                    <span className="text-xs text-textMuted capitalize">{order.order_type.replace('_', ' ')}</span>
                                                </div>
                                                <span className="font-mono text-primary font-bold bg-primary/10 px-2 py-1 rounded text-sm">
                                                    {settings?.currency || '$'}{parseFloat(order.total_amount).toFixed(2)}
                                                </span>
                                            </div>
                                            
                                            {order.customer_name && (
                                                <div className="text-xs text-textMuted mb-3 flex items-center gap-1">
                                                    <FiUserCheck /> {order.customer_name} ({order.customer_phone})
                                                </div>
                                            )}
                                            
                                            <div className="text-xs text-textMuted flex-grow space-y-1 mb-4">
                                                {order.items?.slice(0, 3).map(item => (
                                                    <p key={item.id} className="truncate">
                                                        <span className="text-textMuted/70">{item.quantity}x</span> {item.product_name || 'Product'} {item.variation_name ? `(${item.variation_name})`:''}
                                                    </p>
                                                ))}
                                                {order.items?.length > 3 && (
                                                    <p className="italic text-textMuted/50">+ {order.items.length - 3} more items...</p>
                                                )}
                                            </div>
                                            
                                            <div className="mt-auto pt-4 border-t border-slate-200 dark:border-white/10 dark:border-white/5 flex gap-2">
                                                {/* Edit Draft — loads items back into POS cart for full editing */}
                                                <button
                                                    onClick={() => loadDraftForEditing(order)}
                                                    className="flex-1 bg-amber-500/10 hover:bg-amber-500/20 text-amber-400 font-bold text-sm py-2 rounded-lg transition-colors flex items-center justify-center gap-2"
                                                    title="Load items into cart for editing"
                                                >
                                                    <FiEdit2 className="w-3.5 h-3.5" /> Edit Draft
                                                </button>
                                                {/* Checkout & Pay — jumps straight to payment using stored total */}
                                                <button
                                                    onClick={() => loadDraftOrder(order)}
                                                    className="flex-1 bg-emerald-500/10 hover:bg-emerald-500/20 text-emerald-400 font-bold text-sm py-2 rounded-lg transition-colors flex items-center justify-center gap-2"
                                                >
                                                    <FiCheck /> Pay
                                                </button>
                                            </div>
                                        </div>
                                    ))}
                                </div>
                            )}
                        </div>
                    </div>
                </div>
            )}

        </div>
    );
};

export default POSDashboard;

import React, { useEffect, useState } from 'react';
import { useForm } from 'react-hook-form';
import { FiX } from 'react-icons/fi';
import { inventoryApi } from '../../api/inventoryApi';

const PromotionModal = ({ isOpen, onClose, onSubmit, type, initialData }) => {
    const { register, handleSubmit, reset, watch, formState: { errors, isSubmitting } } = useForm();
    const [categories, setCategories] = useState([]);
    const [products, setProducts] = useState([]);

    useEffect(() => {
        if (isOpen) {
            if (initialData) {
                // formatting dates if present
                const formatted = { ...initialData };
                if (formatted.start_date) formatted.start_date = formatted.start_date.substring(0, 16);
                if (formatted.end_date) formatted.end_date = formatted.end_date.substring(0, 16);
                if (formatted.expiry_date) formatted.expiry_date = formatted.expiry_date.substring(0, 16);
                reset(formatted);
            } else {
                reset({
                    is_active: true,
                    is_percentage: false,
                    usage_limit: 0
                });
            }

            if (type === 'rewards' || type === 'campaigns') {
                inventoryApi.getProducts().then(res => setProducts(res.data)).catch(() => {});
            }
            if (type === 'campaigns') {
                inventoryApi.getCategories().then(res => setCategories(res.data)).catch(() => {});
            }
        }
    }, [isOpen, initialData, type, reset]);

    const handleFormSubmit = async (data) => {
        // Convert empty strings to null for foreign keys
        const cleanedData = { ...data };
        if (cleanedData.free_product === "") cleanedData.free_product = null;
        if (cleanedData.target_category === "") cleanedData.target_category = null;
        if (cleanedData.target_product === "") cleanedData.target_product = null;
        if (cleanedData.start_date === "") cleanedData.start_date = null;
        if (cleanedData.end_date === "") cleanedData.end_date = null;
        if (cleanedData.expiry_date === "") cleanedData.expiry_date = null;

        await onSubmit(cleanedData);
    };

    if (!isOpen) return null;

    const titles = {
        loyalty: 'Loyalty Rule',
        rewards: 'Reward',
        campaigns: 'Campaign',
        coupons: 'Coupon Code'
    };

    return (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4">
            <div className="fixed inset-0 bg-black/60 backdrop-blur-sm" onClick={onClose}></div>
            <div className="relative bg-surface w-full max-w-lg rounded-2xl shadow-xl border border-slate-200 dark:border-white/10 flex flex-col max-h-[90vh]">
                <div className="flex items-center justify-between p-6 border-b border-slate-200 dark:border-white/10">
                    <h2 className="text-xl font-bold text-textMain">
                        {initialData ? 'Edit' : 'Create'} {titles[type]}
                    </h2>
                    <button onClick={onClose} className="p-2 text-textMuted hover:text-textMain hover:bg-slate-100 dark:hover:bg-white/5 rounded-full transition-colors">
                        <FiX className="w-5 h-5" />
                    </button>
                </div>

                <div className="flex-1 overflow-y-auto p-6 custom-scrollbar">
                    <form id="promoForm" onSubmit={handleSubmit(handleFormSubmit)} className="space-y-4">
                        
                        {/* LOYALTY RULES */}
                        {type === 'loyalty' && (
                            <>
                                <div>
                                    <label className="block text-sm font-medium text-textMain mb-1">Rule Name</label>
                                    <input type="text" {...register('name', { required: true })} className="form-input" placeholder="e.g. Standard Earn Rate" />
                                </div>
                                <div className="grid grid-cols-2 gap-4">
                                    <div>
                                        <label className="block text-sm font-medium text-textMain mb-1">Spend Amount (EGP)</label>
                                        <input type="number" step="0.01" {...register('spend_amount', { required: true })} className="form-input" placeholder="10.00" />
                                    </div>
                                    <div>
                                        <label className="block text-sm font-medium text-textMain mb-1">Points Earned</label>
                                        <input type="number" step="0.01" {...register('points_earned', { required: true })} className="form-input" placeholder="1.0" />
                                    </div>
                                </div>
                            </>
                        )}

                        {/* REWARDS */}
                        {type === 'rewards' && (
                            <>
                                <div>
                                    <label className="block text-sm font-medium text-textMain mb-1">Reward Name</label>
                                    <input type="text" {...register('name', { required: true })} className="form-input" placeholder="e.g. Free Coffee" />
                                </div>
                                <div>
                                    <label className="block text-sm font-medium text-textMain mb-1">Points Cost</label>
                                    <input type="number" {...register('points_cost', { required: true })} className="form-input" placeholder="100" />
                                </div>
                                
                                <div className="border border-slate-200 dark:border-white/10 p-4 rounded-xl space-y-4">
                                    <h4 className="text-sm font-semibold text-textMain">Reward Effect</h4>
                                    <div className="flex items-center space-x-2">
                                        <input type="checkbox" id="is_percentage" {...register('is_percentage')} className="form-checkbox bg-transparent" />
                                        <label htmlFor="is_percentage" className="text-sm text-textMuted select-none cursor-pointer">Is Percentage Discount?</label>
                                    </div>
                                    <div>
                                        <label className="block text-sm font-medium text-textMain mb-1">Discount Value</label>
                                        <input type="number" step="0.01" {...register('discount_value')} className="form-input" placeholder={watch('is_percentage') ? "e.g. 15 (%)" : "e.g. 50 (EGP)"} />
                                    </div>
                                    <div className="pt-2 border-t border-slate-100 dark:border-white/5">
                                        <label className="block text-sm font-medium text-textMain mb-1">Or Free Product</label>
                                        <select {...register('free_product')} className="form-input">
                                            <option value="">-- No Free Product --</option>
                                            {products.map(p => <option key={p.id} value={p.id}>{p.name}</option>)}
                                        </select>
                                    </div>
                                </div>
                            </>
                        )}

                        {/* CAMPAIGNS */}
                        {type === 'campaigns' && (
                            <>
                                <div>
                                    <label className="block text-sm font-medium text-textMain mb-1">Campaign Name</label>
                                    <input type="text" {...register('name', { required: true })} className="form-input" placeholder="e.g. Summer Happy Hour" />
                                </div>
                                <div>
                                    <label className="block text-sm font-medium text-textMain mb-1">Description</label>
                                    <textarea {...register('description')} className="form-input" rows="2" placeholder="Internal notes..."></textarea>
                                </div>
                                <div className="grid grid-cols-2 gap-4">
                                    <div>
                                        <label className="block text-sm font-medium text-textMain mb-1">Start Date</label>
                                        <input type="datetime-local" {...register('start_date')} className="form-input" />
                                    </div>
                                    <div>
                                        <label className="block text-sm font-medium text-textMain mb-1">End Date</label>
                                        <input type="datetime-local" {...register('end_date')} className="form-input" />
                                    </div>
                                </div>
                                <div className="grid grid-cols-2 gap-4">
                                    <div>
                                        <label className="block text-sm font-medium text-textMain mb-1">Target Category</label>
                                        <select {...register('target_category')} className="form-input">
                                            <option value="">-- Any --</option>
                                            {categories.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}
                                        </select>
                                    </div>
                                    <div>
                                        <label className="block text-sm font-medium text-textMain mb-1">Target Product</label>
                                        <select {...register('target_product')} className="form-input">
                                            <option value="">-- Any --</option>
                                            {products.map(p => <option key={p.id} value={p.id}>{p.name}</option>)}
                                        </select>
                                    </div>
                                </div>
                                <div>
                                    <label className="block text-sm font-medium text-textMain mb-1">Discount %</label>
                                    <input type="number" step="0.01" {...register('discount_percentage', { required: true })} className="form-input" placeholder="10" />
                                </div>
                            </>
                        )}

                        {/* COUPONS */}
                        {type === 'coupons' && (
                            <>
                                <div>
                                    <label className="block text-sm font-medium text-textMain mb-1">Coupon Code</label>
                                    <input type="text" {...register('code', { required: true })} className="form-input uppercase font-mono" placeholder="WELCOME10" />
                                </div>
                                <div className="flex items-center space-x-2 my-2">
                                    <input type="checkbox" id="coupon_is_percentage" {...register('is_percentage')} className="form-checkbox bg-transparent" />
                                    <label htmlFor="coupon_is_percentage" className="text-sm font-medium text-textMain select-none cursor-pointer">Is Percentage Discount?</label>
                                </div>
                                <div>
                                    <label className="block text-sm font-medium text-textMain mb-1">Discount Value</label>
                                    <input type="number" step="0.01" {...register('discount_value', { required: true })} className="form-input" placeholder={watch('is_percentage') ? "e.g. 15 (%)" : "e.g. 50 (EGP)"} />
                                </div>
                                <div className="grid grid-cols-2 gap-4 mt-4">
                                    <div>
                                        <label className="block text-sm font-medium text-textMain mb-1">Usage Limit</label>
                                        <input type="number" {...register('usage_limit')} className="form-input" placeholder="0 for unlimited" />
                                        <p className="text-xs text-textMuted mt-1">Leave 0 for unlimited uses</p>
                                    </div>
                                    <div>
                                        <label className="block text-sm font-medium text-textMain mb-1">Expiry Date</label>
                                        <input type="datetime-local" {...register('expiry_date')} className="form-input" />
                                    </div>
                                </div>
                            </>
                        )}

                        {/* COMMON ACTIVE TOGGLE */}
                        <div className="pt-4 border-t border-slate-200 dark:border-white/10 mt-4">
                            <div className="flex items-center space-x-2">
                                <input type="checkbox" id="is_active" {...register('is_active')} className="form-checkbox w-5 h-5 text-primary rounded border-slate-300 dark:border-white/20 bg-transparent focus:ring-primary focus:ring-offset-background" />
                                <label htmlFor="is_active" className="text-sm font-medium text-textMain select-none cursor-pointer">Active / Enabled</label>
                            </div>
                        </div>
                    </form>
                </div>

                <div className="p-6 border-t border-slate-200 dark:border-white/10 bg-slate-50 dark:bg-white/5 rounded-b-2xl flex justify-end gap-3">
                    <button type="button" onClick={onClose} className="px-4 py-2 text-sm font-medium text-textMain hover:bg-slate-200 dark:hover:bg-white/10 rounded-lg transition-colors">
                        Cancel
                    </button>
                    <button type="submit" form="promoForm" disabled={isSubmitting} className="px-4 py-2 text-sm font-medium text-white bg-primary hover:bg-primary/90 rounded-lg disabled:opacity-50 transition-colors flex items-center">
                        {isSubmitting ? (
                            <><div className="w-4 h-4 border-2 border-white/20 border-t-white rounded-full animate-spin mr-2"></div> Saving...</>
                        ) : 'Save Details'}
                    </button>
                </div>
            </div>
        </div>
    );
};

export default PromotionModal;

import React, { useState, useEffect } from 'react';
import PageHeader from '../../components/PageHeader';
import { FiGift, FiPercent, FiStar, FiTag, FiPlus, FiEdit, FiTrash2 } from 'react-icons/fi';
import toast from 'react-hot-toast';
import { promotionsApi } from '../../api/promotionsApi';
import DataTable from '../../components/DataTable';
import PromotionModal from './PromotionModal';

const PromotionsDashboard = () => {
    const [activeTab, setActiveTab] = useState('loyalty'); // loyalty, rewards, campaigns, coupons
    const [data, setData] = useState([]);
    const [isLoading, setIsLoading] = useState(true);
    
    // Modal state
    const [isModalOpen, setIsModalOpen] = useState(false);
    const [editingItem, setEditingItem] = useState(null);

    useEffect(() => {
        fetchData();
    }, [activeTab]);

    const fetchData = async () => {
        setIsLoading(true);
        try {
            let res;
            if (activeTab === 'loyalty') res = await promotionsApi.getLoyaltyRules();
            else if (activeTab === 'rewards') res = await promotionsApi.getRewards();
            else if (activeTab === 'campaigns') res = await promotionsApi.getCampaigns();
            else res = await promotionsApi.getCoupons();
            setData(res.data);
        } catch (error) {
            toast.error(`Failed to load ${activeTab}`);
        } finally {
            setIsLoading(false);
        }
    };

    const handleDelete = async (id) => {
        if (!window.confirm("Are you sure?")) return;
        try {
            if (activeTab === 'loyalty') await promotionsApi.deleteLoyaltyRule(id);
            else if (activeTab === 'rewards') await promotionsApi.deleteReward(id);
            else if (activeTab === 'campaigns') await promotionsApi.deleteCampaign(id);
            else await promotionsApi.deleteCoupon(id);
            toast.success('Successfully deleted');
            fetchData();
        } catch (err) {
            toast.error('Failed to delete item');
        }
    };

    const handleCreate = () => {
        setEditingItem(null);
        setIsModalOpen(true);
    };

    const handleEdit = (item) => {
        setEditingItem(item);
        setIsModalOpen(true);
    };

    const handleModalSubmit = async (formData) => {
        try {
            if (editingItem) {
                if (activeTab === 'loyalty') await promotionsApi.updateLoyaltyRule(editingItem.id, formData);
                else if (activeTab === 'rewards') await promotionsApi.updateReward(editingItem.id, formData);
                else if (activeTab === 'campaigns') await promotionsApi.updateCampaign(editingItem.id, formData);
                else await promotionsApi.updateCoupon(editingItem.id, formData);
                toast.success('Successfully updated');
            } else {
                if (activeTab === 'loyalty') await promotionsApi.createLoyaltyRule(formData);
                else if (activeTab === 'rewards') await promotionsApi.createReward(formData);
                else if (activeTab === 'campaigns') await promotionsApi.createCampaign(formData);
                else await promotionsApi.createCoupon(formData);
                toast.success('Successfully created');
            }
            setIsModalOpen(false);
            fetchData();
        } catch (error) {
            toast.error(error.response?.data?.detail || error.response?.data?.error || 'Failed to save details');
        }
    };

    const getColumns = () => {
        const actionCol = {
            header: "Actions",
            id: "actions",
            cell: ({ row }) => (
                <div className="flex justify-end gap-2">
                    <button 
                        onClick={() => handleEdit(row.original)}
                        className="p-1.5 text-blue-600 hover:bg-blue-50 rounded-lg transition-colors"
                    >
                        <FiEdit className="w-4 h-4" />
                    </button>
                    <button 
                        onClick={() => handleDelete(row.original.id)}
                        className="p-1.5 text-red-600 hover:bg-red-50 rounded-lg transition-colors"
                    >
                        <FiTrash2 className="w-4 h-4" />
                    </button>
                </div>
            )
        };

        if (activeTab === 'loyalty') {
            return [
                { header: "Rule Name", accessorKey: "name" },
                { header: "Spend Req.", accessorFn: (r) => `${r.spend_amount} EGP` },
                { header: "Points Earned", accessorFn: (r) => `${r.points_earned} pts` },
                { 
                    header: "Status", 
                    id: "status",
                    cell: ({ row }) => {
                        const r = row.original;
                        return (
                            <span className={`px-2 py-1 rounded-full text-xs font-semibold ${r.is_active ? 'bg-green-100 text-green-700' : 'bg-slate-100 text-textMain'}`}>
                                {r.is_active ? 'Active' : 'Inactive'}
                            </span>
                        );
                    }
                },
                actionCol
            ];
        }

        if (activeTab === 'rewards') {
            return [
                { header: "Reward Name", accessorKey: "name" },
                { header: "Points Cost", accessorFn: (r) => `${r.points_cost} pts` },
                { header: "Discount Value", accessorFn: (r) => r.is_percentage ? `${r.discount_value}%` : `${r.discount_value} EGP` },
                { 
                    header: "Status", 
                    id: "status",
                    cell: ({ row }) => {
                        const r = row.original;
                        return (
                            <span className={`px-2 py-1 rounded-full text-xs font-semibold ${r.is_active ? 'bg-green-100 text-green-700' : 'bg-slate-100 text-textMain'}`}>
                                {r.is_active ? 'Active' : 'Inactive'}
                            </span>
                        );
                    }
                },
                actionCol
            ];
        }

        // Add Campaign and Coupon columns similarly if needed...
        return [{ header: "Name/Code", accessorFn: (r) => r.name || r.code }, actionCol]; 
    };

    const tabs = [
        { id: 'loyalty', label: 'Loyalty Engine', icon: FiStar, description: 'Earning rules' },
        { id: 'rewards', label: 'Rewards Menu', icon: FiGift, description: 'Burning rules' },
        { id: 'campaigns', label: 'Campaigns', icon: FiPercent, description: 'Happy hour etc.' },
        { id: 'coupons', label: 'Promo Codes', icon: FiTag, description: 'Vouchers' }
    ];

    return (
        <div className="space-y-6">
            <PageHeader 
                title="Promotions Engine"
                subtitle="Configure how customers earn points, redeem rewards, and use discounts"
                icon={FiGift}
                action={{
                    label: `New ${tabs.find(t => t.id === activeTab)?.label.split(' ')[0] || 'Item'}`,
                    icon: FiPlus,
                    onClick: handleCreate
                }}
            />

            {/* Navigation Tabs */}
            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4 mb-6">
                {tabs.map(tab => (
                    <button
                        key={tab.id}
                        onClick={() => setActiveTab(tab.id)}
                        className={`
                            flex flex-col items-start p-4 rounded-xl border transition-all duration-200 text-left
                            ${activeTab === tab.id 
                                ? 'bg-primary/10 border-primary/30 shadow-sm ring-1 ring-primary/20' 
                                : 'glass-panel hover:border-slate-200 dark:border-white/10'
                            }
                        `}
                    >
                        <div className="flex items-center gap-3 mb-2">
                            <div className={`p-2 rounded-lg ${activeTab === tab.id ? 'bg-primary/20 text-primary' : 'bg-surface text-textMuted'}`}>
                                <tab.icon className="w-5 h-5" />
                            </div>
                            <span className={`font-semibold ${activeTab === tab.id ? 'text-primary' : 'text-textMain'}`}>
                                {tab.label}
                            </span>
                        </div>
                        <span className="text-xs text-textMuted px-1">{tab.description}</span>
                    </button>
                ))}
            </div>

            {/* Data Grid */}
            <div className="glass-panel overflow-hidden">
                <DataTable 
                    columns={getColumns()}
                    data={data}
                    isLoading={isLoading}
                    emptyMessage={`No ${activeTab} configured yet.`}
                />
            </div>

            <PromotionModal 
                isOpen={isModalOpen}
                onClose={() => setIsModalOpen(false)}
                onSubmit={handleModalSubmit}
                type={activeTab}
                initialData={editingItem}
            />
        </div>
    );
};

export default PromotionsDashboard;

import React, { useState, useEffect, useMemo } from 'react';
import { useForm, useFieldArray } from 'react-hook-form';
import { yupResolver } from '@hookform/resolvers/yup';
import * as yup from 'yup';
import toast from 'react-hot-toast';
import { FiPlus, FiTrash2, FiEye, FiCheckCircle, FiTruck } from 'react-icons/fi';
import DataTable from '../../components/DataTable';
import ConfirmModal from '../../components/ConfirmModal';
import { purchasingApi } from '../../api/purchasingApi';
import useSettingsStore from '../../store/settingsStore';

const grnSchema = yup.object().shape({
  purchase_order: yup.string().nullable(),
  supplier: yup.string().required('Supplier is required'),
  notes: yup.string(),
  items: yup.array().of(
    yup.object().shape({
      raw_material: yup.string().required('Material is required'),
      quantity_ordered: yup.number().min(0, 'Must be >= 0'),
      quantity_received: yup.number().min(0.01, 'Quantity must be > 0').required('Required'),
      unit_price: yup.number().min(0, 'Price must be >= 0').required('Required'),
      expiry_date: yup.string().nullable()
    })
  ).min(1, 'At least one item is required')
});

const GoodsReceivedNotes = () => {
    const [grns, setGrns] = useState([]);
    const [suppliers, setSuppliers] = useState([]);
    const [purchaseOrders, setPurchaseOrders] = useState([]);
    const [materials, setMaterials] = useState([]);
    const [isLoading, setIsLoading] = useState(true);
    
    // Modals
    const [isCreateModalOpen, setIsCreateModalOpen] = useState(false);
    const [viewGrn, setViewGrn] = useState(null);
    const [confirmAction, setConfirmAction] = useState({ open: false, grn: null, type: null });

    const { settings } = useSettingsStore();

    const { register, control, handleSubmit, reset, watch, setValue, formState: { errors } } = useForm({
        resolver: yupResolver(grnSchema),
        defaultValues: {
            items: [{ raw_material: '', quantity_ordered: 0, quantity_received: 1, unit_price: 0, expiry_date: '' }]
        }
    });

    const { fields, append, remove, replace } = useFieldArray({
        control,
        name: "items"
    });

    const watchedItems = watch("items") || [];
    const watchedSupplier = watch("supplier");
    const watchedPO = watch("purchase_order");

    const fetchData = async () => {
        setIsLoading(true);
        try {
            // Lazy loading related items, but for now fetch all necessary dropdowns
            // In a real huge app, we'd paginate the dropdowns or use async selects
            const [grnRes, supRes, poRes, matRes] = await Promise.all([
                purchasingApi.getGRNs(),
                purchasingApi.getSuppliers(),
                purchasingApi.getOrders(),
                purchasingApi.getGRNs().then(() => {
                    // Dirty hack since inventoryApi is in another file, let's just fetch it here via full path
                    return import('../../api/inventoryApi').then(({ inventoryApi }) => inventoryApi.getMaterials());
                })
            ]);
            setGrns(grnRes.data);
            setSuppliers(supRes.data);
            
            // Only confirmed or partially received POs can be received
            const receivablePOs = poRes.data.filter(po => ['confirmed', 'partially_received'].includes(po.status));
            setPurchaseOrders(receivablePOs);
            setMaterials(matRes.data);
            
        } catch (error) {
            toast.error('Failed to load data');
        } finally {
            setIsLoading(false);
        }
    };

    useEffect(() => {
        fetchData();
    }, []);

    // Effect to auto-populate items when a PO is selected
    useEffect(() => {
        if (watchedPO) {
            const po = purchaseOrders.find(p => p.id === watchedPO);
            if (po) {
                setValue('supplier', po.supplier);
                // Pre-fill items with remaining quantities
                const grnItems = po.items.map(item => ({
                    raw_material: item.raw_material,
                    quantity_ordered: item.quantity_ordered,
                    quantity_received: Math.max(0, item.quantity_ordered - item.quantity_received), // Suggest remaining
                    unit_price: item.unit_price,
                    expiry_date: ''
                })).filter(item => item.quantity_received > 0);
                
                if (grnItems.length > 0) {
                    replace(grnItems);
                } else {
                    replace([{ raw_material: '', quantity_ordered: 0, quantity_received: 1, unit_price: 0, expiry_date: '' }]);
                    toast('This PO has already been fully received.', { icon: 'ℹ️' });
                }
            }
        }
    }, [watchedPO]);

    const onSubmit = async (data) => {
        try {
            // Data formatting
            const formattedData = {
                ...data,
                purchase_order: data.purchase_order || null,
                items: data.items.map(item => ({
                    ...item,
                    expiry_date: item.expiry_date || null
                }))
            };
            
            await purchasingApi.createGRN(formattedData);
            toast.success('Goods Received Note recorded successfully');
            setIsCreateModalOpen(false);
            fetchData();
        } catch (error) {
             toast.error(error.response?.data?.error || 'Failed to create GRN');
        }
    };

    const handleConfirmAction = async () => {
        try {
            if (confirmAction.type === 'complete') {
                 await purchasingApi.completeGRN(confirmAction.grn.id);
                 toast.success('GRN Completed! Stock has been updated and Invoice generated.');
            }
            setConfirmAction({ open: false, grn: null, type: null });
            setViewGrn(null);
            fetchData();
        } catch (e) {
            toast.error(e.response?.data?.error || `Failed to complete GRN`);
            setConfirmAction({ open: false, grn: null, type: null });
        }
    };

    const columns = useMemo(() => [
        {
            header: 'GRN Number',
            accessorKey: 'grn_number',
            cell: info => <span className="font-semibold text-primary">{info.getValue()}</span>
        },
        {
            header: 'Supplier',
            accessorKey: 'supplier_name',
        },
        {
            header: 'PO Ref',
            accessorFn: row => {
                 if (row.purchase_order && purchaseOrders.length > 0) {
                     const po = purchaseOrders.find(p => p.id === row.purchase_order) || { po_number: 'Unknown' };
                     // Handle lazy load or missing PO in list (if it was fully received previously)
                     return po.po_number || 'Linked';
                 }
                 return 'Direct (No PO)';
            },
        },
        {
            header: 'Date',
            accessorFn: row => new Date(row.received_date).toLocaleDateString(),
        },
        {
            header: 'Status',
            accessorKey: 'status',
            cell: info => {
                const status = info.getValue();
                const colors = {
                    'draft': 'bg-yellow-500/20 text-yellow-400',
                    'completed': 'bg-green-500/20 text-green-400',
                };
                return (
                    <span className={`px-2 py-1 rounded-full text-xs font-medium uppercase tracking-wider ${colors[status] || colors.draft}`}>
                        {status.replace('_', ' ')}
                    </span>
                )
            }
        },
        {
            header: 'Actions',
            id: 'actions',
            cell: info => (
                <button 
                    onClick={(e) => { e.stopPropagation(); setViewGrn(info.row.original); }}
                    className="p-1.5 bg-white/5 text-white rounded hover:bg-white/10 transition-colors"
                >
                    <FiEye className="w-4 h-4" />
                </button>
            )
        }
    ], [purchaseOrders, settings]);

    return (
        <div className="p-6">
            <div className="flex justify-between items-center mb-6">
                <h1 className="text-2xl font-bold text-white">Goods Received Notes (GRN)</h1>
                <button 
                    onClick={() => {
                        reset({ items: [{ raw_material: '', quantity_ordered: 0, quantity_received: 1, unit_price: 0, expiry_date: '' }] });
                        setIsCreateModalOpen(true);
                    }}
                    className="bg-primary hover:bg-primary/90 text-white px-4 py-2 rounded-lg font-medium transition-colors flex items-center space-x-2"
                >
                    <FiPlus className="w-5 h-5" />
                    <span>Receive Goods</span>
                </button>
            </div>

            <DataTable 
                columns={columns} 
                data={grns} 
                isLoading={isLoading}
                searchPlaceholder="Search GRNs..."
            />

            {/* Create GRN Modal - Redesigned */}
            {isCreateModalOpen && (
                <div className="fixed inset-0 z-50 flex items-center justify-center p-4">
                    <div className="fixed inset-0 bg-black/60 backdrop-blur-sm" onClick={() => setIsCreateModalOpen(false)}></div>
                    <div className="relative glass-panel w-full max-w-5xl h-[85vh] flex overflow-hidden rounded-2xl border border-white/10 shadow-2xl shadow-black/50">
                        {/* Sidebar */}
                        <div className="w-1/3 bg-[#0f172a] p-6 border-r border-white/5 flex flex-col relative z-10">
                            <h2 className="text-xl font-bold text-white mb-6">Record Received Goods</h2>
                            
                            <form id="grn-form" onSubmit={handleSubmit(onSubmit)} className="space-y-6 flex-1 overflow-y-auto pr-2 custom-scrollbar">
                                {/* Type Selector visually acting as Tabs */}
                                <div className="bg-background/50 p-1.5 rounded-lg flex space-x-1 mb-6 border border-white/5">
                                    <button 
                                        type="button"
                                        onClick={() => { setValue('purchase_order', ''); replace([{ raw_material: '', quantity_ordered: 0, quantity_received: 1, unit_price: 0, expiry_date: '' }]); }}
                                        className={`flex-1 py-2 text-sm font-medium rounded-md transition-all ${!watchedPO ? 'bg-primary text-white shadow' : 'text-textMuted hover:text-white'}`}
                                    >
                                        Direct Receipt
                                    </button>
                                    <button 
                                        type="button"
                                        className={`flex-1 py-2 text-sm font-medium rounded-md transition-all ${watchedPO ? 'bg-primary text-white shadow' : 'text-textMuted hover:text-white'}`}
                                        // This button just acts as a visual prompt; actual selection is below
                                    >
                                        From P.O.
                                    </button>
                                </div>

                                <div>
                                    <label className="block text-sm font-medium text-textMuted mb-2">Purchase Order (Optional)</label>
                                    <select {...register('purchase_order')} className="form-input bg-background/50 border-white/5 shadow-inner">
                                        <option value="">-- No PO (Direct Receipt) --</option>
                                        {purchaseOrders.map(po => (
                                            <option key={po.id} value={po.id}>{po.po_number} - {po.supplier_name}</option>
                                        ))}
                                    </select>
                                    {watchedPO && <p className="text-xs text-primary mt-2 flex items-center"><FiCheckCircle className="mr-1" /> Items auto-filled from PO</p>}
                                </div>

                                <div className={`transition-all duration-300 ${watchedPO ? 'opacity-50 pointer-events-none' : 'opacity-100'}`}>
                                    <label className="block text-sm font-medium text-textMuted mb-2">Supplier *</label>
                                    <select {...register('supplier')} className="form-input bg-background/50 border-white/5 shadow-inner" disabled={!!watchedPO}>
                                        <option value="">-- Choose Supplier --</option>
                                        {suppliers.filter(s => s.is_active).map(s => (
                                            <option key={s.id} value={s.id}>{s.name}</option>
                                        ))}
                                    </select>
                                    {errors.supplier && <span className="text-red-400 text-xs mt-1 block">{errors.supplier.message}</span>}
                                </div>

                                <div>
                                    <label className="block text-sm font-medium text-textMuted mb-2">Delivery Notes / Remarks</label>
                                    <textarea {...register('notes')} className="form-input bg-background/50 border-white/5 shadow-inner" rows="3" placeholder="Driver name, conditions, etc."></textarea>
                                </div>
                            </form>
                            
                            <div className="pt-6 border-t border-white/10 mt-auto">
                                <div className="flex space-x-3">
                                    <button type="button" onClick={() => setIsCreateModalOpen(false)} className="px-4 py-3 rounded-xl font-medium text-white bg-white/5 hover:bg-white/10 transition-colors w-1/3">
                                        Cancel
                                    </button>
                                    <button form="grn-form" type="submit" className="px-4 py-3 rounded-xl font-bold tracking-wide text-white bg-yellow-500 hover:bg-yellow-400 shadow-lg shadow-yellow-500/25 transition-all w-2/3 flex justify-center items-center text-gray-900">
                                        Record GRN
                                    </button>
                                </div>
                            </div>
                        </div>

                        {/* Main Content */}
                        <div className="w-2/3 bg-[#16213e] flex flex-col relative z-0">
                            <div className="absolute top-0 right-0 w-96 h-96 bg-yellow-500/10 rounded-full blur-[100px] pointer-events-none"></div>

                            <div className="p-6 border-b border-white/5 flex justify-between items-center bg-[#1e293b]/50 backdrop-blur-md sticky top-0 z-10">
                                <h3 className="text-lg font-bold text-white flex items-center">
                                    <FiTruck className="mr-2 text-yellow-400" /> Received Inventory
                                </h3>
                                {!watchedPO && (
                                    <button 
                                        type="button" 
                                        onClick={() => append({ raw_material: '', quantity_ordered: 0, quantity_received: 1, unit_price: 0, expiry_date: '' })}
                                        className="text-sm px-4 py-2 bg-yellow-500/10 text-yellow-400 border border-yellow-500/20 hover:bg-yellow-500/20 rounded-lg flex items-center space-x-2 transition-all font-medium"
                                    >
                                        <FiPlus /> <span>Add Item</span>
                                    </button>
                                )}
                            </div>
                            
                            <div className="flex-1 overflow-y-auto p-6 space-y-3 custom-scrollbar relative z-10">
                                <div className="grid grid-cols-12 gap-2 text-[11px] font-bold text-textMuted uppercase tracking-wider px-2 mb-2 items-center">
                                    <div className={`col-span-${watchedPO ? '3' : '4'}`}>Material</div>
                                    <div className="col-span-2 text-center">Cost</div>
                                    {watchedPO && <div className="col-span-2 text-center">Ordered</div>}
                                    <div className={`col-span-${watchedPO ? '2' : '3'} text-center`}>Received *</div>
                                    <div className="col-span-2 text-center">Expiry</div>
                                    <div className="col-span-1 text-center">Del</div>
                                </div>
                                
                                {fields.length === 0 && (
                                    <div className="text-center py-12 opacity-50">
                                        <p className="text-white border border-dashed border-white/20 p-8 rounded-xl bg-white/5 inline-block">No items to receive.</p>
                                    </div>
                                )}

                                {fields.map((field, index) => {
                                    const qtyOrdered = parseFloat(watchedItems[index]?.quantity_ordered) || 0;
                                    const qtyReceived = parseFloat(watchedItems[index]?.quantity_received) || 0;
                                    
                                    // Highlight if they receive more or less than ordered (only relevant for POs)
                                    const isDiscrepancy = watchedPO && qtyReceived !== qtyOrdered;

                                    return (
                                        <div key={field.id} className={`grid grid-cols-12 gap-2 items-center bg-white/5 hover:bg-white/10 border ${isDiscrepancy ? 'border-yellow-500/30 bg-yellow-500/5' : 'border-white/5'} p-2 rounded-xl transition-colors relative`}>
                                            <div className={`col-span-${watchedPO ? '3' : '4'}`}>
                                                <select {...register(`items.${index}.raw_material`)} className="w-full bg-black/20 border border-white/10 rounded-lg px-2 py-2 text-sm text-white focus:outline-none focus:border-primary transition-colors appearance-none scrollbar-thin" disabled={!!watchedPO}>
                                                    <option value="" className="bg-[#0f172a]">Material...</option>
                                                    {materials.filter(m => m.is_active || m.id === watchedItems[index]?.raw_material).map(m => (
                                                        <option key={m.id} value={m.id} className="bg-[#0f172a]">{m.name}</option>
                                                    ))}
                                                </select>
                                                {isDiscrepancy && <span className="absolute -top-2 left-4 text-[9px] bg-yellow-500 text-gray-900 font-bold px-1.5 py-0.5 rounded shadow z-10">Discrepancy</span>}
                                            </div>
                                            
                                            <div className="col-span-2 relative flex items-center">
                                                <span className="absolute left-2 text-textMuted text-xs font-medium">{settings?.currency || '$'}</span>
                                                <input type="number" step="0.01" {...register(`items.${index}.unit_price`)} className="w-full bg-black/20 border border-white/10 rounded-lg pl-6 pr-2 py-2 text-sm text-right text-white focus:outline-none focus:border-primary transition-colors font-mono" readOnly={!!watchedPO} />
                                            </div>

                                            {watchedPO && (
                                                <div className="col-span-2">
                                                    <input type="number" readOnly={!!watchedPO} {...register(`items.${index}.quantity_ordered`)} className="w-full bg-black/20 border border-white/10 rounded-lg px-2 py-2 text-sm text-center text-textMuted focus:outline-none focus:border-primary transition-colors font-mono" />
                                                </div>
                                            )}

                                            <div className={`col-span-${watchedPO ? '2' : '3'}`}>
                                                <input type="number" step="0.001" placeholder="0" {...register(`items.${index}.quantity_received`)} className="w-full bg-black/20 border border-white/10 rounded-lg px-2 py-2 text-sm text-center text-white focus:outline-none focus:border-primary transition-colors font-mono font-bold" />
                                            </div>
                                            
                                            <div className="col-span-2">
                                                <input type="date" {...register(`items.${index}.expiry_date`)} className="w-full bg-black/20 border border-white/10 rounded-lg px-2 py-2 text-xs text-white focus:outline-none focus:border-primary transition-colors" />
                                            </div>

                                            <div className="col-span-1 flex justify-center">
                                                <button type="button" onClick={() => remove(index)} className="w-7 h-7 rounded-lg bg-red-500/10 text-red-400 hover:bg-red-500 hover:text-white flex items-center justify-center transition-colors">
                                                    <FiTrash2 className="w-4 h-4" />
                                                </button>
                                            </div>
                                        </div>
                                    )
                                })}
                                {errors.items?.root && <div className="bg-red-500/10 border border-red-500/30 text-red-400 p-3 rounded-lg text-sm">{errors.items.root.message}</div>}
                            </div>
                        </div>
                    </div>
                </div>
            )}

            {/* View GRN Modal */}
            {viewGrn && (
                <div className="fixed inset-0 z-50 flex items-center justify-center p-4">
                    <div className="fixed inset-0 bg-black/60 backdrop-blur-sm" onClick={() => setViewGrn(null)}></div>
                    <div className="relative glass-panel w-full max-w-3xl p-6">
                        <div className="flex justify-between items-start mb-6">
                            <div>
                                <h2 className="text-2xl font-bold text-white tracking-tight">{viewGrn.grn_number}</h2>
                                <p className="text-textMuted mt-1">Supplier: <span className="text-white font-medium">{viewGrn.supplier_name}</span></p>
                                <p className="text-textMuted text-sm mt-1">Received By: {viewGrn.received_by_name} on {new Date(viewGrn.received_date).toLocaleDateString()}</p>
                            </div>
                            <span className={`px-3 py-1 rounded-full uppercase tracking-wider text-xs font-bold border ${
                                viewGrn.status === 'completed' ? 'bg-green-500/20 text-green-400 border-green-500/30' : 'bg-yellow-500/20 text-yellow-400 border-yellow-500/30'
                            }`}>
                                {viewGrn.status.replace('_', ' ')}
                            </span>
                        </div>
                        
                        <div className="glass-panel p-4 mb-6">
                            <table className="w-full text-left text-sm">
                                <thead>
                                    <tr className="border-b border-white/10 text-textMuted">
                                        <th className="pb-2 font-medium">Material</th>
                                        <th className="pb-2 font-medium text-center">Received Qty</th>
                                        <th className="pb-2 font-medium text-right">Unit Price</th>
                                        <th className="pb-2 font-medium text-center">Expiry</th>
                                    </tr>
                                </thead>
                                <tbody className="divide-y divide-white/5">
                                    {viewGrn.items?.map(item => (
                                        <tr key={item.id}>
                                            <td className="py-3 text-white">{item.raw_material_name}</td>
                                            <td className="py-3 text-center font-bold text-primary">{parseFloat(item.quantity_received)}</td>
                                            <td className="py-3 text-right text-textMuted">{settings?.currency || '$'}{parseFloat(item.unit_price).toFixed(2)}</td>
                                            <td className="py-3 text-center text-textMuted">{item.expiry_date || '-'}</td>
                                        </tr>
                                    ))}
                                </tbody>
                            </table>
                        </div>

                        <div className="flex justify-between items-center pt-4 border-t border-white/10">
                            <div className="flex space-x-3">
                                {viewGrn.status === 'draft' && (
                                    <button 
                                        onClick={() => setConfirmAction({ open: true, grn: viewGrn, type: 'complete' })} 
                                        className="px-4 py-2 bg-green-500/20 text-green-400 border border-green-500/30 hover:bg-green-500/30 rounded-lg flex items-center space-x-2 transition-colors font-medium"
                                    >
                                        <FiCheckCircle /> <span>Confirm & Add To Stock</span>
                                    </button>
                                )}
                            </div>
                            <button onClick={() => setViewGrn(null)} className="px-5 py-2 bg-white/5 hover:bg-white/10 text-white rounded-lg transition-colors">
                                Close
                            </button>
                        </div>
                    </div>
                </div>
            )}
            
            <ConfirmModal 
                isOpen={confirmAction.open}
                title="Complete Goods Received Note"
                message="Are you sure you want to COMPLETE this GRN? This will permanently add the items to your Inventory Stock, update unit costs, and generate an Accounting Invoice. This action cannot be undone."
                onConfirm={handleConfirmAction}
                onCancel={() => setConfirmAction({ open: false, grn: null, type: null })}
                confirmText="Verify and Complete"
            />
        </div>
    );
};

export default GoodsReceivedNotes;

import React, { useState, useEffect, useMemo } from 'react';
import { useForm } from 'react-hook-form';
import { yupResolver } from '@hookform/resolvers/yup';
import * as yup from 'yup';
import toast from 'react-hot-toast';
import { FiDollarSign, FiEye, FiCheckCircle, FiX } from 'react-icons/fi';
import ConfirmModal from '../../components/ConfirmModal';
import DataTable from '../../components/DataTable';
import { purchasingApi } from '../../api/purchasingApi';
import useSettingsStore from '../../store/settingsStore';

const paymentSchema = yup.object().shape({
    amount_paid: yup.number().min(0.01, 'Must be > 0').required('Required'),
    payment_method: yup.string().required('Required'),
    reference: yup.string(),
    notes: yup.string()
});

const Invoices = () => {
    const [invoices, setInvoices] = useState([]);
    const [isLoading, setIsLoading] = useState(true);
    
    // Modals
    const [viewInvoice, setViewInvoice] = useState(null);
    const [isPaymentModalOpen, setIsPaymentModalOpen] = useState(false);
    const [invoiceToPay, setInvoiceToPay] = useState(null);

    const { settings } = useSettingsStore();

    const { register, handleSubmit, reset, setValue, formState: { errors, isSubmitting } } = useForm({
        resolver: yupResolver(paymentSchema)
    });

    const fetchData = async () => {
        setIsLoading(true);
        try {
            const res = await purchasingApi.getInvoices();
            setInvoices(res.data);
        } catch (error) {
            toast.error('Failed to load invoices');
        } finally {
            setIsLoading(false);
        }
    };

    useEffect(() => {
        fetchData();
    }, []);

    const openPaymentModal = (invoice) => {
        setInvoiceToPay(invoice);
        // Pre-fill with remaining amount
        const remaining = parseFloat(invoice.total_amount) - parseFloat(invoice.paid_amount || 0);
        reset({
            amount_paid: remaining,
            payment_method: 'bank_transfer',
            reference: '',
            notes: ''
        });
        setIsPaymentModalOpen(true);
    };

    const onPaymentSubmit = async (data) => {
        try {
            await purchasingApi.payInvoice(invoiceToPay.id, data);
            toast.success('Payment recorded successfully!');
            setIsPaymentModalOpen(false);
            fetchData();
        } catch (error) {
            toast.error(error.response?.data?.error || 'Failed to record payment');
        }
    };

    const columns = useMemo(() => [
        {
            header: 'Invoice #',
            accessorKey: 'invoice_number',
            cell: info => <span className="font-semibold text-primary">{info.getValue()}</span>
        },
        {
            header: 'Supplier',
            accessorKey: 'supplier_name',
        },
        {
            header: 'Generated Date',
            accessorFn: row => new Date(row.invoice_date).toLocaleDateString(),
        },
        {
            header: 'Total Amount',
            accessorFn: row => `${settings?.currency || '$'}${parseFloat(row.total_amount).toFixed(2)}`,
            cell: info => <span className="font-mono">{info.getValue()}</span>
        },
        {
            header: 'Balance Due',
            accessorFn: row => `${settings?.currency || '$'}${(parseFloat(row.total_amount) - parseFloat(row.paid_amount || 0)).toFixed(2)}`,
            cell: info => {
                // Must extract just the number to evaluate if balance is zero
                const balanceStr = info.getValue().replace(settings?.currency || '$', '');
                const balance = parseFloat(balanceStr);
                return <span className={`font-mono font-bold ${balance <= 0 ? 'text-green-400' : 'text-red-400'}`}>{info.getValue()}</span>
            }
        },
        {
            header: 'Status',
            accessorKey: 'status',
            cell: info => {
                const status = info.getValue();
                const colors = {
                    'pending': 'bg-red-500/20 text-red-400',
                    'partially_paid': 'bg-yellow-500/20 text-yellow-400',
                    'paid': 'bg-green-500/20 text-green-400'
                };
                return (
                    <span className={`px-2 py-1 rounded-full text-xs font-medium uppercase tracking-wider ${colors[status] || colors.pending}`}>
                        {status.replace('_', ' ')}
                    </span>
                )
            }
        },
        {
            header: 'Actions',
            id: 'actions',
            cell: info => (
                <div className="flex space-x-2">
                    <button 
                        onClick={(e) => { e.stopPropagation(); setViewInvoice(info.row.original); }}
                        className="p-1.5 bg-white/5 text-white rounded hover:bg-white/10 transition-colors"
                        title="View Details"
                    >
                        <FiEye className="w-4 h-4" />
                    </button>
                    {info.row.original.status !== 'paid' && (
                        <button 
                            onClick={(e) => { e.stopPropagation(); openPaymentModal(info.row.original); }}
                            className="p-1.5 bg-green-500/20 text-green-400 rounded hover:bg-green-500/30 transition-colors"
                            title="Record Payment"
                        >
                            <FiDollarSign className="w-4 h-4" />
                        </button>
                    )}
                </div>
            )
        }
    ], [settings]);

    return (
        <div className="p-6">
            <div className="flex justify-between items-center mb-6">
                <div>
                    <h1 className="text-2xl font-bold text-white">Supplier Invoices</h1>
                    <p className="text-textMuted text-sm">Automatically generated from completed GRNs</p>
                </div>
            </div>

            <DataTable 
                columns={columns} 
                data={invoices} 
                isLoading={isLoading}
                searchPlaceholder="Search invoices..."
            />

            {/* Pay Invoice Modal */}
            {isPaymentModalOpen && invoiceToPay && (
                <div className="fixed inset-0 z-50 flex items-center justify-center p-4">
                    <div className="fixed inset-0 bg-black/60 backdrop-blur-sm transition-opacity" onClick={() => setIsPaymentModalOpen(false)}></div>
                    <div className="relative glass-panel w-full max-w-lg overflow-hidden transform transition-all shadow-2xl shadow-green-500/10">
                        {/* Decorative Header Background */}
                        <div className="absolute top-0 right-0 w-64 h-64 bg-green-500/20 rounded-full blur-[80px] pointer-events-none -translate-y-1/2 translate-x-1/3"></div>
                        
                        <div className="p-8 relative z-10">
                            <div className="flex justify-between items-start mb-6">
                                <div>
                                    <h2 className="text-2xl font-black text-white tracking-tight flex items-center">
                                        <FiDollarSign className="text-green-400 mr-2" /> Record Payment
                                    </h2>
                                    <p className="text-textMuted mt-1">
                                        Paying Invoice: <span className="text-white font-mono bg-white/5 py-0.5 px-2 rounded ml-1">{invoiceToPay.invoice_number}</span>
                                    </p>
                                </div>
                                <button onClick={() => setIsPaymentModalOpen(false)} className="p-2 text-textMuted hover:text-white bg-white/5 hover:bg-white/10 rounded-xl transition-colors">
                                    <FiX className="w-5 h-5" />
                                </button>
                            </div>

                            <div className="bg-[#0f172a]/80 border border-white/5 rounded-2xl p-4 mb-6 flex justify-between items-center shadow-inner">
                                <div>
                                    <p className="text-textMuted text-xs font-medium uppercase tracking-wider mb-1">Current Balance Due</p>
                                    <p className="text-2xl font-mono font-bold text-red-400">
                                        {settings?.currency || '$'}{(parseFloat(invoiceToPay.total_amount) - parseFloat(invoiceToPay.paid_amount || 0)).toFixed(2)}
                                    </p>
                                </div>
                                <div className="text-right">
                                    <p className="text-textMuted text-xs font-medium uppercase tracking-wider mb-1">Total Invoice</p>
                                    <p className="text-white font-mono">{settings?.currency || '$'}{parseFloat(invoiceToPay.total_amount).toFixed(2)}</p>
                                </div>
                            </div>
                            
                            <form onSubmit={handleSubmit(onPaymentSubmit)} className="space-y-5">
                                <div>
                                    <label className="block text-sm font-semibold text-white/90 mb-2">Payment Amount ({settings?.currency || '$'}) *</label>
                                    <div className="relative">
                                        <span className="absolute left-4 top-1/2 -translate-y-1/2 text-green-400 font-bold">{settings?.currency || '$'}</span>
                                        <input type="number" step="0.01" {...register('amount_paid')} className="w-full bg-[#0f172a] border-2 border-green-500/30 text-white rounded-xl py-3 pl-16 pr-4 focus:ring-2 focus:ring-green-500/50 focus:border-green-500 text-xl font-mono font-bold transition-all shadow-inner" />
                                    </div>
                                    {errors.amount_paid && <span className="text-red-400 text-xs mt-1 block">{errors.amount_paid.message}</span>}
                                </div>
                                
                                <div className="grid grid-cols-2 gap-4">
                                    <div>
                                        <label className="block text-sm font-semibold text-white/90 mb-2">Payment Method</label>
                                        <select {...register('payment_method')} className="w-full bg-[#0f172a] border border-white/10 text-white rounded-xl py-3 px-4 focus:ring-2 focus:ring-primary focus:border-primary transition-all">
                                            <option value="cash">Cash</option>
                                            <option value="bank_transfer">Bank Transfer</option>
                                            <option value="instapay">InstaPay</option>
                                            <option value="check">Check</option>
                                        </select>
                                    </div>
                                    <div>
                                        <label className="block text-sm font-semibold text-white/90 mb-2">Transaction Ref</label>
                                        <input {...register('reference')} placeholder="e.g. TR-99381" className="w-full bg-[#0f172a] border border-white/10 text-white rounded-xl py-3 px-4 focus:ring-2 focus:ring-primary focus:border-primary transition-all placeholder:text-gray-600" />
                                    </div>
                                </div>

                                <div>
                                    <label className="block text-sm font-semibold text-white/90 mb-2">Internal Notes</label>
                                    <textarea {...register('notes')} placeholder="Optional notes about this payment..." className="w-full bg-[#0f172a] border border-white/10 text-white rounded-xl py-3 px-4 focus:ring-2 focus:ring-primary focus:border-primary transition-all resize-none placeholder:text-gray-600" rows="2"></textarea>
                                </div>

                                <div className="flex justify-end space-x-3 pt-6 mt-4">
                                    <button type="button" onClick={() => setIsPaymentModalOpen(false)} className="px-5 py-3 rounded-xl font-medium text-white bg-white/5 hover:bg-white/10 transition-colors w-1/3">
                                        Cancel
                                    </button>
                                    <button type="submit" disabled={isSubmitting} className="w-2/3 px-5 py-3 rounded-xl font-bold tracking-wide text-gray-900 bg-green-500 hover:bg-green-400 shadow-[0_0_20px_rgba(34,197,94,0.3)] transition-all flex justify-center items-center disabled:opacity-50 disabled:cursor-not-allowed">
                                        {isSubmitting ? 'Processing...' : 'Confirm Payment'}
                                    </button>
                                </div>
                            </form>
                        </div>
                    </div>
                </div>
            )}

            {/* View Invoice Modal - Redesigned */}
            {viewInvoice && (
                <div className="fixed inset-0 z-40 flex items-center justify-center p-4">
                    <div className="fixed inset-0 bg-black/60 backdrop-blur-sm" onClick={() => setViewInvoice(null)}></div>
                    <div className="relative glass-panel w-full max-w-4xl max-h-[90vh] flex flex-col overflow-hidden rounded-2xl border border-white/10 shadow-2xl shadow-black/50">
                        
                        {/* Header */}
                        <div className="p-6 border-b border-white/10 bg-[#0f172a] relative overflow-hidden">
                            <div className={`absolute top-0 right-0 w-64 h-64 rounded-full blur-[80px] opacity-20 pointer-events-none ${viewInvoice.status === 'paid' ? 'bg-green-500' : viewInvoice.status === 'partially_paid' ? 'bg-yellow-500' : 'bg-red-500'}`}></div>
                            
                            <div className="relative z-10 flex justify-between items-start">
                                <div>
                                    <div className="flex items-center space-x-3 mb-2">
                                        <h2 className="text-3xl font-black text-white tracking-tight">{viewInvoice.invoice_number}</h2>
                                        <span className={`px-3 py-1 rounded-md text-xs font-black uppercase tracking-widest ${
                                            viewInvoice.status === 'paid' ? 'bg-green-500 text-gray-900 shadow-[0_0_15px_rgba(34,197,94,0.3)]' : 
                                            viewInvoice.status === 'partially_paid' ? 'bg-yellow-500 text-gray-900 shadow-[0_0_15px_rgba(234,179,8,0.3)]' : 
                                            'bg-red-500 text-white shadow-[0_0_15px_rgba(239,68,68,0.3)]'
                                        }`}>
                                            {viewInvoice.status.replace('_', ' ')}
                                        </span>
                                    </div>
                                    <p className="text-textMuted flex items-center">
                                        Supplier: <span className="text-white font-bold ml-2">{viewInvoice.supplier_name}</span>
                                    </p>
                                </div>
                                <button onClick={() => setViewInvoice(null)} className="text-textMuted hover:text-white transition-colors bg-white/5 p-2 rounded-lg">
                                    <FiX className="w-5 h-5" />
                                </button>
                            </div>
                        </div>
                        
                        {/* Body */}
                        <div className="p-6 flex-1 overflow-y-auto bg-[#16213e] custom-scrollbar">
                            
                            {/* Financial Summary */}
                            <div className="grid grid-cols-3 gap-4 mb-8">
                                <div className="bg-[#1e293b]/80 p-5 rounded-2xl border border-white/5 flex flex-col justify-center">
                                    <p className="text-sm text-textMuted font-medium mb-1">Total Billed</p>
                                    <p className="text-3xl font-mono text-white tracking-tight">{settings?.currency || '$'}{parseFloat(viewInvoice.total_amount).toFixed(2)}</p>
                                </div>
                                <div className="bg-[#1e293b]/80 p-5 rounded-2xl border border-white/5 flex flex-col justify-center">
                                    <p className="text-sm text-textMuted font-medium mb-1">Amount Paid</p>
                                    <p className="text-3xl font-mono text-green-400 tracking-tight">{settings?.currency || '$'}{parseFloat(viewInvoice.paid_amount || 0).toFixed(2)}</p>
                                </div>
                                <div className={`p-5 rounded-2xl border flex flex-col justify-center ${viewInvoice.status === 'paid' ? 'bg-green-500/10 border-green-500/20' : 'bg-red-500/10 border-red-500/30 shadow-[inset_0_0_20px_rgba(239,68,68,0.1)]'}`}>
                                    <p className={`text-sm font-medium mb-1 ${viewInvoice.status === 'paid' ? 'text-green-400' : 'text-red-400'}`}>Balance Remaining</p>
                                    <p className={`text-3xl font-mono font-black tracking-tight ${viewInvoice.status === 'paid' ? 'text-green-400' : 'text-red-400'}`}>
                                        {settings?.currency || '$'}{(parseFloat(viewInvoice.total_amount) - parseFloat(viewInvoice.paid_amount || 0)).toFixed(2)}
                                    </p>
                                </div>
                            </div>
                            
                            {/* Action Row */}
                            {viewInvoice.status !== 'paid' && (
                                <div className="mb-8 flex justify-end">
                                    <button 
                                        onClick={() => {
                                            setViewInvoice(null);
                                            setInvoiceToPay(viewInvoice);
                                            setIsPaymentModalOpen(true);
                                        }}
                                        className="bg-green-500 hover:bg-green-400 text-gray-900 px-6 py-3 rounded-xl font-bold transition-all shadow-lg shadow-green-500/25 flex items-center space-x-2"
                                    >
                                        <FiDollarSign className="w-5 h-5" />
                                        <span>Record New Payment</span>
                                    </button>
                                </div>
                            )}

                            {/* Payment Timeline */}
                            <div>
                                <h3 className="text-lg font-bold text-white mb-4 flex items-center">
                                    <FiCheckCircle className="mr-2 text-primary" /> Payment History Timeline
                                </h3>
                                
                                {viewInvoice.payments?.length > 0 ? (
                                    <div className="space-y-4 relative before:absolute before:inset-0 before:ml-5 before:-translate-x-px md:before:mx-auto md:before:translate-x-0 before:h-full before:w-0.5 before:bg-gradient-to-b before:from-transparent before:via-white/10 before:to-transparent">
                                        {viewInvoice.payments.map((payment, idx) => (
                                            <div key={payment.id} className="relative flex items-center justify-between md:justify-normal md:odd:flex-row-reverse group is-active">
                                                {/* Timeline dot */}
                                                <div className="flex items-center justify-center w-10 h-10 rounded-full border border-white/20 bg-[#1e293b] text-primary shadow shrink-0 md:order-1 md:group-odd:-translate-x-1/2 md:group-even:translate-x-1/2 z-10">
                                                    <FiDollarSign className="w-4 h-4" />
                                                </div>
                                                
                                                {/* Card */}
                                                <div className="w-[calc(100%-4rem)] md:w-[calc(50%-2.5rem)] glass-panel p-4 rounded-xl border border-white/5 hover:border-primary/30 transition-colors">
                                                    <div className="flex justify-between items-start mb-1">
                                                        <span className="text-white font-bold text-lg font-mono tracking-tight">+{settings?.currency || '$'}{parseFloat(payment.amount).toFixed(2)}</span>
                                                        <span className="text-[10px] font-bold text-textMuted bg-white/5 px-2 py-1 rounded uppercase tracking-wider border border-white/5">{payment.payment_method.replace('_', ' ')}</span>
                                                    </div>
                                                    <p className="text-xs text-textMuted mb-2">{new Date(payment.payment_date).toLocaleString()}</p>
                                                    
                                                    {(payment.reference || payment.notes) && (
                                                        <div className="text-xs border-t border-white/5 pt-2 mt-2">
                                                            {payment.reference && <p><span className="text-textMuted">Ref:</span> <span className="text-white font-mono">{payment.reference}</span></p>}
                                                            {payment.notes && <p className="text-textMuted italic mt-1">{payment.notes}</p>}
                                                        </div>
                                                    )}
                                                </div>
                                            </div>
                                        ))}
                                    </div>
                                ) : (
                                    <div className="text-center py-12 bg-white/5 border border-dashed border-white/10 rounded-xl">
                                        <p className="text-textMuted">No payments recorded yet.</p>
                                    </div>
                                )}
                            </div>
                        </div>

                    </div>
                </div>
            )}
        </div>
    );
};

export default Invoices;

import React, { useState, useEffect, useMemo } from 'react';
import { useForm, useFieldArray } from 'react-hook-form';
import { yupResolver } from '@hookform/resolvers/yup';
import * as yup from 'yup';
import toast from 'react-hot-toast';
import { FiPlus, FiTrash2, FiEye, FiCheckCircle, FiXCircle, FiShoppingCart, FiAlertCircle } from 'react-icons/fi';
import DataTable from '../../components/DataTable';
import ConfirmModal from '../../components/ConfirmModal';
import { purchasingApi } from '../../api/purchasingApi';
import { inventoryApi } from '../../api/inventoryApi';
import useSettingsStore from '../../store/settingsStore';

const orderSchema = yup.object().shape({
  supplier: yup.string().required('Supplier is required'),
  expected_delivery_date: yup.string().nullable(),
  is_recurring: yup.boolean(),
  recurrence_interval: yup.string().nullable(),
  notes: yup.string(),
  items: yup.array().of(
    yup.object().shape({
      raw_material: yup.string().required('Material is required'),
      quantity_ordered: yup.number().min(0.01, 'Quantity must be > 0').required('Required'),
      unit_price: yup.number().min(0, 'Price must be >= 0').required('Required'),
    })
  ).min(1, 'At least one item is required')
});

const PurchaseOrders = () => {
    const [orders, setOrders] = useState([]);
    const [suppliers, setSuppliers] = useState([]);
    const [materials, setMaterials] = useState([]);
    const [isLoading, setIsLoading] = useState(true);
    
    // Modals
    const [isCreateModalOpen, setIsCreateModalOpen] = useState(false);
    const [viewOrder, setViewOrder] = useState(null);
    const [confirmAction, setConfirmAction] = useState({ open: false, order: null, type: null });

    const { settings } = useSettingsStore();

    const { register, control, handleSubmit, reset, watch, formState: { errors, isSubmitting } } = useForm({
        resolver: yupResolver(orderSchema),
        defaultValues: {
            items: [{ raw_material: '', quantity_ordered: 1, unit_price: 0 }]
        }
    });

    const { fields, append, remove } = useFieldArray({
        control,
        name: "items"
    });

    const watchedItems = watch("items") || [];
    const totalAmount = watchedItems.reduce((acc, item) => acc + ((parseFloat(item.quantity_ordered) || 0) * (parseFloat(item.unit_price) || 0)), 0);

    const fetchData = async () => {
        setIsLoading(true);
        try {
            const [ordersRes, supRes, matRes] = await Promise.all([
                purchasingApi.getOrders(),
                purchasingApi.getSuppliers(),
                inventoryApi.getMaterials()
            ]);
            setOrders(ordersRes.data);
            setSuppliers(supRes.data);
            setMaterials(matRes.data);
        } catch (error) {
            toast.error('Failed to load data');
        } finally {
            setIsLoading(false);
        }
    };

    useEffect(() => {
        fetchData();
    }, []);

    const onSubmit = async (data) => {
        try {
            // Need to manually calculate item total prices
            const formattedData = {
                ...data,
                total_amount: totalAmount,
                items: data.items.map(item => ({
                    ...item,
                    total_price: (parseFloat(item.quantity_ordered) * parseFloat(item.unit_price)).toFixed(2)
                }))
            };
            
            if (!formattedData.expected_delivery_date) {
                formattedData.expected_delivery_date = null;
            }
            if (!formattedData.recurrence_interval) {
                formattedData.recurrence_interval = null;
            }
            
            await purchasingApi.createOrder(formattedData);
            toast.success('Purchase Order drafted successfully');
            setIsCreateModalOpen(false);
            fetchData();
        } catch (error) {
             toast.error(error.response?.data?.error || 'Failed to create PO');
        }
    };

    const handleConfirmAction = async () => {
        try {
            if (confirmAction.type === 'confirm') {
                 await purchasingApi.confirmOrder(confirmAction.order.id);
                 toast.success('Order confirmed and dispatched!');
            } else if (confirmAction.type === 'cancel') {
                 await purchasingApi.cancelOrder(confirmAction.order.id);
                 toast.success('Order cancelled.');
            }
            setConfirmAction({ open: false, order: null, type: null });
            setViewOrder(null);
            fetchData();
        } catch (e) {
            toast.error(e.response?.data?.error || `Failed to ${confirmAction.type} order`);
            setConfirmAction({ open: false, order: null, type: null });
        }
    };

    const columns = useMemo(() => [
        {
            header: 'PO Number',
            accessorKey: 'po_number',
            cell: info => <span className="font-semibold text-primary">{info.getValue()}</span>
        },
        {
            header: 'Supplier',
            accessorKey: 'supplier_name',
        },
        {
            header: 'Total Value',
            accessorFn: row => `${settings?.currency || '$'}${parseFloat(row.total_amount).toFixed(2)}`,
        },
        {
            header: 'Status',
            accessorKey: 'status',
            cell: info => {
                const status = info.getValue();
                const colors = {
                    'draft': 'bg-gray-500/20 text-gray-400',
                    'confirmed': 'bg-blue-500/20 text-blue-400',
                    'partially_received': 'bg-yellow-500/20 text-yellow-400',
                    'received': 'bg-green-500/20 text-green-400',
                    'cancelled': 'bg-red-500/20 text-red-400'
                };
                return (
                    <span className={`px-2 py-1 rounded-full text-xs font-medium uppercase tracking-wider ${colors[status] || colors.draft}`}>
                        {status.replace('_', ' ')}
                    </span>
                )
            }
        },
        {
            header: 'Created By',
            accessorKey: 'created_by_name',
        },
        {
            header: 'Actions',
            id: 'actions',
            cell: info => (
                <button 
                    onClick={(e) => { e.stopPropagation(); setViewOrder(info.row.original); }}
                    className="p-1.5 bg-white/5 text-white rounded hover:bg-white/10 transition-colors"
                >
                    <FiEye className="w-4 h-4" />
                </button>
            )
        }
    ], [settings]);

    return (
        <div className="p-6">
            <div className="flex justify-between items-center mb-6">
                <h1 className="text-2xl font-bold text-white">Purchase Orders</h1>
                <button 
                    onClick={() => {
                        reset({ items: [{ raw_material: '', quantity_ordered: 1, unit_price: 0 }] });
                        setIsCreateModalOpen(true);
                    }}
                    className="bg-primary hover:bg-primary/90 text-white px-4 py-2 rounded-lg font-medium transition-colors flex items-center space-x-2"
                >
                    <FiPlus className="w-5 h-5" />
                    <span>Create Draft PO</span>
                </button>
            </div>

            <DataTable 
                columns={columns} 
                data={orders} 
                isLoading={isLoading}
                searchPlaceholder="Search POs..."
            />

            {/* Create PO Modal - Redesigned Dashboard Layout */}
            {isCreateModalOpen && (
                <div className="fixed inset-0 z-50 flex items-center justify-center p-4">
                    <div className="fixed inset-0 bg-black/60 backdrop-blur-sm" onClick={() => setIsCreateModalOpen(false)}></div>
                    <div className="relative w-full max-w-6xl h-[85vh] flex overflow-hidden rounded-2xl border border-white/10 shadow-2xl shadow-black/50">
                        {/* Sidebar: Order Details */}
                        <div className="w-1/3 bg-[#0f172a] p-6 border-r border-white/5 flex flex-col relative z-10">
                            <h2 className="text-xl font-bold text-white mb-6">Draft Purchase Order</h2>
                            
                            <div className="space-y-6 flex-1 overflow-y-auto pr-2 custom-scrollbar">
                                <div>
                                    <label className="block text-sm font-medium text-textMuted mb-2">Select Supplier *</label>
                                    <select {...register('supplier')} className="form-input bg-background/50 border-white/5 shadow-inner">
                                        <option value="">-- Choose Supplier --</option>
                                        {suppliers.filter(s => s.is_active).map(s => (
                                            <option key={s.id} value={s.id}>{s.name}</option>
                                        ))}
                                    </select>
                                    {errors.supplier && <span className="text-red-400 text-xs mt-1 block">{errors.supplier.message}</span>}
                                </div>

                                <div>
                                    <label className="block text-sm font-medium text-textMuted mb-2">Expected Delivery Date</label>
                                    <input type="date" {...register('expected_delivery_date')} className="form-input bg-background/50 border-white/5 shadow-inner" />
                                </div>
                                
                                <div className="bg-background/40 rounded-xl p-4 border border-white/5">
                                    <div className="flex items-center space-x-3 mb-4">
                                        <div className="relative flex items-center">
                                            <input type="checkbox" {...register('is_recurring')} id="is_recurring" className="peer w-5 h-5 opacity-0 absolute cursor-pointer" />
                                            <div className="w-5 h-5 rounded border border-white/20 bg-background/50 peer-checked:bg-primary peer-checked:border-primary flex items-center justify-center pointer-events-none transition-colors">
                                                <FiCheckCircle className="w-3.5 h-3.5 text-white opacity-0 peer-checked:opacity-100" />
                                            </div>
                                        </div>
                                        <label htmlFor="is_recurring" className="text-sm font-medium text-white cursor-pointer select-none">Recurring Order</label>
                                    </div>
                                    
                                    <div className={`transition-all duration-300 overflow-hidden ${watch('is_recurring') ? 'max-h-24 opacity-100' : 'max-h-0 opacity-0'}`}>
                                        <label className="block text-xs font-medium text-textMuted mb-1">Frequency</label>
                                        <select {...register('recurrence_interval')} className="form-input bg-background/80 text-sm py-2">
                                            <option value="">Select Interval...</option>
                                            <option value="daily">Daily</option>
                                            <option value="weekly">Weekly</option>
                                            <option value="biweekly">Bi-Weekly</option>
                                            <option value="monthly">Monthly</option>
                                        </select>
                                    </div>
                                </div>
                            </div>
                            
                            <div className="pt-6 border-t border-white/10 mt-auto">
                                <div className="mb-6">
                                    <p className="text-textMuted text-sm mb-1">Estimated Total</p>
                                    <p className="text-4xl font-black tracking-tight bg-clip-text text-transparent bg-gradient-to-r from-primary to-accent">
                                        {settings?.currency || '$'}{totalAmount.toFixed(2)}
                                    </p>
                                </div>
                                <div className="flex space-x-3">
                                    <button type="button" onClick={() => setIsCreateModalOpen(false)} className="px-4 py-3 rounded-xl font-medium text-white bg-white/5 hover:bg-white/10 transition-colors w-1/3">
                                        Cancel
                                    </button>
                                    <button onClick={handleSubmit(onSubmit)} type="button" disabled={isSubmitting} className="px-4 py-3 rounded-xl font-bold tracking-wide text-white bg-primary hover:bg-primary/90 shadow-lg shadow-primary/25 transition-all w-2/3 flex justify-center items-center disabled:opacity-50 disabled:cursor-not-allowed">
                                        {isSubmitting ? 'Creating...' : 'Create Order'}
                                    </button>
                                </div>
                            </div>
                        </div>

                        {/* Main Content: Order Items Grid */}
                        <div className="w-2/3 bg-[#16213e] flex flex-col relative z-0">
                            {/* Decorative Background Blob */}
                            <div className="absolute top-0 right-0 w-96 h-96 bg-primary/10 rounded-full blur-[100px] pointer-events-none"></div>

                            <div className="p-6 border-b border-white/5 flex justify-between items-center bg-[#1e293b]/50 backdrop-blur-md sticky top-0 z-10">
                                <h3 className="text-lg font-bold text-white flex items-center">
                                    <FiShoppingCart className="mr-2 text-primary" /> Order Manifest
                                </h3>
                                <button 
                                    type="button" 
                                    onClick={() => append({ raw_material: '', quantity_ordered: 1, unit_price: 0 })}
                                    className="text-sm px-4 py-2 bg-primary/10 text-primary border border-primary/20 hover:bg-primary/20 hover:border-primary/30 rounded-lg flex items-center space-x-2 transition-all font-medium"
                                >
                                    <FiPlus /> <span>Add Item</span>
                                </button>
                            </div>
                            
                            <div className="flex-1 overflow-y-auto p-6 space-y-3 custom-scrollbar relative z-10">
                                <div className="grid grid-cols-12 gap-3 text-xs font-bold text-textMuted uppercase tracking-wider px-2 mb-2 items-center">
                                    <div className="col-span-1 text-center">#</div>
                                    <div className="col-span-4">Raw Material</div>
                                    <div className="col-span-2 text-center">Qty</div>
                                    <div className="col-span-2 text-center">Price / Unit</div>
                                    <div className="col-span-2 text-right">Ext. Total</div>
                                    <div className="col-span-1 text-center">Drop</div>
                                </div>
                                
                                {fields.length === 0 && (
                                    <div className="text-center py-12 opacity-50">
                                        <p className="text-white border border-dashed border-white/20 p-8 rounded-xl bg-white/5 inline-block">No items added to manifest yet.</p>
                                    </div>
                                )}

                                {fields.map((field, index) => {
                                    const qty = parseFloat(watchedItems[index]?.quantity_ordered) || 0;
                                    const price = parseFloat(watchedItems[index]?.unit_price) || 0;
                                    const rowTotal = (qty * price).toFixed(2);
                                    
                                    return (
                                        <div key={field.id} className="grid grid-cols-12 gap-3 items-center bg-white/5 hover:bg-white/10 border border-white/5 p-2 rounded-xl transition-colors group">
                                            <div className="col-span-1 text-center text-textMuted font-mono text-sm opacity-50 group-hover:opacity-100 transition-opacity">
                                                {String(index + 1).padStart(2, '0')}
                                            </div>
                                            <div className="col-span-4">
                                                <select {...register(`items.${index}.raw_material`)} className="w-full bg-black/20 border border-white/10 rounded-lg px-3 py-2.5 text-sm text-white focus:outline-none focus:border-primary transition-colors appearance-none scrollbar-thin">
                                                    <option value="" className="bg-[#0f172a]">Select Material...</option>
                                                    {materials.filter(m => m.is_active || m.id === watchedItems[index]?.raw_material).map(m => (
                                                        <option key={m.id} value={m.id} className="bg-[#0f172a]">{m.name} ({m.unit?.abbreviation || 'unit'})</option>
                                                    ))}
                                                </select>
                                            </div>
                                            <div className="col-span-2">
                                                <input type="number" step="0.001" placeholder="0" {...register(`items.${index}.quantity_ordered`)} className="w-full bg-black/20 border border-white/10 rounded-lg px-2 py-2.5 text-sm text-center text-white focus:outline-none focus:border-primary transition-colors font-mono" />
                                            </div>
                                            <div className="col-span-2 relative">
                                                <span className="absolute left-3 top-1/2 -translate-y-1/2 text-textMuted text-xs">{settings?.currency || '$'}</span>
                                                <input type="number" step="0.01" placeholder="0.00" {...register(`items.${index}.unit_price`)} className="w-full bg-black/20 border border-white/10 rounded-lg pl-7 pr-2 py-2.5 text-sm text-right text-white focus:outline-none focus:border-primary transition-colors font-mono" />
                                            </div>
                                            <div className="col-span-2 text-right text-sm font-mono font-bold text-accent pr-2 shadow-sm">
                                                {settings?.currency || '$'} {rowTotal}
                                            </div>
                                            <div className="col-span-1 flex justify-center">
                                                <button type="button" onClick={() => remove(index)} className="w-8 h-8 rounded-lg bg-red-500/10 text-red-400 hover:bg-red-500 hover:text-white flex items-center justify-center transition-colors">
                                                    <FiTrash2 className="w-4 h-4" />
                                                </button>
                                            </div>
                                        </div>
                                    )
                                })}
                                {errors.items?.root && <div className="bg-red-500/10 border border-red-500/30 text-red-400 p-3 rounded-lg text-sm flex items-center"><FiAlertCircle className="mr-2" />{errors.items.root.message}</div>}
                            </div>
                        </div>
                    </div>
                </div>
            )}

            {/* View PO Modal - Shows actual PO items, read only, with action buttons */}
            {viewOrder && (
                <div className="fixed inset-0 z-50 flex items-center justify-center p-4">
                    <div className="fixed inset-0 bg-black/60 backdrop-blur-sm" onClick={() => setViewOrder(null)}></div>
                    <div className="relative glass-panel w-full max-w-3xl p-6">
                        <div className="flex justify-between items-start mb-6">
                            <div>
                                <h2 className="text-2xl font-bold text-white tracking-tight">{viewOrder.po_number}</h2>
                                <p className="text-textMuted mt-1">Supplier: <span className="text-white font-medium">{viewOrder.supplier_name}</span></p>
                            </div>
                            <span className="px-3 py-1 rounded-full uppercase tracking-wider text-xs font-bold bg-white/10 text-white border border-white/20">
                                {viewOrder.status.replace('_', ' ')}
                            </span>
                        </div>
                        
                        <div className="glass-panel p-4 mb-6">
                            <h3 className="text-sm font-semibold text-textMuted uppercase tracking-wider mb-4">Line Items</h3>
                            <table className="w-full text-left text-sm">
                                <thead>
                                    <tr className="border-b border-white/10 text-textMuted">
                                        <th className="pb-2 font-medium">Material</th>
                                        <th className="pb-2 font-medium text-center">Ordered</th>
                                        <th className="pb-2 font-medium text-center">Received</th>
                                        <th className="pb-2 font-medium text-right">Unit Price</th>
                                        <th className="pb-2 font-medium text-right">Total</th>
                                    </tr>
                                </thead>
                                <tbody className="divide-y divide-white/5">
                                    {viewOrder.items?.map(item => (
                                        <tr key={item.id}>
                                            <td className="py-3 text-white">{item.raw_material_name}</td>
                                            <td className="py-3 text-center">{parseFloat(item.quantity_ordered)}</td>
                                            <td className={`py-3 text-center font-bold ${item.quantity_received >= item.quantity_ordered ? 'text-green-400' : 'text-yellow-400'}`}>
                                                {parseFloat(item.quantity_received)}
                                            </td>
                                            <td className="py-3 text-right text-textMuted">{settings?.currency || '$'}{parseFloat(item.unit_price).toFixed(2)}</td>
                                            <td className="py-3 text-right font-mono text-accent">{settings?.currency || '$'}{parseFloat(item.total_price).toFixed(2)}</td>
                                        </tr>
                                    ))}
                                </tbody>
                            </table>
                        </div>

                        <div className="flex justify-between items-center pt-4 border-t border-white/10">
                            <div className="flex space-x-3">
                                {viewOrder.status === 'draft' && (
                                    <>
                                        <button 
                                            onClick={() => setConfirmAction({ open: true, order: viewOrder, type: 'confirm' })} 
                                            className="px-4 py-2 bg-blue-500/20 text-blue-400 border border-blue-500/30 hover:bg-blue-500/30 rounded-lg flex items-center space-x-2 transition-colors"
                                        >
                                            <FiCheckCircle /> <span>Confirm Order</span>
                                        </button>
                                        <button 
                                            onClick={() => setConfirmAction({ open: true, order: viewOrder, type: 'cancel' })} 
                                            className="px-4 py-2 bg-red-500/20 text-red-400 border border-red-500/30 hover:bg-red-500/30 rounded-lg flex items-center space-x-2 transition-colors"
                                        >
                                            <FiXCircle /> <span>Cancel Order</span>
                                        </button>
                                    </>
                                )}
                            </div>
                            <button onClick={() => setViewOrder(null)} className="px-5 py-2 bg-white/5 hover:bg-white/10 text-white rounded-lg transition-colors">
                                Close
                            </button>
                        </div>
                    </div>
                </div>
            )}
            
            <ConfirmModal 
                isOpen={confirmAction.open}
                title={`${confirmAction.type === 'confirm' ? 'Confirm' : 'Cancel'} Purchase Order`}
                message={`Are you sure you want to ${confirmAction.type} PO: ${confirmAction.order?.po_number}?`}
                onConfirm={handleConfirmAction}
                onCancel={() => setConfirmAction({ open: false, order: null, type: null })}
                confirmText={confirmAction.type === 'confirm' ? 'Yes, Confirm' : 'Yes, Cancel'}
                isDestructive={confirmAction.type === 'cancel'}
            />
        </div>
    );
};

export default PurchaseOrders;

import React, { useState, useEffect, useMemo } from 'react';
import { 
  FiShoppingCart, FiDollarSign, FiClock, FiAlertCircle, 
  FiArrowRight, FiTruck, FiFileText
} from 'react-icons/fi';
import { Link } from 'react-router-dom';
import { purchasingApi } from '../../api/purchasingApi';
import useSettingsStore from '../../store/settingsStore';
import toast from 'react-hot-toast';

const StatCard = ({ title, value, icon: Icon, color, subtitle }) => (
    <div className="glass-panel p-6 relative overflow-hidden group">
        <div className={`absolute -right-6 -top-6 w-24 h-24 rounded-full opacity-10 blur-2xl group-hover:scale-150 transition-transform duration-500`} style={{ backgroundColor: color }}></div>
        <div className="flex items-start justify-between relative z-10">
            <div>
                <p className="text-textMuted text-sm font-medium mb-1">{title}</p>
                <h3 className="text-3xl font-bold text-white tracking-tight">{value}</h3>
                {subtitle && <p className="text-xs text-textMuted mt-2">{subtitle}</p>}
            </div>
            <div className={`p-3 rounded-xl`} style={{ backgroundColor: `${color}20`, color: color }}>
                <Icon className="w-6 h-6" />
            </div>
        </div>
    </div>
);

const PurchasingDashboard = () => {
    const [isLoading, setIsLoading] = useState(true);
    const [stats, setStats] = useState({
        activePOs: 0,
        pendingDeliveries: 0,
        unpaidInvoices: 0,
        totalSpendMTD: 0
    });
    const [recentActivity, setRecentActivity] = useState({
        pos: [],
        grns: []
    });

    const { settings } = useSettingsStore();

    useEffect(() => {
        const fetchDashboardData = async () => {
            setIsLoading(true);
            try {
                // Fetching all necessary data to calculate stats
                const [poRes, grnRes, invRes] = await Promise.all([
                    purchasingApi.getOrders(),
                    purchasingApi.getGRNs(),
                    purchasingApi.getInvoices()
                ]);

                const pos = poRes.data;
                const grns = grnRes.data;
                const invoices = invRes.data;

                // Calculate Metrics
                const activePOs = pos.filter(po => ['confirmed', 'partially_received'].includes(po.status)).length;
                const pendingDeliveries = grns.filter(grn => grn.status === 'pending').length;
                const unpaidInvoices = invoices.filter(inv => ['pending', 'partially_paid'].includes(inv.status)).length;
                
                // Calculate Spend for Current Month
                const currentMonth = new Date().getMonth();
                const currentYear = new Date().getFullYear();
                
                const mtdSpend = invoices
                    .filter(inv => {
                        const invDate = new Date(inv.invoice_date);
                        return invDate.getMonth() === currentMonth && invDate.getFullYear() === currentYear;
                    })
                    .reduce((sum, inv) => sum + parseFloat(inv.total_amount), 0);

                setStats({
                    activePOs,
                    pendingDeliveries,
                    unpaidInvoices,
                    totalSpendMTD: mtdSpend
                });

                // Grab 5 most recent
                setRecentActivity({
                    pos: pos.slice(0, 5),
                    grns: grns.slice(0, 5)
                });

            } catch (error) {
                console.error("Dashboard error:", error);
                toast.error("Failed to load purchasing dashboard data");
            } finally {
                setIsLoading(false);
            }
        };

        fetchDashboardData();
    }, []);

    if (isLoading) {
        return (
            <div className="p-6 md:p-8 pt-24 h-full flex flex-col justify-center items-center">
                <div className="animate-spin rounded-full h-12 w-12 border-t-2 border-b-2 border-primary mb-4"></div>
                <p className="text-textMuted">Loading Purchasing Metrics...</p>
            </div>
        );
    }

    return (
        <div className="p-6 md:p-8 pt-24">
            <div className="mb-8">
                <h1 className="text-3xl font-bold tracking-tight text-white mb-2">Purchasing Command Center</h1>
                <p className="text-textMuted">Monitor your supply chain, orders, and financial commitments.</p>
            </div>

            {/* Top Stats Grid */}
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6 mb-8">
                <StatCard 
                    title="Active Purchase Orders" 
                    value={stats.activePOs} 
                    icon={FiShoppingCart} 
                    color="#3b82f6" // Blue
                    subtitle="Awaiting full delivery"
                />
                <StatCard 
                    title="Pending Deliveries" 
                    value={stats.pendingDeliveries} 
                    icon={FiTruck} 
                    color="#eab308" // Yellow
                    subtitle="GRNs needing confirmation"
                />
                <StatCard 
                    title="Unpaid/Partial Invoices" 
                    value={stats.unpaidInvoices} 
                    icon={FiAlertCircle} 
                    color="#ef4444" // Red
                    subtitle="Action required for suppliers"
                />
                <StatCard 
                    title="Month-to-Date Spend" 
                    value={`${settings?.currency || '$'}${stats.totalSpendMTD.toFixed(2)}`} 
                    icon={FiDollarSign} 
                    color="#22c55e" // Green
                    subtitle="Total invoiced this month"
                />
            </div>

            <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
                {/* Recent POs */}
                <div className="glass-panel p-6 flex flex-col h-[400px]">
                    <div className="flex justify-between items-center mb-6">
                        <div className="flex items-center space-x-2">
                            <FiFileText className="text-primary w-5 h-5" />
                            <h3 className="text-lg font-bold text-white">Recent POs</h3>
                        </div>
                        <Link to="/purchasing/orders" className="text-xs font-medium text-primary hover:text-primary/80 flex items-center transition-colors">
                            View All <FiArrowRight className="ml-1" />
                        </Link>
                    </div>
                    
                    <div className="overflow-y-auto pr-2 space-y-3 flex-1 pb-4 custom-scrollbar">
                        {recentActivity.pos.length > 0 ? (
                            recentActivity.pos.map(po => (
                                <Link to="/purchasing/orders" key={po.id} className="block bg-white/5 hover:bg-white/10 p-4 rounded-xl border border-white/5 transition-all">
                                    <div className="flex justify-between items-start mb-2">
                                        <p className="font-semibold text-white tracking-wide">{po.po_number}</p>
                                        <span className="text-xs font-mono text-accent">{settings?.currency || '$'}{parseFloat(po.total_amount).toFixed(2)}</span>
                                    </div>
                                    <div className="flex justify-between items-center">
                                        <p className="text-sm text-textMuted">{po.supplier_name}</p>
                                        <span className={`px-2 py-0.5 rounded-full text-[10px] font-bold uppercase tracking-wider ${
                                            po.status === 'confirmed' ? 'bg-blue-500/20 text-blue-400' :
                                            po.status === 'received' ? 'bg-green-500/20 text-green-400' :
                                            po.status === 'draft' ? 'bg-gray-500/20 text-gray-400' :
                                            'bg-yellow-500/20 text-yellow-500'
                                        }`}>
                                            {po.status.replace('_', ' ')}
                                        </span>
                                    </div>
                                </Link>
                            ))
                        ) : (
                            <div className="flex flex-col items-center justify-center h-full text-textMuted opacity-50">
                                <FiFileText className="w-12 h-12 mb-3" />
                                <p>No recent purchase orders</p>
                            </div>
                        )}
                    </div>
                </div>

                {/* Recent Goods Received */}
                <div className="glass-panel p-6 flex flex-col h-[400px]">
                    <div className="flex justify-between items-center mb-6">
                        <div className="flex items-center space-x-2">
                            <FiTruck className="text-yellow-400 w-5 h-5" />
                            <h3 className="text-lg font-bold text-white">Recent GRNs</h3>
                        </div>
                        <Link to="/purchasing/grn" className="text-xs font-medium text-primary hover:text-primary/80 flex items-center transition-colors">
                            View All <FiArrowRight className="ml-1" />
                        </Link>
                    </div>
                    
                    <div className="overflow-y-auto pr-2 space-y-3 flex-1 pb-4 custom-scrollbar">
                        {recentActivity.grns.length > 0 ? (
                            recentActivity.grns.map(grn => (
                                <Link to="/purchasing/grn" key={grn.id} className="block bg-white/5 hover:bg-white/10 p-4 rounded-xl border border-white/5 transition-all">
                                    <div className="flex justify-between items-start mb-2">
                                        <p className="font-semibold text-white tracking-wide">{grn.grn_number}</p>
                                        <p className="text-xs text-textMuted">{new Date(grn.received_date).toLocaleDateString()}</p>
                                    </div>
                                    <div className="flex justify-between items-center">
                                        <p className="text-sm text-textMuted">{grn.supplier_name}</p>
                                        <span className={`px-2 py-0.5 rounded-full text-[10px] font-bold uppercase tracking-wider ${
                                            grn.status === 'completed' ? 'bg-green-500/20 text-green-400' : 'bg-yellow-500/20 text-yellow-500'
                                        }`}>
                                            {grn.status.replace('_', ' ')}
                                        </span>
                                    </div>
                                </Link>
                            ))
                        ) : (
                            <div className="flex flex-col items-center justify-center h-full text-textMuted opacity-50">
                                <FiTruck className="w-12 h-12 mb-3" />
                                <p>No recent goods received</p>
                            </div>
                        )}
                    </div>
                </div>
            </div>
            
            {/* Quick Actions (Optional Add-on if layout needs balance later) */}
            <div className="mt-8 grid grid-cols-1 md:grid-cols-3 gap-6">
                <Link to="/purchasing/orders" className="glass-panel p-6 flex items-center space-x-4 hover:border-primary/50 transition-colors cursor-pointer group">
                    <div className="w-12 h-12 rounded-xl bg-blue-500/20 text-blue-400 flex items-center justify-center group-hover:scale-110 transition-transform">
                        <FiShoppingCart className="w-6 h-6" />
                    </div>
                    <div>
                        <h4 className="font-bold text-white group-hover:text-primary transition-colors">Draft Purchase Order</h4>
                        <p className="text-sm text-textMuted">Order new stock from suppliers</p>
                    </div>
                </Link>
                <Link to="/purchasing/grn" className="glass-panel p-6 flex items-center space-x-4 hover:border-yellow-500/50 transition-colors cursor-pointer group">
                    <div className="w-12 h-12 rounded-xl bg-yellow-500/20 text-yellow-400 flex items-center justify-center group-hover:scale-110 transition-transform">
                        <FiTruck className="w-6 h-6" />
                    </div>
                    <div>
